body:
[Proposition prop:inheritance of properties of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $G$ be a locally compact topological group with Haar measure $\mu$ that acts on $\mathcal{X}$. Assume further that $\pi \in \mathcal{I}(G)$ is $G$-invariant. We have
	\begin{enumerate}
		\item($\pi$-stationarity) If $P \in \mathcal{S}(\pi)$, then $P_{da}(G,\nu)$ (and hence $\overline{P}, \widetilde{P}, P_{la}, P_{ra}, (P_{la})_{ra}$) $\in \mathcal{S}(\pi)$ and $(P_{la})^* = P^*_{ra}$.

		\item($\pi$-reversibility) If $P \in \mathcal{L}(\pi)$ and $\nu$ is symmetric in the sense that $(g,h) \overset{D}{=} (h^{-1},g^{-1}) \sim \nu$ where $\overset{D}{=}$ denotes equality in distribution, then $P_{da}(G,\nu) \in \mathcal{L}(\pi)$. In particular, this yields $\overline{P}, \widetilde{P}, (P_{la})_{ra} \in \mathcal{L}(\pi)$.

		\item(compactness) Assume that $G$ is a finite group. If $P$ is a compact operator, then $P_{da}(G,\nu)$ (and hence $\overline{P}, \widetilde{P}, P_{la}, P_{ra}, (P_{la})_{ra}$) are compact operators.

		\item(trace-class operator) Suppose that $P$ is a trace-class operator and $G$ is a finite group. Then
		\begin{align*}
			\mathrm{Tr}(P) = \mathrm{Tr}(\overline{P}),
		\end{align*}
		and hence $\mathrm{Tr}(\overline{P}) < \infty$. Assume further that $P \in \mathcal{L}(\pi)$ (and hence $\overline{P}$) is a non-negative $L^2(\pi)$-self-adjoint operator, then $P$ is trace-class implies that $\overline{P}$ is trace-class.

		\item(Hilbert-Schmidt operator) If $P$ is a Hilbert-Schmidt operator, then
		\begin{align*}
			\left\lVert P \right\rVert_{\mathrm{HS}} \geq \norm{\overline{P}}_{\mathrm{HS}}, \quad \left\lVert P \right\rVert_{\mathrm{HS}} \geq \norm{P_{la}}_{\mathrm{HS}} \geq \norm{(P_{la})_{ra}}_{\mathrm{HS}}, \quad \left\lVert P \right\rVert_{\mathrm{HS}} \geq \norm{P_{ra}}_{\mathrm{HS}}.
		\end{align*}
		Consequently, $\overline{P}, P_{la}, P_{ra}, (P_{la})_{ra}$ are Hilbert-Schmidt operators. If $G$ is assumed to be a finite group, then $P_{da}(G,\nu)$ and hence $\widetilde{P}$ are Hilbert-Schmidt operators.		
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

