[Theorem thm:equivctdscausality of arXiv:2412.02948, 'Causal transport on path space'] A coupling $\pi \in \Pi\del{\eta,\nu}$ is a causal coupling if and only if the filtrations $\deln{\mathcal{H}^\eta_t \otimes \cbrn{\emptyset, \mathcal{W}^d}}_{t\in \sbr{0,1}}$ and $\del{\del{\mathcal{H}_t \otimes \mathcal{H}_t}^\pi}_{t+ \in \sbr{0,1}}$ on $\deln{\mathcal{W}^d \times \mathcal{W}^d, \mathcal{F}_1 \otimes \mathcal{F}_1, \pi}$ 
satisfy the  $H$-hypothesis:

  \begin{equation}

        \mathcal{M}^2\deln{\pi, \deln{\mathcal{H}^\eta_t \otimes \cbrn{\emptyset, \mathcal{W}^d} }_{t\in [0,1]}} \subseteq \mathcal{M}^2\deln{\pi, \del{\del{\mathcal{H}_t \otimes \mathcal{H}_t}^\pi}_{t+ \in \sbr{0,1}}}.
    \end{equation}

[Proposition 5 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] Let $\rho \in L^1_\loc(I\times \R^d)$. Then the following are equivalent:
\begin{enumerate}
	\item $\rho$ solves \eqref{CE};
	\item for any $\fhi \in C_c^1(\R^d)$ the function $t \mapsto \int_{\R^d} \rho(t,x) \fhi(x) \, dx$ belongs to the Sobolev space $W^{1,1}_\loc(I)$ and
	\begin{equation}
		\d_t \int_{\R^d} \rho(t,x) \fhi(x) \, dx = \int_{\R^d} \rho(t, x) \v(t, x) \cdot \nabla \fhi(x) \, dx
	\end{equation}
	in the sense of distributions (or, equivalently, for a.e. $t$);
	\item there exists a negligible set $N \subset I$ such that
	for all $s, t \in I\setminus N$ and for all $\fhi \in C^1_c(\R^d)$ 
	\begin{equation}
		\int_{\R^d} \rho(t,x) \fhi(x) \, dx = \int_{\R^d} \rho(s,x) \fhi(x) \, dx + \int_s^t \int_{\R^d} \rho(\tau, x) \v(\tau, x) \cdot \nabla \fhi(x) \, dx \, d\tau.
	\end{equation}
\end{enumerate}

[Prop P:KPZFP-marginals of arXiv:2604.10020, 'The directed landscape in half-space'] Take $\rho\in\mathbb{R}\cup\{-\infty\}$, and $\mathcal{Q}^\rho$ a subsequential limit in law of $\mathcal{Q}^\rho_n$ (when $\rho\in\mathbb{R}$) or $\mathcal{Q}^{-c(2n)^{1/3}}_n$ for some $c>0$ (when $\rho=-\infty$).
For any $f \in \operatorname{UC}_+$ with $\limsup_{x\to\infty} f(x)/x < \infty$, a finite set $Y\subset \mathbb{R}_{\ge 0}$, and $s\in\mathbb{R}$, $t>0$, we have
		\begin{equation}

		    \left(\max_{x \ge 0} f(x) + \mathcal{Q}^\rho(x, s; y, s + t) : y \in Y\right) \stackrel{d}{=} ( \mathfrak{h}^\rho(y, t ; f) : y \in Y).
		\end{equation}

[Proposition prop:convergence of R-transforms of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{f_{n}\}_{n\geq 1}$ satisfy Assumption (assump:main assumption of the paper). 
	\begin{enumerate}
		\item Let $R_{\mu_{c,\Sigma}}$ be the $R$-transform of $\mu_{c,\Sigma}$, then 
		\begin{equation}
			\lim\limits_{n\rightarrow\infty}-\frac{f_{n}'(nu)}{f_{n}(nu)}= R_{\mu_{c,\Sigma}}(u),
		\end{equation} 
		uniformly on compact subsets of $\mathbb{C}_{-}$.

		\item Define $\left[ \log(1-xw)\frac{x^2+1}{x^2}+\frac{w}{x}\right]\Big|_{x=0}:=-\frac{w^2}{2}$ by continuous extension, then		
		\begin{equation}
			\lim\limits_{n\rightarrow\infty}\frac{1}{n}\log f_{n}(nu)-\frac{1}{n}\log f_{n}(-n\ii)=-c(u+\ii)+\int_{\mathbb{R}}\log\left(\frac{1-ux}{1+\ii x}\right)\frac{x^2+1}{x^2}+\frac{u+\ii}{x}\mathrm{d}\Sigma(x),
		\end{equation}  uniformly on compact subsets of $\mathbb{C}_{-}$.
		\item For any $M\in\mathbb{R}$ define $\log_{M}|z|:=\max(\log|z|,-M)$, then \begin{align}
			\lim\limits_{n\rightarrow\infty} &\frac{1}{n}\log_{M}| f_{n}(nu)|-\frac{1}{n}\log_{M}| f_{n}(-n\ii)|\\
			&=\operatorname{Re}\left(-c(u+\ii)\right)+\int_{\mathbb{R}}\left[\log_{M}\left|{1-ux}\right|-\log_{M}\left|{1+\ii x}\right|\right]\frac{x^2+1}{x^2} +\operatorname{Re}\frac{u+\ii}{x}\mathrm{d}\Sigma(x),\nonumber
		\end{align} uniformly on compact subsets of $\mathbb{C}_{-}\cup\mathbb{R}\setminus\{0\}$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:minima of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] Let $v\geq 2$. Then
    \begin{align}
    \notag\phi_n(v) &\ge \min\left(\mathrm{Fr}^{>v}_n(v), \mathrm{Fr}^{>v}_n(1)\right), \quad\text{and }\\
    \phi_n^{\scriptscriptstyle{({2}})}(v)&\ge \min\left(\mathrm{Fr}_n^{>v}(v)\mathrm{Fr}_n^{>v}(\mathrm{pa}(v)),  \,\,\,  \mathrm{Fr}_n^{>v}(v) \mathrm{Fr}_n^{>v}(1),   \,\,\,  \mathrm{Fr}_n^{>v}(v) \mathrm{Fr}_n^{>v}(2),   \,\,\,  \mathrm{Fr}_n^{>v}(1)\mathrm{Fr}_n^{>v}(2)\right).
    \end{align}
    Further, for $v=2$, one has
    \begin{equation}
        \phi_n^{\scriptscriptstyle{({2}})}(2) \ge \min\left(\mathrm{Fr}_n^{>3}(2)\mathrm{Fr}_n^{>3}(1),  \,\,\,  \mathrm{Fr}_n^{>3}(2)\mathrm{Fr}_n^{>3}(3),   \,\,\,  \mathrm{Fr}_n^{>3}(1)\mathrm{Fr}_n^{>3}(3)\right).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Existence and uniqueness of the marginal flow) of arXiv:2607.25685, 'Mimicking diffusion processes with differential equations'] \ 

\begin{enumerate}
\item[\textup{(a)}] \emph{(Uniqueness)} Under assumptions  \textup{(E1)}, \textup{(D$_{\mathrm E}$)} and \textup{(I1)}, there is at most one weak solution of the Fokker-Planck-Kolmogorov equation \eqref{eq:fp}
in $\mathcal X$ with initial condition $p_0$.
\item[\textup{(b1)}] \emph{(Existence of solutions and $L^2$ estimate)}
Under assumptions  \textup{(E1)}, \textup{(D$_{\mathrm E}^+$)}, and \textup{(I1)} there exists a weak solution $p\in \mathcal X$ of \eqref{eq:fp}
 with initial condition $p_0$, and it  satisfies
\begin{align}
  \sup_{s\le T}\|p_s\|_{L^2}^2&\;\le\;\|p_0\|_{L^2}^2\,e^{\theta},
  \\[2pt]
  \epsilon^2\!\int_0^T\!\|\nabla p_s\|_{L^2}^2\,\dd s
&\;\le\;\|p_0\|_{L^2}^2\,\big(1+\theta\,e^{\theta}\big),

\end{align}
where 
$\theta:=\int_0^T\|[\Div f(\cdot,s)]^-\|_{L^\infty}\,\dd s$.
In particular:
\begin{equation}
  \sup_{s\le T}\|p_s\|_{L^2}^2+\epsilon^2\!\int_0^T\!\|\nabla p_s\|_{L^2}^2\,\dd s
  \;\le\;2\,\|p_0\|_{L^2}^2\,e^{2\theta}.
\end{equation}
\item[\textup{(b2)}] \emph{(Moments and Fisher information)}
If, in addition,  \textup{(I2)} is satisfied then $$\sup_{t\leq T}\int_{\mathbb{R}^d}\|x\|^2 p_t(x) dx <\infty \qquad {\rm and}\qquad \int_0^T I(p_t)dt <\infty $$
\item[\textup{(c)}] \emph{(Identification)} If $X$ is any weak solution of the stochastic differential equation \eqref{eq:sde}
with $X_0\sim p_0\Leb$ whose   marginals are absolutely continuous with densities in
$\mathcal X$, then the density flow of $X$ is the (unique) weak solution of the Fokker-Planck-Kolmogorov equation \eqref{eq:fp} with initial condition $p_0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:nonbacktracking of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] \begin{itemize}
    \item[(i)] 

For $n\ge 2$,  we define  $V_n$ as the $n$-th non-backtracking power of $H$,
\begin{equation}
    \begin{aligned}(V_n)_{xy}:=\sum_{x_0,x_1,\ldots,x_n}\delta_{x,x_0}\delta_{x_n,y}\left[\prod_{i=0}^{n-2}\mathbf{1}(x_i\ne x_{i+2})\right] H_{x_0x_1}H_{x_1x_2}\cdots H_{x_{n-1}x_n},
    \end{aligned}
\end{equation}
while   $V_0:=\mathbb{I}, V_1:=H$ and $V_n:=0$ for $n<0$.

\item[(ii)] We introduce  two   matrices $\Phi_2$ and $\Phi_3$ through
\begin{equation}
    (\Phi_2)_{xy}:=\delta_{xy}\sum_{z}(|H_{xz}|^2-\sigma_{xz}^2), \quad (\Phi_3)_{xy}:=-|H_{xy}|^2H_{xy},
\end{equation}
and  also introduce the shorthand $\underline{\Phi_3V_n}$ defined by
\begin{equation}
(\underline{\Phi_3V_n})_{xy}:=\sum_{x_0,x_1,\ldots x_{n-2}}\delta_{x,x_0}\delta_{x_{n-2},y}\left[\prod_{i=0}^{n-4}\mathbf{1}(x_i\ne x_{i+2})\right] (\Phi_{3})_{x_0x_1}H_{x_1x_2}\cdots H_{x_{n-3}x_{n-2}},
\end{equation}
while by  convention  $\underline{\Phi_3V_0}=\underline{\Phi_3V_1}=\underline{\Phi_3V_2}=0$,  $\underline{\Phi_3V_3}=\Phi_3$ and $\underline{\Phi_2 V_n}:=\Phi_2V_{n-2}$. 

\item[(iii)]  Similarly, we introduce 
\begin{equation}
    (\widehat{\Phi}_3)_{xy}:=|\widehat{H}_{xy}|^2\widehat{H}_{xy}, ~~(\widehat{\Phi}_2)_{xy}:=\delta_{xy}\sum_{z}B_{xz}^2\sigma_{xz}^2(|\widetilde{W}_{xz}|^2-1),
\end{equation}
and 
\begin{equation}
(\underline{\widehat{\Phi_3V_n}})_{xy}:=\sum_{x_0,x_1,\ldots x_{n-2}}\delta_{x,x_0}\delta_{x_{n-2},y}\left[\prod_{i=0}^{n-4}\mathbf{1}(x_i\ne x_{i+2})\right] (\widehat{\Phi}_{3})_{x_0x_1}\widehat{H}_{x_1x_2}\cdots \widehat{H}_{x_{n-3}x_{n-2}},
\end{equation}
while by   convention  $\underline{\widehat{\Phi_3V_3}}=\widehat{\Phi}_3$ and $\underline{\widehat{\Phi_2 V_n}}:=\widehat{\Phi}_2\widehat{V}_{n-2}$. Here $\widehat{V}$ is the resulting  matrix after replacing all $H$ by   $\widehat{H}$   in (equation equ:def_V of the paper). 
\end{itemize}

[Lemma 3 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] Suppose that $X_0$ is a dense linear subspace of a normed space $(X, \|\cdot\|_X)$.
	Then for any $u\in C^1_c(\R; X)$ with $\supp u \subset (a,b)$ and for any $\eps >0$
	there exists a function 
	$v$ of the form
	\begin{equation*}
		v(t) = \sum_{k=1}^n \psi_k(t) v_k, 
	\end{equation*}
	where $v_k \in X_0$ and $\psi_k \in C^\infty_c(\R)$, 
	such that $\supp \psi_k\subset (a,b)$ and
	\begin{equation*}
		\|u-v\|_{C^1(\R; X)} < \eps.
	\end{equation*}

