[Proposition 13 of arXiv:2608.26565, 'A Horizon-Free Extrinsic Penrose Inequality'] Suppose that $D\in\mathcal A_S$ is outermost toward $\mathcal E_+$. Then
	\begin{equation}
		m_+(S)\geq\sqrt{\frac{|D|}{\pi}}
		\geq\sqrt{\frac{A_S}{\pi}}.

	\end{equation}

[Definition eq:weightedSobo of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Set $\alpha\in (0,1)$.
On every flowbox $\square \simeq [0,1]^2 $ \emph{avoiding the unstable curves} with local coordinates $(r,\theta)$ where $V=\partial_r$, we define these local semi-norms on smooth connections as~:
\begin{equation}
\Vert A\Vert_{\mathcal{W}^{\alpha,\alpha-1;p}_{r,\theta}(\square) }\coloneq  \left( \int_{I^2} \frac{\Vert W(r_1,.)-W(r_2,.) \Vert^p_{W^{\alpha,p}_{\theta,J}}}{\vert r_1-r_2\vert^{1+\alpha p}} \mathrm{d} r_1\mathrm{d} r_2 \right)^{\frac{1}{p}}+\Vert W\Vert_{L^p(\square)}  \end{equation}
for $\tilde{A}(r,u) \coloneq \partial_\theta W(r,\theta) $ and $W(.,0)=0$.

[Thm 2 (Corollary 8.2 of Yano--Yano--Yor \cite{Yano-Yano-Yor}) of arXiv:2608.26642, '2608.26642'] Let $X$ be a symmetric $\alpha$-stable process with $1<\alpha\le 2$. Suppose that $\mu$ is a finite positive Radon measure satisfying $\int_\R (1+|y|^{\alpha-1})\,\mu(dy)<\infty$. Then
\begin{align}
\lim_{t\to \infty}\frac{\P_x[F_s\cdot \Gamma_t^\mu]}{\P_x[\Gamma_t^\mu]}=\mathscr{P}_x\left[F_s\cdot \frac{\Gamma_\infty^\mu}{\mathscr{P}_x[\Gamma_\infty^\mu]}\right]\qquad \text{for}\ F_s\in b\F_s,
\end{align}
where $\mathscr{P}_x$ is the universal $\sigma$-finite measure (see Section \ref{S5} for details). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 10 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] For fixed integers $N\geq M\geq 0$, let $x=(x_1,\dots,x_N)$ be the ordered coordinates of TASEP particles at time $t$ and let $y=(y_1,\dots,y_M)$ denote the ordered initial coordinates of the particles. In the case $y_M > N-M+1$, the half-line open TASEP has transition probability from an empty state to $x$ given by the following: when $N+M$ is even
	\begin{equation}

		\mathbb{P}_t(y\to x) = (-1)^{\binom{N}{2}}\mathrm{e}^{-\alpha t} \pf\left[\begin{array}{cc}
			\mathsf{Q} & \mathsf{U} \\[5pt]
			-\mathsf{U}^T & 0
		\end{array}\right],
	\end{equation}
	when $N+M$ is odd
	\begin{equation}

		\mathbb{P}_t(y\to x) = (-1)^{\binom{N}{2}}\mathrm{e}^{-\alpha t} 
		\pf\left[\begin{array}{ccc}
			\mathsf{Q} & \mathsf{p} & \mathsf{U}\\[5pt]
			-\mathsf{p}^T & 0 & 0 \\[5pt]
		 	-\mathsf{U}^T & 0 & 0
		\end{array}\right].
	\end{equation}
    Here, $\mathsf{Q}$ is a skew-symmetric $N\times N$-dimensional matrix and $\mathsf{p}$ is a column vector of length $N$ which are the same as those in Theorem \ref{thm: transition prob pfaffian kernel}, while $\mathsf{U}$ is a $N\times M$-dimensional matrix whose entries are given by
    \begin{align*}
        [\mathsf{Q}]_{i,j} := & Q_{i,j}(x_{N-i+1},x_{N-j+1}), \\ 
        [\mathsf{p}]_i := & p_{i}(x_{N-i+1}), \\
        [\mathsf{U}]_{i,k} := & U_{i-k}(x_{N-i+1}-y_{M-k+1}),
    \end{align*}
    for all $1\leq i,j\leq N$ and $1\leq k\leq M$. The functions $Q_{i,j}$ and $p_i$ are defined by \eqref{eq:Q-kernel} and \eqref{eq:p-kernel} respectively while we define the integral kernel
	\begin{align}

		U_{k}(z) := \oint_\gamma \frac{\dd w}{2\pi\ii} \frac{(w-1)^{N-M-k}\mathrm{e}^{t(w-1)}}{w^{z-k+N-M+1}},
	\end{align}
    where the contour $\gamma$ encloses the (possible) pole at the origin. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemme 70 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] The following inequalities hold.

\begin{alignat*}{2}
\frac{1}{N} |\lambda_j^\pm - \zeta_j | &\leq |\lambda_{j+1}^\pm - \zeta_j | &&\leq N |\lambda_j^\pm - \zeta_j | \, , \\
\frac{1}{N} |\zeta_k - \eta_{k+1}| &\leq  \; \;   |\zeta_k - \eta_k| &&\leq N |\zeta_k - \eta_{k+1}|  \; .
\end{alignat*}

