		\eta_t^\mathsf{x} \coloneqq \frac{\gamma_t \eta_t^\mathsf{p}}{2}\,, \qquad \eta_t^\mathsf{p} \coloneqq \frac{c_0 \omega}{\exp(\omega\,(T-t))-1}\,.
