and since $x^2 \geq \log^2(1+\phi_v) \geq x^2 - x^3 + \fr{1}{4} x^4$, we also have
\begin{equation}
    \Rnd{1 - \fr{3}{4}p}^d \geq
    \E[\log^2(1+\phi_v)] \geq
    \Rnd{1 - \fr{3}{4}p}^d - \Rnd{1 - \fr{7}{8}p}^d + \fr{1}{4} \Rnd{1 - \fr{15}{16}p}^d.
\end{equation}
Combining these, we obtain
\begin{align}

    \Rnd{1 - \fr{3}{4}p}^d &- \Rnd{1 - \fr{1}{2}p}^{2d} 
    + \Rnd{1 - ...","release_manifest_digest":"sha256:1bf31ca8e016d6c15c2d1673aafdac22e2dab42596484738ae2c86d80c27c723","revision_digest":"sha256:af5fa7e318cf53859a5379b988ade0d02ec757798f4455ca99da8f0abcdbc518","source_id":"arxiv:2511.07350","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Theorem thm:codiff of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), for any $s, t \in \mathbb{R}$:
\begin{equation}

\tau\!\bigl(X^{(n)}_H(s),\, X^{(n)}_H(t)\bigr)
= \int_\mathbb{R}
\bigl[|f_n(s,u)|^\alpha + |f_n(t,u)|^\alpha
- |f_n(s,u) - f_n(t,u)|^\alpha\bigr]\,du.
\end{equation}

[Lemma 21 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $2< p<\infty$.
    Assume that $|F|\in L^{p-1}_{\loc}(\Omega_T)$ and that $u\in  L^{p-1}_{\loc}(0,T;W^{1,p-1}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$. Moreover, assume that there exist a parabolic cylinder $2Q=2\Qla=B_{2\rho}\times I_{2\rho}^\la \Subset\Omega_T$ and a constant $\gamma>1$ such that
\[
   \gamma^{-1}\la\le \biggl(\fiint_{2Q} (|\na u|+|F|)^{p-1}\, dz\biggr)^\frac{1}{p-1}\le \la.
\]
Then there exists a constant $c=c(n,p,L,\gamma)$ such that 
\begin{equation*}
    \begin{split}
        \frac{|u(x,t)-u(x,s)|}{|t-s|^\frac{1}{2}}
    &\le c  ( M^*((|\na u|+|F|)^{p-1} 1_{2Q})(x,t) \\
    &\qquad + M^*((|\na u|+|F|)^{p-1} 1_{2Q})(x,s)+1  )^\frac{p}{2(p-1)}
    \end{split}
\end{equation*}
for almost every $x\in B_\rho$ and $t,s\in I_\rho^\la$.

[Defi def:increasing_kernel of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] \begin{enumerate}
			\item Consider  $\mu, \nu \in \mathcal{P}(\mathbb{R})$ and $P \in \textnormal{Marg}(\mu,\nu).$ We say that $P$ has increasing kernels for the stochastic order if there exists a disintegration  $P(dx,dy) = \mu(dx)k_x(dy)$ and a Borel set $\Gamma$ such that $\mu(\Gamma)=1$ and  $k_x \leq_{st} k_y$ for every $x < y \in \Gamma^2$,
			\item Consider  $T \subset \mathbb{R}$  and $P \in \mathcal{P}\left(\mathbb{R}^{T}\right)$. We say that $P$ has increasing kernels for the stochastic order if, for every $s<t \in T^2$, $P^{s,t}$ has increasing kernels for the stochastic order.
		\end{enumerate}

[Lem 6 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Let $X\sim \Hyp(n_1,n,m)$ with $\mathbb EX=\frac{n_1m}{n}\geq 10$. There exists absolute constants $C,c$ such that for all $\delta<1/2$,
		\begin{equation} 
			\mathbb P(|X-\mathbb E X|\geq (\mathbb EX)^{1/2+\delta})\leq C\exp(-c(\mathbb EX)^{2\delta}).
		\end{equation}

[Definition def:ulip-uip of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] A logic $L$ with a language $\mathscr{L}$ is said to enjoy \emph{Uniform interpolation property (UIP)} if
  for any $\varphi \in \mathscr{L}$ and any finite $P \subseteq \mathord{\mathrm{PropVar}}$,
  there is $\chi \in \mathscr{L}$ such that:
  \begin{enumerate}
    \item $\mathrm{V}(\chi) \subseteq \mathrm{V}(\varphi) \setminus P$;
    \item $\varphi \to \chi \in L$;
    \item $\chi \to \psi \in L$ for any $\psi \in \mathscr{L}$ such that $\varphi \to \psi \in L$ and $\mathrm{V}(\psi) \cap P = \emptyset$.
  \end{enumerate}

[Lemma LEM:partition of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $ Q \in \mathbb{Z}$ with $Q>0$, $\delta_\varepsilon=\eta\sqrt{\varepsilon \log \frac 1\varepsilon}$, $d_\varepsilon=\big|\log (\varepsilon \log \frac 1\varepsilon)   \big|$, as in (equation LDPIN2 of the paper) and (equation LDPIN3 of the paper), and let $F$ be a bounded function. Then  
\begin{align*}
\int F(\phi) \rho_\varepsilon^Q(d\phi)
= \int_{   \{  \textup{dist}(\phi, \mathcal{M}_Q^{\varepsilon, \, \ge d_\varepsilon} ) <\delta_\varepsilon        \} } F(\phi) \rho_\varepsilon^Q(d\phi)+\textup{O}(e^{-c  \log \frac 1\varepsilon }).
\end{align*}

[Thm 13 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] For all $f\in C(\mathscr{C}^{1-\kappa};\R)$ with linear growth there exists a finite constant $C$ such that
    \begin{align*}
        \sup_T|W_T(f)|\leq C.
    \end{align*}

[Definition 6 (\cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] For a graph $F$ with $\chi(F)=r+1\geq 3$, define
	\begin{equation*}
		a(F):=\min\{|I|: I\subseteq V(F)\text{ is independent and }\chi(F-I)\le r\}.
	\end{equation*}
	If $a(F)=1$, the graph $F$ is called singleton-boundary.

[Theorem 7 of arXiv:2608.30561, '\Large Informative Label Missingness in Multiclass Classification: Information Geometry an'] Under the conditions above,
\begin{equation}
\Delta_R
=
\sum_{j=1}^{r}
w_j
\frac{\lambda_j-1}{\lambda_j}.

\end{equation}
Consequently, if
\(\mathcal{P}=\{j:\lambda_j>1\}\) and
\(\mathcal{N}=\{j:\lambda_j<1\}\), then
\(\Delta_R>0\) if and only if
\begin{equation}
\sum_{j\in\mathcal{P}}
w_j
