body:
[Theorem thm:eikm-completeness of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] \begin{equation*}
    \textbf{KI} = \set{ \varphi \in \mathscr{L}_{\Box\Diamond}; \forall \mathfrak{F} \in \FrameClass{\Box\text{-p}} \cap \FrameClass{\Diamond\text{-p}}\, (\mathfrak{F} \vDash^{\text{h}} \varphi) }.
  \end{equation*}
  \begin{proof}
    ($\subseteq$) It suffices to show that $\textsf{CD}$ is h-valid on any $\Box$-p and $\Diamond$-p frame.
    Take any $\Box$-p and $\Diamond$-p model $\mathfrak{M} = (W, \leq, \sqsubset, V)$ and any $x_0, x_1 \in W$
    such that $x_0 \leq x_1 \Vdash^{\text{h}} \Box (\varphi \lor \psi)$, then we shall show that $x_1 \Vdash^{\text{h}} \Diamond \varphi \lor \Box \psi$,
    that is, at least one of $x_1 \Vdash^{\text{h}} \Diamond \varphi$ or $x_1 \Vdash^{\text{h}} \Box \psi$ holds.
    Suppose $x_1 \not \Vdash^{\text{h}} \Box \psi$, then there are $x_2, y_2 \in W$ such that $x_1 \leq x_2 \sqsubset y_2 \not \Vdash^{\text{h}} \psi$.
    By the $\Box$-p condition, there is $y_1 \in W$ such that $x_1 \sqsubset y_1 \leq y_2$.
    Here, $y_2 \not \Vdash^{\text{h}} \psi$ implies $y_1 \not \Vdash^{\text{h}} \psi$ by persistency.
    Also, $x_1 \Vdash^{\text{h}} \Box (\varphi \lor \psi)$ and $x_1 \leq x_1 \sqsubset y_1$ imply $y_1 \Vdash^{\text{h}} \varphi \lor \psi$.
    So we have $x_1 \sqsubset y_1 \Vdash^{\text{h}} \varphi$. Therefore, $x_1 \Vdash^{\text{h}} \Diamond \varphi$ holds.

    ($\supseteq$) By Proposition (prop:canonical-model-is-dia-p of the paper) and Truth lemma,
    it suffices to show that $\mathfrak{M}_{\textbf{KI}}^*$ satisfies the $\Box$-p condition.
    Take any $x = (\Gamma_x, \Delta_x)$, $x' = (\Gamma_x', \Delta_x')$, and $y' = (\Gamma_y', \Delta_y')$ such that $x \leq^* x' \sqsubset^* y'$,
    then $\Gamma_x \subseteq \Gamma_x'$, $\Box^{-1} \Gamma_x \subseteq \Box^{-1} \Gamma_x' \subseteq \Gamma_y'$, and $\Diamond^{-1} \Delta_x' \subseteq \Delta_y'$.
    \begin{claim*}
      $(\Box^{-1} \Gamma_x, \Diamond^{-1} \Delta_x \cup \Delta_y')$ is $\textbf{KI}$-consistent.
      \begin{subproof}
        Suppose not, then there are finite $A \subseteq \Box^{-1} \Gamma_x$, $B \subseteq \Diamond^{-1} \Delta_x$, and $C \subseteq \Delta_y'$ such that
        $\textbf{KI} \vdash \bigwedge A \to \left( \bigvee B \lor \bigvee C\right)$. Then:
        \begin{center}
          \AxiomC{$\bigwedge A \to \left( \bigvee B \lor \bigvee C\right)$}
          \RightLabel{\scriptsize{$\textsf{M}_\Box$}}
          \UnaryInfC{$\Box \bigwedge A \to \Box \left( \bigvee B \lor \bigvee C \right)$}
          \RightLabel{\scriptsize{$\textsf{C}_\Box$}}
          \UnaryInfC{$\bigwedge \Box A \to \Box \left( \bigvee B \lor \bigvee C \right)$}
          \RightLabel{\scriptsize{$\textsf{CD}$}}
          \UnaryInfC{$\bigwedge \Box A \to \left( \Diamond \bigvee B \lor \Box \bigvee C \right)$}
          \RightLabel{\scriptsize{$\textsf{C}_\Diamond$}}
          \UnaryInfC{$\bigwedge \Box A \to \left( \bigvee \Diamond B \lor \Box \bigvee C \right)$}
          \DisplayProof
        \end{center}
        Then $\left(\bigvee \Diamond B \lor \Box \bigvee C\right) \in \Gamma_x$ by $\textbf{KI}$-consistency,
        then $\Box \bigvee C \in \Gamma_x$ by $\Diamond B \subseteq \Delta_x$ and Corollary (cor:saturation of the paper),
        then $\bigvee C \in \Box^{-1} \Gamma_x \subseteq \Box^{-1} \Gamma_x' \subseteq \Gamma_y'$,
        so there is at least one $\varphi \in C$ such that $\varphi \in \Gamma_y'$,
        which is a contradiction since $C \subseteq \Delta_y'$.
      \end{subproof}
    \end{claim*}
    Now that $(\Box^{-1} \Gamma_x, \Diamond^{-1} \Delta_x \cup \Delta_y')$ is $\textbf{KI}$-consistent,
    then by Lindenbaum lemma, there is $y = (\Gamma_y, \Delta_y) \in W_{\textbf{KI}}^*$ such that
    $\Box^{-1} \Gamma_x \subseteq \Gamma_y$ and $\Diamond^{-1} \Delta_x \cup \Delta_y' \subseteq \Delta_y$.
    It is clear that $x \sqsubset^* y$, so it suffices to show that $y \leq^* y'$.
