\item[(i)] For all $\delta > 0$
\begin{eqnarray*}
\lim_{\epsilon \rightarrow 0} \P\left(  \sup_{0\leq t \leq T} |X^\epsilon (t) - \mathcal{X} (t)| > \delta  \right)= 0. 	
\end{eqnarray*}
\item[(ii)] For $A\in \R$,  let define $\ Q^{\varepsilon}(A)=\P\left( Y^\varepsilon(.)^{-1}(A)\right)$. Then there exists a sub-sequence $Q^{\epsilon_n}$ which converges to $Q$  weakly in the Meyer-Zheng topology.
\end{description}

