[Proposition prp-existence-ep of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] For every $\epsilon\in(0,1)$, there	 exist a   weak martingale solutions to (equation ep_approx of the paper)--(equation eqn354865865 of the paper) with initial data $(u_0,\psi_0)$, which satisfies 
		\begin{equation}\mathrm{ess \, sup}_{t\in [0,T]}\biggl(
			 \frac{1}{2}\int_{\mathbb{T}^3}
			|u_{\epsilon,t}|^2 +\psi_{\epsilon,t}^2 \,\mathrm{d} x 	+ \epsilon \int_0^t \int_{\mathbb{T}^3} 
			|\Delta  u_{\epsilon}|^2
			+ |\Delta \psi_{\epsilon}|^2\,\mathrm{d} x\,\mathrm{d} s\,-\,\epsilon t\biggr) \,\le\, 
			\frac{1}{2}\int_{\mathbb{T}^3}
			|u_0|^2 +\psi_0^2 \,\mathrm{d} x,
		\end{equation}
		$\mathbb{P}$-almost surely, as well as 
		\begin{equation}
			\mathbb{E} \bigl[\| q_\epsilon \|_{ \mathcal{M}([0,T]\times \mathbb{T}^3) }\bigr]\,\le\, 	\biggl(1 \,+\, \frac{4F_2 +G_2 }{8}T \biggr)  \biggl(
			\frac{1}{2}\int_{\mathbb{T}^3}|u_0|^2 +|\psi_0|^2 \,\mathrm{d} x\,+\,2 \epsilon T
			\biggr)^{1/2}.
		\end{equation}

