body:
[Lemma lem:p_bound of arXiv:2605.05193, 'Grokability in five inequalities'] Define the explicit Nazarov main term
\begin{equation}
L(n,\rho):=\frac{1}{\sqrt{2\pi}}\frac{1}{\rho}\exp\!\Big(\frac{\rho^4}{4n}\Big)e^{-\rho^2/2}.
\end{equation}
Fix constants $a>0$ and $W>0$. Then there exist constants $C_{a,W}>0$ and
$n_0(a,W)$ such that for all $n\ge n_0(a,W)$, all $\rho=a n^{1/4}$, and all
$r=\sqrt{n-1}+w$ with $|w|\le W$, one has
\begin{equation}
p(r)\ \le\ L(n,\rho)\,\exp\!\Big(\frac{w\rho^2}{\sqrt{n}}\Big)\,
\exp\!\Big(\frac{C_{a,W}}{\sqrt{n}}\Big).
\end{equation}

[Lem 2 of arXiv:2609.00743, '$L_p$ Brunn-Minkowski inequality for the eigenvalue of generalized Monge-Ampère equation'] Let $u$ be a closed convex function on $\mathbb{R}^n$, and let $u^*$ denote its Legendre transform. Then
\begin{equation}
u(x)+u^{*}(\xi)\geq \xi\cdot x\quad \text{for all }x,\xi\in\mathbb{R}^n. 
\end{equation}
Moreover, the following three statements are equivalent:
\begin{itemize}
\item[(a)] $u(x)+u^{*}(\xi)=\xi\cdot x$;
\item[(b)] $\xi\in\partial u(x)$;
\item[(c)] $x\in\partial u^{*}(\xi)$.
\end{itemize}

[Lemma lemma_exponential_decay_with_gamma_n_upper of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] Let $\gamma:\mathbb{R}_+^* \to \mathbb{R}_+^*$ be a function such that $\lim_{\varepsilon \to 0^+}\gamma(\varepsilon)=\overline{\gamma}$. Then, for all $\mu_0 \in \mathcal{P}(\mathbb{Z})$,
\begin{align}
\limsup_{\varepsilon \to 0^+} \limsup \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P} \left( \ell_{2 \left \lceil \frac{\gamma(\varepsilon) n}{2} \right \rceil+1} \in B(\mu_0,\varepsilon) \right) & \leq -\overline{\gamma} I_{\textup{DV}}(\mu_0). 
\end{align}
In addition, for all $\varepsilon>0$, all $R \geq R_{\overline{\mathbb{Z}}}(\varepsilon)$ and all $\rho \in \{-,+\}$,
\begin{align}
\limsup \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P}_{\rho R}\left(\Omega_{2 \left \lceil \frac{\gamma(\varepsilon) n}{2} \right \rceil+1,\textup{exc}}^{\rho} \right) & \leq -\gamma(\varepsilon) I_{\textup{Cr}}^{p_{\rho}}(0) + \gamma(\varepsilon) g(\varepsilon), \\
\limsup \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P}_{\rho R}\left( \Omega_{2 \left \lceil \frac{\gamma(\varepsilon) n}{2} \right \rceil + 1,\textup{mea}}^{\rho} \right) & \leq - \gamma(\varepsilon) \inf_{\rho x \in [0,1]} I_{\textup{Cr}}^{p_{\rho}}(x) + \gamma(\varepsilon) g(\varepsilon), 
\end{align}
where $g$ is as in Proposition~(proposition_exponential_rate_of_decay_exc_and_end of the paper).

