[Thm theorem:Lp of arXiv:2504.19942, 'The edge-averaging process on graphs \\ with random initial opinions'] For every $p\in[1,\infty)$, there exists $C_p>0$ (depending only on $p$), such that if the i.i.d.\ initial opinions $\{f_0(v)\}_{v \in V}$ are in $L^p$, then for every $t>0$ and every $o\in V$,
\begin{equation}
\|f_t(o)-\mu\|_p\leq C _p\|f_0(o)-\mu\|_p \cdot
\begin{cases}
    t_*^{\frac{1-p}{2p}}&p\in [1,2),\\
    t_*^{-1/4}&p\geq 2,
\end{cases}
\end{equation}
where  $t_*:=\min(t,|V|^2)$. 
Moreover, if $V$ is infinite and  $p \in [1,2)$, then
$\|f_t(o)-\mu\|_p =o\big(t^{\frac{1-p}{2p}}\big)$ as $t \to \infty$. \newline (In particular $f_t(o) \to \mu$ in $L^1$ if $f_0(o) \in L^1$.) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition {{\cite[Definition~1.15 of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] {wom}}}]
	Let $\chi$ be a Dirichlet character modulo $N$. Then a modular form $f\in M_k(\Gamma_1(N))$ has Nebentypus character $\chi$ if
	\begin{align*}
		f\left(\dfrac{az+b}{cz+d}\right)=\chi(d)(cz+d)^kf(z),
	\end{align*} 
	for all $z\in \mathbb{H}$ and all $\begin{bmatrix}
		a & b \\
		c & d
	\end{bmatrix}\in\Gamma_0(N)$. We denote the space of such modular forms by $M_k(\Gamma_0(N),\chi)$.

