[Corollary cor:brown_sig_def of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] If $X$ is a time-augmented Brownian motion $X_t = \widehat{W}_t$, then $a^k_t \equiv {\color{NavyBlue}{\mathbf{k}}}$, so that $\mathbf{D}_s a^k_t \equiv 0$, and, for $\mathbb{P} \otimes ds \otimes dt\text{-almost every } (\omega, s, t) \in \Omega \times [0,T]^2$ with $s \leq t$,
    \begin{equation}
        \mathbf{D}_s^i \sig[t] = \sig[s] \otimes {\color{NavyBlue}{\mathbf{i}}} \otimes \sig[s, t].
    \end{equation}
    Moreover, $\sigW \in \mathbb{D}^{\infty, 2}$ for a.e. $t \in [0, T]$, and,  for $\mathbb{P} \otimes dt^{\otimes (n+1)}\text{-almost every } (\omega, s_1, \ldots, s_n, t) \in \Omega \times [0,T]^{n+1}$ with $s_1 \leq \ldots \leq s_n  \leq t$, we have
    \begin{equation}
        \mathbf{D}_{s_1}^{i_1} \cdots \mathbf{D}_{s_n}^{i_n} \sig[t]
        = \sig[s_1] \otimes {\color{NavyBlue}{\mathbf{i_1}}} \otimes \sig[s_1, s_2]
          \otimes {\color{NavyBlue}{\mathbf{i_2}}} \otimes \cdots \otimes {\color{NavyBlue}{\mathbf{i_n}}} \otimes \sig[s_n, t].
    \end{equation}

