[Definition 8 (Minimal primitive support) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $1\le s\le Q$, define
\begin{equation}
 \cS_s(F)
 =\ol{\Span}
 \left\{
 \Ran\mathscr L_{a,q,\bm m}^{(s)}:
 1\le a\le d,\ q\le Q,\ m_s\ge1
 \right\}\subset E_s.

\end{equation}
Put $\cS(F)=\bigoplus_{s\le Q}\cS_s(F)$.

[Corollary cor:ordered-generic-type-diversity of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For each fixed $k\geq3$, as $h\to\infty$, both the number of realized ordered
$h$-addition-table types and the number of realized generic $B_h$-types
are
\begin{equation}
 \Theta_k\!\left(h^{(k-1)(k-2)}\right).
\end{equation}

[Defi defi28 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] A real valued  adapted right continuous process with left limits $(V_t)_{t\in [0,\tau]}$ is called a bounded mean oscillation $(\operatorname{BMO})$ if 
				\begin{align*}
					[V]_{\operatorname{BMO}}:= \sup_{0\leq s\leq S\leq S'\leq \tau}\|\mathbb{E}[|V_{S'}-V_{S-}|/\mathfrak{F}_{ S}]\|_{\infty} <\infty,
				\end{align*}
				where the supremum is taken over all the stopping times $S,S'$; $V_{S-} =\lim_{r\uparrow S}V_r$ and we set $V_{0-} =V_0$, by convention.

[Lem control_Y of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] For small enough $\eta > 0$, for any $\varepsilon > 0$ and $a \geq 0$, we have
	\begin{align*}
	\Pp{ \exists u \in \mathcal{N}(t) : 
		R_u(t) \geq m(t)-a, \max_{s\in [t/2,t]} \mathopen{}\mathclose\bgroup\originalleft\lvert\theta_u(s)\aftergroup\egroup\originalright\rvert \leq \eta,
		\mathopen{}\mathclose\bgroup\originalleft\lvertY_u(t)\aftergroup\egroup\originalright\rvert \geq t^{\frac{\kappa}{2} +\varepsilon} }
	\xrightarrow[t\to\infty]{} 0.
	\end{align*}

[Definition 28 (Types of nodes) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Given a trajectory space $\Se$ and a node $(S,j)$:
	\begin{itemize}
		\item $(S,j)$ is called an \emph{up-down node} if
		\begin{equation} 
			\sup_{\tilde{S} \in \Se_{(S, j)}}~~ (\tilde{S}_{j+1} - S_{j}) >    0\quad \mbox{and}\quad
			\inf_{\tilde{S} \in \Se_{(S, j)}} ~~(\tilde{S}_{j+1} - S_{j}) <    0.
		\end{equation}
		\item $(S,j)$ is called a \emph{flat node} if
		\begin{equation} 
			\sup_{\tilde{S} \in \Se_{(S, j)}}~~ (\tilde{S}_{j+1} - S_{j}) =    0 =
			\inf_{\tilde{S} \in \Se_{(S, j)}} ~~(\tilde{S}_{j+1} - S_{j}).
		\end{equation}
	\end{itemize}
	\noindent $(S, j)$ is called an arbitrage-free node if (\ref{upDownProperty}) or (\ref{flat}) hold, otherwise it
	is called an \emph{arbitrage node}. An arbitrage node $(S, j)$ is said to be of \emph{type I}, if there exists $\hat{S}\in\Se_{(S, j)}$	such that $\hat{S}_{j+1} = S_j$; otherwise it is said to be of \emph{type II}.

[Lemma lem:brownian-ball-localization of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Assume $d<4$. For every $0<T<\infty$ there are $C=C(d)>0$ and $c=c(d)>0$
	such that, for every $A\geq1$ and every compact $K\subset\mathbb{R}^d$,
	\[
		\sup_{u\in K}
		\bigl(\mathcal U_Z(T,u)-\mathcal U_{Z,A}(T,u)\bigr)
		\leq
		Ce^{-cA^2/T}
		\sup_{\substack{z\in\mathbb{R}^d:\\ \inf_{y\in K}|z-y|\leq A}}
		\mathcal U_Z(T,z)\, .
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 43 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Assume (equation 42 of the paper) and define the law of a random field
\(Z^{Q,\pi}\) on \(\mathcal T\) by
\begin{equation}
  \Ehat{H(Z^{Q,\pi})}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \E*{
    \rho_\pi(Q^{[g]})^\alpha
    H\left(
      \frac{Q^{[g]}}{\rho_\pi(Q^{[g]})}
    \right)
  }, \qquad H \in \mathfrak H.

\end{equation}  On
\(\{\rho_\pi(Q^{[g]})=0\}\), the ratio in
(equation 44 of the paper) may be defined arbitrarily and the
corresponding summand is understood to be zero. If
\(\widehat{\mathbb P}_\pi\) stands for the resulting probability measure,
then:
\begin{enumerate}[(i)]
\item (equation 44 of the paper) is a probability law,
\[
  \rho_\pi(Z^{Q,\pi})=1
  \quad\text{almost surely},
  \qquad
  \Ehat{(Z_v^{Q,\pi})^\alpha}=1,
  \quad v\in\mathcal T;
\]
in particular, \(Z^{Q,\pi}\neq\mathbf 0\) almost surely;
\item \(Z^{Q,\pi}\) is almost surely \(\alpha\)-summable, i.e.,
\[
  \sum_{v\in\mathcal T}(Z_v^{Q,\pi})^\alpha<\infty;
\]
\item for every \(F\in\mathfrak H_\alpha\),
\begin{equation}
  \Ehat{F(Z^{Q,\pi})}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}\E{F(Q^{[g]})}.

\end{equation}
Consequently, \(Z^{Q,\pi}\) is branch-BR stationary, and its
homogeneous class does not depend on \(\pi\);
\item its tail measure is
\begin{equation}
  \nu_Q(A)
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \int_0^\infty
  \mathbb P\{rQ^{[g]}\in A,\ Q^{[g]}\neq\mathbf 0\}
  \alpha r^{-\alpha-1}\mathrm d r,
  \qquad A\in\mathcal B(\mathcal F),

\end{equation}
and satisfies
\begin{equation}
  \nu_Q\bigl((B^u)^{-1}A\bigr)
  =
  \nu_Q(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad u\in\mathcal T;

\end{equation}
\item the root spectral tail field \(\Theta^Q\) is independent of
\(\pi\) and satisfies
\begin{equation}
  \E{H(\Theta^Q)}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \E*{
    \mathbf 1_{\{Q_g>0\}}
    Q_g^\alpha
    H\left(
      \left(\frac{Q_{gv}}{Q_g}\right)_{v\in\mathcal T}
    \right)
  }, \qquad F\in\mathfrak H.

\end{equation}
The summand is understood to be zero on \(\{Q_g=0\}\). In particular, $
  \mathbb P\{\sum_{v\in\mathcal T}(\Theta_v^Q)^\alpha<\infty\}=1$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop cocycle_cber of arXiv:2608.06644, 'Applications of the cluster graphing'] The following holds:
    \begin{enumerate}
        \item The $\mathcal{G}^{\mathrm{cl}}$-component of $\pi({x}) = [(x,u)]_{\Gamma} \in Y$ is isomorphic to the cluster of $u$ in $\pi(x)$.
        \item 
        If $G$ is unimodular, then $\mathcal{G}^{\text{cl}}$ is pmp by [Gaboriau05], [CTT22]. 
        \begin{enumerate}
            \item More generally, if $G$ is a quasi-transitive graph, the equivalence relation $\mathcal{R}_{\mathcal{G}^{\mathrm{cl}}}$ is measure-class-preserving with respect to $\nu$, and the corresponding Radon-Nikodym cocycle is given by
\begin{equation*}
\Tilde{\mathbf{w}}^{[x,u]_\Gamma}([x,v]_\Gamma) = \mathbf{w}_\Gamma^u (v).
    \end{equation*}
    In other words, it is essentially induced by $\mathbf{w}_\Gamma$.
        \end{enumerate}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dyadic of arXiv:2606.11248, 'Persistent Homology of the Planar Wiener Sausage: Brownian Scaling and a Logarithmic Expec'] There exist deterministic constants $c_{0}>0$, $c_{1}>0$, and an almost surely finite random integer $n_{0}$ such that, almost surely, for every integer $n\ge n_{0}$,
\begin{equation}
\operatorname{card}\Bigl\{i\in\{n,\ldots,2n-1\}:\rho_{K_{1}}(A_{i})\ge\frac{c_{0}}{\sqrt{n}\,\log n}\Bigr\}\ge c_{1}n.
\end{equation}

