body:
[Coro normalizedsequence of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] Define the normalized sequence $\{\gamma_n\}_n$ by
    \begin{equation*}
        \gamma_n := \frac{n! \varepsilon_n}{(b-a)^n}
        =
        \mathbb{E}\mleft[\mleft(\frac{b-X}{b-a} \mright)^n \mright] \in [0,1], \qquad n \geq 0.
    \end{equation*}
    Then the following hold:
    \begin{coroitems}
        \item The sequence $\{\gamma_n\}_n$ is non-increasing and bounded in $[0,1]$, and satisfies $\gamma_n \searrow \mathbb{P}(X = a)$ as $n \to \infty$. 
        \item For all $\delta \in (a,b)$, 
        \[
            \gamma_n
            \leq \mathbb{P}(X \leq \delta) + \mleft(\frac{b- \delta}{b-a}\mright)^n, \qquad n \geq 0.
        \]
        \item If there exists $\delta > 0$ such that $\mathbb{P}(X \geq a + \delta) = 1$, then 
        \begin{equation}
            \varepsilon_n \leq \frac{(b-a-\delta)^n}{n!}, \qquad n \geq 0.
        \end{equation}
        \item If $\mathbb{P}(X = a) > 0$, then
        \begin{equation}
            \lim_{n \to \infty} \frac{(n+1)\varepsilon_{n+1}}{\varepsilon_n} = b-a.
        \end{equation}
    \end{coroitems}

