[Conjecture 38 (cf.\ {\cite[Conjecture 1.3) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS24}}] 
	Let $G=K_n$ be the complete graph with $n$ vertices and edge weights $\weight(e) = \exp(-\beta \omega_e)$, where $\omega_e$ are i.i.d.\ uniform on $[0,1]$. Then, with high probability with respect to the averaged law $\widehat{\P}$, we have that
	\begin{equation*}
	\diam \big( \cT^\omega_{n, \beta} \big) =
	\begin{dcases}
	n^{\frac{1}{2}+o(1)} & \beta \leq C n, \\
	n^{\frac{1}{2} - \frac{\gamma}{2}+o(1)} & \beta  = n^{1 + \gamma+o(1)}, \quad 0 < \gamma < \frac{1}{3}, \\
	n^{\frac{1}{3}+o(1)} & \beta \geq C n^{\frac{4}{3}}.
	\end{dcases}
	\end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 78 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $E$ be another Banach space, and let $\varphi \in L(E,W)$ be arbitrary. Setting
\begin{align*}
L(V,E) \to L(V,W), \quad S \mapsto \varphi S,
\end{align*}
we may regard $\varphi$ as an element from $L(L(V,E),L(V,W))$. Furthermore, we have
\begin{align*}
| \varphi |_{L(L(V,E),L(V,W))} \leq | \varphi |_{L(E,W)}.
\end{align*}

