[Corollary cross-limit of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] It holds
\begin{equation*}
L^{\ast }(x)<x\ (x<c^{\ast }),\qquad L^{\ast }(x)>x\ (x>c^{\ast }).
\end{equation*}

as well as 
\begin{equation*}
T^{\ast }(x)>x\ (x<c^{\ast }),\qquad T^{\ast }(x)<x\ (x>c^{\ast }).
\end{equation*}

[Lemma lem: lemma on typical and odd particles of arXiv:2607.20097, 'Phase transition for the asymptotic entropy of branching random walks on groups'] The following limits exist for every $\delta,K>0$ almost surely
\begin{align*}
W^{\text{typ}}:= W_{\delta,K}^{\text{typ}}:=\lim_{n\to\infty}\frac{\#\mathsf{Typ}_n}{\rho^n},&&W^{\text{odd}} := W_{\delta,K}^{\text{odd}} := \lim_{n\to\infty}\frac{\#\mathsf{Odd}_n}{\rho^n}.
\end{align*}
Moreover, for the limit $W$ of the population martingale $W_n=Z_n/\rho^n$ it holds $W = W^{\text{typ}}+W^{\text{odd}}$,
and also the following limits hold almost surely
\begin{align*}
\lim_{K\to\infty} W_{\delta,K}^{\text{typ}} = W,& &\lim_{K\to\infty} W_{\delta,K}^{\text{odd}} = 0. 
\end{align*}

[Lemma 28 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Let $\alpha>0$, $u\in \CC$ with $\re(u)>-\alpha$,  and $\tilde v<\re(u)$ such that $ |\tilde v|<\alpha$.
  For  $\re(u)>t_1>t_2>\dots>t_k> |\tilde v|$, with $t_{k+1}=0$, denote
\begin{multline}
    \II_{t_1,\dots,t_k}(u,\tilde v) = \tfrac{1}{(2\pi)^k \Gamma(u+\tilde v)\prod_{j=1}^k \Gamma(2t_j-2t_{j+1})}
\\ \cdot  \int_{(0,\infty)^{k}}
\prod_{j=1}^{k-1}
\left|
\Gamma(t_j-t_{j+1}+\i y_j+\i y_{j+1})
\Gamma(t_j-t_{j+1}+\i y_j-\i y_{j+1})
\right|^2
\\ \cdot  \left(
\prod_{j=1}^k
\tfrac{|\Gamma(\alpha+t_j+\i y_j)|^2}
     {|\Gamma(2\i y_j)|^2}
\right)
\left|\Gamma(t_k+\tilde v+\i y_k)\right|^2 \left|\Gamma(t_k-\tilde v+\i y_k)\right|^2
\\ \cdot
\Gamma(u-t_1+\i y_1)\,\Gamma(u-t_1-\i y_1)
\,\d y .
\end{multline}

Then
\begin{equation}
    \GGG_{t_1,\dots,t_k}(u,\tilde v) = \II_{t_1,\dots,t_k}(u,\tilde v).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 11 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $F=\{F_t=(I_p(f_t^1),\ldots,I_p(f_t^m))\,,\;t\in \R_+\}$ be an $\R^m$-valued chaos process on an abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$, satisfying hypothesis $\mathbf{(H_2)}$, and assume that the coefficients $(b_k)_{1 \leq k \leq d}$ and $(\sigma_{k,\ell})_{1 \leq k \leq d,\, 1 \leq \ell \leq m}$ of the stochastic differential equation \eqref{eq:SDEsDrivenF} satisfy hypothesis $\mathbf{(H_1)}$.
Then, for every $h\in\HHH$, almost every $\omega\in\Omega$, every $t\in [0,T]$ and every $1 \leq k \leq d$, the map $\Gamma_{h,t}^{k}(\star,\omega)$ is differentiable on $\R$, with derivative given, for every $\varepsilon \in \R$, by
	\begin{equation}
		\frac{d}{d\varepsilon}\Gamma_{h,t}^{k} (\varepsilon,\omega)= \mathcal{D} \Psi_t^k(S_{\star, \varepsilon}^{h}(\omega))\left[\frac{d}{d \varepsilon} S_{\star, \varepsilon}^{h}(\omega)\right].
	\end{equation}
In particular, for $\varepsilon=0$, we get
	\begin{equation}
		\left.\frac{d}{d\varepsilon}\Gamma_{h,t}^{k} (\varepsilon,\omega)\right|_{\varepsilon=0}= \mathcal{D} \Psi_t^k(F_\star(\omega))\left[\langle D F_\star(\omega), h\rangle_{\HHH}\right].
	\end{equation}

