[Lemma 3 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mathcal{K}$, $\mathcal{Q}$, and $\mathcal{R}$ be such that $A\cap B\in \mathcal{R}$ for every $A\in \mathcal{K}$ and $B\in \mathcal{Q}$.
  \begin{enumerate}
  \item [(i)] $A\cap B\in \sigma(\mathcal{R})$ for every $A\in \sigma(\mathcal{K})$ and $B\in \sigma(\mathcal{Q})$.
  \item [(ii)] Let $A\in \sigma(\mathcal{K})$, $B\in \sigma(\mathcal{Q})$, and $A\subset B$. Then $A\in \sigma(\mathcal{R})$.
  \item [(iii)] $\sigma(\mathcal{K})\cap \sigma(\mathcal{Q})\subset\sigma(\mathcal{R})$.
  \end{enumerate}

