[Corollary 8 (Directional tails) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] If \(C_X(t)<\infty\), then for every \(x\geq0\),
\begin{equation}
 \Pp\left\{\ip{t}{X}\geq
 \sqrt{2V_X(t)x}+C_X(t)x\right\}\leq\e^{-x}.
\end{equation}

[Corollary 31 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Fix $m\in \N$ and a measurable, non-increasing function $\Omega:\R_+\to\R_+$. For $i=1,\dots,m$, let $c_i>0$. Suppose $f_1,\dots,f_{m+1}:\R^n\to\R_+$ are measurable, even functions that satisfy
    $$\left(\prod_{i=1}^{m}f_i(a_i)\right)\cdot f_{m+1}(v) \leq \Omega^{m+1}\left(\sum_{i=1}^mc_i|\langle a_i,v\rangle|\right) \quad \text{for all } a_1,\dots,a_m,v\in \R^n.$$ 
    Then, we have
    \begin{equation}
  \begin{split}
    &\prod_{i=1}^m\left(\int_{\R^n}f_i(x)dx\right)\Bigg(\int_{\R^n} f_{m+1}(v)^\frac{1}{m}dv\Bigg)^m
    \\
    &\leq \left(\int_{\R^n}\cdots\int_{\R^n}\Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m c_i|\langle a_i, \xi \rangle|\right)^{m+1}\right)da_1\cdots da_m\right)\left(\int_{\R^n}\Omega\left(|v|^\frac{m+1}{m}\right)dv\right)^{m}.
\end{split}
    \end{equation}
    When $\Omega$ is log-concave and integrable over $\R_+$, equality holds when there exists $C>0$ such that $$\prod_{i=1}^mf_i(a_i) = C\cdot \Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m c_i|\langle a_i, \xi \rangle|\right)^{m+1}\right) \text{ and }f_{m+1} = \frac{1}{C} \cdot \Omega\left( |\cdot|^{\frac{m+1}{m}}\right)^m.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:harris0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Suppose $\alpha =0$, let $T_A=\inf\{t\geq 0: \Lambda_t^0\ge A\}$. Consider a function $r:\mathbb N\cup\{0\} \to \mathbb R$ that does not change sign and satisfies

\begin{equation} 
\begin{split}
  \varphi_{n+1}(r(n+1))> 1, \quad \forall n\geq 0, \quad \mbox{if } r(0)>0;\\
  \varphi_{n+1}(r(n+1))< 1, \quad \forall n\geq 0, \quad \mbox{if } r(0)<0.
\end{split}

\end{equation}
where $\varphi$ is as in (equation e:defphi of the paper). Then, $\mathbb E^x[T_A]<\infty$ if both the following conditions hold:
\begin{enumerate} \setlength{\itemsep}{0.75em}
  \item $\sup_n \varphi_n(r(n))<\infty$ and $\sup_n r(n)<\infty$, and
  \item $\inf_{n\geq 1}|\varphi_n(r(n))-1|>0$.
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 (Three spread bounds) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $p \in (0,1)$, $\nu > 0$, and suppose $Y_{p,\nu} \in \SG(1,a)$. Then
\begin{align}
    \nu &\le \frac{1}{\sqrt{p(1-p)}},
    \\
    (1-p)\,\nu &\le a\ell + \sqrt{2\ell}.

\end{align}
For $p < 1/2$ one also has the quadratic bound
\begin{align}
    \nu \le a\beta_p + \sqrt{a^2\beta_p^2 + \frac{2\beta_p}{1 - 2p}}.

\end{align}
At $p = 1/2$ the last expression is interpreted by continuity, via \eqref{eqn:lhopital}, where it equals $2$; the bound holds there as well, reducing to \eqref{eqn:sgvariance}.

