[Prop lem-uppboundJ_W of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $M,R\in(1,\infty)$ and any odd $m\in\mathbb{N}$. Recall $\mathfrak p_{W_{R},M}$  defined in (equation pMdef of the paper). The constants $C$ and $C_{M,\mathfrak r,T}$ stem from Lemma~(lem-lowerboundlogpint of the paper), while $C_M$ appears first in Lemma~(lem-UpperLDPbound of the paper). Then the following hold.

\begin{enumerate} 
\item For any $\xi\in{\mathcal M }_1({\mathcal L }_{W_{mR}}^{{{\scriptscriptstyle{({M}})}}}\times{\mathcal S }^{{{\scriptscriptstyle{({M}})}}}_{W_{mR}})$ such that $\psi=\partial \Pi_{W_{mR}}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)$ is $W_{mR}$-admissible,
\begin{equation}
J_{W_R;M}(f_{m,R}(\xi))
 \leq J_{W_{mR};M}(\xi)+ \frac {C_M}{(mR)^{d/2}}-\frac 1{|W_{mR}|}\langle\psi,\mathfrak p_{W_{mR},M}\rangle,
\end{equation}
and, for any $x\in \mathbb{R}^d$ such that $x+W_R\subset W_{mR}$,
\begin{equation}
J_{W_R;M}(\theta_x(\Pi_{x+W_R}(\xi)))\leq J_{W_{mR};M}(\xi)+ \frac {C_M}{(mR)^{d/2}}-\frac 1{|W_{mR}|}\langle\psi,\mathfrak p_{W_{mR},M}\rangle.
\end{equation}
where $J_{W;M}$ is defined in (equation JWMTdef of the paper) with all other parameters $K,L,T,\vartheta$ equal to $\infty$. 

\item For any  $P\in {\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }^{{{\scriptscriptstyle{({M}})}}}\times {\mathcal S }^{{{\scriptscriptstyle{({M}})}}})$ such that  $P$ is $W_{mR}$-ergodic and $\Pi^{{{\scriptscriptstyle{({\mathcal S }})}}}_{W_R}(P)$ is concentrated on $A^{{{\scriptscriptstyle{({\mathcal S }})}}}_{W_R;M,\mathfrak r, T}\cap{\mathcal S }_{W_R}^{{{\scriptscriptstyle{({\vartheta, S}})}}}$,
\begin{equation}
\begin{aligned}
J_{W_R;M}(\Pi_{W_R}(P))&\leq J_{W_{mR};M}(\Pi_{W_{mR}}(P))+ \frac {C_M}{(mR)^{d/2}}+\Big[\frac {C_{M,\mathfrak r,T}}{mR}+\frac{C\vartheta^2}S\Big]\langle P,\mathfrak N_U^{\ssup\ell}\rangle.
\end{aligned}
\end{equation}

\item For any  $P,P_1,P_2,\dots\in {\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }\times {\mathcal S })$ such that $P_n$ converges weakly to $P$, we have $J_{W_R}(\Pi_{W_R}(P))\leq \liminf_{n\to\infty} J_{W_{R_n}}(\Pi_{W_{R_n}}(P_n))$  for any sequence $R_n\downarrow R$.

\item For any $\xi\in{\mathcal M }_1({\mathcal L }^{{{\scriptscriptstyle{({M}})}}}_{W_{R}}\times{\mathcal S }^{{{\scriptscriptstyle{({M}})}}}_{W_{R}})$ such that $\psi=\partial \Pi_{W_{R}}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)$ is $W_{R}$-admissible,  and for  any $k\in\mathbb{N}$,
\begin{equation}
\begin{aligned}
J_{W_R;M}(\xi)&\geq  \inf\big\{J_{3^k W_{R};M}(\xi^{{{\scriptscriptstyle{({k}})}}})\colon \xi^{{{\scriptscriptstyle{({k}})}}}\in \widetilde{\mathcal M }_1^{{{\scriptscriptstyle{({k}})}}},\Pi_{3^k W_R\to W_R}(\xi^{{{\scriptscriptstyle{({k}})}}})=\xi\big\}
 -\frac {C_M}{R^{d/2}}+\frac 1{|W_{R}|}\langle\psi,\mathfrak p_{W_{R},M}\rangle.
\end{aligned}
\end{equation}
\end{enumerate}

