[Lemma lem-decomp-qtf of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] There is a constant $C$ such that a sample from $M_W^f$ can be obtained by conformally welding a tuple $(\mathcal{D}_1, \mathcal{D}_2, \mathcal{D}_3, \mathcal T)$ sampled from 
		\begin{equation}
		\begin{split}
			C \int 1_{\ell_1 + \ell + \ell_3 > r + r_2} \Big(&\mathcal M^\mathrm{f.d.}_{0,2}(W; \ell_1+\ell+\ell_3 - r - r_2, \ell_1) \times \mathcal  M_{0,2}^\mathrm{f.d.}(W; \cdot, r_2) \\ &\times \mathcal M_{0,2}^\mathrm{f.d.}(\gamma^2-2; \ell_3, \cdot) \times \mathrm{QT}^f(\gamma^2-W,\gamma^2-W,\gamma^2-2; r, \ell)\Big),
		\end{split}
		\end{equation}
		where in~(equation eq-decomp-qtf of the paper) we integrate over $(\ell_1, \ell, \ell_3, r, r_2) \in (0,\infty)^5$ with respect to Lebesgue measure. 


		Moreover, for a sample from $M_W^f$, under the embedding of $\tilde \mathcal{D}$ as $(\mathbb{H}, \phi, \eta, i, \infty)$, let $\tau$ be the time that $\eta$ disconnects $i$ from $\partial \mathbb{H}$, let $G \subset \mathbb{H}$ be the connected component of $\mathbb{H} \backslash \eta$ such that $\eta(\tau) \in \overline G$ and $\overline G \cap \partial \mathbb{H}\neq \emptyset$, and let $[x_2, x_3] = \overline G \cap \partial \mathbb{H}$. Let $E$ be the event that $\eta$ hits $x_2$ before hitting $x_3$. Then a sample from $1_E M_W^f$ can be obtained from conformally welding $(\mathcal{D}_1, \mathcal{D}_2, \mathcal{D}_3, \mathcal T)$ sampled from~(equation eq-decomp-qtf of the paper) but with the integrand containing the additional factor $1_{\ell_3 > r_2}$.

[Theorem thm: enhancement converge of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Almost surely for every $(\varphi_1,\varphi_2) \sim \nu^0\otimes \nu^0$, there exist a random variable
\begin{equation}
	\Xi^\partial_\infty(\varphi_1,\varphi_2)\in \boldsymbol{\mathfrak B} 
\end{equation}
called the \emph{limiting enhanced boundary field} such that the following holds.
\begin{enumerate}
\item[\textup{(I)}] {\rm \bf (Almost sure convergence)} Almost surely in $(\varphi_1,\varphi_2) \sim \nu^0\otimes \nu^0$, we have the following convergnce in the Banach space $\boldsymbol{\mathfrak B}$: 
\begin{equation}
\lim_{T \rightarrow \infty} \Xi^\partial_T(\rho_T \ast \varphi_1, \rho_T \ast \varphi_2) =\Xi^\partial_\infty(\varphi_1,\varphi_2)
\end{equation}
\item[\textup{(II)}] { \rm  \bf (Distributional convergence)} Almost surely in $\varphi \sim \nu^0$, we have the following convergence in law:
\begin{equation}
	\big( \Xi^\partial_T(\rho_T \ast \varphi, \cdot) \big) _* \nu^0_T\rightharpoonup \big( \Xi^\partial_\infty(\varphi, \cdot) \big)_* \nu^0.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary Cor:length of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] For each $\varepsilon>0$, there exists constants $A,B$ depending on $\varepsilon$ such that for all $n\ge 1$ and $v$:
\[
\mathchoice
{\mathbb P \left( \rule{0pt}{11pt} |\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon) \right)}
{\mathbb P \left(|\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon)\right)}
{\mathbb P \left(|\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon)\right)}
{\mathbb P \left(|\gamma^n(v)|\ge n (\Lambda(v)+1+\varepsilon)\right)}
\le A \exp(-Bn). 
\]

[Lemma lem:perc_triangle of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 15$.
For any $\gamma > 0$, there is a $\delta = \delta(\gamma) \in (0,\delta_1)$ such that for $p \in [p_c - \delta, p_c)$ and $\mu \in \Omega_p$,
\begin{equation}
\begin{aligned}

{\sf T}^{(\mu)}(p) &\le 2 {\sf T}^{(0)}(p_c) + \gamma , \\
\tilde{\sf T}^{(\mu)}(p) &\le 2 \tilde {\sf T}^{(0)}(p_c) + \gamma , \\
{\sf B}^{(2\mu)}(p) &\le {\sf B}^{(0)}(p_c) + \gamma .
\end{aligned}
\end{equation}

[Proposition 49 of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Define a mapping $\ki \colon [0,\infty) \to \bR_+\times \bR$ by 
\begin{equation}
\ki:=\varrho\circ \kappa\circ \eta.
\end{equation}

(i) The range of $\ki$ is the gasket $\rK$.

(ii) The jump times of the process $\ki$  coincide with those of $\eta$.

(iii) For a jump time $\ell$ of $\eta$, if $\cT$ is the spindle associated through \eqref{eq:bijection subor spindles}, we have
\begin{equation}
        (\eta_{\ell-},\eta_{\ell})=(A_{s_{\cT}},A_{t_{\cT}}),\;(\ki_{\ell-},\ki_{\ell})=(\varrho_{s_{\cT}},\varrho_{t_{\cT}}). 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 5 of arXiv:2607.22374, 'Asymptotic properties of the heat equation driven by stochastic measure'] Let Assumptions A\ref{assxu} -- A\ref{assxm} hold, $u^L$ is the solution to~\eqref{eq:bemfgl}, $u$ is the solution to~\eqref{eq:bemfg}. Then, for each $\delta>0$ there exist versions of $u^L, u$ such that for all $\omega\in\Omega$ for each $x\in D_L$, $L=i\delta$, $i\in\zz_+$, $0<t\le T$, for any $0<\lambda<\frac{1}{4}$ holds
\begin{equation}
|u^L(t,x)-u(t,x)|\le  C_{\delta}(\omega) C_\lambda  e^{-\frac{\lambda (L-|x|)^2}{t}} .
\end{equation}

