body:
[Lemma lem:spde of arXiv:2604.20094, 'Persistence and local extinction for superprocesses in random environments'] Let \(T>0\). Under {\bf Assumption} (aspt:1 of the paper),
	the following hold true.
	\begin{enumerate}[(i)]
		\item  Equation (equation eq:spde1 of the paper) has a unique solution $u \in   L^2(\Omega; C([0,T]; L^2))\bigcap L^2([0,T]\times \Omega; H^1)$, and
		\begin{equation*}
			{\mathbf E}  \Big[  \sup_{0\leqslant t\leqslant T}\|u(t)\|_2^2 \Big] +{\mathbf E}  \int_0^T\|u(t)\|_{H^1}^2dt\leqslant C \left(1+\|f\|_2^2+{\mathbf E}  \int_0^T \|k(t)\|_2^2 \mathrm{d} t\right),
		\end{equation*}
		where $C$ only depends on $\lambda$ and $T$.

		\item Assume that $b$ and $\sigma$ in additionally satisfy
		\begin{align}
			rb(t,x,r)+|\sigma (t,x,r)|^2\leqslant \lambda r^2,
		\end{align}
		and that $f\in L^p$ and ${\mathbf E}\int_0^T \|k(t)\|_p^p \mathrm{d} t <\infty$ for some $p\geqslant 2$. Then
		\begin{equation}
			{\mathbf E}  \Big[  \sup_{0\leqslant t\leqslant T}\|u(t)\|_p^p \Big] +{\mathbf E}  \int_0^T\|\nabla u(t)\|_{p}^p \mathrm{d} t\leqslant C \left(\|f\|_p^p+{\mathbf E}  \int_0^T \|k(t)\|_p^p \mathrm{d} t\right).
		\end{equation}

		\item Assume in additionally that $b(t,x,0)\geqslant 0$ and $\sigma(t,x,0) =0$, and that $f\geqslant 0$ and $k\geqslant 0$. Then
		\begin{equation}
			{\mathbf P} \left( \hbox{for a.e. } x\in {\mathbb R}^d,  ~ u(t,x)\geqslant 0 \hbox{ for every  } t\in [0,T] \right)  =1.
		\end{equation}
	\end{enumerate}

