body:
[Corollary cor:BBMD of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega\subset \mathbb{G}$ be a bounded domain with smooth boundary with no characteristic points. Then, 
    \begin{align*}
    \lim_{\alpha\nearrow 1} (1-\alpha) \operatorname{Per}^{(\alpha)}_\mathcal{H}(\Omega)=\frac{1}{\pi}\operatorname{Per}_\mathcal{H}(\Omega).
    \end{align*}
    Also, for any measurable set $\Omega$ with $\operatorname{Vol}(\Omega)<\infty$ and $\operatorname{Per}_{\mathcal{H}}(\Omega)<\infty$,
    \begin{align*}
    \lim_{\alpha\searrow 0} \operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega)=\operatorname{Vol}(\Omega).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 65 (Fixed-weight capture and global harmonic budget) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] At the $j$-th split of weight $s$, with the separated cluster \eqref{all:eq:5.7a},
\begin{equation}
 \lambda_{\max}(E_s^{[j]})\ge\frac{\widehat{\mathfrak H}_s^{[j]}}{d},
 \qquad
 \sum_a\norm{P_{V_{s,j}}r_{a,s}^{[j]}}^2
 \ge\frac{\widehat{\mathfrak H}_s^{[j]}}{dsR^2}.

\end{equation}
Hence
\begin{equation}
 \boxed{\kappa_{s,d}^{\triangle}=\frac1{ds}.}

\end{equation}
For the successive promotions at all weights,
\begin{equation}
 \boxed{
 \sum_{s\ge1}\sum_{j\ge0}
 \frac{\widehat{\mathfrak H}_s^{[j]}}{s}
 \le dR^4.}

\end{equation}
At one fixed $s$,
\begin{equation}
 \sum_{j\ge0}\widehat{\mathfrak H}_s^{[j]}
 \le dsR^2\sum_a\norm{r_{a,s}^{[0]}}^2.

\end{equation}

[Definition 3 (Stochastic maximal regularity) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $p\in [2,\infty), \kappa\in [0,p/2-1)\cup\{0\}$.
    \begin{enumerate}
        \item We write $A\in \mathcal{SMR}_{p,\kappa}$ if for all $T\in (0,\infty)$ there exists a constant $C_T\ge 0$ such that for all $a\in [0,T]$, every stopping time $\tau\colon\Omega\to [a,T]$ and every progressively measurable $f\in L^p(\Omega;L^p(a,\tau,w_\kappa^a;X_0))$ and $g\in L^p(\Omega;L^p(a,\tau,w_\kappa^a;\gamma(\ell^2,X_{1/2})))$ there exists a strong solution $u$ to~\eqref{eq:linear-stochastic-evolution} with $u_a=0$ that is unique in $L^p(\Omega;L^p(a,\tau,w_\kappa^a;X_1))$ and satisfies
        \begin{equation}
            \nrm{u}_{L^p(\Omega;L^p(a,\tau,w_\kappa^a;X_1))}\le C_T\nrm{f}_{L^p(\Omega;L^p(a,\tau,w_\kappa^a;X_0))}+C_T\nrm{g}_{L^p(\Omega;L^p(a,\tau,w_\kappa^a;\gamma(\ell^2,X_{1/2})))}.
        \end{equation}
        \item For $p\in(2,\infty)$ and $ \kappa\in [0,p/2-1)$, we write $A\in \mathcal{SMR}_{p,\kappa}^\bullet$ if $A\in \mathcal{SMR}_{p,\kappa}$ and for all $\theta\in(0,1/2)$ and $T\in (0,\infty)$ there exists a constant $C_{T,\theta}\ge 0$ such that for all $[a,b]\seq[0,T]$, for every progressively measurable $f\in L^p(\Omega;L^p(a,b,w_\kappa^a;X_0))$ and $g\in L^p(\Omega;L^p(a,b,w_\kappa^a;\gamma(\ell^2,X_{1/2})))$ the strong solution $u$ to~\eqref{eq:linear-stochastic-evolution} with $u_a=0$ on $[a,b]$ satisfies
        \begin{equation}
            \nrm{u}_{L^p(\Omega;H^{\theta,p}(a,b,w_\kappa^a;X_{1-\theta}))}\le C_{T,\theta}\nrm{f}_{L^p(\Omega;L^p(a,b,w_\kappa^a;X_0))}+C_{T,\theta}\nrm{g}_{L^p(\Omega;L^p(a,b,w_\kappa^a;\gamma(\ell^2,X_{1/2})))}.
        \end{equation}
        \item For $p=2$ and $\kappa=0$, we write $A\in \mathcal{SMR}_{2,0}^\bullet$ if $A\in \mathcal{SMR}_{2,0}$ and for all $T\in (0,\infty)$ there exists a constant $C_T\ge 0$ such that for all $[a,b]\seq [0,T]$, every progressively measurable $f\in L^2(\Omega\times(a,b);X_0)$ and $g\in L^2(\Omega\times(a,b);\gamma(\ell^2,X_{1/2}))$, the strong solution to~\eqref{eq:linear-stochastic-evolution} with $u_a=0$ on $[a,b]$ satisfies
        \begin{equation}
            \nrm{u}_{L^2(\Omega;C([a,b];X_{1/2}))}\le C_T\nrm{f}_{L^2(\Omega;L^2(a,b;X_0))}+C_T\nrm{g}_{L^2(\Omega;L^2(a,b;\gamma(\ell^2,X_{1/2})))}.
        \end{equation}
    \end{enumerate}

[Theorem 3 of arXiv:2506.13913, '2506.13913'] {Existence of Brownian motion}{exis-BM}
There exists a probability space \((\Omega, \mathcal{F}, \mathbb{P})\) and a stochastic process \(\{W_t\}_{t \geq 0}\) on \(\Omega\) such that the finite-dimensional distributions 
of \(W_t\) are given by
\begin{equation}
\mathbb{P}(W_{t_1} \in F_1, \cdots, W_{t_k} \in F_k) =
\int_{F_1 \times \cdots \times F_k} p(t_1, x, x_1) \cdots p(t_k - t_{k-1}, x_{k-1}, x_k) \, dx_1 \cdots dx_k,
\end{equation}
where \(F_1, \cdots, F_k\) denote Borel sets in \(\mathbb{R}\) and \(k \in \mathbb{N}\).

[Lemma Lipschitz Bound of arXiv:2411.09260, 'The Hydrodynamic Limit of Hawkes Processes on Adaptive Stochastic Networks'] For any $c \in \Gamma_E$ any $\theta \in \mathcal{E}$, any $z , y \in \mathcal{D}([0,T] , \Gamma)$, there exists a unique $ \lbrace j_{\theta,\eta} \rbrace_{\theta,\eta \in \mathcal{E}}  \in   \mathcal{D}([0,T] , \mathcal{P}( \Gamma_E) ) $, written $ j_{\theta\eta} := (j_{\theta\eta,t})_{t\leq T}$ such that for all $t\leq T$, and all $a \in \Gamma_E$,
\begin{align}
j_{\theta\eta,t}(a) = v_{\theta\eta}(z_0, y_0,a)+ \sum_{b \in \Gamma_E : b \neq a} \int_0^t \bigg\lbrace j_{\theta\eta,s}(b) l_{b\mapsto a}(z_s , y_s)   - j_{\theta\eta,s}(a)    l_{a\mapsto b}(z_s , y_s)  \bigg\rbrace ds
\end{align}
We write
\begin{align}
\Psi_{\theta \eta , t} &:  \mathcal{D}([0,t] , \Gamma)^2 \mapsto \mathcal{D}\big([0,t] , \mathcal{P}( \Gamma_E) \big) \\
\Psi_{\theta \eta,t}(  z , y) &:=   j_{\theta\eta}.
\end{align}
Furthermore for each $T > 0$, there exists a constant $C_T$ such that for all $t\leq T$,
\begin{align}
\sup_{\theta,\eta\in \mathcal{E}} \norm{ \Psi_{\theta \eta,t}(  z , x) -  \Psi_{\theta \eta,t}(  \tilde{z} , \tilde{x}) } \leq C_T \big( \norm{z - \tilde{z}}_t + \norm{x - \tilde{x}}_t \big). 
\end{align}

