[Lemma lem:characteristic function W of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] The characteristic function of the risk process $W$ is given by
\begin{align}
\mathbb{E}\SBRA{{\mathrm e}^{i\alpha\, W(t)}}&=\mathbb{E}\SBRA{\exp\left({\varphi_X(\alpha )\int_0^tI(s)\,{\mathrm d} s+\varphi_Y(\alpha )\int_0^t(N-I(s))\,{\mathrm d} s}\right)} \notag\\
&={\mathrm e}^{\varphi_Y(\alpha)Nt}\,\mathbb{E}\SBRA{\exp\left({ {{\left(\varphi_X(\alpha )-\varphi_Y(\alpha)\right)}}\int_0^tI(s)\,{\mathrm d} s}\right)}. 
\end{align}

[Definition 2 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For a fixed $\mu \in \eP(T)$, the {\em Shannon rate-distortion function} is defined as
\begin{align}
	R_\mu(\epsilon)& \deq \inf_{(\tau,\tau'): \, P_\tau = \mu} \left \{ I(\tau;\tau') : \Ex d^2(\tau,\tau') \le \epsilon \right\},
\end{align}
where the infimum is over random elements $(\tau,\tau')$ of $T \times T$ such that $P_\tau = \mu$.

[Definition 22 (Standard $\gfour$-Null forms) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\varphi$ and $\widetilde{\varphi}$ be scalar functions.
We define
 $\nullform_{(\gfour)}(\partial\varphi,\partial\widetilde{\varphi})$ to be the following 
derivative-quadratic term:
\begin{subequations}
\begin{align}
\nullform_{(\gfour)}(\partial \varphi,\partial \widetilde{\varphi})
& \eqdef 
(\gfour^{-1})^{\alpha \beta} 
\partial_{\alpha} \varphi \partial_{\beta} \widetilde{\varphi}.
\end{align}For $0 \leq \alpha < \beta \leq 3$, 
we define $\nullform_{(\alpha \beta)}(\partial \varphi,\partial\widetilde{\varphi})$
to be the following derivative-quadratic term:
\begin{align}
\nullform_{(\alpha \beta)}(\partial\varphi,\partial\widetilde{\varphi})
& \eqdef 	\partial_{\alpha} \varphi \partial_{\beta} \widetilde{\varphi} 
			- 
			\partial_{\beta} \varphi \partial_{\alpha} \widetilde{\varphi}.
\end{align}
\end{subequations}

[Lemma lem:Gaussian_moment of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $g\sim\mathcal{N}(0,1)$. For non-negative integers $a$ and $b$, define
\begin{equation}
I(a,b) := \mathbb{E}\!\left[(g^2 - 1)^a g^{2b}\right].
\end{equation}
Then we have
\begin{itemize}
\item[(i)] \textbf{(Recursion)} For $a\ge 2$,
\begin{equation}
I(a,0)=  2(a-1)\big(I(a-1,0)+I(a-2,0)\big),
\end{equation} 
and for $a\ge 1, b\ge 1$,
\begin{equation}
I(a,b)=2a\, I(a-1,b)+ (2b-1)\,I(a,b-1),
\end{equation}
with initial conditions
\begin{equation}
I(0,0) =1,\quad I(1,0) =0,\quad I(0,b) = (2b-1)!!.
\end{equation}

\item[(ii)] \textbf{(Inequality)} For $b=0,\,a\ge 2$ or $b\ge 1,\,a\ge 0$,
\begin{equation}
 \mathbb{E}[g^{2a+2b}] \leq 2^a\, \mathbb{E}[(g^2-1)^a g^{2b}].
\end{equation}
\end{itemize}

