[Lemma Phi of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \bigskip For each $n\geq 0$, the function $\Phi _{n}(x)$has two
fixed points at $0$ and $1$, and a unique fixed point in $(0,1)$. If we
denote the latter by $\phi _{n}$ then
\begin{equation}
\Phi _{n}(x)>x\quad \text{for }x\in (0,\phi _{n}),\qquad \Phi _{n}(x)<x\quad 
\text{for }x\in (\phi _{n},1).  
\end{equation}

Moreover, there exists a closed interval $I_{n}\subset (0,1)$ such that $
\phi _{n}\in I_{n}$ and \ \ \ 
\begin{equation}
\Phi _{n}^{^{\prime }}(x)\leq 1\quad \text{for all }x\in I_{n}.

\end{equation}

[Definition 3 of arXiv:2608.23462, '2608.23462'] Let $(y_t)_{t \in [0,\infty)}$ be a curve in $\R^{d_1}$. We say that $(y_t)_{t \in [0,\infty)}$ is an \emph{asymptotic pseudo-trajectory} of the averaged ODE \eqref{eq:averaged0} if and only if it holds 
	for all $ T \in (0,\infty) $ that
	\begin{align} 
	\lim_{T_0 \to \infty} \sup_{t \in [T_0,T_0+T]} |y_t-\mathbf x_{t-T_0}(y_{T_0})|=0.
	\end{align}

