[Definition defn:wallblock of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] A \emph{walk} of $(\hat{\mathfrak D}_{i_m}^{N_m})^{k_m} \cdots (\hat{\mathfrak D}_{i_1}^{N_1})^{k_1}$ consists of $\vec r=\{r_j\}_{j=1}^N$, with each $r_j:\llbracket 0, Q_m\rrbracket\to \mathbb Z_{\ge 0}$, satisfying the following conditions.
Denote $\mathscr{H}(t)=\sum_{j=1}^N r_j(t)$.
\begin{enumerate}
    \item $|\mathscr{H}(t)-\mathscr{H}(t-1)|=1$ for each $t\in \llbracket 1, Q_m\rrbracket$, $\mathscr{H}(t)\ge 0$, and  $\mathscr{H}(0)=\mathscr{H}(Q_m)=0$.
        \item For each $\ell\in \llbracket 1, m\rrbracket$ and $t\in \llbracket Q_{\ell-1}+1, Q_\ell\rrbracket$, we must have one of the two cases:
        \begin{itemize}
        \item Either, $r_{i_\ell}(t)=r_{i_\ell}(t-1)\pm 1$ and $r_j(t)=r_j(t-1)$ for all $j\ne i_\ell$;
        \item Or there exists one and only one index\footnote{This corresponds to the third option, i.e., $O(t)=\top$, in (defn:tie of the paper).} $j\ne i_\ell$, such that $r_j(t)\neq r_j(t-1)$ .
    Besides, in this case, necessarily $\mathscr{H}(t)=\mathscr{H}(t-1)-1$, and $j\le N_\ell$, and the differences $r_j(t)-r_j(t-1)$ and $r_j(t)-r_{i_\ell}(t-1)+1/2$ are of opposite signs.

        \end{itemize}
\end{enumerate}

[Corollary cor:scaberry of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Assume that $\phi_\ell\randin \mathcal{C}^\infty(M)$ is a sequence of Gaussian fields that satisfies a $\mathcal{C}^3$ scaling limit as in (def:scalim of the paper), in the range $(0,\rho)$, with \emph{parameters}: $\mathsf P_\ell=(K, \sigma_\ell,\lambda_\ell, 0,\rho)$. Assume that the limit field $F$ is $\phi_{[\alpha,1]}^{\mathbb{R}^n}$ for some $\alpha\in [0,1)$, or that it is $\phi_{1}^{\mathbb{R}^n}$ and that $n\ge 2$.
    Then, there is $r_0>0$ such that for any sequence $r_0\le r_\ell\le \rho \lambda_\ell$, we have 
\begin{gather}

{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)}{\lambda_\ell}\right\}\le 
{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)[2]}{\lambda_\ell}\right\}
+\mathrm{O}(1)\Bigg( r_\ell^{n}\lambda_\ell^{-n}
+

\int_{\substack{x,y\in M,
\\
\frac{r_\ell}{\lambda_\ell}
\le \mathrm{dist}(x,y)\le \rho}}\|\sigma_\ell^{-2}j^{1,1}_{x,y}E\|^4_{g^{\lambda_\ell}} \dd x \dd y 
\Bigg).
\end{gather} 
where $\mathrm{O}(1)$ denotes a bounded sequence.

