[Lemma 11 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $3\le d\le 5$, there exists $C>C'>0$ such that for any $M\ge 1$, $N\ge CM$, $v\in  \widetilde{B}(\frac{N}{C'})\setminus   \widetilde{B}(M)$ and $D\subset [\widetilde{B}(M)]^c$, 
 	\begin{equation}
 	\begin{split}
 	 	 \mathbb{P}^D\big( \bm{0}\xleftrightarrow{\ge 0}\partial B(N), v\xleftrightarrow{\ge 0} \partial B(N)   \big)  
 		 \lesssim   M^{-\frac{d}{2}+1}N^{-\frac{d}{2}} \cdot \sum\nolimits_{x\in \partial \mathcal{B}(d  N)}  \mathbb{P}^D\big(  v \xleftrightarrow{\ge 0} x  \big).
 	\end{split}
 	\end{equation}

