[Proposition prop:global_hajek of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:hatngdef of the paper), let us write
\begin{equation}
    \widehat{\mathsf{N}}_G(x) = \mathsf{N}_G(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{E}(x).
\end{equation}
Then, for all $\zeta \in (0,1)$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P}\mleft[\mleft|\widehat{\mathsf{N}}_G(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G(X)\mright]\mright| > n^{\mathsf{v}-1.5+\zeta}\mright] \leq \exp\mleft(-cn^\zeta\mright).
\end{equation}
In particular, for all $\xi > 0$ we have
\begin{equation}
    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_relation_pointandboundary of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d),
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that 
	\begin{equation}
	M^{-\varsigma_d(N)}	\lesssim 	\frac{ \mathbb{P}^D\big(A\xleftrightarrow{\ge 0} x\big)}{\mathbb{P}^D\big(A\xleftrightarrow{\ge 0}  B(M)\big)}\cdot M^{(\frac{d}{2}-1)\boxdot (d-4)}	 \lesssim   M^{3\varsigma_d(M)}
	\end{equation}
for all $N\ge 1$ and $x\in \partial B(M)$ if either of the following two conditions holds:
\begin{enumerate}
	\item[(a)] $A\subset \widetilde{B}(N)$, $M\ge \ensuremath{C_{\ref*{const_relation_pointandboundary1}}}N^{( 1 \boxdot \frac{d-4}{2})+\varsigma_d(N)}$ and $D\subset  \widetilde{B}(N)\cup [\widetilde{B}(2M)]^c$;


	\item[(b)] $A\subset [\widetilde{B}(N)]^c$, $M\le \ensuremath{c_{\ref*{const_relation_pointandboundary2}}}N^{(1 \boxdot \frac{2}{d-4})-\varsigma_d(N)}$ and $D\subset  [\widetilde{B}(N)]^c \cup \widetilde{B}(\frac{1}{2}M)$.

	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:DPW_QD of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Given $m\geqslant 0$ and  $\theta\in (-\frac{\pi}{2},\frac{\pi}{2})$, there exists a constant $C>0$ depending only on $m$ and $\theta$ such that
	\begin{equation}
		\sqrt{|\Omega|}\, \lambda_\Omega  \bigg (\theta, \frac{m}{\sqrt{|\Omega|}} \bigg)
		 - \sqrt{\pi}\, \lambda_\mathbb{D} \bigg (\theta, \dfrac{m}{\sqrt{\pi} }\bigg)
		 \leqslant C \left( \dfrac{|\partial\Omega|}{\sqrt{4\pi |\Omega|}}-1 \right)
	\end{equation}
for every bounded simply connected domain~$\Omega\subset \mathbb{R}^2$ with $C^2$~boundary. (Proof in the paper; no proof environment follows the statement in the TeX.)

