[Proposition 7 of arXiv:2607.15125, '2607.15125'] (Flajolet - Odlyzko \cite{flajolet1990singularity})  
Assume that, with the sole exception of the singularity $z=1$, $F(z)$ is analytic in the domain $\Delta(\epsilon,\theta) \coloneqq \{z : \abs{z} \le 1 + \epsilon,  \abs{\mathrm{Arg}(z-1)} \ge \theta \}$ where $\epsilon > 0$ and $\pi/2 <\theta < \pi$. Assume further that as $z$ tends to 1 in $\Delta$,
     \begin{equation*}
         F(z) \sim G(z),
     \end{equation*}
     Then, as $n\to\infty$, the nth Taylor coefficient of $F(z)$ satisfies 
     \begin{equation}
         [z^n]F \sim [z^n]G
     \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_Z of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] For fixed $i,j \in \{0,1, 2, \ldots, n\}$ we denote
    \begin{align}
        Z_{i,j}^n := \sqrt{n} \cdot  \Big(V_{\sigma_n}\big(\frac{i}{n}, \frac{j}{n}\big) - V_{g}\big(\frac{i}{n}, \frac{j}{n}\big)\Big).
    \end{align}

[Definition D:horizon-topology of arXiv:2604.10020, 'The directed landscape in half-space'] Let $L$ be an interval in $\mathbb{R}$ and let $J \in \{\mathbb{R}, \mathbb{Z}\}$, and fix a distinguished point $\gamma_0 \in L$. Define $\mathcal{D}(L, J, \gamma_0)$ to be the set of functions $F:L \times J \to \mathbb{R}$, such that (denoting $F_\gamma(j)=F(\gamma,j)$)
\begin{itemize}[nosep]
    \item $F_{\gamma_0}$ is continuous if $J = \mathbb{R}$;
    \item $F_\gamma(0) = 0$ for all $\gamma$;
    \item there is a $\sigma$-finite measure $\mu_F$ on $L \times J$ such that for any $\gamma_1<\gamma_2\in L$ and $j_1<j_2\in J$, we have
    \begin{equation}

        \mu_F((\gamma_1, \gamma_2] \times ((j_1, j_2]\cap J)) = F(\gamma_1, j_1) + F(\gamma_2, j_2) - F(\gamma_1, j_2) - F(\gamma_2, j_1). 
    \end{equation}
\end{itemize}
We say that $F^n \to F$ in $\mathcal{D}(L, J, \gamma_0)$ if $F^n_{\gamma_0} \to F_{\gamma_0}$ in the uniform-on-compact topology, and $\mu_{F^n} \to \mu_F$ vaguely. This turns $\mathcal{D}(L, J, \gamma_0)$ into a Polish space.

[Definition 6 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] $\Phi$ is said to be Ces\`aro eventually continuous with respect to a family $\mathfrak{F}\subset\mathcal{A}$ at $x\in \X$ if for any $f\in\mathfrak{F}$,
		\begin{equation*}
			\limsup\limits_{x'\rightarrow x}\limsup\limits_{t\rightarrow\infty}|Q_tf(x')-Q_tf(x)|=0.
		\end{equation*}

[Corollary density-conditions of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Assume that $F$ has a continuous positive density 
$f$ on $(0,1)$, and define 
\begin{equation}
G_{F}(x)=F(x)+F(1-x)-1,\qquad x\in \lbrack 0,1].  
\end{equation}
Then:

\begin{enumerate}
\item If $f(x)-f(1-x)$ changes sign at most once on $(0,1)$, then $G_{F}$
has a constant sign on $[0,1]$.

\item Consequently, by \textit{Claim~(prob-meaning of the paper)}, 
\begin{equation}
H_{F}(u)=Q(u)+Q(1-u)-1  
\end{equation}
has a constant sign on $[0,1]$, and by \textit{Corollary~(HF-one-sign of the paper)}
the first defect $D_{0}$ has a constant sign on $[0,1]$.

\item A sufficient condition for the hypothesis in \emph{(1)} is that the
ratio 
\begin{equation}
x\longmapsto \frac{f(x)}{f(1-x)}  
\end{equation}
be monotone on $(0,1)$.
\end{enumerate}

