body:
[Definition 5 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] (solution to the martingale problem). Given a probability measure $\mu$ on $\ell_\rho^{2\theta}(\mathbb{Z}^+)$, a probability measure $\mathbf{P}$ on $(\Omega_{Spin},\mathscr{B}^{Spin})$ is called a solution to the martingale problem associated to (\ref{INFSDE2}) with initial law $\mu$ if 
    \begin{itemize}
        \item[(i)] for every $T>0$
        \begin{equation*}
            \mathbf{P}\left(\sup\limits_{t\in[0,T]}\Vert X(t)\Vert_{2\theta,\rho}<\infty\right)=1;
        \end{equation*}
        \item[(ii)] for every $h\in C_c^{2,Cly}(\ell_\rho^{2}(\mathbb{Z}^+))$(or $h\in C^{2,Cyl}(\ell_\rho^{2}(\mathbb{Z}^+) )$), the process $M^h(t)$ defined $\mathbf{P}-a.s.$ on $(\Omega_{Spin},\mathscr{B}^{Spin})$ as 
        \begin{equation*}
            M^h(t):=h(X(t))-h(X(0))-\int_0^t\mathscr{L}h(X(s))ds,
        \end{equation*}
        is a continuous (local) martingale under $(\Omega_{Spin},\mathscr{B}^{Spin}, \mathbf{P},\{\mathscr{B}^{Spin}_t\})$;
        \item[(iii)] $\mu=\mathbf{P}\circ X(0)^{-1}$.
    \end{itemize}

[Lemma Phi-const-direct of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] The limit map $\Phi _{\infty }$ is constant on $
(0,1)$ and equal to $c^{\ast }$ 
\begin{equation}
\Phi _{\infty }(x)\equiv c^{\ast }=\frac{1}{2},\quad x\in (0,1).  
\end{equation}

[Lemma 4 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] For every $\alpha, \beta,\gamma >0$, there exists a constant $c>0$ such that the following holds for every $\delta < 1/2$.
	Consider $x_0,y \in \cD(\delta)$ with $\Vert x-y \Vert \leq (4/5) r_\delta$ such that $x_0$ and $y$ lie on different sides of some barrier $B_i$ with $i\geq 1$.
	Define
	\begin{align}
		\cE_1 \de \inf\{t\geq 0: s_i(t) \neq s_i(0) \} \quad \text{ and }\quad \cE_2 \de \inf\{t\geq \cE_1: s_i(t)\neq  s_i(\cE_1)\} - \cE_1 \nonumber
	\end{align}
	to be the first two increments between times for which $s_i$ changes value.
	Then,
	\begin{align}
		\bbP\bigl( \cE_1 <  \alpha r_\delta, \,  \cE_2 >  \beta r_\delta, \,  \Vert   W_t - (t/ r_\delta^2) (y- x_0) \Vert \leq   \gamma r_\delta,\, \forall t\leq  r_\delta^2 \bigr) \geq c  r_\delta \lambda_{\min}.  
	\end{align}

