[Theorem thm:shuffle of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] For bounded-variation paths and words $u,v$,
\begin{equation}
\inner{\mathrm{Sig}(x)}{u}\,\inner{\mathrm{Sig}(x)}{v}
=
\inner{\mathrm{Sig}(x)}{u\mathbin{\sqcup\!\sqcup} v},
\end{equation}
where $u\mathbin{\sqcup\!\sqcup} v$ is the sum of all order-preserving interlacings of $u$ and $v$.

[Lemma 17 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] For any integer $p \ge 2$ and $0 < \theta < 1/6$,
        \begin{equation}

        \Bigg| \mathbb{E} \bigg[ \int_{-\infty}^{\infty}\int_{[0, t]_<^{p}} \prod_{j=1}^p\Delta_{\epsilon}(W(s^{j}) - x)  \mathrm{d} \mathbf{s} \mathrm{d} x
        \bigg]^m \Bigg| \le C^m \epsilon^{\theta(p-1) m} (m!)^p \Big( \frac{t^m}{m!} \Big)^{\frac{p+1}{2} - (p-1)\theta}.
        \end{equation}

