[Prop 40 (Finite-window Kearns--Saul inequality) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] {Let $p\in(0,1/2]$ and $a>0$. The inequality}
\begin{align}
    \E\left[e^{\lambda(\berv-p)}\right]
    \leq e^{A\lambda^2}
    \qquad\text{for all }|\lambda|\leq\frac1a

\end{align}
{holds with $A=A_p(a)$ and with no smaller constant, where}
\begin{align}
    A_p(a)
    &=
    \begin{cases}
        \displaystyle
        \frac{1-2p}
        {\displaystyle4\log\left(\frac{1-p}{p}\right)},
        & \displaystyle2\log\left(\frac{1-p}{p}\right)\leq\frac{1}{a},\\[8mm]
        \displaystyle
        a^2\log\left(
            p\,e^{(1-p)/a}
            +(1-p)\,e^{-p/a}
        \right),
        & \displaystyle 2\log\left(\frac{1-p}{p}\right)>\frac{1}{a}.
    \end{cases}

\end{align}
{For $p<1/2$, \eqref{eqn:kswindow} at $A=A_p(a)$ is an equality at exactly one nonzero $\lambda$ of the window: $\lambda=2\log\left((1-p)/p\right)$ on the first branch, $\lambda=1/a$ on the second. At $p=1/2$ the first branch is read by \eqref{eqn:lhopital} as $A_{1/2}(a)=1/8$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Strichartz estimates) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $s\ge 0$, $(\mu,r)$ be higher-order Schrödinger admissible, and $\psi_0\in H_t^{\frac{s+1}{3}}(\mathbb{R})$, $\psi_1\in H_t^{\frac{s}{3}}(\mathbb{R})$ satisfy \eqref{supp-cond}.  Then, the solution of \eqref{HNLSreduced} represented by the formula \eqref{sol_for_reduced} satisfies 
\begin{equation}
    \left\|v\right\|_{L^\mu_t((0, T); H^{s,r}_x(\mathbb{R}_+))}\lesssim (1+e^{cT'}(T')^{\frac12+\frac 1 \mu})\sum_{b=0}^1\|\psi_b\|_{H_t^{\frac{s+1-b}{3}}},
\end{equation} 
where $c$ and the constant of the inequality may depend only on the fixed parameters such as $s,\alpha,\beta$, and $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2606.17472, '2606.17472'] Let $(A_t, t\ge 0)$ be a positive continuous additive functional of $X$, and let $\nu$ be its Revuz measure. Assume that $\nu$ is a finite measure and has compact support. Then there exists a martingale $M^\nu$ such that
\begin{align}

  \int_\R h(X_t-y)\nu(dy)=\int_\R h(x-y)\nu(dy)+M_t^\nu +A_t,\qquad t\geq 0.
\end{align}
In particular, it holds that
\begin{align}

\varphi_B(X_t)=\varphi_B(x)+M_t^{\mu_B}+\int_B L_t^y \mu_B(dy),\qquad t\geq 0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 59 (All-order singular lattice profiles) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $\Gamma=\mathbb Z^D$, $m\ge2$, and
\[
 \frac{(m-1)D}{2m}<\sigma\le\frac D2,
 \qquad c_x=\langle x\rangle^{-\sigma}.
\]
Put
\[
 \beta_m=m\left(\frac D2-\sigma\right),\qquad
 \gamma_m=2m\sigma-(m-1)D,
\]
and
\begin{equation}

 \Omega_{m,\sigma}(R)=
 \begin{cases}
  R^{\beta_m},&\sigma<D/2,\\
  \log(e+R)^{m/2},&\sigma=D/2.
 \end{cases}
\end{equation}
For $R_+=\max\{L,Q\}$ and $R_-=\min\{L,Q\}$,
\begin{equation}

 \Prof_{m,r}(K_{m,N}^{L,Q}(c))
 \le C\Omega_{m,\sigma}(R_+)R_-^{D/r},
 \qquad2\le r\le\infty.
\end{equation}
If $N\ge M$ and $\sigma<D/2$, then
\begin{align}

 &\Prof_{m,r}(K_{m,N}^{L,Q}(c)-K_{m,M}^{L,Q}(c))\notag\\
 &\quad\le C\Omega_{m,\sigma}(R_+)R_-^{D/r}
 \min\{1,(R_+/M)^{\gamma_m/2}\}.
\end{align}
At $\sigma=D/2$, for every $0<\vartheta<D$ the right side is replaced by
\begin{equation}

 C_\vartheta\Omega_{m,D/2}(R_+)R_-^{D/r}
 \min\{1,(R_+/M)^{\vartheta/2}\}.
\end{equation}

[Theorem thm:sep of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] Let $t: C\to\mathbb P^1$ be cyclic of degree $n$ with branch data $(l_1,\dots,l_r)$, the point at infinity included when it is a branch point. Then there is a birational map from $C$ to a curve $v^n=h(u)$ with $k(u)=k(t)$ and $h\in k[u]$ separable if and only if there is $c\in(\mathbb Z/n\mathbb Z)^\times$ such that

\begin{equation}
c\,l_j\equiv 1\pmod n\quad\text{for every $j$ with at most one exception.}
\end{equation}

[Definizione 14 (Composition law) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let us consider two stochastic transformations $T_1=(\Phi_1, B_1, \eta_1, h_1) \in S_m(M,M')$ and $ T_2=(\Phi_2, B_2, \eta_2, h_2)\in S_m(M',M'')$. We define $ T_2\circ T_1$ as the unique transformation corresponding to the composition $F_{T_2}\circ F_{T_1}$ of the associated isomorphisms, i.e. \begin{equation*}
 T_2 \circ T_1 := \big( \Phi_2 \circ \Phi_1, \ (B_2 \circ \Phi_1)  B_1, \ (\eta_2 \circ f_1)  \eta_1,\ \sqrt{\eta_1}B_1^{-1}( h_2 \circ \Phi_1) + h_1 \big) \in S_m(M,M''),
 \end{equation*}
 where $\Phi_2 \circ \Phi_1=(\tilde{\Phi}_2\circ \tilde{\Phi}_1,f_2\circ f_1).$
 In the same way, we define $\ T_1^{-1}$ as the unique transformation corresponding to the inverse isomorphism $\ F_{T_1}^{-1}$, i.e.
 \begin{equation*}
        T_1^{-1}:=( \Phi_1^{-1}, \ (B_1 \circ \Phi_1^{-1})^{-1}, \ (\eta_1 \circ f_1^{-1})^{-1}, - \frac{1}{\sqrt{\eta_1}} B_1  h_1 \circ \Phi_1^{-1}) \in S_m(M',M).
    \end{equation*}

[Lemma lem:comparison_of_fields of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Fix $b \in (0,a/100)$ deterministic and depending only on $a$.  Suppose that we have the setup described above and let $\hat{\Psi}_1$ denote the GFF on $\BD$ with boundary conditions given by $b_j$ on the counterclockwise arc of $\partial \BD$ from $\hat{x}_j$ to $\hat{x}_{j+1}$ for all $j \in \{1,2,3,4\}$.  Let $\mathcal{Z}_{\varepsilon}$ denote the Radon--Nikodym derivative of the conditional law of $\tilde{\Psi}_1$ restricted to $\BD \setminus \bigcup_{j=1}^4 \overline{B_{\varepsilon^b}(y_j)}$ with respect to the conditional law of $\hat{\Psi}_1$ restricted to $\BD \setminus \bigcup_{j=1}^4 \overline{B_{\varepsilon^b}(y_j)}$,  in both cases given the boundary conditions of $\tilde\Psi_1$ (in particular,  the points $\hat x_j , y_j$ and the values $b_j$).  Then,  for all $p>0$,  we have that
\begin{align*}
\BE[\mathcal{Z}_{\varepsilon}^p ] \to 1 \quad \text{as} \quad \varepsilon \to 0.
\end{align*}

[Definition def:mixing-time of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] For a probability measure $\mu$ on $\mathbf{S}_N$, let $P^t_{\mu}(A) = \mathbb{P}( X_t \in A \mid  X_0 \sim \mu )$. The (worst-case) mixing time is defined by:
    \begin{align*}
        t_{\mathsf{mix}}(\varepsilon) =  \inf \{ t >0 :\max_{x \in \mathbf{S}_N } d_{\textsc{tv}} ( P^t_x, \pi_{\beta} ) \leq  \varepsilon  \} \, .
    \end{align*}
    where $d_{\textsc{tv}}$ is the total-variation distance. 
    Given $M$, let $\mathcal{M}_E$ denote the collection of probability measures invariant under the map $e_1 \to - e_1$, then we define the symmetric mixing time to be:
    \begin{align*}
        t_{\mathsf{mix}}^{\mathsf{sym}} (\varepsilon) = \inf \{ t > 0 : \max_{\mu \in \mathcal{M}_E} d_{\textsc{tv}}( P^t_{\mu} ,\pi_{\beta}) \leq \varepsilon \} \, .
    \end{align*}
    We denote $t_{\mathsf{mix}}$ and $t_{\mathsf{mix}}^{\mathsf{sym}}$ as the values $t_{\mathsf{mix}}(1/4)$ and $t_{\mathsf{mix}}^{\mathsf{sym}}(1/4)$ respectively.

[Theorem eq: Levy-Ito decomposition of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] If $(X_t,Y_t)_{t\geq 0}$ is a two-dimensional L\'{e}vy process, then there exists $b=(b^{X},b^{Y})\in\mathbb{R}^2$, a two-dimensional Brownian motion $(B^{X}_t,B^{Y}_t)_{t\geq 0}$ with the covariance matrix $\Sigma$ and a Poisson random measure $N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y)$ with the intensity measure $\mathrm{d}t\nu(\mathrm{d}x,\mathrm{d}y)$ such that for $t\geq 0$,
\begin{equation}
\begin{aligned}
X_t=b^{X}t+B^{X}_t+\int_{0}^{t}\int_{|x|<1}x\widetilde{N}^{X}(\mathrm{d}s,\mathrm{d}x)+\int_{0}^{t}\int_{|x|\geq 1}xN^{X}(\mathrm{d}s,\mathrm{d}x),\\
Y_t=b^{Y}t+B^{Y}_t+\int_{0}^{t}\int_{|y|<1}y\widetilde{N}^{Y}(\mathrm{d}s,\mathrm{d}y)+\int_{0}^{t}\int_{|y|\geq 1}yN^{Y}(\mathrm{d}s,\mathrm{d}y),
\end{aligned}
\end{equation}
where
\[N^{X}(\mathrm{d}t,\mathrm{d}x)=1_{x\neq 0}\int_{\mathbb{R}}N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y), N^{Y}(\mathrm{d}t,\mathrm{d}y)=1_{y\neq 0}\int_{\mathbb{R}}N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y),\] \[\nu^{X}(\mathrm{d}x)=1_{x\neq 0}\int_{\mathbb{R}}\nu(\mathrm{d}x,\mathrm{d}y), \nu^{Y}(\mathrm{d}y)=1_{y\neq 0}\int_{\mathbb{R}}\nu(\mathrm{d}x,\mathrm{d}y)\]
and
\[\widetilde{N}^{X}(\mathrm{d}t,\mathrm{d}x)=N^{X}(\mathrm{d}t,\mathrm{d}x)-\mathrm{d}t\nu^{X}(\mathrm{d}x), \widetilde{N}^{Y}(\mathrm{d}t,\mathrm{d}y)=N^{Y}(\mathrm{d}t,\mathrm{d}y)-\mathrm{d}t\nu^{Y}(\mathrm{d}y).\]
Moreover, $(B_t)_{t\geq 0}$ is independent of $N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y)$ and
\begin{equation*}
N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y)=\sum_{(s,\Delta X_s,\Delta Y_s):(\Delta X_s,\Delta Y_s)\neq (0,0)}\delta_{(s,\Delta X_s,\Delta Y_s)}(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y),
\end{equation*}
where $\delta_{z_0}(\mathrm{d}z)$ is the Dirac measure at $z_0\in[0,\infty)\times(\mathbb{R}^2\setminus\{(0,0)\})$. In addition, $(B^{X}_{t})_{t\geq 0}$ is a measurable function of $(X_t)_{t\geq 0}$, and $(B^{Y}_t)_{t\geq 0}$ is a measurable function of $(Y_t)_{t\geq 0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:u and h of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $q\in(0,1)$ and $c\in[0,1)$.  For each $n,k,\ell\in\mathbb{Z}_{\geq0}$, we define 
\begin{equation}
    u_n^k(\ell)=(1-q)^{2n}\sum_{\lambda\in\mathsf{Sign}_2}s_{\lambda/(\ell,0)}((q)^n){\bf 1}_{\{\lambda_1-\lambda_2=k\}}.
\end{equation}
Here and below, we write $(x)^n$ to mean the $n$-tuple $(x,\dots,x)$, and use the convention $s_{\lambda/\mu}((x)^0)={\bf 1}_{\{\lambda=\mu\}}$. 
For each $k,\ell\in\mathbb{Z}_{\geq0}$, $n\in\mathbb{N}$, and $x\in\llbracket0,n\rrbracket$, we also define
\begin{equation}
   h_{x,n}^k(\ell)= \frac{u_{n-x}^{k}(\ell)}{\sum_{j\geq0}c^j u_n^{k}(j)}.
\end{equation}
The finiteness of (equation eq:definition of u of the paper) and of the denominator on the right side of (equation eq:definition of h of the paper) are implied by Lemma (lem:formula u and h of the paper) below. Note that \(u_n^k(0)\geq (1-q)^{2n} s_{(k,0)/(0,0)}((q)^n)  >0\), hence the denominator on the right side of (equation eq:definition of h of the paper) is positive.

[Lemma 23 (Deep vertices imply large mass earlier) of arXiv:2604.25877, 'Asymptotic height of Plancherel random trees'] Fix an integer $s\ge2$. For every $h\ge s-1$,
\begin{equation}
\{H_n>h\}
\subseteq
\left\{\exists\,u:\ |u|=h-(s-1)\ \text{and}\ K(u)\ge s+1\right\}.
\end{equation}

[Theorem 20 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of $m$-dependent and linear stationary random variables in a sub-linear space $\sles$ with 
    \begin{equation}
        C_{\V}(X_1^2)<\infty,
    \end{equation}
    and 
    \begin{equation}
        \bE[X_1] = \be[X_1] = 0,

    \end{equation}
    Denote $S_n=\sum_{i=1}^nX_i$ and $\lsigma^2, \usigma^2$ are defined as in (\ref{limit-sigma}). Further assume $\lsigma^2>0$ and $\mbE$ satisfies the condition (CC), then for $V = \V^{\mathcal{P}}, \mathbb{C}^*$ or $\Vstar$,
    \begin{equation}
        V\left(C\left\{\frac{\sum_{i=1}^n X_i}{\sqrt{2n\log\log n}}\right\}=[-\sigma,\sigma]\right)=
        \begin{cases}
            1 & \text{ if } \sigma\in[\lsigma, \usigma],\\
            0 & \text{ if } \sigma\notin[\lsigma, \usigma].
        \end{cases}

    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem_loc of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Suppose that $h\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^2)$ and
  $f\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^{2n+2})$, and that $u_0$ as well as $u_{0t}$ satisfy ((init of the paper))
  and are such that
  \begin{eqnarray*}
	h(u_0(x),u_{0t}(x))>0
	\qquad \mbox{for all } x\in\overline{\Omega}.
  \end{eqnarray*}
  Then there exist $T_{max}\in (0,\infty]$ as well as a function
  \begin{eqnarray*}
	u \in C^0([0,T_{max});C^1(\overline{\Omega})) \cap C^{2,1}(\overline{\Omega}\times (0,T_{max}))
  \end{eqnarray*}
  such that
  \begin{eqnarray*}
	u_t \in C^0([0,T_{max});C^1(\overline{\Omega})) \cap C^{2,1}(\overline{\Omega}\times (0,T_{max})),
  \end{eqnarray*}
  that 
  \begin{eqnarray*}
	h\big(u(x,t),u_t(x,t)\big)>0
	\qquad \mbox{for all $x\in\overline{\Omega}$ and } t\in [0,T_{max}),
  \end{eqnarray*}
  that ((0 of the paper)) is satsified in the classical sense in $\Omega\times (0,T_{max})$, and that
  \begin{eqnarray}\label{ext}
	& & \hspace*{-20mm}
	\mbox{if $T_{max}<\infty$, \quad then \quad 
	either } 
	\liminf_{t\nearrowT_{max}} \inf_{x\in\Omega} h\big(u(x,t),u_t(x,t)\big)=0
	\quad \mbox{or} \nonumber\\
	& & \hspace*{20mm}
	\limsup_{t\nearrowT_{max}} \Big\{ \|u(\cdot,t)\|_{C^{1+\iota}(\overline{\Omega})} + \|u_t(\cdot,t)\|_{C^{1+\iota}(\overline{\Omega})} \Big\}
	= \infty
	\quad \mbox{for all } \iota>0.
  \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 45 of arXiv:2607.18104, '2607.18104'] Fix some $T>0$. Consider the narrow wedge initial data $\hfix^{\vee}_0$, i.e.,
\begin{equation}
    \hfix^{\vee}_0(y) := \begin{cases}
        0 & \text{ if } z =0, \\
        -\infty & \text{ otherwise.}
    \end{cases}
\end{equation}
As $\varepsilon \rightarrow 0$, we have convergence as a process in $x\in \R$ and $t\geq 0$ of
   \begin{equation}
   \varepsilon^{-\frac{1}{3}} \hfixp(\hfix^{\vee}_0;y\varepsilon^{\frac{2}{3}};t\varepsilon)\rightarrow   \hfix(\hfix^{\vee}_0;y;t).
\end{equation}

