[Lemma 6 of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] Let $N(\d t,\d z)$ be a Poisson random measure on $\mathscr{B}\left(\mathbb{R}_{+}\right) \otimes \mathcal{Z}$ with compensator $\nu(\d z)\d t$  and fix $T>0$. Let $Y$ be the solution to the SDE
\begin{equation}
    \mathrm{d} Y(t)  =-\lambda Y(t) \mathrm{d} t+\int_{Z}h(t,z) \widetilde{N}(\d t,\d z) ,\quad Y(0)  =0,
\end{equation}
where $h$ is predictable with almost surely c\`agl\`ad sample paths.
\begin{enumerate}
\item If $\mathbb{E}\left(\int_{0}^{T} \int_{Z}|h(t, z)| \nu(\d z) \d t\right)<\infty$, then for any stopping time $\tau$, there exists a function $\varrho:[0, \infty) \rightarrow[0, \infty)$ with $\lim _{\lambda \rightarrow \infty} \varrho(\lambda)=0$ such that
\begin{equation}
    \begin{split}
        \mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}|Y(t)|^{p}\right)& \leq \varrho(\lambda) \bigg[\mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}\int_{Z}|h(t,z)|^{q}\nu(\d z)\right)^{p/q}\bigg].
    \end{split}
\end{equation}
holds for any $q \in[1,2]$ and $p \in(0, q]$.

\item If  $\mathbb{E}\left(\int_{0}^{T} \int_{Z}|h(t, z)|^{2} \nu(\d z) \d t\right)<\infty$ and $p \geq 2$, then for any stopping time $\tau$, there exists a function $\varrho:[0, \infty) \rightarrow[0, \infty)$ with $\lim _{\lambda \rightarrow \infty} \varrho(\lambda)=0$ such that
\begin{equation}
    \begin{split}
        \mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}|Y(t)|^{p}\right)& \leq \varrho(\lambda) \bigg[\mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}\int_{Z}|h(t,z)|^{2}\nu(\d z)\right)^{p/2}\\
        &\qquad\qquad +\mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}\int_{Z}|h(t,z)|^{p}\nu(\d z)\right)\bigg].
    \end{split}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:critical-shift of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] As $s\to\infty$,
\begin{equation}
 \mathcal R_{N,\beta}(s)
 =2N-\frac{(N-2)^2}{4s}
 +\frac{(N-2)(\beta_N^*-\beta)}{s^2}+O(s^{-3}),
\end{equation}
where
\begin{equation}
 \beta_N^*=\frac{N^3+18N^2+20N-24}{192}.
\end{equation}
If $\beta<\beta_N^*$, then $h_{N,\beta}$ cannot be a global supersolution for
the potential $A_N|n|^{-2}$.

