[Definition def:loops-loop variables of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] We will represent loops $\ell$ in $\Lambda$ by the sequence of oriented edges $\ell = e_1 \cdots e_n$ that are traversed by $\ell$. We denote $|\ell| := n$. Let $Q : E_\Lambda^+ \ra G$ be a lattice gauge configuration. For  a loop $\ell=e_1e_2\dots e_n$, let $Q_{\ell}:=Q_{e_1}Q_{e_2}\dots Q_{e_n}$ denote the corresponding loop variable. We define
\begin{equs}
W_\ell(Q) := \tr(Q_\ell),
\end{equs}
where $\tr = \frac{1}{N} \Tr$ is the normalized trace.
We refer to $W_\ell$ as a Wilson loop observable.

[Theorem 46 (Scale-invariant reduced capture) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Assume $\mathfrak H:=\mathfrak H_Q(A,r)>0$.  Choose $q_*$ with maximal
$\lambda_*=\lambda_{\max}(E_{q_*})$, let $L_*$ be its full top eigenspace, and promote
\begin{equation}
 V_*=N_{q_*}R_{q_*}L_*.

\end{equation}
Then
\begin{equation}
 \lambda_*\ge\frac{\mathfrak H}{dQ},\qquad
 \inf_{0\ne c\in L_*}
 \frac{\norm{N_{q_*}R_{q_*}c}}{\norm{c}}
 \ge\frac{\mathfrak H}{dQR},

\end{equation}
and
\begin{equation}
 \sum_{a,q}\norm{P_{V_*}r_{a,q}}^2
 \ge
 \kappa_{Q,d}\frac{\mathfrak H}{R^2},
 \qquad
 \boxed{\kappa_{Q,d}=\frac1{dQa_Q}}.

\end{equation}

[Lemma 61 (Kernel identities) of arXiv:2609.02267, 'Locally Conformally Flat Manifolds with Positive Scalar Curvature: Kleinian Groups, Moduli'] For $b>0$ and $x,y\in S^n$ with $x\ne y$,
\begin{equation}
 L_{g_{st},x}\mathfrak q(x,y)^{-b}
 =A_{n,b}\mathfrak q(x,y)^{-b}+B_{n,b}\mathfrak q(x,y)^{-b-2},
\end{equation}
where
\[
 A_{n,b}=\frac{(n-1)(n-2-b)(n-b)}{n-2},
 \qquad
 B_{n,b}=\frac{4(n-1)b(n-2-b)}{n-2}.
\]
In particular, both coefficients are positive when $0<b<n-2$.
Moreover, if $\lambda>0$, then
\begin{align}
 L_{g_{st},x}\bigl(\mathfrak q^{2-n}\ell(\mathfrak q)^{-\lambda}\bigr)
 &=\frac{4(n-1)\lambda}{n-2}\mathfrak q^{-n}
   \frac{(n-2)\ell(\mathfrak q)-(\lambda+1)}{\ell(\mathfrak q)^{\lambda+2}}
 \notag\\
 &\quad+\frac{(n-1)\lambda}{n-2}\mathfrak q^{2-n}
   \frac{2\ell(\mathfrak q)+\lambda+1}{\ell(\mathfrak q)^{\lambda+2}}.

\end{align}
For $\lambda=a/2=(n-2)/4$, this expression is positive and
\begin{equation}
 L_{g_{st},x}\bigl(\mathfrak q^{2-n}\ell(\mathfrak q)^{-a/2}\bigr)
 \asymp \mathfrak q^{-n}\ell(\mathfrak q)^{-a/2-1}
 \qquad(0<\mathfrak q\le2).
\end{equation}

