[Proposition 2 of arXiv:2506.13913, '2506.13913'] {}{}
 Let \(\{W_t\}_{t \geq 0}\) be a Brownian motion defined starting at $x$ on a probability space \((\Omega, \mathcal{F}, \mathbb{P})\), taking values in \(\mathbb{R}\). Then, for any \(t > 0\), the transition density \(p(t, x, y)\) of the process is given by
 \begin{equation}
    p(t, x, y) = \frac{1}{\sqrt{2 \pi t}} \exp\left(-\frac{(y - x)^2}{2t}\right), \quad x, y \in \mathbb{R}. 
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: limiting threshold of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] For each $t \geq 0$, let
	\begin{equation*}
		\bar\boldsymbol{y}_*^-(t) \vcentcolon= \liminf_{N \to \infty} \bar\boldsymbol{y}_*^N(t) \quad \text{and} \quad \bar\boldsymbol{y}_*^+(t) \vcentcolon= \limsup_{N \to \infty} \bar\boldsymbol{y}_*^N(t).
	\end{equation*}
	The following property holds in the set $\Gamma$ of probability one:
	\begin{equation*}
		\bar\boldsymbol{y}_*(t) \leq \bar\boldsymbol{y}_*^-(t) \quad \text{and} \quad \bar\boldsymbol{\nu}_t\left(\left[\bar\boldsymbol{y}_*(t), \bar\boldsymbol{y}_*^+(t)\right)\right) = 0 \quad \text{for all} \quad t \in \mathcal{C}.
	\end{equation*}
	If $\bar\boldsymbol{y}_*^+(t) < \infty$, then the latter equality also holds for the closed interval $[\bar\boldsymbol{y}_*(t), \bar\boldsymbol{y}_*^+(t)]$.

