[Theorem thm: bulk of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists a Banach space, $\boldsymbol{\mathfrak B}$ such that the following holds. Let $\sigma \in \{ \emptyset,-,+\}$.
\begin{enumerate}
\item[\rm (I)]\textbf{\textup{(Lifted amplitude).}} Let $T>0$. There exists measurable maps
\begin{itemize}
	\item $\Xi^\partial_T:\mathcal C^{-1/2-\kappa}(\mathbb T^2) \times \mathcal C^{-1/2-\kappa}(\mathbb T^2) \rightarrow \boldsymbol{\mathfrak B} \quad \hfill \textup{(Enhancement)}$
	\item $\boldsymbol{\mathcal A}^\sigma_T: C^\infty(M) \times \boldsymbol{\mathfrak B} \rightarrow \mathbb R \quad \hfill \textup{(Lift)}\hspace{2.2em}$
\end{itemize}
such that for every $f \in C^\infty(M_\sigma)$ and almost surely for every $(\varphi^\sigma_-,\varphi^\sigma_+) \sim \nu^0\otimes \nu^0$,
\begin{equation}
\mathcal A_T^\sigma(f \mid \varphi_-^\sigma,\varphi_+^\sigma)=\boldsymbol{\mathcal A}^\sigma_T(f, \Xi^\partial_T(\varphi^\sigma_-,\varphi^\sigma_+)).
\end{equation}
\item[\rm (II)] {\rm \bf {(Limit amplitude and convergence).}} There exists a measurable map, called the limiting lifted amplitude,
\begin{equation}
	\boldsymbol{\mathcal A}^\sigma_\infty:C^\infty(M_\sigma)\times \boldsymbol{\mathfrak B} \rightarrow \mathbb R
\end{equation}
such the following convergence statement holds. Let $(\Xi^\partial_T) \subset \boldsymbol{\mathfrak B}$ and $\Xi^\partial_\infty \in \boldsymbol{\mathfrak B}$ be such that $\Xi^\partial_T \rightarrow \Xi^\partial_\infty$ in $\boldsymbol{\mathfrak B}$. Then for every $f \in C^\infty(M_\sigma)$,
\begin{equation} 
	\lim_{T \rightarrow \infty} \boldsymbol{\mathcal A}^\sigma_T(f,\Xi^\partial_T) = \boldsymbol{\mathcal A}^\sigma_\infty(f, \Xi^\partial_\infty).
\end{equation}
\item[\textup{(III)}] \textup{\bf (Almost sure bounds)} For every $f \in C^\infty(M)$, there exists $c,C,p>0$ such that for every $T \in (0,\infty]$ and every $\Xi^\partial \subset \boldsymbol{\mathfrak B}$,
\begin{align}
\boldsymbol{\mathcal{A}}_{T}^\sigma(f,\Xi^\partial)
 \leq
  C \exp(c  \|\Xi^\partial \|^{p}_{\boldsymbol{\mathfrak{B}}}), 	
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

