body:
[Definition 62 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We introduce the following notions:
\begin{enumerate}
\item We call the $\bbr^{d \times d}$-valued process $\bbb = \bbb^{\text{\rm It\^o}}$ defined by the It\^{o} integrals
\begin{align}
\bbb_{s,t} := \int_s^t B_{s,r} \otimes dB_r, \quad s,t \in [0,T]
\end{align}
the \emph{It\^{o}-enhancement} of Brownian motion.

\item We call the process $\bfb = \bfb^{\text{\rm It\^o}}$ defined as $\bfb := (B,\bbb)$ the \emph{It\^{o}-enhanced Brownian motion}.
\end{enumerate}

[Definition discreteW of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] Let  
  $$\mathbb W:=\{w=(w(0),w(1), \ldots)\mid w(n) \in \mathbb Z, w(n+1)-w(n) \in \{-1,1\}, n \in \mathbb{N}_0\},$$
  and for $p\in (0,1)$ let $(W, (\mathbb{P}_k^p)_{k\in \mathbb{Z}})$ be the canonical model of a (discrete-time) random walk with step size~1 and upward transition probability  $p$. (In particular, $\mathbb{P}_k^p(W(0)=k)=1$ , $\mathbb{P}_k^p(W(1)=k+1)=p$.)

  For $k \in \mathbb{N}_0$ and $w \in \mathbb W$ let
\begin{equation}
    \tau_k(w):= \min\{n\in \mathbb{N}_0\mid w(n) =k\}, \quad \tau_k^+(w):= \min\{n\in \mathbb{N}\mid w(n) =k\},
\end{equation}
be the first visit time of $k$ and the first return time to $k$, respectively, and let
\begin{equation}
    \sigma_k(w):= \max\{n\in \mathbb{N}_0\mid w(n) =k, \, w(j) \in \mathbb{N} \mbox{ for } j \in \{0, \ldots, n-1\}\}
\end{equation}
be the time of the last visit of $k$ before $w$ hits $0$.

[Proposition prop_pointtoset_speed of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exists a constant $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d)>0$ such that for any $N\ge 1$, $A\subset \widetilde{B}(N)$, $x_1,x_2\in [B(\ensuremath{C_{\ref*{const_pointtoset_speed}}}N^{1+\varsigma_d(N)})]^c$, $M\ge 2(|x_1|\vee |x_2|)$ and $D\subset \widetilde{B}(N)\cup [\widetilde{B}(M)]^c$, 
	\begin{equation}
		|x_1|^{d-2}	\mathbb{P}^D\big( A \xleftrightarrow{\ge 0}  x_1 \big) \asymp |x_2|^{d-2}	\mathbb{P}^{D}\big( A \xleftrightarrow{\ge 0}  x_2 \big). 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture conj:barcode_density_limit of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] The following limits
	\begin{equation*}
	\rho_0(t)\coloneqq
		\lim_{M\to\infty}
		\mathfrak{a}(1-\tfrac{t}{2})
		\sum_{n=0}^{M+1/2}
		\frac{-q^{-n}
		\mathcal{F}_n^t(0)\mathcal{F}_n^{t-1}(0)
		}{\|\mathcal{F}_n\|^2_{\ell^2(\mathbb{Z})}}
		,\quad
		\rho_1(t)\coloneqq
		\lim_{M\to\infty}
		\mathfrak{a}(1-\tfrac{t}{2})
		\sum_{n=0}^{M}
		\frac{-q^{-n}
		\mathcal{F}_n^t(0)\mathcal{F}_n^{t-1}(0)
		}{\|\mathcal{F}_n\|^2_{\ell^2(\mathbb{Z})}}
	\end{equation*}
	exist for all $t\in \mathbb{Z}$,
	where $M\in \mathbb{Z}$, and the sums are over $n\in \frac12\mathbb{Z}_{\ge0}$.
	Moreover, they take only two different values, depending on the parity of $t$:
	\begin{equation*}
		\rho^{\mathrm{barcode}}_{\mathrm{even}}\coloneqq \rho_0(2k)=\rho_1(2k+1),\qquad
		\rho^{\mathrm{barcode}}_{\mathrm{odd}}\coloneqq \rho_0(2k+1)=\rho_1(2k+2),
	\end{equation*}
	and $\rho^{\mathrm{barcode}}_{\mathrm{even}}+\rho^{\mathrm{barcode}}_{\mathrm{odd}}=1$.

	The pre-limit barcode density has the following asymptotic behavior
	for all $t\in \mathbb{Z}$:
	\begin{equation*}
		\lim_{L\to\infty}
		\rho^{\mathrm{barcode}}_{(L)}(t)
		=
		\begin{cases}
			\rho^{\mathrm{barcode}}_{\mathrm{even}}, & \text{if } t \text{ is even};\\
			\rho^{\mathrm{barcode}}_{\mathrm{odd}}, & \text{if } t \text{ is odd}.
		\end{cases}
	\end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition prop:F_upper_bound of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Let $\|A_N\|_{\mathrm{op}} = a$. Under Assumption (itm:B1 of the paper) in Definition (mixingdef of the paper), the diagram functions defined in (equation equ:F_formula of the paper) satisfy the following upper bounds.
\begin{enumerate}[label=(\roman*)]
    \item 
        If $\Gamma\in \mathscr{D}_{s;\beta}^*$  is a diagram without open edges,  then
         \begin{equation}
        \big|F_{\Gamma}(\{n_j\})\big|\le N\big(b_n\big)^{|E|-|V|+1}\frac{n^{|V|-1}}{(|V|-1)!}.
    \end{equation}
    \item  If   $\Gamma\in\mathscr{D}_{s;\beta}^{*}$ is a diagram with at least one open edge,  then  \begin{equation}
        \big|F_{\Gamma}(\{n_j\})\big|\le (1+a^n)r^{|V_{\mathrm{b}}|}\big(b_n\big)^{|E_{\mathrm{int}}|-|V_{\mathrm{int}}|}\frac{n^{|V|}}{(|V|)!}.
    \end{equation}
\end{enumerate}

