[Lemma 16 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] Suppose that $f_1, f_2, g: \Z^n \to \R$ are nonnegative and bounded, where (i) $f_1$ is symmetric and positive definite, (ii) $f_2 \le f_1$ on $\Omega_n^K$, and (iii) $f_2 = f_1$ on $\Omega_n^1 = \Z^{(n)}$. Then for any $t \ge 0$, 
\begin{align*}
	0&\le \sum_{\bx \in \Z^n} f_1(\bx) U_n^K(t) g(\bx) - \sum_{\bx \in \Omega_n^K} f_2(\bx) V_n^K(t) g(\bx) \\
	&\le \sum_{\bx \in \Omega^1_n} g(\bx) \big[U_n^K(t) - V_n^K(t)\big] f_1(\bx)  + \sum_{\bx \in (\Omega_n^1)^c} g(\bx) U_n^K(t) f_1(\bx),  
\end{align*}
provided that all sums converge.

[Thm 82 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $j\geq 0$.
For $\varepsilon>0$, set
\begin{displaymath}
\Ns_{\varepsilon}(\clus_j) = \{ z\in \inter(\Gamma_j)\setminus \clus_j \vert 
\CR(z,\inter(\Gamma_j)\setminus \clus_j)<\varepsilon \CR(z,\inter(\Gamma_j))\},
\end{displaymath}
\begin{displaymath}
\widetilde{\Ns}_{\varepsilon}(\clus_j)
= \{ z\in \inter(\Gamma_j)\setminus \clus_j \vert \CR(z,\inter(\Gamma_j)\setminus \clus_j)<\varepsilon\}.
\end{displaymath}
Then, for every $N\geq 0$,
\begin{displaymath}
\ind_{\Ns_{\varepsilon}(\clus_j)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\psi_{2k+1,j}}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+ o(\vert\log\varepsilon\vert^{-(N+1/2)}),
\end{displaymath}
where $o(\vert\log\varepsilon\vert^{-(N+1/2)})$ is in the sense
$L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Further,
\begin{displaymath}
\ind_{\widetilde{\Ns}_{\varepsilon}(\clus_j)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\tilde{\psi}_{2k+1,j}}{\big(\frac{1}{2\pi}
\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+ o(\vert\log\varepsilon\vert^{-(N+1/2)}),
\end{displaymath}
where
\begin{displaymath}
\tilde{\psi}_{2k+1,j} = 
\sum_{j=0}^{k} \dfrac{(2k+1)!}{2^{j} j! (2(k-j)+1)!}
\,\Big(\dfrac{1}{2\pi} \log \CR(z,\inter(\Gamma_j))\Big)^{j}\,\psi_{2(k-j)+1,j}.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

