[Lemma C(a)-def-2 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] With $f, \phi, u_\phi,  C(f, \alpha)$ given as in Lemma (C(a) definition of the paper), it holds that, as $t\to \infty$\footnote{The range of integration for (equation second-def-C(a) of the paper) in [Lemma 9.10-[Bovier_book]] is given to be $(0,\infty)$. However, since $u_{\phi}(t, \sqrt{2}t + x) \to 0$ as $t\to \infty$ pointwise in $x$ (see Lemma (when-does-u-go-to-zero of the paper)), one can easily change the range of integration to $(-\infty, \infty)$ by invoking the dominated convergence theorem.},
\begin{equation}
\frac{1}{\sqrt{2\pi}} \int_{-\infty}^\infty u_\phi(t, \sqrt{2}t + z) e^{(\sqrt{2}+ \alpha)z - \alpha^2t /2} dz \to C(f, \alpha).     
\end{equation}
In particular, for $\lambda >\sqrt{2}$, $\mu =\lambda + \sqrt{\lambda^2-2}$, and $\alpha(\lambda) := \mu -\sqrt{2}$, by substituting $ z = (\lambda -\sqrt{2})t - x$, 
\begin{equation}
    \frac{1}{\sqrt{2\pi}} \int_{-\infty}^{\infty} u_{\phi}(t, \lambda t -x)e^{-\mu x} dx \to C(f, \alpha(\lambda)). 
\end{equation}
Also, for any fixed $x \in \mathbb{R}$ (see equation (9.50) of [Bovier_book]), 
\begin{equation}
    C(f(x + \cdot), \alpha(\lambda)) = e^{\mu x}C(f, \alpha(\lambda)).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 5 (Common-shape asymptotic relative efficiency) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Assume the conditions of \Cref{thm:risk-hessian}. Under a common-shape two-component Weibull mixture, suppose $AB<0$, so that Bayes' rule has the unique simple decision boundary $y_0$. For the $\mathrm{full}$ estimator relative to the estimator based on the completely classified sample,
\begin{equation}
\ARE_{\mathrm{full}:\mathrm{CC}}^{\mathrm{C}}
=
\frac{
g_C(y_0)^\top
\J_{\mathrm{CC},C}^{-1}
g_C(y_0)
}{
g_C(y_0)^\top
\J_{\mathrm{full},C}^{-1}
g_C(y_0)
}.

\end{equation}

[Cor 2 of arXiv:2607.14674, 'On the entropy of the log-normal distribution'] For the family of densities $g_r$ from \eqref{eq:SC} we have 
\begin{equation}
H[g]<\max_{r\in[-1,1]}H[g_r]
\end{equation}
and the maximum is realized for a unique number $0<r_0<\alpha/\beta_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem comparison-result of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Fix $T > 0$ and assume $f,g: \mathbb{D}([0,T], \mathcal{M}) \to [0,\infty]$ satisfy for all $x \in \mathcal{M}$:
    \begin{gather}
        \mathbb{E}[f(\{X_s^x\}_{s \leq T})] \leq \mathbb{E}[g(\{X_s^x\}_{s \leq T})] \,,
    \\

        \limsup_{t \to \infty} \mathbb{E}\Big[\frac{1}{t}\int_0^t f(\{X_r^x\}_{s\leq r \leq s+T})^2 + g(\{X_s^x\}_{s \leq r \leq s+T})^2ds\Big] < \infty \,.
    \end{gather}
    Then
    \begin{equation}
        \limsup_{t \to \infty} \frac{1}{t}\int_0^t f(\{X_r^x\}_{s\leq r \leq s+T})ds \leq \limsup_{t \to \infty} \frac{1}{t}\int_0^t g(\{X_r^x\}_{s\leq r \leq s+T})ds \,.
    \end{equation}

    Furthermore, if $f$ has the form $f(\phi) = \int_0^T \hat f(\phi(s))ds$ where $\hat f: \mathcal{M} \to [0,\infty]$, $g_2: \mathbb{D}([0,T],\mathcal{M}) \to [0,\infty)$ satisfies $g(\phi) \leq \frac{T}{2}\hat f(\phi(0)) + g_2(\phi)$, and (equation eq-compare-var of the paper) also holds with $g$ replaced by $g_2$, then
    $$\limsup_{t \to \infty} \frac{1}{t}\int_0^t \hat f(X_s^x)ds \leq \frac{2}{T}\limsup_{t \to \infty} \frac{1}{t}\int_0^t g_2(\{X_r^x\}_{s\leq r \leq s+T})ds \,.$$

[Theorem 11 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $p\in[1,\infty]$ and let $\f\in\M_p$. Then 
\begin{equation*}
    Q\coloneqq\bs{\nu\in2^\N;\osc f_n(\nu)>0}
\end{equation*}
is not co-$\sigma$-porous in $(2^\N,\rhoexp)$.

[Proposition 14 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{prop:compactness_space_fluct}
    For each $\tau\in(0,1)$,
    \begin{align*}
        \sup_{t\in [0,T]}\|\xi^{\tau}_t\|_{H^{-3}}&\leq
        Ke^{K\mathcal A_T^\tau}
        \left(1+\int_0^T\|A^\tau_r\|^4_{W^{2,\infty}}dr\right)
        \mathcal N_T^\tau
         \quad \mathbb{P}-a.s.
\end{align*}
for some positive non-random constant $K>0$ independent of $\tau.$

