body:
[Definition def:Lipschitz_width of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] {petrova2023lipschitz}}]

Let $(\mathcal{X},\|\cdot\|_{\mathcal{X}})$ be a Banach space, let
$\mathcal K\subseteq \mathcal{X}$ be bounded, let $n\in\mathbb N_+$, and let
$\gamma\ge 0$.  
For each fixed norm $\|\cdot\|_{Y_n}$ on $\mathbb{R}^n$; the $\|\cdot\|_{Y_n}$-Lipschitz width of $\mathcal{K}$ is defined\footnote{We denote the  closed unit ball
$
    B_{Y_n}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \{y\in\mathbb{R}^n:\|y\|_{Y_n}\le 1\}
$ if a normed space $(\mathbb{R}^n,\|\cdot\|_{Y_n})$.}~
by
\begin{equation}

    d^\gamma(\mathcal K,Y_n)_{\mathcal{X}}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \inf_{\Phi}
        \sup_{f\in\mathcal K}
            \inf_{y\in B_{Y_n}}
                \|f-\Phi(y)\|_{\mathcal{X}},
\end{equation}
where the outer infimum in~(equation eq:def_LipWidth of the paper) is taken over all $\gamma$-Lipchitz maps
$
    \Phi:B_{Y_n}\to\mathcal{X}
$.
The $n$-th Lipschitz width of $\mathcal K$ is obtained by further minimizing over all norms $\|\cdot\|_{Y_n}$ on $\mathbb{R}^n$; i.e.\
\begin{equation}

    d^\gamma_n(\mathcal K)_{\mathcal{X}}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \inf\big\{
        d^\gamma(\mathcal K,Y_n)_{\mathcal{X}}
    :
    \,
        \|\cdot\|_{Y_n} 
            \text{ a norm on } 
        \mathbb{R}^n
    \big\}
.
\end{equation}

[Lemma 14 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Let $f(u)=|u|^{-\beta}$ be the Riesz kernel with $0<\beta<3$. For all positive parameters $a,b$ such that $a+b=3-\beta$, the following statements hold.
\begin{enumerate}
    \item For all $u,\xi\in\mathbb{R}^3$ and $h\in\mathbb{R}$,
    \begin{align}
        f(u+h\xi)-f(u)
        =  |h| ^b \int_{\mathbb{R}^3} |u-hw|^{a-3}
        \bigl(|w+\xi|^{\,b-3}-|w|^{\,b-3}\bigr)\,\mathrm{d}w .
    \end{align}

    \item If, in addition, $|\xi|=1$, then
    \begin{align}
        \bigl|f(u+h\xi)+f(u-h\xi)-2f(u)\bigr|
        \le  |h| ^b \int_{\mathbb{R}^3}& |u-hw|^{a-3}\\
        &\notag \times \bigl||w+\xi|^{\,b-3}+|w-\xi|^{\,b-3}-2|w|^{\,b-3}\bigr|\,\mathrm{d}w .
    \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 of arXiv:2609.02173, 'Bounding Selmer Groups of Superelliptic Jacobians via Class Groups'] Assume Hypothesis~\ref{hyp:local}. Then
\[
\begin{aligned}
\dim_{\mathbb F_p}\operatorname{Cl}(L)[p]_{N\equiv0}
-\sum_{v\mid p}
\left(r_v-1-\dim_{\mathbb F_p}W_v\right)
&\leq
\dim_{\mathbb F_p}\operatorname{Sel}_{\Pi}(J/K) \\
&\leq
\dim_{\mathbb F_p}\operatorname{Cl}(L)[p]_{N\equiv0}
+g[K:\mathbb Q(\zeta_p)].
\end{aligned}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma saddles of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] Assume that $x>0$. Let
$u_k(x)=-W_{k} \left(\!-\frac{1}{ex}\right)$ and
\begin{align}
z_k(x,u)=1+\frac{1}{u}W_{k}(-xue^{-u})\:.
\end{align}
\begin{itemize}
\item[(a)] If $x>1$ and $u>0$ then the function $f(z)$
has two saddles $z_0(x,u)$ and $z_{-1}(x,u)$. These saddles are complex conjugated if $u_0(x)<u<  u_{-1}(x)$, otherwise they are real; furthermore, $z_0(x,u)=z_{-1}(x,u)$ if $u=u_0(x)$ or $u= z_{-1}(x,u)$.
\item[(b)] If $x=1$ then for every $u>0$ the function $f(z)$ has one saddle given by $z_{-1}(1,u)$ if $0<u\le 1$ and by $z_{0}(1,u)$ if $u\ge  1$.
This saddle is real.
\item[(c)]
For every $0<x<1$ and $u>0$ the function $f(z)$ has two saddles $z_0(x,u)$ and $z_{-1}(x,u)$. These saddles are real.
\end{itemize}

