\end{equation*}
Now, writing the left-hand side of the inequality as $\binom{c+d-2}{c-1}\binom{2n-c-d}{n-c}$, we get
\begin{align*} 
 f_B(1,1) &= 2\binom{2n-2}{n-1} -2 \binom{c+d-2}{c-1}\binom{2n-c-d}{n-c} \\[1ex]
 &> 2\binom{2n-2}{n-1} - \frac23 \binom{2n-2}{n-1} = \frac43 \binom{2n-2}{n-1}. 
\end{align*}
On the other hand,
\[ f_B(A)\le f(A) < \frac13 \binom{2n}{n} = \frac{2(2n-1)}{3n} \binom{2n-2}{n-1} < \frac43 \binom{2n-2}{n-1}, ...","release_manifest_digest":"sha256:54b3cd62e2bdbf777a1db4a8c2110651f0ec789bc40c1143a92a9a05d891cefe","revision_digest":"sha256:b890f394b247608d3f52310ce7c37dc088fb41b61afae476ffe40561615de014","source_id":"arxiv:2609.01562","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

