[Lem spectral_NS of arXiv:2606.29829, ''] {[Forsstrom_arXiv]}
	Consider the continuous-time Markov chain $(X_n(t),\Omega_n,\pi_n)$ from above, and Boolean functions $\mathfrak{f}_n:\Omega_n\rightarrow\{0, 1\},\;n\geq 1$. The sequence $\{\mathfrak{f}_n\}_n$ is noise sensitive with respect to $\{(X_n(t),\Omega_n,\pi_n)\}_n$ if and only if, for every integer $k > 0$,
	\[\lim_{n\rightarrow\infty}\sum_{j:\;\theta_{n,1}\leq\theta_{n,j}<k\theta_{n,1}}|\langle \mathfrak{f}_n,\psi_{n,j}\rangle|^2=0.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2609.02327, 'On the counting function of square-full numbers'] Let $k \ge 2$ be any integer.
			For $\Re (s) > \frac {1}{k}$, we have
			\begin{equation}
				F_k(s) := \sum_{n=1}^{\infty}\frac{f_k(n)}{n^s}=\prod \limits_{p} \left ( 1 + \frac {p^{-ks}}{1-p^{-s}} \right ).
			\end{equation}
			In particular,
			\begin{equation}
				F_2(s) := \sum_{n=1}^{\infty}\frac{f_2(n)}{n^s}= \frac {\zeta (2s) \zeta (3s)}{\zeta (6s)}.
			\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:T2-limit of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] We have
\begin{equation}
    |T_{2, n, q}|
    =
    \begin{cases}
        O(n^{-1})        & \text{if } q \in [-1,\,0), \\
        O(n^{-1}\log n)  & \text{if } q = 0, \\
        O(n^{q-1})       & \text{if } q \in (0,\,1).
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 17 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] (\cite[p. 14]{adrs})
  The colligation is called closely inner connected if
  \begin{equation}
    \mathfrak H=\bigvee\left\{{\rm ran}\,A^pB\,:\, p\ge 0\right\}.
  \end{equation}
    The realization is called closely outer connected if
