[Defn integ1 of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Suppose that $(\Omega,{\mathscr{B}},{\mathbb{P}})$ is a complete probability space endowed with the $\sigma$-algebra generated by $(B^{i}(t)\otimes W^{Q,i}(t))_{t\in[0,T],i=1\ldots,N}$ and that is still denoted as $({\mathscr{F}}_{t})_{t\in[0,T]}$. We say that an ${\mathscr{F}}(U)$-valued predictable process $\lambda^{i}(t)$, $t\in[0,T]$, is a weak solution to 

\begin{align}
&{\rm d}\lambda^{i}(t)= {\mathbb R}(X^i(t),\lambda^i(t),\mu^{N}(t))\,{\rm d} t+
\sqrt{2\sigma_\lambda}\,\Pi_{\lambda^i(t)}\,{\rm d} W^{Q,i}(t)   
\end{align}
if  for all $x^{\ast}\in ({\mathscr{F}}(U))^{\ast}$

\begin{align}
\nm{\lambda^{i}(t),x^{\ast}}=\nm{\lambda^{i}(0),x^{\ast}}+ \int_{0}^{t}\nm{{\mathbb R}(X^i(s),\lambda^i(s),\mu^{N}(s)),x^{\ast}}{\rm d} s+ \sqrt{2\sigma}T_{{\mathbbm{1}}_{i}}^{t}x^{\ast}
\end{align}
where ${\mathbbm{1}}_{i}\in {\mathcal H}_{Q}(L({\mathscr{F}}(U),{\mathscr{F}}(U)))$ denotes the projector operator $\Pi_{\lambda^{i}}$. Moreover, we say that $(\lambda^{i}(t))_{t\in[0,T]}$ is a strong solution if 
\begin{align}
\lambda^{i}(t)=\lambda^{i}(0)+ \int_{0}^{t}{\mathbb R}(X^i(s),\lambda^i(s),\mu^{N}(s)){\rm d} s+ \sqrt{2\sigma}\int_{0}^{t}\Pi_{\lambda^{i}(s)}{\rm d} s \hskip 0,4cm \text{${\mathbb{P}}$-a.s..}
\end{align}

[Proposition 5 of arXiv:2604.24390, 'Weak solutions to distribution-dependent stochastic Volterra equations'] Suppose that $(\mu_0,b,\sigma,K_b,K_\sigma)$ satisfy Assumption~\ref{ass:short}. Then, the following statements are equivalent.
  \begin{enumerate}
    \item[(i)] There exists a weak solution $((X,B),(\Omega,\mathcal{F},\mathbb{P}),(\mathcal{F}_t)_{t\in [0,T]})$ to the distribution-dependent SVE~\eqref{eq:MVSVE} in the sense of Definition~\ref{def:weak solution}.

    \item[(ii)] There exists a solution $(Z,(\Omega,\mathcal{F},(\mathcal{F}_t)_{t\in [0,T]},\mathbb{P}))$ to the distribution-dependent Volterra local martingale problem in the sense of Definition~\ref{def: MP for stoch process}.

    \item[(iii)] There exists a solution $P$ to the distribution-dependent Volterra local martingale problem in the sense of Definition~\ref{def:martproblem_new}.
  \end{enumerate}

