\end{align}

[Lemma thm:ldsde-comparison of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Suppose Assumption (asp:potential of the paper) holds. Let $\mu,\nu\in C([s,\8);\mathcal P_2(\mathbb R))$ and $T>0$.
Assume
\begin{equation}
    \int_{\mathbb R}x\mathop{}\!\mathrm{d} \mu_t(x)\leq \int_{\mathbb R}x\mathop{}\!\mathrm{d} \nu_t(x), \ \text{ for all } \ t\in [s,s+T].
\end{equation}
If $\xi,\eta\in L^2(\Omega,\mathcal F_s,\mathbf P)$ and $\mathcal L(\xi)\leq_{\mathrm{st}}\mathcal L(\eta)$, then $\mathcal L(X_t^{s,\mu,\xi})\leq_{\mathrm{st}}\mathcal L(Y_t^{s,\nu,\eta})$ for all $t\in [s,s+T]$.

