[Lem 16 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $p\in\N$ with $p\geq 3$ and $q\in\N$ with $q\leq p-1$. For any $\delta>0$ there exist $C<\infty$, independent of $T$, $\max\{1,\frac{p}{q}2(\frac{q}{p}-\frac{2}{p}+2)^{-1}\}<\beta<\frac{p}{q}$ and $0<\varepsilon\leq \frac{(p-2)\beta}{2(p-q\beta)}$  such that for $\alpha\in\{1,2\}^{p-k}$ and $\gamma\in\{1,2\}^q$
     \begin{align*}
        &|(\int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_{p-q}}))(\partial_{\gamma_1} Z_T(u)...\partial_{\gamma_q}Z_T(u))|\\
        &\lesssim \Vert\int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_{p-q}})\Vert_{W^{-\varepsilon,\frac{\beta}{\beta-1}}}\Vert  \nabla Z_T(u)\Vert_{W^{\varepsilon,\frac{p\beta}{p-(q-1)\beta}}}\Vert \nabla Z_T(u)\Vert_{L^p}^{q-1}
    \end{align*}
    and
    \begin{align*}
       &\mathbb{E}\left[ |(\int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_{p-q}}))(\partial_{\gamma_1} Z_T(u)...\partial_{\gamma_q}Z_T(u))|\right]\\
       &\leq C+\delta\mathbb{E}\left[\Vert \nabla Z_T(u)\Vert_{L^p}^p+\frac{1}{2}\Vert u\Vert_\mathcal{H}^2\right].
    \end{align*}

