body:
[Theo thm:near-critical-RSW-random-interacting of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Consider the $t$-weakly random Ising model on $\Lambda_n$ whose coupling constants are given by (equation eq:interacting-model of the paper). Then there exist positive constants $c_1>0$ and $c_2>0 $ such that for any $0\leq t \leq c_2.\log(n)^{-2}$, one has
\begin{equation}
	\mathbf{P}\Bigg[ \mathbb{P}^{\textnormal{free}}_{\Lambda_n,\omega,t} \big( \textnormal{There exist an open circuit in } \mathrm{A}_{\frac{n}{2},n} \big) > c_1  \Bigg] \geq 1-O(\frac{1}{n^4}).
\end{equation}
Moreover, for this interacting model, there exist a large enough contant $C>0$ such that if $t_n=\log(n)^{-C}$  the analog of Theorems (thm:random-SLE of the paper) and (thm:random-energy-density of the paper) hold. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2608.10415, 'Continuous random variables'] When rolling a usual die $n$ times in a row:
\begin{enumerate}
\item For $f_i=\#i$, we have $E(f_i)=n/6$.

\item For $g_i=i\#i$, we have $E(g_i)=ni/6$.

\item For $h={\rm sum}$, we have $E(h)=3.5n$.
\end{enumerate}

[Theorem 105 (cf.\ {\cite[Theorem 2.5) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {Mak24}}] 
    There exists constants $L, \eta > 0$ such that for $\epsilon \geq n^{-1/4}$ with $\epsilon =o(1)$ and
    \begin{equation*}
        p \not\in \Big[ \frac{1 - \epsilon}{n}, \frac{1+\epsilon}{n}\Big],
    \end{equation*}
    we have that
    \begin{equation}
        \P \Big( \big| \mathcal{C}_2(p) \big| \geq L \log(n) \epsilon^{-2} \Big) = O(n^{-\eta}).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 (Freidlin-Wentzell uniform LDP) of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $\mathcal{K}$ be the family of all compactness subset of $H$. We say sequence $\{X^{\epsilon}_{\cdot;t_0,\xi}\}_{\epsilon>0}\subset \mathcal{E}$ indexed by $\xi \in H$ satisfies the uniform large deviation principle with rate function $\cI_{\xi}$, uniformly in $\mathcal{K}$ if the following two conditions hold:
    \begin{itemize}
        \item [1.] Upper bound. For any $K \in \mathcal{K}$, $\delta>0$ and $s_0>0$,
            \begin{equation*}
                \limsup_{\epsilon \rightarrow 0} \sup_{\xi \in K} \sup_{s \leq s_0} \Big\{ \epsilon \log \P \big( \inf_{\Phi \in \{\Phi \in \mathcal{E}; \, \cI_{\xi}(\Phi) \leq s\} } d_{\mathcal{E}}(X^{\epsilon}_{\cdot;t_0,\xi},\phi) \geq \delta \big) + s \Big\} \leq 0.
            \end{equation*}
        \item [2.] Lower bound. For any $K \in \mathcal{K}$, $\delta>0$ and $s_0>0$,
            \begin{equation*}
                \liminf_{\epsilon \rightarrow 0} \inf_{\xi \in K} \inf_{\{\Phi \in \mathcal{E}; \, \cI_{\xi}(\Phi) \leq s_0\}} \Big\{ \epsilon\,\log \P \big( d_{\mathcal{E}}(X^{\epsilon}_{\cdot;t_0,\xi},\Phi) <\delta \big) + \cI_{\xi}(\Phi) \Big\} \geq 0.
            \end{equation*}
    \end{itemize}

[Thm -3 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] Let $F(S_{t_{1}},\dots S_{t_{N}})$ be a measurable
function with at most polynomial growth at infinity, and 
\[
f(s)=\mathbb{E}[F(S_{t_{1}},\dots,S_{t_{N}})|S_{t_{0}}=s].
\]
Denote
\begin{equation}
J(s,x)=(\partial_{x}H_{0})^{-1}(\partial_{s}H_{0}).
\end{equation}
Then
\begin{equation}
\begin{aligned}\partial_{s^{(l)}}f(s) & =\mathbb{E}\Big[F(S)\Big(\sum_{k=0}^{1}\frac{1}{(\Delta t_{1})^{k/2}}\Theta_{l}^{(k)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})\Big)\Big]\end{aligned}
,
\end{equation}
where
\begin{align}
\Theta_{l}^{(0)}(s,z,x) & =-\sum_{p=1}^{n}\partial_{x^{(p)}}J_{pl}(s,x),\\
\Theta_{l}^{(1)}(s,z,x) & =\sum_{p=1}^{n}z^{(p)}J_{pl}(s,x),
\end{align}
with $s,z,x\in\mathbb{R}^{1\times n}$. Moreover,
\begin{equation}
\begin{aligned}\partial_{s^{(l)}s^{(m)}}^{2}f(s) & =\mathbb{E}\Big[F(S)\Big(\sum_{k=0}^{2}\frac{1}{(\Delta t_{1})^{k/2}}\Lambda_{lm}^{(k)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})\Big)\Big]\end{aligned}
,
\end{equation}
where 
\begin{align}
\Lambda_{lm}^{(0)}(s,z,x) & =\sum_{p,r}\big(\partial_{x^{(r)}}J_{rm}\partial_{x^{(p)}}J_{pl}\big)(s,x)\nonumber \\
 & \quad+\sum_{p,r}\big(J_{rm}\partial_{x^{(r)}x^{(p)}}^{2}J_{pl}\big)(s,x)-\sum_{p}\partial_{s^{(m)}x^{(p)}}^{2}J_{pl}(s,x),\\
\Lambda_{lm}^{(1)}(s,z,x) & =\sum_{p}z^{(p)}\partial_{s^{(m)}}J_{pl}(s,x)-\sum_{p,r}z^{(p)}\big(J_{rm}\partial_{x^{(r)}}J_{pl}\big)(s,x)\nonumber \\
 & \quad-\sum_{p,r}z^{(p)}\big(\partial_{x^{(r)}}J_{rm}\cdot J_{pl}\big)(s,x)-\sum_{p,r}z^{(r)}\big(J_{rm}\cdot\partial_{x^{(p)}}J_{pl}\big)(s,x),\\
\Lambda_{lm}^{(2)}(s,z,x) & =\sum_{p,r}z^{(r)}z^{(p)}(J_{rm}J_{pl}-\delta_{rp}J_{rm}J_{pl})(s,x),
\end{align}
with $s,z,x\in\mathbb{R}^{1\times n}$ and $\delta_{rp}$ being the
Dirac notation. (Proof in the paper; no proof environment follows the statement in the TeX.)

