[Lemma lemma-property-phi of arXiv:2607.08187, 'Asymptotic behaviours of critical branching random walk in $\mathbb{R}^d$'] There exists a positive constant $C_\phi$ such that 
	\begin{align}
		|\phi^{(x)}(u)-\phi^{(x)}(v)|\le C_\phi~|u-v||u^{\alpha-1}+v^{\alpha-1}|,\quad \forall~u,v\in[0,x^{\frac{2}{\alpha-1}}],
	\end{align}
	and for each $K>0$, 
	\begin{align}
		\lim_{x\to \infty}\sup_{u\in [0,K]} \left| 
		u^{-\alpha}\phi^{(x)}(u)
		-\mathcal{C}(\alpha) \right| = 0,
	\end{align}
	where the constant $\mathcal{C}(\alpha)$ is defined in (equation Stable-branching of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn root-finding of arXiv:2411.14336, 'Finding the root in random nearest neighbor trees'] A root finding algorithm for a random tree $T_n$ generated via a geometric process on $\mathbf{T}^d$ is given inputs $\varepsilon \in (0,1)$, $d \in \mathbf{N}$, and one of the following:
\begin{itemize}
    \item (Embedded root finding) the unlabeled tree $T_n^\circ$ embedded in $\mathbf{T}^d$;
    \item (Metric root finding) the adjacency matrix of the unlabeled tree $T_n^\circ$, with corresponding edge lengths;
    \item (Graph root finding) only the adjacency matrix of $T_n^\circ$.
\end{itemize}
It outputs a subset of vertices $H_{\mathbf{T}^d}(\varepsilon, T_n^{\circ})$ of size independent of $n$ (only depends on $\varepsilon$), which contains the root with probability $1 - \varepsilon$, i.e., 
\begin{equation}
  \liminf_{n \to \infty} \mathbf{P}_{T_n}\left\{ 1 \in H_{\mathbf{T}^d}(\varepsilon, T_n^{\circ})\right\} \geq 1 - \varepsilon.
\end{equation}
We refer to $H_{\mathbf{T}^d}(\varepsilon, T_n^{\circ})$ as $H(\varepsilon, n)$ throughout the paper when the underlying metric space $\mathbf{T}^d$ and input unlabeled tree $T_n^{\circ}$ on $n$ vertices are clear from the context.

[Theorem 5 of arXiv:2512.04297, 'Mixing at the Batchelor Scale for White-In-Time Flows'] The analogous statements of Theorem \ref{thm:lower_bound_low_modes} and its two corollaries hold for the three-dimensional model \eqref{spde:3D}.
\begin{enumerate}[(i)]
    \item     For $\kappa\geq 0$ and $f_0\in L_0^2(\tor^3) \setminus \{0\}$, let $f_t$ be the solution to \eqref{spde:3D}. The decay rate of the $L^2$-norm of the six innermost modes is lower bounded by
    \begin{equation}
        \limsup_{t\to \infty} \frac{1}{t} \log \norm{\Pi_{\leq 1}f_t}_{L^2} \geq -(2\pi)^2 \left( 1 + \kappa \right ).
    \end{equation}
    \item The exponential dissipation rate $\lambda_{\omega, f_0}^\kappa$, as given by \eqref{eq:dissipation_rate}, is lower bounded by
    \begin{equation}
        \lambda_{\omega, f_0}^\kappa  \geq -(2\pi)^2 \left(1 + \kappa \right ).
    \end{equation}
    \item     For $s> 0$ the exponential mixing rate without diffusion is of order $1\land s$, that is, there exists a constant $C>0$ such that
    \begin{equation}
        C^{-1} (1\wedge s) \leq \gamma_s \leq C (1\wedge s), \quad \forall\, s>0.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Maruyama_stationary_increments of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] (Maruyama for Gaussian processes with stationary increments)
		Let $B$ be a $\mathbb{R}^{d}$-valued Gaussian process with stationary increments and independent coordinates, with $a_{i}=0$ for $1\leq i \leq d$.
		\begin{itemize}
			\item $B$ is ergodic and weakly-mixing if and only if $\mu_{i}$ is non-atomic for any $1\leq i \leq d$,
			\item $B$ is mixing if and only if
			\begin{equation*}
				V_{a,b}(t) \underset{\|t\|\to +\infty}{\longrightarrow}  0, \quad a,b \in \mathbb{R}^{d},
			\end{equation*}
			where 
			\begin{align*}
				V_{a,b}(t)&=\cov{B_{-a}}{ B_{t+b}-B_{t}}\\
				&=\Sigma_{t+a}+\Sigma_{t+b}-\Sigma_{t+a+b}-\Sigma_{t}.
			\end{align*}
		\end{itemize}
		In particular, if $\mu_{i}$ is absolutely continuous for $1\leq i \leq d$, then $B$ is mixing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:small_time_intro of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 1$, $x\in{\mathbb Z^d}$, and $\varepsilon \in (0, \frac{1}{2} s_0^{-1}]$.
For all $\abs x \ge 2 \sqrt d$, we have
\begin{equation}
\int_0^{T} \mathrm{d} t\, \abs{ I_{t}(x) } ,\;\;
\int_0^{T} \mathrm{d} t\, \rho_t(x;\eta,\Lambda)
\lesssim \sqrt \varepsilon  B(x; \eta) ,
\end{equation}
with constants that depend only on $d, M, K_{\mathrm{IR}}, s_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 (Exact Poissonized identity) of arXiv:2606.29635, 'Extremality and Limit Laws for the Siblings of the Coupon Collector'] For every $N\ge1$, every probability vector $p$, and every $j\ge2$,
\begin{equation}
        \E_p U_j^N=\sum_{k=1}^N\int_0^\infty p_k\e^{-p_kt}\frac{(p_kt)^{j-1}}{(j-1)!}\prod_{i\ne k}(1-\e^{-p_it})\dd t.
\end{equation}

[Definition defi:nuc of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] The choice of $\nu_{c,\infty}^{(\emptyset)}$ is called the critical point and also denote
\begin{align}
	\nu_c = \nu^{(\emptyset)}_{c,\infty}  . 
\end{align}

