[Conjecture of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Using the same notation as in Theorem (thm:diagfluc of the paper), we conjecture that 
\begin{equation*} \begin{split} 
    &{\rm Law} \left( \left(  \frac{\pi^*(t N)}{N^{1/2}}  , \frac{\mathcal{L} \left( tN \mathbf{v}_1+ \pi^*(t N) \mathbf{v}_2 \right)- t\ell N}{\mathsf{\sigma} N^{1/2}}  \right)_{t\in (0,1)}
    \, \bigg| \,  \mathcal{L}(aN, bN)= \ell N \right) \xrightarrow{\textit{f.d.d.}} {\rm Law} \left( (\mathbb{B}^{\mathrm{br}}_2(t), \mathbb{B}^{\mathrm{br}}_1(t) )_{t\in (0,1)} \right)
\end{split} \end{equation*}
where $\mathbb{B}^{\mathrm{br}}_1$ and $\mathbb{B}^{\mathrm{br}}_2$ are correlated Brownian bridges given by (equation eq:defcd of the paper). (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition prop:physical-coagulation-equation of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] For \(\alpha\ge-1\) and every \(k\ge1\),
\begin{equation}

\begin{aligned}
    c_k'(t)
    =\frac{1}{2d(t)}
      \sum_{i=1}^{k-1}K_\alpha(i,k-i)c_i(t)c_{k-i}(t) -\frac{c_k(t)}{d(t)}
      \sum_{j\ge1}K_\alpha(k,j)c_j(t),
\end{aligned}
\end{equation}
with \(c_1(0)=1\) and \(c_k(0)=0\) for \(k\ge2\). Moreover,
\begin{equation}

    d'(t)=-\sum_{k\ge1}k^{-\alpha}c_k(t).
\end{equation}
Equivalently, the particle densities satisfy

\begin{equation}

\begin{aligned}
    V_k'(t)
    &=\frac{k}{2d(t)}\sum_{i=1}^{k-1}
      \frac{K_\alpha(i,k-i)}{i(k-i)}V_i(t)V_{k-i}(t) 
      -\frac{kV_k(t)}{d(t)}\sum_{j\ge1}  \frac{K_\alpha(k,j)}{k j} V_j(t).
\end{aligned}
\end{equation}

