[Lemma 12 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, for $\zeta\in\C^+$, define
        \begin{align}
                \wh\Om(R,\zeta):=I_L+\zeta R+\cals[R]R-\La R. 
        \end{align}
        Then the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item The equation $\wh\Om(R,\zeta)=0$ has a unique solution $\wh\Pi(\zeta)\in\calM_+$. The map $\zeta\mapsto\wh\Pi(\zeta)$ is holomorphic on $\C^+$ and $\Im\wh\Pi(\zeta)>0$ for every $\zeta\in\C^+$.
                \item There exists a unique positive semidefinite matrix-valued measure $\wh V$ on $\R$ such that
                      \begin{align}
                              \wh\Pi(\zeta)=\int_{\R}\frac{\wh V(\dd x)}{x-\zeta},\qquad \wh V(\R)=I_L, \nonumber
                      \end{align}
                      and, for some constant $C_1<\infty$, $\supp\wh V\subset[-C_1,C_1]$.
                \item The measure $\wh V$ satisfies
                      \begin{align}
                              \wh V(B)=J\wh V(-B)J,\qquad J=\begin{pmatrix}I_M & 0    \\
               0   & -I_N\end{pmatrix}, \nonumber
                      \end{align}
                      for every Borel set $B\subset\R$. Consequently, $\avg{\wh V}_L$ is a compactly supported symmetric probability measure on $\R$, and $\avg{\wh\Pi(\zeta)}_L$ is its Stieltjes transform.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 (Dyadic Volterra estimate) of arXiv:2607.10813, '2607.10813'] Let $a,b\in\mathfrak C$ with $a\ne b$, $Q\le c_{\mathrm{ap}}N$, and $0<s<1-2\beta_b$.
\begin{align}
  \norm{\cD^{a;b}_{N,Q}P_Qw}_{C_TH^{s-1}}
  \lesssim{}&N^{-1+2\beta_b}\norm{P_Qw}_{L_T^\infty L^2}\notag\\
  &+N^{-1+2\beta_b}Q^s
    \norm{\partial_tw}_{C_TH^{-1}},
\end{align}
and
\begin{equation}
  \norm{\cD^{a;b}_{N,Q}P_Qw}_{L_T^\infty B_{2,\infty}^{\sigma-1}}
  \lesssim_T
  N^{-1+2\beta_b}
  \paren{Q^{-1}\norm{w}_{L_T^\infty B_{2,\infty}^{\sigma}}
  +\norm{\partial_tw}_{L_T^\infty B_{2,\infty}^{\sigma-1}}}.
\end{equation}
The constants are uniform in $N,Q$ and in the spectral cutoff.  If
$[\mathfrak h_b]_{\beta_b,0}\le H$ and $\parvec$ ranges over a separated
parameter class, the implicit constants are bounded by a constant depending
on $H$ and the parameter class.  The phase-gap constants themselves are
independent of the forcing profiles.

[Lem 9 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Under Assumption~\ref{ass:main}, assuming also that \(b_0>\kappa/2\), it holds that
    \[
    \E\left[ 
    \exp\left\{
    \lambda\int_0^T \Vert X_t\Vert_2^2\,dt
    \right\}
    \right]
    \leq e^{\kappa dT} 
    \E\left[\exp\left\{\frac{\kappa}{2}\Vert X_0\Vert_2^2
    \right\}\right]
    <\infty
    \]
    for any \(0\leq \lambda\leq\kappa^2\) and \(T>0\) fixed. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$. There exists $C>0$ such that the following holds. For every $G$ subgraph of $\mathbb Z^d$, every $\beta\in [\beta_c/2,\beta_c]$, every $J\in (\mathbb R^+)^{E(G)}$ which satisfies $J_{st}\leq \beta$ for every $st\in E(G)$, every $x,y\in V(G)$, and every $zw,uv\in E(G)$,
\begin{equation}
	\langle \sigma_x\sigma_y ; \sigma_z \sigma_w ; \sigma_{u}\sigma_v \rangle_{G,J}\leq C\Big(\langle \sigma_x\sigma_z\rangle_{G,\beta} \langle \sigma_w\sigma_u\rangle_{G,\beta}\langle \sigma_v\sigma_y\rangle_{G,\beta}+\langle \sigma_y\sigma_z\rangle_{G,\beta} \langle \sigma_w\sigma_u\rangle_{G,\beta}\langle \sigma_v\sigma_x\rangle_{G,\beta}\Big).
\end{equation}

