[Lemma lemma_upper and lower for F-KPP of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \begin{enumerate}[label= (\alph*)]
    \item Let $f, \phi, u_\phi$ be as in Proposition (Bramson-psi-estimate-for-one-sided-f of the paper) and $0<\alpha<\beta<\infty$. Then, there exist $t_0\ge 1, C_1, C_2 >0$ such that for all $t \ge t_0$ and $z \in [\alpha t, \beta t]$,
    \begin{equation}
        C_1\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t} \le u_\phi(t,z+\sqrt 2t)\le C_2\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t}.
    \end{equation}
The upper bound in the above holds for $\phi$ with $f\in C_c^+(\mathbb{R})$ as well. 
    \item Let $0< \alpha < \beta < \infty$. Then, there exists $t_0 \geq 1$, $K>0$ large enough and constants $C_1, C_2 >0$ such that for all $t\geq t_0$ and $z\in [\alpha t, \beta t]$,
    \begin{equation}
        C_1\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t} \le u_M(t, \sqrt{2}t + z - K ) - u_M(t, \sqrt{2}t + z + K )\le C_2\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t}.
    \end{equation}
\end{enumerate}

[Conjecture conj:kmixing of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] For $k = o(n)$, the $(d, n, \mu)$ balanced chain with $k$ balls being moved from each urn in each step exhibits cutoff around the time
    \begin{equation}
        \frac{t_{\textup{mix}}^{(n),1}}{k} = \frac{n \log n}{2k \gamma}(1 + o(1)),
    \end{equation}
    where $t_{\textup{mix}}^{(n),1}$ denotes the cutoff time for the corresponding $k = 1$ chain. Furthermore, for $k$ satisfying $\Omega(n) = k = n - \Omega(n)$, the chain exhibits cutoff around its mixing time $t_{\textup{mix}}^{(n),k}$, which is of the same order as the expressions in (equation eq:OrderkSteps of the paper). (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 9 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] As $n\to\infty$,
\begin{equation}
Z_n=\sum_{j\ge n+1}2^j\exp\big(-\eee^{j^2-n^2}/2\big)\eta_j=o\big(\exp\big(-\eee^{2n}/2\big)\big)\quad\text{{\rm a.s.}}
\end{equation}

