[Definition def:laplacian-general of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] The \emph{directed Laplacian operator} of $G$ is the operator $\mathscr{L}^- = \mathscr{L}^-_{G} : L^2(V) \to
    L^2(V)$ given by
    \begin{equation}
        \mathscr{L}^-f \vcentcolon= \frac{1}{2} \sum_{u,v \in V} w(u,v) \left(f(u) - f(v)\right)^+ (e_v - e_u)
    \end{equation}
    for each $f \in L^2(V)$. In this paper, we use the notation $x^{+}:=\max\{x,0\}$, for $x\in \mathbb{R}$.

[Prop 17 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Let $(A_n)_{n \in \BN}$ be a sequence of subsets of $\BZ_{\geq 0}$, and $(r_n)_{n \in \BN}, (\lambda(n))_{n \in \BN}$ be a sequence of positive numbers.
    For $C \in \CC$, let
    \begin{equation*}
        W_{A_n,\lambda(n)}'(C) = \sum_{Y \in \CP_{\lambda(n)}} \mathbf{1}\{\CP_{\lambda(n)}(B(Y;r_n) \setminus \{Y\}) \in A_n\} \cap \{Y \in C\}.
    \end{equation*}
    Define
    \begin{equation*}
        \begin{aligned}
            &I_{1,C}(n) := \lambda(n)^2 \int_C F(dx) \int_{B(x;3r_n) \cap C} F(dy) P[\CP_{\lambda(n)}(B_x^n) \in A_n] P[\CP_{\lambda(n)}(B_y^n) \in A_n],\\
            &I_{2,C}(n) := \lambda(n)^2 \int_C F(dx) \int_{B(x;3r_n) \cap C} F(dy) P[\{\CP_{\lambda(n)}^y(B_x^n) \in A_n\} \cap \{\CP_{\lambda(n)}^x(B_y^n) \in A_n\}],
        \end{aligned}
    \end{equation*}
    where $B_x^n := B(x;r_n)$ and $\CP_{\lambda(n)}^x := \CP_{\lambda(n)} + \delta_x$.
    Then,
    \begin{equation*}
        d_\text{TV}(W_{A_n,\lambda(n)}'(C), \text{Po}(E[W_{A_n,\lambda(n)}'(C)])) \leq \min\left(3, \frac{1}{E[W_{A_n,\lambda(n)}'(C)]}\right) (I_{1,C}(n) + I_{2,C}(n))
    \end{equation*}
    holds.

