[Theorem 2 (Covariance-existence criterion) of arXiv:2607.09994, '2607.09994'] Suppose Assumptions~\ref{ass:stationarity}, \ref{ass:innovations} and \ref{ass:perron-excitation} hold. Then the following are equivalent:
\begin{enumerate}
    \item the stationary solution is square-integrable, \( \mathbb E\|Z\|^2<\infty \);
    \item the second-order spectral radius satisfies \( \rho(\Top)<1 \).
\end{enumerate}
Equivalently,
\begin{equation}
\mathbb E\|Z\|^2<\infty
\quad\Longleftrightarrow\quad
\rho(\Tmat)<1.

\end{equation}

When \eqref{eq:main-equivalence} holds, the regime-weighted second moments \(M_1,\ldots,M_M\) are the unique finite solution of
\begin{equation}
M_j
=
\sum_{i=1}^M p_{ij}A_jM_iA_j^\top+\pi_jQ_j,
\qquad j=1,\ldots,M.

\end{equation}
Equivalently, in vectorised form,
\begin{equation}
\operatorname{vec}(M)
=
\Tmat\operatorname{vec}(M)+q,

\end{equation}
and therefore
\begin{equation}
\operatorname{vec}(M)
=
(I-\Tmat)^{-1}q.

\end{equation}

Moreover, the following second-order quantities are well-defined.
\begin{enumerate}
    \item The covariance matrix is
    \begin{equation}
    \Sigma
    =
    \operatorname{Var}(Z)
    =
    \mathbb E[ZZ^\top]
    =
    \sum_{j=1}^M M_j.

    \end{equation}

    \item For components \(Z^a\) and \(Z^b\),
    \begin{equation}
    \operatorname{Var}(Z^a)=\Sigma_{aa},
    \qquad
    \operatorname{Cov}(Z^a,Z^b)=\Sigma_{ab}.

    \end{equation}

    \item If \(\Sigma_{aa}>0\) and \(\Sigma_{bb}>0\), then
    \begin{equation}
    \operatorname{Corr}(Z^a,Z^b)
    =
    \frac{\Sigma_{ab}}{\sqrt{\Sigma_{aa}\Sigma_{bb}}}.

    \end{equation}
\end{enumerate}

[Lemma eq:useful_bound_1 of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:useful_bounds}
