body:
[Lem 31 (Spatial Markov property at level $7\ell$) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Fix $\ell\in\mathrm{GoodScales}$ and $k,k'\geq 7\ell+1$. Let $\DMC$ and $\DMC'$ be defined under the black-golden coupling $\mathbb{P}_{k,k'}$ of~\cref{defn:black-golden coupling}. Then the following assertions are true:
\begin{enumerate}
\item 
For $m\in\intervalleentier{7\ell +1}{k}$ and  $m'\in\intervalleentier{7\ell +1}{k'}$, the $\Gf_\ell$-conditional distribution of $(\DMC(H_{7\ell}), \DMC'(H'_{7\ell}))$ on the event $\{\DMC(H_{7\ell}-1)=m, \DMC'(H'_{7\ell}-1)=m'\}$ is given by
\begin{align}
\Law\left((\DMC(H_{7\ell}), \DMC'(H'_{7\ell})) \ | \  \Gf_\ell \right) = \Law((B_m,B_{m'}) \ | \ B_m \leq 7\ell, B'_m \leq 7\ell).
\end{align}
\item Conditionally on $\sigma(\Gf_{\ell}, (\DMC(H_{7\ell}),\DMC'(H'_{7\ell}))$, the chains $(\DMC(H_{7\ell}+t))_{t\geq 0}$ and $(\DMC'(H'_{7\ell}+t))_{t\geq 0}$ have the distribution of $\DMC$ and $\DMC'$ under the black-golden coupling $\bbP_{\DMC(H_{7\ell}),\DMC'(H'_{7\ell})}$.
\end{enumerate}

[Prop 22 of arXiv:2607.21759, 'Marchenko--Pastur law for tensor powers of exchangeable unconditional vectors'] For each $n$, let $\mathbf X^{(n)} = (X_1,\dotsc,X_n)$ be an exchangeable vector, and let $d = o(\sqrt n)$. Assume \cref{cond:2nd-4th-compare}. As $n \to \infty$, \begin{equation} 
        \liminf_n \E(X_1^2 \dotsm X_{2d}^2) - \bigl(\E X_1^2\dotsm X_d^2\bigr)^2 \geq 0.
    \end{equation} This means precisely that $X_1^2 X_2^2\dotsm X_{d}^2$ and $X_{d+1}^2 X_{d+2}^2\dotsm X_{2d}^2$ cannot be asymptotically negatively correlated.

