[Theorem 16 (Banach contraction principle) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $\left(\mathcal{X},\rho\right)$ be a complete metric space. Let $\Psi:\mathcal{X}\rightarrow\mathcal{X}$ be a contraction mapping over $\mathcal{X}$. Then $\Psi$ admits a unique fixed point $x^*\in\mathcal{X}$, i.e.,
    \begin{equation*}
        \exists!\,x^*\in\mathcal{X} \,:\, x^*=\Psi(x^*).
    \end{equation*}

[Lemma 10 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] For every integer $q\geq0$, the function $h_q$ in~\cref{eq:hq-definition} satisfies
\begin{equation}
  \Lip(h_q)=A^q,
  \qquad
  \frac{1}{2A^q}
  \leq \Delta(h_q)
  \leq \frac{1}{A^q+1}
  \leq \frac{1}{A^q},
  \qquad
  A = \frac{15}{8}.

\end{equation}

[Lem 11 of arXiv:2605.30779, '2605.30779'] Let $X$ be an $N$-dimensional real symmetric (resp.~complex Hermitian) matrix with distinct eigenvalues $\mu_1 > \dotsb > \mu_N$, $\w$ be a unit $N$-dimensional column vector in $\realR^N$ (resp.~$\compC^N$), $d$ be a real number, and $Y = X + d \w \w^{\top}$ (resp.~$Y = X + d \w \w^*$) has distinct eigenvalues $\lambda_1 > \dotsb > \lambda_N$. We assume $\{ \mu_j \}^N_{j = 1} \cup \{ \lambda_j \}^N_{j = 1}$ consists of $2N$ distinct real numbers, and for any $k = 1, \dotsc, N$, $\x_k$ is a unit eigenvector of $Y$ associated with $\lambda_k$. Then
  \begin{equation}
    \w^\top(\lambda_k I - X)^{-1} \w =\frac{1}{d},
  \end{equation}
  and
  \begin{equation} 
    \lvert \langle \x_k, \w \rangle \rvert^2 = \frac{\lvert \langle \w, (\lambda_k I - X)^{-1} \w \rangle \rvert^2}{\langle \w, (\lambda_k I - X)^{-2} \w \rangle} = \frac{1}{d^2} \frac{1}{\langle \w, (\lambda_k I - X)^{-2} \w \rangle}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:sequential-consistency of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] For gamble space $(\Omega,\mathcal{Z})$ and measurable variable $X:\Omega\to\overline{\mathbb{R}}$, we define
  \begin{align}
    \overline{\mathbb{E}}^0 X &:= \sup_{P\in\Delta_0(\mathcal{Z})} \mathbb{E}_P X~,
  \end{align}
  and $\underline{\mathbb{E}}^0 X := -\overline{\mathbb{E}}^0(-X)$.
  Similarly, for a sequential gamble space $(\mathcal{Y},\hat\mathcal{Z},T)$, we define
  \begin{align}
    \overline{\mathbb{E}}^* X &:= \sup_{P\in\Delta_0^T(\hat\mathcal{Z})} \mathbb{E}_P X~,
  \end{align}
  and $\underline{\mathbb{E}}^* X := - \overline{\mathbb{E}}^*(-X)$.
  In both cases, if $\mathbb{E}_P X$ is undefined, we define it to be $\infty$.

[Prop p:300.1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $\gamma$ is chosen small enough, then, given any $0 < \eta' < \eta < \frac{1}{2}$ small enough (depending only on $\gamma$), for each $u,k \geq 0$ there exists a probability measure ${\rm O}^{k}_u$ on $\mathbb{R}^{{\rm Q}(k)}$ such~that 
\begin{equation}
\frac{\big|{\mathbf R}_n^{k}(u)\big|}{\sqrt{n}}
\bigg|\int f_k\,{\rm d} \mathcal{O}^{k}_{n,u} - \int f_k\, {\rm d} (\widehat{\Theta}^k_{n,u} \otimes {\rm O}^{k}_u)\bigg| \overset{\mathbb{P}} \longrightarrow \, 0 \,,
\end{equation}
as $n \to \infty$ followed by $k \to \infty$, uniformly over all measurable $f_k: {\rm D} \times \mathbb{R}^{{\rm Q}(k)} \to \mathbb{R}$ with $\|f_k\|_\infty \leq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

