[Theorem 8 (Refined \cref{thm:intro-static}) of arXiv:2608.31008, 'Stability of gravitational instantons with a bounded Killing vector field'] Let $(M^4,g)$ be connected, oriented and Ricci-flat, and let $K\not\equiv0$ be a
Killing field satisfying
\begin{equation}
 \kappa\wedge d\kappa=0.
\end{equation}
Put $F=d\kappa$, $F^\pm$ its $\pm$-selfdual parts, and $h=F^-\circ F^+$.  Then $h$ is TT and
\begin{equation}
 \langle\cE_gh,h\rangle
 =-\frac12\Big|d\Big(\tfrac{|F|^2}{2}\Big)\Big|^2.
\end{equation}
If the right-hand side vanishes identically, then $g$ is flat.

[Lemma lemma-3.9 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Assume~$\beta=\beta_\text{\rm c}$. There exists a constant~$C'>0$ such that for all~$n\ge k\ge0$,
\begin{equation}

\frac{a_k(1)}{a_k(0)}
\ge\frac{C'}{\sqrt{1+k}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 99 (Theorem 1 in \cite{MP05}) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] For $u,v \in V(G)$, let $q_t(u,v)$ be the $t$-step transition kernel of the lazy random walk on $(G, \weight)$. 
    For any $t>1$ and $\chi \in (0,1)$ such that 
        \begin{equation*}
        t \geq 1 + \int_{4 \min\{\pi(u), \pi(v)\}}^{\frac{4}{\chi}} \frac{4}{r \Phi_{(G, \weight)}^2(r)} dr,
    \end{equation*}
    we have 
        \begin{equation*}
        \Big| \frac{q_t(u,v)}{\pi(v)} -1 \Big| \leq \chi.
    \end{equation*}
    Furthermore,
    \begin{equation*}
        \tmix \leq 1 + \int_{4 \pi_{\mathrm{min}}}^{8} \frac{4}{r \Phi_{(G, \weight)}^2(r)} dr.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma threeeventsnsigma of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $A_n$ be as in Lemma (corollary3.6chap9 of the paper). Let $\Delta>0,\kappa>0$ and $\sigma\in(0,1)$ be fixed constants. Fix any $\lambda_1,\lambda_2\in[-(2-\kappa)\sqrt{n},(2-\kappa)\sqrt{n}]$ satisfying $|\lambda_1-\lambda_2|\geq\Delta n^{\sigma-\frac{1}{2}}$. Then \begin{enumerate}
\item We can find some constant $\Delta_0>0$ and some $C_0>0$ depending on $\Delta$ such that, for any $1\leq k\leq \Delta_0n^\sigma$ and $j\neq i$, we have
    \begin{equation}
        \mathbb{P}(c_j(i;k)\leq C_0n^\sigma)\leq \exp(-\Omega(n^{\sigma/2})).
    \end{equation} \item For any $i\neq j\in\{1,2\}$, on an event with probability $1-e^{-\Omega(n^{\sigma/2})},$ we have
\begin{equation}
    \frac{\mu_{c_i(j;1)}(\lambda_i)}{\mu_1(\lambda_i)}\leq 10^{-1}.
\end{equation}
\item Fix a given $(\theta_1,
\theta_2)\in\mathbb{R}^2$ and some $j\neq i\in\{1,2\}$ that satisfy $|\frac{\theta_j}{\mu_1(\lambda_j)}|\geq |\frac{\theta_i}{\mu_1(\lambda_i)}|$. We can find some $\Delta_1>0$ depending on $\Delta$ such that on an event with probability $1-e^{-\Omega(n^{\sigma/2})},$ for any $1\leq k\leq \Delta_1n^{\sigma}$, we have 
\begin{equation}
   |\theta_i| \frac{\mu_{c_i(j;k)}(\lambda_i)}{\mu_1(\lambda_i)}\leq 10^{-1}|\theta_j|\frac{\mu_k(\lambda_j)}{\mu_1(\lambda_j)}
\end{equation}
\end{enumerate} The constant term in the error $\exp(-\Omega(n^{\sigma/2}))$ depends on all the constants $\Delta,\kappa,\sigma>0$.

[Proposition 27 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For every compact connected two-step pair,
		\begin{equation}
			\log\det\nolimits_\zeta'(-\Delta_{\pLie})
			=\gamma_{\mathrm E}
			-C_{G,L}\mathscr A_{Q/2,1}(\beta_{G,L})
			-\mathcal G_{G,L}.
		\end{equation}
		Equivalently,
		\begin{equation}
			\log\det\nolimits_\zeta'(-\Delta_{\pLie})
			=-\operatorname*{FP}_{\varepsilon\downarrow0}
			\int_\varepsilon^\infty\frac{p_t(e)-1}{t}\,\mathrm dt
			-\gamma_{\mathrm E}\zeta_{\pLie}(0),
		\end{equation}
		where $\operatorname{FP}$ denotes the constant term after the power and logarithmic divergences prescribed by \eqref{zeta:complete-local-heat-equation} have been removed.

[Corollary cor:plateau of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>8$ and $L \ge L_0$.
There exists $C_1 > 0$ such that for $r$ sufficiently large
and $p_* = p_c - C_1 V^{-1/2}$,
\begin{equation} 
G_{p_*} ^{ \mathbb{T} }(x) \asymp \frac{1}{\nnnorm x^{d-2}} + \frac{1}{V^{3/4}}
	\qquad (x\in \mathbb{T}_r^d)
\end{equation}
and
\begin{equation}
    \chi^{\mathbb{T}}(p_*) \asymp V^{1/4}.
\end{equation}

[Definition def:fringe of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For a vertex $v\in [n]$, we call the subtree of $v$ in the rooted tree $(T_n, 1)$ the fringe tree attached to $v$, or the fringe tree of $v$. For its size, we write 
\begin{equation}
    \mathrm{Fr}_n(v):=|(T_n, 1)_{v\downarrow}|=|(T_n, \mathrm{pa}(v))_{v\downarrow}|,
\end{equation}
    where the last equality holds for all $v \geq 2$.
    Furthermore, given $m \in \mathbb{N}$ and $v \in [n]$, we define the fringe tree of $v$ witnessed after time $m$ as the set of vertices in $(T_n, 1)_{v\downarrow}$ whose unique path to $v$ in $T_n$ has no edges  that arrived before time $m+1$.  We write $\mathrm{Fr}_n^{>m}(v)$ for its size.

