        \PP{\forall w \ge 0\,:\,|{\mathbf C}_{T,w}| \le n\,  \exp\Big(-\Big(\frac{3}{2}\Big)^{w+\tau}\Big)} = 1- \log(n)^{-\omega(1)}\,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 92 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] The following statements are true:
\begin{enumerate}
\item The orbit map operator
\begin{align*}
\Omega : \big( D(A), |\cdot|_{D(A)} \big) \to \big( \scrd_X^{2\alpha}([0,T],W), \| \cdot \|_{X,2\alpha} \big), \quad \xi \mapsto ( u_{\xi}, 0 )
\end{align*}
is a continuous linear operator between seminormed spaces with operator norm bounded by
\begin{align*}
\| \Omega \| \leq M e^{\omega T} T^{1-2 \alpha}.
\end{align*}
\item The orbit map operator
\begin{align*}
\Omega : \big( D(A), |\cdot|_{D(A)} \big) \to \big( \scrd_X^{2\alpha}([0,T],W), \interleave \cdot \interleave_{X,2\alpha} \big), \quad \xi \mapsto ( u_{\xi}, 0 )
\end{align*}
is a continuous linear operator between Banach spaces with operator norm bounded by
\begin{align*}
\| \Omega \| \leq M e^{\omega T} T^{1-2 \alpha} + 1.
\end{align*}
\end{enumerate}

