[Proposition 10 (Linear maps, sums, and L\'evy time) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] Let all random vectors below be centered and have finite second moments.
\begin{enumerate}
\item If \(L:\R^d\to\R^m\) is linear, then
\begin{equation}
 C_{LX}(t)=C_X(L^\top t),\qquad t\in\R^m.
\end{equation}
\item If \(X\) and \(Y\) are independent vectors in \(\R^d\), then
\begin{equation}
 C_{X+Y}(t)\leq\max\{C_X(t),C_Y(t)\}.
\end{equation}
\item If \((L_r)_{r\geq0}\) is a centered L\'evy process with finite second moments, then for every \(r>0\),
\begin{equation}
 C_{L_r}(t)=C_{L_1}(t).
\end{equation}
\end{enumerate}

