body:
[Proposition prop:global_well_cutoff of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $4< p<+\infty$ and $-\frac{1}{2}<r<-\frac{2}{p}$. For all $\omega_0\in B^{-2/p}_{g,2,p},$ there exists a unique local p-solution $(\omega,\tau)$ of (equation main_ito_cutoff of the paper) satisfying $\tau=+\infty$ $\mathbb{P}-a.s.$ and
 \begin{align*}
     \omega&\in H^{\theta,p}_{loc}\left([0,+\infty);H_g^{-2\theta}\right)\cap  C\big([0,+\infty);B^{-\frac{2}{p}}_{g,2,p}\big)\quad \mathbb{P}-a.s.\quad  \text{for all } \theta\in [0,1/2).
 \end{align*}
 Moreover, for all $T>0$, there exists $C=C(T)$ such that
    \begin{align}
     \mathbb{E}\Big[\sup_{s\in [0,T]}\|\omega_s\|^p_{B^{-\frac{2}{p}}_{g,2,p}}\Big]+\mathbb{E}\int_0^T \|\omega_s\|_{H^0_g}^p \,\mathrm{d}s\leq C(T)\Big(1+\|\omega_0\|_{B^{-\frac{2}{p}}_{g,2,p}}^p\Big) .
    \end{align}
    Moreover the hidden constant $C(T)$ depends only on $\sup_{t\in [0,T]}\|\theta\|^2_{\ell^2}$, and not on the particular choice of frequency localization ($n>1$) of the noise (c.f. (hyp_noise of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: no but possibly one event in small interval of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Consider the process defined as:
	\begin{equation*}
		\boldsymbol{w}(t) \vcentcolon= t - \max \asetc{a_i}{i \geq 1, a_i \leq t} \quad \text{for all} \quad t \geq 0, 
	\end{equation*}
	which represents the amount of time elapsed since the last arrival at time $t$. For each $i \in \mathbbm{Z}$ and $0 \leq s < t$, the following inequality holds almost surely:
	\begin{equation}

		P\probarg*{B_i^c(s, t) | \mathcal{F}_s} \leq \frac{\bar F\left(\boldsymbol{w}(s)\right) - \bar F\left(\boldsymbol{w}(s) + t - s\right)}{\bar F\left(\boldsymbol{w}(s)\right)} + \sum_{j = 1 - M}^{\mathcal{R}(s)} H_j^1(s, t),
	\end{equation}
	where $B_i^c(s, t)$ is the complement of $B_i(s, t)$. Also, let us fix a realization and suppose that there exist a constant $\eta \in (0, \kappa)$, a compact set $(0, 0) \in C \subset U_g$ and a time $T \geq 0$ such that
	\begin{equation}

		\boldsymbol{w}(t) \leq \eta \quad \text{and} \quad \left(\boldsymbol{x}_j(t), \boldsymbol{y}_j(t)\right) \in C \quad \text{if} \quad 1 - M \leq j \leq \mathcal{R}(T) \quad \text{and} \quad t \in [0, T].
	\end{equation}
	Then there exist two deterministic constants $K \geq 0$ and $\delta > 0$, which only depend on $\eta$ and $C$, such that if $t - \delta \leq s < t \leq T + \delta$, then we have:
	\begin{equation*}
		\frac{\bar F\left(\boldsymbol{w}(s)\right) - \bar F\left(\boldsymbol{w}(s) + t - s\right)}{\bar F\left(\boldsymbol{w}(s)\right)} + \sum_{j = 1 - M}^{\mathcal{R}(s)} H_j^1(s, t) \leq K\left[1 + M + \mathcal{R}(s)\right](t - s).
	\end{equation*}

[Lemma 15 of arXiv:2604.00598, 'Allowing for Imprecision in the Game-theoretic Characterisation of the Poisson Process'] Fix some \(s,t\in\posreals\) such that \(s<t\).
For all \(n\in\nats\), we define \(\Delta_n\coloneqq\gr{t-s}/n\), \(t^n_k\coloneqq s+\gr{k-1}\Delta_n\) for all \(k\in\set{1, \dots, n+1}\)  and \[A_n
\coloneqq \set{\pth\in\countpaths\colon \gr{\forall k\in\set{1, \dots, n}}~\pth\gr{t^n_{k+1}}\leq\pth\gr{t^n_k}+1 }.\]
Then
\begin{equation*}
\gr{\forall\epsilon\in\sposreals}
\gr{\exists n_\epsilon\in\nats}
\gr{\forall n\in\nats, n\geq n_\epsilon}~
\oscuprev{\indica{\compl{A_n}}}[s]
<\epsilon
\end{equation*}

