[Lemma thm:BregDivisIntegral thm of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] For any twice-differentiable $\varphi$, 
	\begin{align}
	\int_x^p(p-t)\varphi''(t)dt&=\varphi(p)-\varphi(x)-(p-x)\varphi'(x)
	\end{align}

[Lemm 14 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $b\colon [0, 1] \times \bR \to \bR$ and $\sigma \colon [0, 1] \times \bR \to \bR$ be $\cB([0, 1])\otimes \cB(\bR)/\cB(\bR)$-measurable and assume there is a constant $L$ depending only on $(b, \sigma)$ such that, for all $x, y \in \bR$ and $t \in [0, 1]$,
\begin{align*}
& |b(t, x) - b(t, y)| + |\sigma(t, x) - \sigma(t, y)| \le L |x - y|,\\
& |b(t, x)| + |\sigma(t, x)| \le L(1 + |x|).
\end{align*} 
Then, the following SDE with given $x_0 \in \bR$,
\begin{align*}
Y(t) = x_0 + \int_0^t b(u, Y(u)) \od u + \int_0^t \sigma(u, Y(u)) \od \beta(u), \quad t \in [0, 1],
\end{align*}
has a strong solution $Y = (Y(t))_{t \in [0, 1]}$, which is unique up to a  $\bP$-null set, and satisfies
\begin{align*}
\bE\lt[\sup_{0 \le t \le 1} |Y(t)|^q\rt] < \infty, \quad \forall q \in [1, \infty).
\end{align*}
Moreover, there exists a $\cB(\cC)/\cB(\cC)$-measurable $\Phi\colon \cC \to \cC$ depending only on $(x_0, b, \sigma)$ such that
\begin{align*}
Y(\omega, \cdot) = \Phi(\beta(\omega, \cdot)) \quad \trm{for }\bP\trm{-a.s. } \omega \in \Omega.
\end{align*}

[Proposition th:uniq_path-app of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (A0 of the paper)--(A5 of the paper) and that
\begin{align}

&\exists\,\varepsilon \in (0,1):\quad
{\mathcal A}^{-(1+\theta)+2{\tilde \beta}
+2(1-\theta){\tilde \delta}+2\varepsilon}\in{\mathscr L}^1({\mathcal H},{\mathcal H})\,,\\

   &{\tilde \alpha}\leq {\tilde \beta}\,, \qquad
   {\tilde \alpha}+(1-\theta){\tilde \delta}<\frac\theta2\,.
\end{align}
Then, for every $T>0$ there exists a constant $\mathfrak L>0$, depending only on the structural data ${\tilde \alpha},{\tilde \beta},{\tilde \delta},\theta,T$, such that, 
for every weak mild solutions $(X,\mathcal W)$ and $(Y,\mathcal  W)$ to (equation SDE-app of the paper) with initial data $x,y\in D({\mathcal A}^{-{\tilde \alpha}})$, respectively, in the sense of Definition~(def-sol-app of the paper), with the same cylindrical Wiener process $\mathcal W$ and defined on the same probability space, it holds that 
\begin{equation}

\|X-Y\|_{C^0([0,T];L^2(\Omega; D({\mathcal A}^{-{\tilde \alpha}}))}\leq 
\mathfrak L\|x-y\|_{D({\mathcal A}^{-{\tilde \alpha}})}.
\end{equation}

[Proposition prop:relu-switching-distance of arXiv:2608.22910, 'A Commutator Framework for Selective Spectral Alignment in Deep Neural Networks'] For every \(s,t\),
\begin{equation}
\|D_\ell(\cdot,t)-D_\ell(\cdot,s)\|_{
\mathrm L^2(\mu;F)}^2
=
\sum_{r=1}^{m_{\ell+1}}
\mu\bigl(A_{\ell,r}(t)\triangle A_{\ell,r}(s)\bigr).
\end{equation}
Moreover, if \(z_{\ell,r}(x,t_n)\to z_{\ell,r}(x,t)\) for
\(\mu\)-almost every \(x\) and
\begin{equation}
\mu\bigl(Z_{\ell,r}(t)\bigr)=0,
\qquad r=1,\ldots,m_{\ell+1},
\end{equation}
then \(D_\ell(\cdot,t_n)\to D_\ell(\cdot,t)\) in
\(\mathrm L^2(\mu;F)\).

[Theorem thm:ordered-group-shadow of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Let $\Gamma$ be any linearly ordered abelian group, let
$A=(a_0<\cdots<a_{k-1})\subset\Gamma$, where $k\geq2$, and let
$h\in\mathbb Z_{\geq1}$.  Write
$r=r_h^\Gamma(A)$ and $d=k-1-r$.  There are integers
\[
 0=b_0<b_1<\cdots<b_{k-1}
\]
such that, for every $1\leq j\leq h$ and $u,v\in\mathcal U_{j,k}$,
\begin{equation}
 \operatorname{sgn}_{\Gamma}\!\left(\sum_i(u_i-v_i)a_i\right)
 =\operatorname{sgn}\!\left(\sum_i(u_i-v_i)b_i\right),
\end{equation}
and
\begin{equation}
 b_{k-1}
 \leq d h^{d-1}\prod_{i=1}^{r}p_i^\Gamma(A)
 \leq(k-1-r)h^{k-2},
\end{equation}
with the empty product understood as one.  For fixed $k$, the universal
$h$-exponent $k-2$ is optimal, already for subsets of $\mathbb Z$.

[Lemma lem:Step2 of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] Let $(Z,d,\mathfrak{m})$ be as in (Setting of the paper), and let us assume it verifies the global Sobolev inequality (equation eqn:GlobalSobolev of the paper), and the Ricci lower bound (equation eqn:RicciControl of the paper) in (assumptions of the paper). Let $f\in W^{1,2}(Z,d,\mathfrak{m})$ verify $\Delta f= -\lambda f$ for some $\lambda\geqslant 0$. Then there is a constant $C>0$ such that 
    \begin{equation}
        |\nabla f|(x)\leqslant C d(x,S)^{-1}, \qquad \forall x:d(x,S)\leqslant 1.
    \end{equation}

