[Lemma 7 (Uniform remainder of a finite Debye hierarchy) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] For $z\in[0,z_0]$, define
\[
 N_M(z)=\sum_{j=0}^Mz^jN_j,\qquad
 V_M(z)=\sum_{j=0}^Mz^jV_j,\qquad
 \Phi_M(z)=\sum_{j=0}^Mz^j\Phi_j,
\]
and put $\ell_j=s+3(M-j)+5$ for $0\le j\le M$.
Assume that the coefficient identities
\eqref{eq:coefficient-mass}--\eqref{eq:coefficient-poisson} hold through
order $M$, that the base profile has the bounds of
\cref{prop:smooth-simple-wave}, and that
\begin{equation}
\begin{split}
 \mathcal B_M={}&
 \sum_{j=1}^M\sup_{t_0\le t\le T}\bigl(
 \norm{(N_j,V_j,\Phi_j)(t)}_{H^{\ell_j}}
 +\norm{\pa_t(N_j,V_j,\Phi_j)(t)}_{H^{\ell_j-1}}\bigr)<\infty.

\end{split}
\end{equation}
Suppose also that the positive-order coefficients and their derivatives tend
to zero at spatial infinity.  Then, uniformly for $0\le z\le z_0$,
\begin{equation}
\begin{split}
 &\norm{\mathcal F_n(z)}_{H^{s+1}}
 +\norm{\mathcal F_u(z)}_{H^{s+1}}
 +\norm{\mathcal F_\phi(z)}_{H^{s+1}}
 +\norm{\pa_t\mathcal F_\phi(z)}_{H^s}
 \le C_{\mathcal B_M,t_0,T}z^{M+1},

\end{split}
\end{equation}
where
\begin{align}
 \mathcal F_n(z)&=\pa_tN_M(z)+\pa_1(N_M(z)V_M(z)),
 \\
 \mathcal F_u(z)&=\pa_tV_M(z)+V_M(z)\pa_1V_M(z)
 +\pa_1h_i(N_M(z))+\pa_1\Phi_M(z),
 \\
 \mathcal F_\phi(z)&=z\pa_1^2\Phi_M(z)
 -e^{\Phi_M(z)}+N_M(z).

\end{align}

