[Lemma 7 of arXiv:2506.10256, 'Clustering of large deviations events in heavy-tailed moving average processes: the catast'] For any $\delta>0$ and $M>0$,
\begin{equation} 
\lim_{n\to\infty}\frac{\sum_{\substack{i,j=-Mn, \ldots, Mn\\i\not=j}}
  P(\|Z_i\|>n\delta, \|Z_j\|>n\delta)}{P(S_0^n\in n\Gamma)}=0. 
\end{equation}

[Theorem 144 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Suppose that
\index{$S$@Miscelenea!$a_{\pm}$@$\hat a$}
\index{$S$@Miscelenea!$\bar b_{R}$@$\hat b$}
\begin{equation}

a^{\shharp}_{\rho_{a}}\leq 
\hat  a,\quad\hat b_{q\beta,p\beta,\rho_{b}}\leq \hat  b.
\end{equation}
 Then for any $u\in E^{1,2}_{q,p,\beta}$ 
and  $\lambda\geq \lambda_{0}\rho_{b}^{-2}$ 
\begin{equation}

\|\lambda u,\sqrt\lambda Du, \partial_{t}u, D^{2}u\|_{  E_{q,p,\beta}}
\leq N _{1}\rho_{b}^{-\alpha}\|f\|_{  E_{q,p,\beta}}, 
\end{equation}
where   
$$
f=\cL  u-\lambda u:=\partial_{t}u+(1/2)a^{ij}D_{ij}u+b^{i}D_{i}u-\lambda u,\quad \alpha=
d+2+\beta-\frac{d}{p}-\frac{2}{q}.
$$
Furthermore, for any
$f\in E_{q,p,\beta}$ and $\lambda\geq\lambda_{0}\rho_{b}^{-2}$ there exists a unique
$u\in E^{1,2}_{q,p,\beta}$ such that in
$\bR^{d+1}$
\begin{equation}

\cL u -\lambda u=-f. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:larger group is better of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Assume $P\in \mathcal{S}(\pi)$. Let $G_1\leq G_2$ be two locally compact topological groups with Harr measure $\mu_1$ and $\mu_2$ respectively that act on $\mathcal{X}$. Assume $\pi$ is $G_2$-invariant (and hence $G_1$-invariant). For $i=1,2$, denote $(P_{la})_{ra}(G_i)$ as the independent-double-average of $P$ under group $G_i$. Then we have 
    \begin{equation*}
        \gamma((P_{la})_{ra}(G_2))\geq \gamma((P_{la})_{ra}(G_1)).
    \end{equation*}

