[Lem 16 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Let \(Y_t\) be the Ornstein-Uhlenbeck process defined in~\eqref{OU_a0}. Then, for any \(p\geq 1\), it holds that
        \[
        \left(
        \E_{\PP^{OU}_y}\left[
        \Vert Y_t\Vert_2^p
        \right]
        \right)^{1/p}
        \leq 2^{1-1/p}\left(
        e^{-2a_0 t} 
        \Vert y\Vert_2
        +\sqrt{\frac{1-e^{-4a_0 t}}{a_0}}
        \left(
        \frac{\Gamma((d+p)/2)}{\Gamma(d/2)}
        \right)^{1/p}
        \right).
        \]

[Lemma 5 of arXiv:2605.30091, 'Computing lower expectations with respect to total variation distance and chi-squared dive'] For any $k\in\{\ell+1,\ldots,n\}$, the following are equivalent:
\begin{equation*}
\mathcal{Q}_k\neq\emptyset
\Leftrightarrow
m_k\delta-(1-m_k)\geq0
\Leftrightarrow
\delta\geq\frac{1-m_k}{m_k}.
\end{equation*}
Whenever either of these is true, we have that
\begin{equation}
    \min_{q\in\mathcal{Q}_k} E_q(f)=\mu_k-\sigma_k\sqrt{m_k\delta-(1-m_k)}.
\end{equation}
The minimum is then furthermore attained uniquely for $q_k\in\mathbb{R}^\mathcal{X}$ with $q_k(x_i)=0$ for all $i>k$ and, for all $i\in\{1,\ldots,k\}$,
\begin{equation}
    q_k(x_i)
    =\frac{p(x_i)}{m_k}\left(1-\frac{f(x_i)-\mu_k}{\sigma_k}\sqrt{m_k\delta-(1-m_k)}\right).
\end{equation}
Finally, $q_k(x_k)>0$ (and then also $q_k(x_i)>0$ for all $i\in\{1,\ldots,k\}$) if and only if $\delta<\delta_k$, and $q_k(x_k)=0$ (and then also $q_k(x_i)\geq0$ for all $i\in\{1,\ldots,k\}$) if and only if $\delta=\delta_k$

