\begin{equation*}
\P\Big(\big(\LLpaeps\big)_{(x,s\tilde{\omega}^{-1};y,t\tilde{\omega}^{-1}) \in \SetTw \cap \mathcal{D}_{n^{-1}}} \in \cdot \, \Big| \, \mathcal{A}_n \Big) \rightarrow \P\Big( (\Lpa)_{(x,s;y,t ) \in \SetT \cap \mathcal{D}_{n^{-1}}} \in \cdot \, \Big| \, \mathcal{A}_n \Big) . 
\end{equation*}

