[Lemma lem:approxmeasx_unif_bounded of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] The family $(\mu^{(a,\varepsilon)})_{\varepsilon>0}$ of measures on $(L, \mathcal{B}(L))$ is uniformly bounded for any $a\in (0,1)$. More precisely, it holds for all $\varepsilon>0$ that
	\begin{equation*}
		\mu^{(a,\varepsilon)}(L) \leq (2\pi a (1-a))^{-1/2} < \infty.
	\end{equation*}

[Lemma 39 (Four-moment cancellation with a Lindeberg remainder) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Let $X_e$ and $\widehat X_e$ be centered variables satisfying
\begin{equation}
 \E X_e^q=\E\widehat X_e^q,
 \qquad q=1,2,3,4.
\end{equation}
Let $\Phi_e:\R\to\mathbb C$ satisfy $|\Phi_e(u)|\le1$.  Suppose that
there are $\varepsilon_0>0$ and a constant $C$, independent of
$e,N,\varepsilon$, such that, for $0<\varepsilon\le\varepsilon_0$,
\begin{equation}
 \sup_{|u|\le\varepsilon\sqrt N}
 |\Phi_e^{(5)}(u)|\le C N^{-5/2}
\end{equation}
and
\begin{equation}
 |\Phi_e^{(q)}(0)|\le C N^{-q/2},
 \qquad q=0,1,2,3,4.
\end{equation}
Assume that the target variables satisfy the averaged fourth-moment Lindeberg
condition and that $\sup_e|\widehat X_e|\le C_*$.  Then
\begin{equation}
 \lim_{\varepsilon\downarrow0}
 \limsup_{N\to\infty}
 \sum_e
 \left|
 \E\Phi_e(X_e)-\E\Phi_e(\widehat X_e)
 \right|=0,
\end{equation}
provided the functions $\Phi_e$ are the conditional edge observables along
one telescoping path and the derivative constants are uniform in the open-edge
matrices.

[Theorem 1 of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] If $p>1$, $\alpha\in(0,1]$, $(p,\alpha)\neq(2,1)$, $u(0)=0$, and $u\in\ell^p(\N,x^{-2})$, then
\begin{equation}
    \mathcal{E}_p^{\N_0}(u)
    \geq
    \sum_{x\in\N} w_{p,\alpha}(x)|u(x)|^p,
\end{equation}
where
\begin{equation}
    w_{p,\alpha}(x)
    :=
    \frac{1}{a_p+1}
    \frac{\Delta x^{\alpha a_p}}{x^{\alpha a_p}}
    +
    \frac{a_p}{a_p+1}
    \frac{\Delta x^\alpha}{x^\alpha},
    \qquad x\in\N.
\end{equation}
The Hardy weight $w_{p,\alpha}$ is strictly positive; it is critical whenever
\begin{equation}
\alpha\leq\frac{1}{a_p+1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $p_0,p_1,q_0,q_1 \in[1,\infty]$ and $\alpha_0,\alpha_1,\mu_0,\mu_1 \in \R$ and $p,q,\alpha,\mu$ such that
\begin{equation*} 
\frac{1}{p}=\frac{1-\theta}{p_0}+\frac{\theta}{p_1},\quad \frac{1}{q}=\frac{1-\theta}{q_0}+\frac{\theta}{q_1},
\end{equation*}
and
\begin{equation*}
\alpha=(1-\theta)\alpha_0+\theta\alpha_1, \quad  \mu=(1-\theta)\mu_0 + \theta \mu_1
\end{equation*}
for $\theta \in[0,1]$. Then there exists $C>0$ such that
\begin{equation*} 
\|u\|_{\mathcal{B}^\alpha_{p,q,\mu}(\R^d)} \leq C \|u\|_{\mathcal{B}^{\alpha_0}_{p_0,q_0,\mu_0}(\R^d)}^{1-\theta} \|u\|_{\mathcal{B}^{\alpha_1}_{p_1,q_1,\mu_1}(\R^d)}^{\theta}.
\end{equation*}
In particular, we have
\begin{equation*}
\|u\|_{\CH_\mu^\alpha}\le C\|u\|_{\CH_{\mu_0}^{\alpha_0}}^{1-\theta}\|u\|_{\CH_{\mu_1}^{\alpha_1}}^\theta.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] There is a constant $c>0$ such that
\begin{equation}
\mathcal{I}(1,D_L\cap B_K)=\frac{L^{-\frac{3}{2}}}{\sqrt{2\pi} \sigma}\mathbb{E}_\nu[e^{-\frac{(t^+)^2}{2\sigma^2}}{\color{red} e^{L^{-\frac{3}{2}}\tau^3 (t^+)^3}}] \cdot\big(1+O(L^{-c})\big).
\end{equation}

[Lemma 3 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $\langle G_n \rangle$ be an exhaustion of $\Z^d$ and let $\nu^\infty$ be the MSF measure on $\Z^d$. Then 
    \begin{align*}
        e \in \text{MSF} &\Longrightarrow \exists N \in \N \text{ with } e \in \text{MST of } G_n \text{ for } n \geq N, \\
        e \not\in \text{MSF} &\Longrightarrow \exists N \in \N \text{ with } e \not\in \text{MST of } G_n \text{ for } n \geq N.
    \end{align*}
    Furthermore, the edge $e$ is in the MSF if and only if there exists some finite vertex set $W$ such that $e$ has the minimal weight in the (finite) edge set $E(W,V \setminus W)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:BL-limits of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let  $\tilde{\mathcal{P}}$  be a marked point process on $\mathbb{R}^d\times\mathbb{K}$.  Let $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be an
real-valued score function, and assume that $\xi$ is \textnormal{BL}-localizing on all
finite windows of $\tilde{\mathcal{P}}$ as in~(equation Lp-stab of the paper) for a given $p \in \mathbb{N}$
(tacitly assuming the existence of the uniformly bounded correlation function $\rho^{(p)}(\bk{x}{1}{p})$).

\begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item 
For a given vector  $\bk x1p \in(\mathbb{R}^d)^p$, 
the  random vectors  $\bk{\xi^{(r)}}1p(\tilde{x}, \tilde{\mathcal{P}})$ 
(under the Palm distributions ${\mathbb{P}}_{\bk x1p}$ of $\tilde{\mathcal{P}}$) 
converge in the $d_{\textnormal{BL}, \bk{x}{1}{p}}$ metric (and hence in law) as $r\to\infty$ to a probability distribution on $\mathbb{R}^p$, represented here by the random vector  $\Upsilon_{\bk x1p}=(\Upsilon_{\bk x1p}[1],\ldots,\Upsilon_{\bk x1p}[p])\in \mathbb{R}^p$, i.e.,
$$\bk{\xi^{(r)}}1p(\tilde{x}, \tilde{\mathcal{P}})
\xrightarrow[r \to \infty]{\textnormal{BL},\bk x1p} \Upsilon_{\bk x1p}
$$
and the speed of convergence is bounded by the same decreasing function $\varphi_p$ as in~(equation Lp-stab of the paper), namely
\begin{align} 
 \sup_{x_1,\ldots,x_p \in \mathbb{R}^d} 
 d_{\textnormal{BL}, \bk x1p}(\bk{\xi^{(r)}}1p(\tilde{x}, \tilde{\mathcal{P}}), \Upsilon_{\bk x1p})  \leq 4\varphi_p(r), \ r > 0.
\end{align}
\item 
The probability distributions represented by $\Upsilon_{\bk x1p}$ are probability kernels from $(\mathbb{R}^d)^p$ to $\mathbb{R}^p$; formally, for any measurable function $f$ on $\mathbb{R}^p$, the function $(\mathbb{R}^d)^p\owns\bk x1p\mapsto\mathbb{E} [f(\Upsilon_{\bk x1p})]\in\mathbb{R}$ is measurable.
\item   The convergence holds also for $\bk{\xi}1p(\tilde{x},\tilde{\mathcal{P}}_n)$:
\begin{equation}
\bk{\xi}1p(\tilde{x},\tilde{\mathcal{P}}_n) \xrightarrow[n \to \infty]{\textnormal{BL},\bk x1p} \Upsilon_{\bk x1p}
\end{equation}
with the speed of convergence bounded by the same decreasing function $\varphi_p$ of the  distance $ d(\bk x1p,\partial W_n)$ from  $\{x_1,\ldots, x_p\}\subset W_n$ to the boundary of $W_n$:
\begin{equation} d_{\textnormal{BL}, \bk x1p}(\bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}}_n),\Upsilon_{\bk x1p})  \leq
 6\varphi_{p}(d(\bk x1p,\partial W_n)).
 \end{equation}
\item  If $\tilde{\mathcal{P}}$ is stationary and $\xi$ is translation invariant, then the  distribution of $\Upsilon_{\cdot}$ is translation invariant:
i.e., for all $y\in\mathbb{R}^d$
 $$\Upsilon_{\bk x1p}
\overset{\text{law}}{=}\Upsilon_{\bk x1p-y}=\Upsilon_{(x_1-y,\ldots,x_p-y)}.
$$

\end{enumerate}

\begin{enumerate}[wide,label=(\roman*),  labelindent=0pt]
\setcounter{enumi}{4}
\item  When  $\xi$ is defined on  $\mathbb{R}^d \times \mathbb{K} \times
  \mathcal{N}_{\mathbb{R}^d \times \mathbb{K}}$ and satisfies \textnormal{BL}-localization~(equation Lp-stab-infinite of the paper)  for some $p\ge 1$, then for $\{x_1,\ldots, x_p\}\subset W_n$ we have
\begin{equation}
d_{\textnormal{BL}, \bk x1p}( \bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}}_n), \bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}}))\le 12\varphi_{p}(d(\bk x1p,\partial W_n)),
\end{equation}
and hence, under $\mathbb{P}_{\bk x1p}$, $\bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}})$ has the law of 
$\Upsilon_{\bk x1p}$.
\end{enumerate}

[Lemma lambda-basechange of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $T$ and ${\mathcal{C}}$ as above, and let $A\in T$ arbitrary. Then:
    \begin{enumerate}
        \item The unique map $\pi_A^*\colon T_{/A}\times{\mathcal{C}}(A)\to T_{/A}\times_T\textup{Un}^\textup{ct}({\mathcal{C}})$ of cartesian fibrations over $T_{/A}$ extending the inclusion of $\{\textup{id}_A\}\times{\mathcal{C}}(A)$ admits a relative left adjoint $\pi_{A!}$.
        \item Writing $\lambda_A$ for the composite $\textup{pr}\circ\pi_{A!}$, the diagram
        \[
            \begin{tikzcd}
               T_{/A}\times_T\textup{Un}^\textup{ct}({\mathcal{C}})\arrow[d,"\textup{pr}"']\arrow[r,"\lambda_A"]&{\mathcal{C}}(A)\arrow[d,"a_!"]\\
               \textup{Un}^\textup{ct}({\mathcal{C}})\arrow[r,"\lambda"'] & {\mathcal{C}}(1)
            \end{tikzcd}
        \]
        commutes up to homotopy.
    \end{enumerate}
    \begin{proof}
        For the first statement it suffices to apply Lemma~(lemma:pi!-rel-la of the paper) to the restriction of ${\mathcal{C}}$ along the forgetful functor $T_{/A}^{\textup{op}}\to T^{\textup{op}}$. 

        For the second statement, note that [HA]*{Proposition 7.3.2.6} shows that  $T_{/A}\times_T\pi_!\colon T_{/A}\times_T\textup{Un}^\textup{ct}({\mathcal{C}})\to T_{/A}\times{\mathcal{C}}(1)$ is left adjoint to $T_{/A}\times_T\pi^*$. On the other hand, the composite
        \[
            T_{/A}\times{\mathcal{C}}(1)\xrightarrow{\;\textup{id}\times a^*\;}T_{/A}\times{\mathcal{C}}(A)\xrightarrow{\;\pi_A\;}T_{/A}\times_T\textup{Un}^\textup{ct}({\mathcal{C}})
        \]
        agrees with $T_{/A}\times_T\pi^*$ as both are maps of cartesian fibrations over $T_{/A}$ and their straightenings are given at the terminal object $\textup{id}_A$ by $a^*\colon{\mathcal{C}}(1)\to{\mathcal{C}}(A)$. Passing to left adjoints, we see that $T_{/A}\times_T\pi_{!}$ is equivalent to $(a_!\times\textup{id})\circ\pi_{A!}$. The claim now follows by postcomposing with the projection $T_{/A}\times{\mathcal{C}}(1)\to{\mathcal{C}}(1)$.
    \end{proof}

[Lemma 9 of arXiv:2511.06414, 'Non-uniform Edgeworth expansions for weakly dependent random variables and their applicati'] There are polynomials $U_{r,n}$ with bounded coefficients and degrees depending only on $r$ so that 
\begin{equation}
\left|\tilde \Phi_{m,n}(x)-\left(\Phi(x)+\varphi(x)\sum_{r=1}^{m-2}B_n^{-r}U_{r,n}(x)\right)\right|\leq C_m(1+|x|^{e_m})e^{-x^2/4}\sig_n^{-(m-1)}
\end{equation}
where $C_m$ and $e_m$ are constants which depend only on $m$.

[Theorem thm:PDEs of arXiv:2512.17808, 'Zeros of polynomial powers under the heat flow'] Let $\mathcal{D}\coloneq \{(z,t)\in\mathbb{C}^2: t=|t|e^{i\theta}\neq 0, e^{-i\theta/2} z \in \mathcal{D}_{|t|}\}$.
\begin{enumerate}
\item The logarithmic potential $U_t$ satisfies the Hamilton-Jacobi PDE
\begin{align}
\partial_{t}U_t(z)=-(\partial_z U_t(z))^2, \quad (z,t)\in\mathcal{D},
\end{align}
where $\partial_t$ is the Wirtinger derivative of $t\in\mathbb{C}$.
\item The Stieltjes transform $m_t$ satisfies the PDEs
\begin{align}
\partial_t m_t(z)&=-\frac{1}{2}\partial_z(m_t^2(z))=-m_t(z)\partial_z m_t(z), \quad (z,t)\in\mathcal{D},\\
\partial_{\bar t}m_t(z)&=-\frac{1}{2}\partial_z\overline{(m_t^2(z))}=-\overline{m_t(z)}\partial_z \overline{m_t(z)}, \quad (z,t)\in\mathcal{D} .
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

