[Lemma lemma_exponential_decay_with_gamma_n_lower of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] Fix $\varepsilon>0$ and let $\gamma>0$ be a constant, which may depend on $\varepsilon$. Then, for all $R \geq R_{\overline{\mathbb{Z}}}(\varepsilon)$,
\begin{align}
-\gamma I_{\textup{Cr}}^{p_{\sigma}}(0) - \gamma g(\varepsilon) & \leq \liminf \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P}_{\sigma R}\left( \Omega_{2 \left \lceil \frac{\gamma n}{2} \right \rceil+1,\textup{exc}}^{\sigma} \right),  \\
-\gamma \inf_{\sigma x \in [0,1]}I_{\textup{Cr}}^{p_{\sigma}}(x)  - \gamma g(\varepsilon) & \leq \liminf \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P}_{\sigma R}\left( \Omega_{2\left \lceil \frac{\gamma n}{2} \right \rceil+1,\textup{mea}}^{\sigma} \right), 
\end{align}
where $g$ is as in Proposition~(proposition_exponential_rate_of_decay_exc_and_end of the paper). In addition, for all $\mu_0 \in \mathcal{P}(\mathbb{Z})$,
\begin{align}
-\gamma I_{\textup{DV}}(\mu_0)& \leq \lim_{R \to \infty} \liminf \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P} \left( \ell_{2 \left \lceil \frac{\gamma n}{2} \right \rceil+1} \in B(\mu_0,2^{-R}\varepsilon) \right). 
\end{align}

