[Lemma lem:neumann of arXiv:2608.17022, 'Sharp hypocoercive convergence estimates for underdamped Langevin dynamics with specular r'] Let $\Omega\subset\mathbb{R}^d$ be a bounded convex domain and $U\in C^2(\overline\Omega)$, and let $-\mathscr{L}_{\mathrm{o}}$ be the nonnegative self-adjoint operator on $L^2(\mu_x)$ associated with the closed form $\mathcal E$ on $H^1(\Omega)$. Then,
\begin{align}
D(\mathscr{L}_{\mathrm{o}})=\{h\in H^2(\Omega):\ \partial_nh=0\ \text{$\sigma$-a.e.\ on }\partial\Omega\},\qquad
\mathscr{L}_{\mathrm{o}} h=\Delta_xh-\nabla_xU\cdot\nabla_xh,
\end{align}
and there is $C=C(\Omega,U)$ such that
\begin{equation}
\|h\|_{H^2(\Omega)}\le C\big(\nrm[\mu_x]{\mathscr{L}_{\mathrm{o}} h}+\nrm[\mu_x]{h}\big),\qquad h\in D(\mathscr{L}_{\mathrm{o}}).
\end{equation}

[Lemma l4.3 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Let $M>0$, $\{h^{\varepsilon}\}_{\varepsilon\in(0,1)}\subset\mathcal{A}_{M}$ and $\Delta$ be as in Definition $((2.11 of the paper))$. Then
	\begin{equation}
		\dfrac{1}{\Delta}\mathbb{E}\int_0^T|Y_t^{\varepsilon,h^\varepsilon}-Y_t^{\varepsilon}|^2dt\to0,~~as~\varepsilon\to0.
	\end{equation}

[Lemma lem:radial-moment-bound of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] For every $n\ge 1$, there exists a constant $C_n>0$ such that, for all $\beta\ge 0$ and all $A\in(0,\infty]$,
\begin{align*}
    \frac{
    \int_0^A t^n e^{-t^2/2-\beta t}\,dt
    }{
    \int_0^A t^{n-1}e^{-t^2/2-\beta t}\,dt
    }
    \le C_n .
\end{align*}

