[Defn unitaryweingarten of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] For any $L\in \mathbb{N}$ and $\alpha\in\mathrm{S}_L$
\begin{equation}

   \mathrm{Wg}_L(\alpha, N) := 
	\frac{1}{L!} \sum_{\lambda \vdash L} 
	\frac{d_\lambda \chi^{\lambda}(\alpha)}{\prod_{\square \in \lambda }
	(N + c(\square))}  
\end{equation}
where the product runs over all boxes $\square=(i,j)$ in the Young diagram 
associated to $\lambda$ and $c(\square):=j-i$.
Here $d_\lambda$ denotes the dimension and $\chi^{\lambda}$ denotes the 
character of 
the irreducible representation of $\mathrm{S}_L$ associated to $\lambda$.

[Defi 5 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] For any fixed $t_*\ge 0$ and for any  continuous  function $X(t,i)$ defined for $t\ge i+t_*$ and $i\in[0,i_\dagger)$,
	we say that a  bounded and continuous function $\underline u(t,i,x)$ defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $x\ge X(t,i)-R$ is a
	subsolution of   \eqref{moving frame-u} for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$,
	if $\partial_t \underline u(t,i,x)$ and $\partial_i\underline u(t,i,x)$ exist a.e. such that 
		\begin{equation*}
		\begin{aligned}
			\left\{\begin{split}
				&	\partial_t \underline u(t,i,x)  + \partial_i \underline u(t,i,x) \le 0,~~~~~~~ ~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~x\ge X(t,i)-R, \\
				&	\underline u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *\underline u(t,i,x)\md i,  ~~~~~~~~~~~~~~~t\ge  i_\dagger+t_*,   ~x\ge X(t,0).
			\end{split}\right.		
		\end{aligned}
	\end{equation*}
A supersolution $\overline u$ to \eqref{moving frame-u} for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$ can be defined in the same way with the inequality signs being reversed.


	Analogously, 	for any fixed $t_*>0$ large and for any  continuous and nondecreasing  functions $X^\pm(s)$ defined for $s\ge t_*$ such that $X^-(s)\le X^+(s-i_\dagger)$ for all $s\ge t_*$,  a  bounded and continuous function $\underline u(t,i,x)$ defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $X^-(t)-R\le x\le X^+(t)+R$ is called a
	subsolution of \eqref{moving frame-u}   for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\in[X^-(t), X^+(t-i)]$,
	if $\partial_t \underline u(t,i,x)$ and $\partial_i\underline u(t,i,x)$ exist a.e. such that
\begin{equation*}
\begin{aligned}
	\left\{\begin{split}
		&	\partial_t \underline u(t,i,x)  + \partial_i \underline u(t,i,x) \le 0,~~~~~~~~~~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~X^-(t)\le x\le X^+(t-i), \\
		&\underline	u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *\underline u(t,i,x)\md i,  ~~~~~~~~~~~~~~~~t\ge t_*+ i_\dagger,   ~X^-(t)\le x\le X^+(t).
	\end{split}\right.		
\end{aligned}
\end{equation*}
A supersolution $\overline u$ to \eqref{moving frame-u} for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\in[X^-(t), X^+(t-i)]$ can be defined in the same way with the inequality signs being reversed.

	For each case above,  super- and subsolutions for \eqref{moving frame-nonlinear} can be defined in a similar way.

[Lemma l.mtgl of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $\Phi$ be a classical solution of~(equation e.Parisi_PDE of the paper) with continuously differentiable $L$, continuous $\alpha$, and a smooth terminal condition.
Let $X$ be a strong solution of~(equation e.X_t= of the paper).
Let $g:[0,T]\times\mathbb{R}^{D}\to\mathbb{R}$ be continuous and let $\Psi$ be a classical solution of
\begin{align}
    \partial_t\Psi(t,x) + \left\langle \accentset{\mbox{\large\bfseries .}}{L}(t),\, \nabla^2 \Psi(t,x) + 2\alpha(t) \nabla\Psi\nabla\Phi^\intercal(t,x) \right\rangle_{S^{D}} + g(t,x)=0
\end{align}
for $(t,x)\in[0,T]\times\mathbb{R}^{D}$. Then,
\begin{align*}\Psi(t,X_t)+\int_0^t g(r,X_r)\mathrm{d} r 
\end{align*}
is a martingale with index $t\in[0,T]$.

