[Theorem t:localized_SMR of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix $\nu>0$ and let $Q=I\times B$ be a parabolic cylinder of side length $\varrho\in (0,1/2]$. Suppose that $(\zeta_n)_n : I\times \Omega\times B \to \ell^2$ is progressively measurable, and that there exist $M>0$ and $\nu_0\in (0,\nu)$ such that 
\begin{align}

&\frac{1}{2}\sum_{n\geq 1} |\zeta_n\cdot \xi |^2\leq \nu_0 |\xi|^2 \ \text{ for all }\xi\in{\mathbb R}^d,  & &({{\normalfont{\text{Parabolicity}}}})\\

&\sup_I \|(\zeta_n)_n\|_{W^{1,\infty}(B;\ell^2)}\leq M. & &({{\normalfont{\text{Regularity}}}})\\

&\nabla\cdot \zeta_n =0 \text{ in }\mathscr{D}'(B) \ \text{ for all }n.   & &({{\normalfont\text{Noise incompressibility}}})
\end{align}
Fix $r\in (1,\infty)$, $p,q\in (2,\infty)$ and $\eta\in (0,1)$. Then there exists a constant $C_0>0$ depending only on $p,q,r,M,\varrho,d,\nu,\nu_0$ and $\eta$ for which the following estimate holds  for any local solution $(v,\pi,(\widetilde{\pi}_n)_n)$ to the stochastic Stokes system (equation eq:turbulent_Stokes_xi_linear of the paper) on $Q$ (see Definition (def:local_solutions_NSE of the paper)):
\begin{align}
\nonumber
\Big({\mathbf E}\sup_{\eta I}\|v\|_{B^{1-2/p}_{q,p}(\eta  B)}^r\Big)^{1/r}
&+ \big({\mathbf E}\|\nabla v\|_{L^p( \eta I;L^q(\eta B))}^r\big)^{1/r}
\leq C_0
\big( {\mathbf E}\| v\|_{L^2(Q)}^r \big)^{1/r}\\
\nonumber
&+C_0 \big({\mathbf E}\|\pi\|_{L^2(I;H^{-1}(B))}^r\big)^{1/r}
+C_0\big({\mathbf E}\|(\widetilde{\pi}_n)_{n}\|_{L^2(Q;\ell^2)}^r\big)^{1/r}
\\ 
& + C_0\big({\mathbf E}\|F\|_{L^p(I;L^q(B))}^r\big)^{1/r}+ C_0\big({\mathbf E}\|(G_n)_n\|_{L^p(I;L^q(B;\ell^2))}^r\big)^{1/r},

\end{align}
whenever the right-hand side is finite. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3} and \eqref{PETNs-3.01} hold. Then there exists $\epsilon_0\in(0,1)$ such that, for every $\epsilon\in(0,\epsilon_0)$, $\tau\in\mathbb R$, and $\zeta\in L^4(\Omega,\mathscr F_\tau;\mathcal H)$ with $\mathbb E[|\partial_z\zeta|^4]<\infty$, the solution of \eqref{PEeq-2.15} satisfies 
	\begin{align}
		\begin{split}
			&~~\mathbb{E}\left[|v(t,\tau,\zeta)|^{4}\right]+\int_{\tau}^t e^{\kappa (s-t)}\mathbb{E}\left[|v(s,\tau,\zeta)|^{2}\|v(s,\tau,\zeta)\|^2\right]ds\\
			&\leq \rho_1 \left(e^{-\kappa(t-\tau)}\mathbb{E}\left[|\zeta|^{4}\right]+ \int_\tau^te^{-\kappa(t-s)}|g(s)|^{4}ds+1\right),
		\end{split}
	\end{align}
	where $\rho_1$ is a positive constant independent of $\zeta$, $\tau$ and $t$.

