[Theorem eq:resslim of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] First, we assume that
\begin{itemize}
\item[$\mathbf{(H0)}$] $\forall x>0, \quad g(x,0) < 0 < g(x,R_{\max})$,
\item [$\mathbf{(H1)}$] $\forall x >0, \displaystyle{\int_{0}^{x} \dfrac{d(t)}{g(t,0)} \mathrm{d}t} = - \infty$.
\end{itemize}
Then, we assume that there exists a weight function $\omega$ such that
\begin{itemize}
\item[$\mathbf{(H2)}$]
$\omega \in \mathcal{C}^{1}(\mathbb{R}^{*}_{+})$ is positive, non-decreasing, Lipschitz continuous on $(1,+\infty)$, and
\begin{itemize}
\item[$\mathbf{(a)}$] $\exists c_{g}>0, \forall x>0, \quad  \sup_{R \in [0,R_{\max}]} |g(x,R)| \leq c_{g}\omega(x)$,
\item[$\mathbf{(b)}$] $\exists c_{b}>0, \forall x>1, \quad b(x) \leq c_{b}\omega(x)$,
\item[$\mathbf{(c)}$] $\exists c_{d}>0, \forall x>0, \quad d(x) \omega(x) \leq c_{d}$.
\end{itemize} 
\end{itemize}
Finally, we assume that the sequence $\left(\left(\mu^{K}_{t},R^{K}_{t}\right)_{t \geq 0}\right)_{K \in \mathbb{N}^{*}}$ of renormalized processes (formally defined in Section (subsec:construcdeux of the paper)) is such that
\begin{itemize}
    \item[$\mathbf{(H3)}$] there exists a random variable $\mu_{0}^{*} \in \mathcal{M}_{\omega}(\mathbb{R}^{*}_{+})$ such that $(\mu_{0}^{K})_{K \in \mathbb{N}^{*}}$ converges in law towards $\mu_{0}^{*}$ in $(\mathcal{M}_{\omega}(\mathbb{R}^{*}_{+}),\mathrm{w})$,
    \item[$\mathbf{(H4)}$] there exists $p>1$ such that 
    \begin{align*}
    \underset{K \in \mathbb{N}^{*}}{\mathrm{sup}} \hspace{0.1 cm} \mathbb{E}\left(\left\langle \mu^{K}_{0}, 1 + \mathrm{Id} + \omega \right\rangle^{p}\right) < + \infty.
    \end{align*}
\end{itemize} 
Under $\mathbf{(H0)}$, $\mathbf{(H1)}$, $\mathbf{(H2)}$, $\mathbf{(H3)}$, $\mathbf{(H4)}$, for all $T \geq 0$, the sequence $\bigg(\left(\mu^{K}_{t},R^{K}_{t}\right)_{t \in [0,T]}\bigg)_{K \in \mathbb{N}^{*}}$ is tight in the Skorokhod space $\mathbb{D}([0,T], (\mathcal{M}_{\omega}(\mathbb{R}^{*}_{+}),\mathrm{w}) \times [0,R_{\max}])$. Any of its accumulation point $(\mu^{*}_{t},R^{*}_{t})_{t \in [0,T]}$ is a continuous process and verifies almost surely, for all $t \in [0,T]$,
\begin{align}
    R^{*}_{t} =  R^{*}_{0} + \displaystyle{\int_{0}^{t}\rho(R^{*}_{s},\mu^{*}_{s})\mathrm{d}s},

\end{align}
     and for every $\varphi :(t,x) \mapsto \varphi(t,x) =: \varphi_{t}(x)$ smooth enough and dominated by $\omega$,
     \begin{multline}
       \langle \mu^{*}_{t}, \varphi_{t} \rangle =  \langle \mu^{*}_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t} \int_{\mathbb{R}^{*}_{+}} \bigg( \partial_{1}\varphi(s,x) + g(x,R^{*}_{s})\partial_{2}\varphi(s,x) }   \\
     + b(x)(\varphi_{s}(x_{0}) + \varphi_{s}(x-x_{0}) - \varphi_{s}(x)) - d(x)\varphi_{s}(x) \bigg) \mu^{*}_{s}(\mathrm{d}x) \mathrm{d}s,

     \end{multline}
     where $\partial_{1}$, respectively $\partial_{2}$, are the partial derivatives with respect to the first, respectively second, variable. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[definition]{def:weaksoloriginal}
   Given $\psi_0\in L^2(\R^d)$, we say that a progressively measurable
   process $\psi^{\tau}$ with paths in $C_w([0,T];L^2)$
   $\mathbb{P}-a.s.$ is a weak solution of \eqref{eq:rmse}  with $\psi^{\tau}_0=\psi_0$ if the following
   identity holds for each $\phi\in \mathscr{S}(\R^d)$ and $t\in [0,T]$:
   \begin{align}
       i\langle \psi^{\tau}_t,\phi\rangle-i\langle \psi_0,\phi\rangle&=-\int_0^t \langle\psi^{\tau}_s, \Delta\phi\rangle ds\notag\\ &-2i\int_0^t\langle \psi^{\tau}_s,A^{\tau}_s\cdot\nabla\phi\rangle ds+\int_0^t \langle|A^{\tau}_s|^2 \psi^\tau_s, \phi\rangle ds\quad \mathbb{P}-a.s.,
   \end{align}
   where $A^{\tau}_t$ is the stationary Ornstein–Uhlenbeck process defined by \eqref{eq:OU_prel}.

[Lemma lem:moment-MKT of arXiv:2412.01015, 'Classical beta ensembles and related eigenvalues processes at high temperature and the Mar'] The moment relation~(equation moment-relation of the paper) is equivalent to the following  recurrence relation
\begin{equation}
	(c)_n h_n = c \sum_{i=0}^{n-1}  \frac{(n-1)!}{i!} (c)_i h_i p_{n-i}, \quad n = 1, 2,\dots, \quad h_0 = 1.
\end{equation}

[Lem fixed-size-family-counts of arXiv:2607.21428, 'Subcritical percolation and network archaeology on random recursive tree substrate network'] Recall that \(W_{n,i}=|\mathcal{B}_{n,i}|\) are the ranked retained-tree blob
		sizes.  The following estimates hold.
		\begin{enumeratea}
			\item Let \(N_k(t)\) be the number of type families of size \(k\) at Yule
			time \(t\).  Then, for each fixed \(k\geqslant1\),
			\[
			\frac{N_k(t)}{Y(t)}
			\to
			q_k
			:=
			\frac{1-p}{p}B\left(k,1+\frac1p\right)
			\qquad\text{a.s.},
			\]
			where \(B(\cdot,\cdot)\) is the Beta function.  If
			\(N_{n,k}:=\#\{i:W_{n,i}=k\}\), then \(N_{n,k}/n\to q_k\) almost surely.
			\item For every fixed \(r>0\),
			\begin{equation}

				\sum_i W_{n,i}^r
				=
				\begin{cases}
					O_{\mathbb P}(n), & pr<1,\\
					O_{\mathbb P}(n\log n), & pr=1,\\
					O_{\mathbb P}(n^{pr}), & pr>1.
				\end{cases}
			\end{equation}
			In particular, for every \(\eta>0\),
			\[
			\sum_i W_{n,i}^r
			=
			O_{\mathbb P}\left(n^{\max\{1,rp\}+\eta}\right).
			\]
			\item For every \(\eta\in(0,1/p)\),
			\begin{equation}

				\sup_{x\geqslant1}
				\frac{x^{1/p-\eta}}{n}
				\#\{i:W_{n,i}\geqslant x\}
				=O_{\mathbb P}(1).
			\end{equation}
			\item If \(pr>1\), then the ranked \(r\)-mass is uniformly tight at scale
			\(n^{pr}\): for every \(\varepsilon>0\),
			\begin{equation}

				\lim_{L\to\infty}\limsup_{n\to\infty}
				\mathbb P\left(
				n^{-pr}\sum_{i>L}W_{n,i}^r>\varepsilon
				\right)=0.
			\end{equation}
		\end{enumeratea}

[Corollary 21 (Finite-time KSD propagation of chaos) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target},
\ref{ass:ksd-kernel}, and \ref{ass:concentration},
\begin{equation}
  \E\KSD_\pi(\mu_t^N,\mu_t)
  \le \frac{C}{\sqrt N}e^{L_{\mathrm{cpl}}t/2}.
\end{equation}

