[Lemma vbjbvbvebi of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $\xi(x)$ be as in (equation eq: xi of the paper). There exist a function $\tilde{\xi}_b(x)$ which is holomorphic in a $b$-independent neighborhood of $x=0$ such that the conjugation
\begin{equation}

\Psi(u)=M_b(x)\Phi(u),\ \ G=-\frac{F}{M_b(1+H_{20})}
\end{equation}
with 
\begin{equation}

M_b(x)=e^{\tilde{\xi}_b(x)}
\end{equation}
and 
\begin{equation}

\left|\begin{array}{l}
\nu_b=\nu+\xi(b)\\
\nu=-\gamma b(\tilde{D}_{11}+\tilde{D}_{30}-\tilde{E}_{11})
\end{array}\right.
\end{equation}
maps 
\begin{equation}
\left[1+H_{20}\right]u(1-u)\Psi'+\left[(1-2u)(1+H_{20})-\gamma(1+G_1)+2uG_2\right]\Psi=uF
\end{equation}
to
\begin{equation}

\Phi'-\left[\frac{\gamma-1}{u}+\frac{\gamma+\nu_b+1}{1-u}\right]\Phi=-\frac{G}{1-u}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma restr-equiv-lQ of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be a homomorphism of compact Lie groups, and let ${\mathcal{F}},{\mathcal{F}}'$ be \emph{families} of closed subgroups (i.e.\ non-empty collections of subgroups closed under subconjugates) of $G$ and $G'$, respectively, such that ${\mathcal{F}}$ contains every closed subgroup $H\subset G$ for which $\alpha(H)\in{\mathcal{F}}'$.
    Then
    \[
        \alpha^*\colon\cat{$\bm{G'}$-Top}\rightleftarrows\textbf{\textup{$\bm G$-Top}} 
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
\alpha_*
    \]
    is a Quillen adjunction with homotopical right adjoint.
    \begin{proof}
        It suffices to show that $\alpha^*$ sends generating (acyclic) cofibrations to (acyclic) cofibrations. By the explicit description of the generating cofibrations, and since $\textbf{\textup{$\bm G$-Top}}$ is topological, it then further suffices to show that $\alpha^*(G'/H')$ is ${\mathcal{F}}$-cofibrant for every $H'\in{\mathcal{F}}'$.

        By Illman's triangulation theorem [illman-triangle]*{Theorem~7.1}, $G'$ admits the structure of a $(G\times H')$-CW-complex, where $g\in G$ acts via left multiplication by $\alpha(g)$ and $h\in H'$ acts via right multiplication by $h^{-1}$. Note that $\alpha(g)g'h^{-1}=g'$ if and only if $h=g'^{-1}\alpha(g)g'$, i.e.~the $(G\times H)$-isotropy of any $g'\in G'$ is contained in the collection $\mathcal G$ of all subgroups of the form $\Gamma_{K,\alpha'}$ where $K\subset G$ and $\alpha'\colon K\to G'$ is conjugate to $\alpha$ and has image in $H'$. In particular, every cell in the $(G\times H')$-CW-structure on $G'$ needs to have isotropy contained in $\mathcal G$, i.e.\ the $(G\times H)$-space $G'$ is $\mathcal G$-cofibrant. To finish the proof, it then suffices by Lemma~(lemma:restr-equiv-rQ of the paper) to observe that for any $\Gamma_{K,\alpha'}\in\mathcal G$ the image under the quotient map $G\times H'\to G$ is precisely $K$, which satisfies $\alpha'(K)\subset H'$, so that $\alpha(K)\in{\mathcal{F}}'$ and hence $K\in\mathcal F$ by assumption.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let {\rm\Cref{assumpDPP_NplayerGame}} hold, and let $\hat\balpha^N \in \mathcal{N}\!\mathcal{A}_{s,N}$ be a sub-game--perfect Nash equilibrium. Then, for any $i \in \{1,\ldots,N\}$ and any $(t,\tilde{t}) \in [0,T] \times [t,T]$, the value process $V^{i,N} \coloneqq J^i(\cdot,\cdot,\hat\alpha^{i,N};\hat\balpha^{N,\smallertext{-}i})$ satisfies
\begin{align*}
V^{i,N}_t = \esssup_{\alpha \in {\cA}_\smalltext{N}} \E^{\P^{\smalltext{\alpha} \smalltext{\otimes}_\tinytext{i} \smalltext{\hat\balpha}^{\tinytext{N}\tinytext{,}\tinytext{-}\tinytext{i}}\smalltext{,}\smalltext{N}\smalltext{,}\smalltext{t}}_\smalltext{\cdot}} \bigg[ &V^{i,N}_{\tilde{t}} + \int_t^{\tilde{t}} f^i_s\big(X^i_{\cdot \land s}, L^N\big(\X^N_{\cdot \land s},(\alpha \otimes_i \hat\balpha^{N,\smallertext{-}i})_s\big), \alpha_s\big) \d s\\
& - \frac{1}{2} \int_t^{\tilde{t}} \partial^2_{m,m} G^i\big(M^{i,\star,N}_s, N^{i,\star,N}_s\big) \d \big[M^{i,\star,N}\big]_s - \frac{1}{2} \int_t^{\tilde{t}} \partial^2_{n,n} G^i\big(M^{i,\star,N}_s, N^{i,\star,N}_s\big) \d \big[N^{i,\star,N}\big]_s \\
& - \int_t^{\tilde{t}} \partial^2_{m,n} G^i\big(M^{i,\star,N}_s, N^{i,\star,N}_s\big) \d \big[M^{i,\star,N},N^{i,\star,N}\big]_s \bigg], \; \P\text{\rm--a.s.}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

