[Lemma eq: S2tilde of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] \begin{align} 
  \begin{split}
   \tilde{S}_2 &= -12 \int \llbracket W^2_T \rrbracket \circ
     \mathbb{W}^{[3]}_T K_T {\mathrm d} x \\ &\qquad \qquad + 12 \left( \int (\llbracket W_T^2
     \rrbracket \succ Z^{\flat}_T) K_T + \int (\llbracket W_T^2 \rrbracket H
     (\varphi_-, \varphi_+)_T) K_T {\mathrm d} x \right) + R_5, 
   \end{split}
   \end{align}
  where
  \begin{align}
    R_5 
    := & - 12 \int (\llbracket W^2_T \rrbracket \prec \mathbb{W}^{[3]}_T) K_T
    {\mathrm d} x + 6 \int (\llbracket W^2_T \rrbracket \prec K_T) K_T {\mathrm d} x -
    6 {\rm Com}_1 (\llbracket W^2_T \rrbracket, K_T) \\
    & + 12 \int (\llbracket W^2_T \rrbracket \succ (Z_T - Z^{\flat}_T)) K_T
    {\mathrm d} x, 
  \end{align}
  and 
  \begin{equation}
  	 {\rm Com}_1 (\llbracket W^2_T \rrbracket, K_T) = \int (\llbracket W^2_T
     \rrbracket \succ K_T) K_T {\mathrm d} x - \int (\llbracket W^2_T \rrbracket
     \circ K_T) K_T {\mathrm d} x. 
   \end{equation}

[Theorem th:um of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Suppose $\mathbb{E}[(X(t)-X(s))^2]^{1/2} \asymp \varphi(|t-s|)$ for all $t,s \in I$, where $\varphi$ is non-decreasing, continuous and regularly varying at 0 of index $\theta \in [0\,,1]$ with

    \begin{align}
        \int_0^h \frac{\varphi(r) \, {\rm d} r}{r \sqrt{\log(1/r)}} \lesssim \varphi(h) \sqrt{\log(1/h)} = o(1) \quad \text{as $h \to 0^+$.}
    \end{align}
    If there exist $C_0>0$, $\rho >0$, $a_0>0$, and $h_0 \in (0\,,1]$ such that
    \begin{align}
        \Var(X(t)-X(s)|X(t')-X(s')) \ge C_0 \Var(X(t)-X(s))
    \end{align}
    uniformly for all $h \in (0\,,h_0]$ and for all $t,s,t',s' \in I$ with $|t-s| \le h$, $|t'-s'| \le h$ and $|s-s'| \ge a_0 h^\rho$, then
    \begin{align}
        \lim_{h\to0^+}\sup_{t,s \in I: 0<|t-s| \le h} \frac{|X(t)-X(s)|}{\varphi(|t-s|) \sqrt{\log(1/|t-s|)}} = K_1 \quad \text{a.s.}
    \end{align}
    where $0<K_1<\infty$ is a constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:intersection-Brownian-multigraph of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] Let $g\in\mathbb Z_{\geq0}$, $m\geq1$, and
$\boldsymbol x\in\mathbb R_{>0}^m$.  For the unstable pairs $(0,1)$ and
$(0,2)$, interpret $F_{g,m}$ by
(equation eq:unstable-intersection-conventions of the paper).  Then
\begin{equation}
  \boxed{
  F_{g,m}(\boldsymbol x)
  =
  \frac{(\pi/2)^{m/2}}
  {(g+m-1)!\sqrt{x_1\cdots x_m}}
  \sum_{\boldsymbol\ell\in
  \mathfrak A_{m,g+m-1}^{\mathrm{conn}}}
  \mathfrak I_{\boldsymbol\ell}(\boldsymbol x).
  }

\end{equation}

Equivalently, let $M=(m_{pq})_{1\leq p\leq q\leq m}$ range over connected
multigraphs on the labeled vertex set $[m]$, with loops allowed and with
unlabeled edge copies, where $m_{pq}$ is the multiplicity of the edge
$\{p,q\}$. Suppose that $b_1(M)=g$.  Define $\mathfrak I_M$ to be
$\mathfrak I_{\boldsymbol\ell}$ for any labeling of the edge copies with
these multiplicities.  Permutation symmetry of the jump-pair variables
makes this independent of the chosen labeling.  Then
\begin{equation}
  F_{g,m}(\boldsymbol x)
  =
  \frac{(\pi/2)^{m/2}}{\sqrt{x_1\cdots x_m}}
  \sum_{\substack{M\text{ connected on }[m]\\ b_1(M)=g}}
  \frac{\mathfrak I_M(\boldsymbol x)}
  {\prod_{p\leq q}m_{pq}!}.

\end{equation}

[Lem of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] We have
    \begin{align}
    \Var\left(\sum_{i=1}^m I_i\left(I_i-1\right)\right)=\frac{2n(n-1)(m-1)}{m^2}.
    \end{align}

