[Theorem 3 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Let $\Phi \in \Delta_{2} \cap \Delta'$ be a $N$-function and let $A$ be an ergodic supralgebra on $\mathbb{\mathbb{R}}_{y}^{d}$ such that $A$ is translation invariant and  each of its elements is uniformly
		continuous.
	For each $\varepsilon > 0$, let $(u_{\varepsilon})_{\varepsilon\in E} \in W^{1}_{0}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$ be the unique solution of (\ref{ras2}). Then, as $\varepsilon \to 0$, 
\begin{equation*}
	u_{\varepsilon} \rightarrow u_{0} \quad  \;\textup{in} \; L^{\Phi}(Q\times\Omega)-weak \,\digamma\, \Sigma ,  
\end{equation*}
and 
\begin{equation*}
	Du_{\varepsilon} \rightarrow Du_{0} + \overline{D}_{\omega}u_{1} + \overline{D}_{y}u_{2} \quad  \;\textup{in} \; L^{\Phi}(Q\times\Omega)^{d}-weak \,\digamma\, \Sigma ,  
\end{equation*}
where $\mathbf{u} = (u_{0}, u_{1}, u_{2}) \in \mathbb{F}_{0}^{1}L^{\Phi}=  W^{1}_{0}L^{\Phi}_{D_{x}}(Q; I_{nv}^{\Phi}(\Omega))\times L^{\Phi}(Q; W^{1}_{\#}L^{\Phi}(\Omega))\times L^{\Phi}(Q\times\Omega; W^{1}_{\#}\mathcal{X}^{\Phi}_{A})$ 
is the unique solution to the minimization problem 
\begin{equation*}
\inf \left\{  F(\mathbf{v})\, : \, \mathbf{v} \in \mathbb{F}_{0}^{1}L^{\Phi} \right\},
\end{equation*}
where the functional $F$ on $\mathbb{F}_{0}^{1}L^{\Phi}$ is defined by 
\begin{equation*}
	F(\mathbf{v}) = \iint_{Q\times\Omega} \pounds_{A} \int  \varrho \circ f(\cdot,\cdot, \mathbb{D}\mathbf{v})\, dydxd\mu,
\end{equation*}
with $\varrho \circ f(\cdot,\cdot, \mathbb{D}\mathbf{v})(x,\omega,y) =  \varrho (f(x,\omega, \cdot, Dv_{0} + \overline{D}_{\omega}v_{1} + \overline{D}_{y}v_{2}(x,\omega,\cdot)))(y)$ for $(x,\omega,y) \in Q \times\Omega\times \mathbb{R}^{d}$ and $\varrho$ as in \eqref{rholabel}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2609.02785, 'Characterization of Stanley-Reisner varieties by their automorphism group'] Let $\Delta$ be the $1$-dimensional complex of a simple graph $G$ on $[n]$, $n\geq2$. Then:
\begin{enumerate}[label=\textup{(\arabic*)}]
\item an edge $\{u,v\}$ is exposed \rchange{if and only if} $u$ or $v$ is a leaf;
\item $\Delta$ is fully exposed \rchange{if and only if} $G$ is a disjoint union of stars with no isolated vertex;
\item $\Delta$ is fully hidden \rchange{if and only if} $G$ has no vertex of degree exactly $1$;
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:poisson_summation_hyperfluctuating of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] There exists a finite positive measure supported on $\mathbb{R}^{+}$ so that
		\begin{equation*}
			s_{\xi_B}(t)-\bar{s}_{\xi_B}(t) = \frac{\sqrt{2\pi}}{t^{1/h}}\int_{0}^{+\infty}\sum_{n \neq 0}\frac{e^{-\frac{1}{2u}(2\pi n+t)^{2}t^{-2/h}}}{\sqrt{u}} \, \mu(\mathrm{d}u).
		\end{equation*}

		Moreover, $\mu$ satisfies
		\begin{equation*}
			e^{-\frac{1}{2}|t|^{2h}} = \int_{0}^{+\infty}e^{-\frac{1}{2}t^{2}u} \,\mu(\mathrm{d}u), \quad t \in \mathbb{R}.  
		\end{equation*}

