body:
[Definition 2 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] For an increasing $f\colon X\to Y$, we define $\varepsilon(f)\colon \varepsilon(X)\to\varepsilon(Y)$ recursively as follows:
    \begin{enumerate}
        \item $\varepsilon(f)(0) = 0$.
        \item $\varepsilon(f)(\varepsilon_x) = \varepsilon_{f(x)}$.
        \item For $\alpha_0\ge \cdots\ge \alpha_{m-1}$ in $\varepsilon(X)$ with $m>1$, we define $\varepsilon(f)\bigl(\omega^{\alpha_0} + \cdots + \omega^{\alpha_{m-1}}\bigr) = \omega^{\varepsilon(f)(\alpha_0)} + \cdots + \omega^{\varepsilon(f)(\alpha_{m-1})}$.
    \end{enumerate}
    We also define the support transformation $\supp^\varepsilon_X\colon \varepsilon(X)\to [X]^{<\omega}$ recursively as follows:
    \begin{enumerate}
        \item $\supp^\varepsilon_X(0) = \varnothing$.
        \item $\supp^\varepsilon_X(\varepsilon_x) = \{x\}$.
        \item For $\alpha_0\ge \cdots\ge \alpha_{m-1}$ in $\varepsilon(X)$ with $m\ge 1$, $\supp^\varepsilon_X\bigl(\omega^{\alpha_0} + \cdots + \omega^{\alpha_{m-1}}\bigr) = \bigcup_{i<m}\supp^\varepsilon_X(\alpha_i)$.
    \end{enumerate}

[Defn Neutrality condition of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] A double divisor $\left(\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right)$ satisfies the neutrality condition $\left(\mathrm{NC}_b\right)$  if 
\begin{equation}
\int\boldsymbol{\sigma}=\int \boldsymbol{\sigma}^{+}+ \int \boldsymbol{\sigma}^{-}=2b.
\end{equation}

[Definition 210 of arXiv:2601.16377, '2601.16377'] We say that $\boldsymbol{F}(z) = (F_h(z))_{h = 1}^H$ is \emph{tame} if for each $h \in [H]$ there exists a complex neighborhood $\amsmathbb{M}_h$ of $[\alpha_h,\beta_h]$ such that
\begin{itemize}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]$;
\item $F_h(x^{\pm}) = \lim_{\epsilon \rightarrow 0^+} F_h(x \pm \ii \epsilon)$ exists for any $x \in (\alpha_h,\beta_h)$;
\item there exists an integer $m_{\boldsymbol{F}}$, called tameness exponent, and a real number $M_{\boldsymbol{F}}$ such that
\[
\sup_{z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]} \big| \big((z - \alpha_h)(z - \beta_h)\big)^{\frac{1}{2}m_{\boldsymbol{F}}} F_h(z)\big| \leq M_{\boldsymbol{F}};
\]
\item the function $x \mapsto F_h(x^+) + F_h(x^-)$ extends to a meromorphic function in $\amsmathbb{M}_h$.
\end{itemize}

[Lemma lem:discrepancy-summary of arXiv:2608.15515, '\LARGE Weak-Type Bounds for Convolution on the Boolean Hypercube'] For every $A\in\mathcal F_\theta$ contained in $\mathcal E_\theta$,
\begin{equation}
 D_A\lesssim
 \kappa_a\Lambda_a\sqrt{\mathcal S_A\mathbb P(A)}
 +\kappa_a\Lambda_a^2\mathcal S_A.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:2s5c-result of arXiv:2411.00930, '\bf \Large Asymptotic Product-form Steady-state for Multiclass Queueing Networks: A Reentr'] Under Assumption~(assumption:2s5c-t-moment of the paper) and~(assumption:multi-scale-2s5c of the paper),
there exist a random vector $(Z_1^\ast, Z_4^\ast)\in\mathbb{R}_+^2$ such that
    \begin{equation*}
        (rZ_1^{(r)}, rZ_2^{(r)}, rZ_3^{(r)}, r^2Z_4^{(r)}, rZ_5^{(r)})\Rightarrow (Z_1^\ast, 0, 0, Z_4^\ast,0),\quad\text{as }r\to0,
    \end{equation*}
    where ``$\Rightarrow$'' denotes convergence in distribution.

   Moreover, $Z_1^\ast$ and $Z_4^\ast$ are independent and have the following marginal distributions
   \begin{equation*}
        Z_1^\ast\sim\exp\big(1/d_1\big),\quad\text{and}\quad Z_4^\ast\sim\exp\big(1/d_4\big),
    \end{equation*}
    with
    \begin{align}
        d_1&=\frac{\alpha_1}{2(m_1+m_3-m_5\frac{m_2}{m_4})}\Big((m_1+m_3-m_5\frac{m_2}{m_4})^2c_{e,1}^2+m_1^2c_{s,1}^2+m_3^2c_{s,3}^2+m_5^2c_{s,5}^2\nonumber\\
        &\qquad\qquad\qquad\qquad\qquad\quad+(\frac{m_5}{m_4})^2\big(m_2^2c_{s,2}^2+m_4^2c_{s,4}^2\big)\Big)\\
        d_4&=\frac{\alpha_1}{2m_4}\Big((m_2+m_4)^2c_{e,1}^2+m_2^2c_{s,2}^2+m_4^2c_{s,4}^2\Big).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] There is a full Harris set $H\in\calX$ such that, for every $x\in H$ and every deterministic sequence $k\to_\lambda\infty$,

\begin{equation*}
\frac{N(k)}{|k|_1}\xrightarrow[k\to_\lambda\infty]{} \rho_\lambda
\end{equation*}

$\Pp_x$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2605.16868, '\ttl'] The infinite-dimensional fluid model is defined as follows: 
\begin{equation}

    \bar{Q}(t) =    \bar{X}(t) + ({\bf1}-\boldsymbol{G}^T) \bar{Y}(t),
\end{equation}
where 
\begin{equation}

  \bar{X}(t) =\bar{Q}(0) + \big[\lambda  - ({\bf1} - \boldsymbol{G}^T)\mu \big]  t,
\end{equation}
\begin{equation}

\bar{Y}(t)=\operatorname{diag}(\mu) \bar{I}(t),
\end{equation}
and $ \bar{I}(t)$ satisfies 
\begin{equation}

d\bar{I}_u(t)\geq0\,, \quad \bar{I}_u(0) = 0\,, \mbox{ and } \int_0^\infty 1_{\{\bar{Q}_u(s)>0\}} \bar{I}_u(ds)=0, \quad \forall\,u \in [0,1].
\end{equation}
We denote $\bar{Q} =\Phi_{\boldsymbol{G}^T}(\bar{X}) $ and $\bar{Y} =\Psi_{\boldsymbol{G}^T}(\bar{X})$ and call them as the reflected process and regulator, respectively. It is apparent that $\bar{Q}(0)\ge0$ and $\bar{X}\in\mathcal{C}_T(L_1)$.

[Theorem 2 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let $V\in\cC^{4k+7}(X_1,\dots,X_d)$ be a $k$-regular potential (see Definition \ref{definition:kregular}), and $Y^N$ a multimatrix model with potential $V$ (see Definition \ref{def:randompot}). There exists a transport map $T^N$ between the law of $Y^N$ and the one of a $d$-tuple of independent GUE random matrices $X^N$, i.e., $T^N$ such that for all measurable functions $f$,
    $$ \E\left[ f(Y^N) \right] = \E\left[ f\circ T^N(X^N) \right].$$

    \noindent Moreover, there exists $T^0 \in (\cC^k(X_1,\dots,X_d))^d$, as well as $T^m\in (\cC^{k+1-m}(X_1,\dots,X_d))^d$ for $m\in [1,k]$, such that, for all $N\geq 1$,
    \begin{equation}

        \sup_{H\in\M_N(\C)_{sa}^d}\ \norm{T^N(H) - \sum_{i=0}^k \frac{T^i(H)}{N^{2i}} } \leq \frac{C_{V,k}}{N^{2k+2}},
    \end{equation}
    for some constant $C_{V,k}$. Besides, there exists another constant $C_{V,k}$ such that
    \begin{align}

        \norm{T^0 - \id }_{\cC^k,\infty}\leq C_{V,k}, \quad\quad \norm{T^m}_{\cC^{k+1-m},\infty}\leq C_{V,k},\quad 1\leq m\leq k.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq_besselfirstmom of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] For any $r\in\{1,\dotsc,R\}$, 
\begin{equation} 
\mathbf{E}_\mathbf{0}\left(A_1^{(1)} A_1^{(2)} \dotsm A_1^{(r)}\right) = (-\nu)^{r-1} \beta_1 \beta_2 \dotsm \beta_r.  
\end{equation}

