[Proposition 12 (Degeneracy of $\dist_{\mathrm{AW}}$) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] For $L, M \in \mathscr{L}(N, d)$ the following are equivalent:
\begin{itemize}
\item[(i)] $\dist_{\mathrm{AW}}(L, M) = 0$, that is, $L \sim M$.
\item[(ii)] There exists $Q = \diag(Q_1, \ldots, Q_N)$, with $Q_t \in \mathscr{O}(d)$ for all $t \in [N]$, such that
\begin{equation} 
M = LQ.
\end{equation}
That is, $M_{s,t} = L_{s,t}Q_t$ (or $L_{s,t} = M_{s,t} Q_t^{\intercal}$) for $s, t \in [N]$. We denote by $\mathscr{O}(N, d) \cong \prod_{t = 1}^N \mathscr{O}(d)$  the set of $Nd \times Nd$ block diagonal matrices whose diagonal blocks are orthogonal.
\end{itemize}
In particular, we have 
\begin{equation} 
\dist_{\AW}(L, M) = 0 \Rightarrow LL^{\intercal} = MM^{\intercal}
\end{equation}
(that is, the covariance matrices coincide) and
\begin{equation} 
\dist_{\AW}(L, M) = \dist_{\AW}(L, MQ)
\end{equation}
for $L, M \in \mathscr{L}(N, d)$ and $Q \in \mathscr{O}(N, d)$.

[Lemma 5 (Half-space reduction) of arXiv:2608.30211, '2608.30211'] Let $W\in L^\infty(\R_+)$ be real and let $\varrho\in[0,1]$.  Then
\begin{equation}
 \lambda(-\Delta+W(y),\Hh^d,\varrho)
 =\lambda(-\partial_y^2+W(y),\R_+,\varrho),
\end{equation}
where $\Hh^d=\R^{d-1}\times\R_+$.

[Lemma 11 of arXiv:2607.18104, '2607.18104'] There exist $c,C>0$ such that for all $\delta>0$ and all $n\in \N$ with $n\geq \delta^{-2}$ the following holds. Fix any rectangle $\widetilde{\mathcal{R}} \subseteq \mathbb{R} \times [0,1]$ of side lengths $\frac{1}{4}$ by $\delta$. Then there exists a coupling $\mathbf{P}$ between a full-space directed landscape $\mathcal{L}^{\prime}$ and an unwrapped patched directed landscape $\Lpat$ such that
\begin{equation}
    \mathbf{P}\left( \Lpat(x,s;y,t) = \mathcal{L}^{\prime}(x,s;y,t) \,\,\, \forall (x,s;y,t) \in (\widetilde{\mathcal{R}})^2_{\uparrow} \cap \mathcal{D}_{n^{-1}} \right) \geq 1 - C\exp(-c\delta^{-1/2}) . 
\end{equation}
The result in \eqref{eq:patchedFullCase1} holds true with $\mathcal{D}_{n^{-1}}$ replaced by $\mathcal{V}_{\delta^{-1}}$.

