body:
[Definition 4 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] A kernel sequence $q=(q_k)_{k\in\N^d}$ is called a discrete multi-time semi-Markov kernel if

\begin{equation*}
\sum_{k\in\N^d}q_k(x,\X)=1,\qquad x\in\X.
\end{equation*}

It is called strict when $q_{\zerod}=0$.

[Prop pair of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Fix $\varepsilon\in(0,1/2)$ and $y\in\mathds{R}$. Then
\begin{align*}
 \sup_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}
 \abs{\frac{B_s}{N_1(s)N_2(s)}-2\gl}
 \stackrel{\pr}{\to}0.
\end{align*}
Moreover,
\begin{align}
 \pr\left(\inf_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}B_s=0\right)\to0,
 \qquad
 \inf_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}B_s\stackrel{\pr}{\to}\infty.
\end{align}
If $g_1,g_2$ are bounded Riemann-integrable functions on $[0,\infty)$, then
\begin{align*}
 \sup_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}
 \abs{\frac1{B_s}\sum_{\{u,v\}\in\mathcal{B}_s}
 g_1\bigl(A_u^{(1)}(s)\bigr)g_2\bigl(A_v^{(2)}(s)\bigr)
 -\prod_{i=1}^2\int_0^\infty g_i(a)e^{-a}\,\mathrm d a}
 \stackrel{\pr}{\to}0,
\end{align*}
where the ratio may be defined arbitrarily on $\{B_s=0\}$. Finally,
\begin{align}
 \int_{\mathfrak{s}_0}^{\mathfrak{s}_1}\frac1n
 \abs{\sum_{e\in\mathcal{B}_s}A_e(s)^{\theta-1}-\Gamma(\theta+1)B_s}\,\mathrm d s
 \stackrel{\pr}{\to}0.
\end{align}

