[Prop 7 of arXiv:2511.00679, 'Stochastic solutions to abstract telegraph-type equations involving fractional dynamics'] The solution of the fractional telegraph-type relativistic diffusion 
\begin{align}
&\bigg[(D_t^{\alpha})^2+2\lambda D_t^{\alpha}-H_{\nu,m}\bigg] u =0,\quad t> 0, \ \alpha, \nu \in(0,1], \\
&u(0)=f,\ \alpha \in(0,1],\\
& D_t^{\alpha}u(0)=0,\ \alpha \in(1/2,1],
\end{align}
is given by the convolution product $u(t,x)=(f\ast \Phi_\alpha(t))(x),$ for each $x\in\mathbb R^d,$where
\begin{equation*}
\Phi_\alpha(t,x)=\frac{1}{(2\pi)^{\frac d2}||x||^{\frac d2-1}}\int_0^\infty r^{\frac d2}J_{\frac d2-1}(r||x||)\widehat\Phi_\alpha(t,r)\de r,\quad t>0
\end{equation*}
and 
\begin{align*}
    \widehat\Phi_\alpha(t,\xi) = &= \frac{1}{2}\bigg[
\bigg(1+\frac{\lambda}{\sqrt{\lambda-\theta(||\xi||)}}\bigg)E_{\alpha,1}(r_1t^\alpha)+\\
&+\bigg(1-\frac{\lambda}{\sqrt{\lambda-\theta(||\xi||)}}\bigg)E_{\alpha,1}(r_2t^\alpha)\bigg],
\end{align*}
where 
$$\theta (||\xi||) = (m^{\frac{2}{\nu}}+||\xi||^2)^{\frac{\nu}{2}}-m$$
and
\begin{align}
\nonumber & r_1 = -\lambda+\sqrt{\lambda^2-\theta (||\xi||)},\\
\nonumber & r_2 = -\lambda-\sqrt{\lambda^2-\theta (||\xi||)}.
\end{align}
Moreover, for $\alpha \in (0,\frac{1}{2}],$ the solution to the problem \eqref{es3eq:fractelcrel}-\eqref{es3eq:fractelc2rel} has the following stochastic representation 
\begin{equation}
u_\alpha(t,x)=\mathbb E_x\left[f(W_d^\nu(\mathcal{L}^\alpha(t) ))\right] ,\quad t>0,x\in\mathbb R^d. 
\end{equation}

