[Defn def-green of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] We define the \textbf{Green's function for random walk on $\mathcal G$ reflected off of $\infty$ and killed upon hitting $\mathcal A$} by 
\begin{equation*}  
G_{\mathcal A}(x,y) := \mathbbm E_x[N_{\mathcal A}(y)]  .
\end{equation*}

[Theorem t:orgs of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] Let $P$ be an increasing stochastic kernel on $S$.
    If $P$ is order reversing, then $P$ is globally stable if and only
            if $P$ is bounded in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 (Variational representation for bridges) of arXiv:2511.14757, 'A weak convergence approach to the large deviations of the dynamic Schr\"odinger problem'] For any bounded, continuous function $F: C([0,1]:\bR ^d) \to \bR$, we have
\begin{equation}
    -\eta \log \bE \left[ \exp \left\{-\frac{1}{\eta} F(X^{\eta, xy}_t)\right\} \right] = \inf_{\nu^\eta \in \mathcal{A}} \bE \left[F(\bar{X}^{\eta, xy}_t) + \frac{1}{2}\int_0^1 | \nu^\eta_s |^2 ds \right],
\end{equation}
where $\calA$ is given in \eqref{eq:defA} and $\bar{X}^{\eta, xy} = \{ \bar{X}^{\eta, xy}_t \}_{t \in [0, 1]} $ is the controlled Brownian bridge characterized by (again interpreted componentwise)
\begin{equation}
    d\bar{X}^{\eta, xy}_t = (b + g_\eta^y)(t, \bar{X}^{\eta, xy}_t) dt + \sqrt{\eta} \sigma dW_t + \sigma \nu^\eta_t dt, \ \ \bar{X}^{\eta, xy}_0 = x,
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 (Sub-Gaussian empirical averages) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Let $Z_1,\ldots,Z_n$ be centered i.i.d. vectors in $\R^d$.  If
$\E e^{a\|Z_1\|^2}\le M$ for some $a,M \in (0,\infty)$, then there are $a',M' \in (0,\infty)$, depending only on $a,M,d$, such that
\begin{equation}
    \E\exp\left(a'n\left\|\frac1n\sum_{j=1}^nZ_j\right\|^2\right)
    \le M'.
\end{equation}

[Lemma lem:power_mean_loewner of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Fix $\varepsilon>0$ and $\mathbf{X}\in\R^{d_1\times d_2}$ 
	with singular value decomposition $\mathbf{X}=\mathbf{U}_{\mathbf{X}} \,\diag(\boldsymbol{\sigma})\,\mathbf{V}_{\mathbf{X}}^\top$ as in (def:optimalweightoperator of the paper). Define $
	\widetilde{\sigma}_i:= \max(\sigma_i,\varepsilon)^{-1}$ for $i \in [d]$ and $\widetilde{\sigma}_i:= \varepsilon^{-1}$ for $i \in [D] \setminus [d]$. For each $q\in[-\infty,\infty]$, 
	let $\mathbf{H}^{(q)}_{\boldsymbol{\sigma},\varepsilon}\in\R^{d_1 \times d_2}$ 
	be given entrywise for $i \in [d_1]$ and $j \in [d_2]$ by
	\begin{equation} 
	\bigl(\mathbf{H}^{(q)}_{\boldsymbol{\sigma},\varepsilon}\bigr)_{ij}
	:=
	\mathcal{M}_q(\widetilde{\sigma}_i,\widetilde{\sigma}_j),
	\end{equation}
	where $\mathcal{M}_q(\cdot,\cdot)$ denotes the $q$-power mean from (eq:def:powermean of the paper). 
	Let $\W{\mathbf{X}}{\varepsilon}^{(q)}$ be the corresponding weight operator defined as in (eq:W:operator:action of the paper), i.e., the operator mapping any $\mathbf{Z}\in\R^{d_1 \times d_2}$ to
	\begin{equation} 
	\W{\mathbf{X}}{\varepsilon}^{(q)}(\mathbf{Z})
	:=\mathbf{U}_{\mathbf{X}}\Bigl(\mathbf{H}^{(q)}_{\boldsymbol{\sigma},\varepsilon}\circ(\mathbf{U}_{\mathbf{X}}^\top \mathbf{Z}\mathbf{V}_{\mathbf{X}})\Bigr)\mathbf{V}_{\mathbf{X}}^\top.
	\end{equation}
	Then for any $-\infty\le q\le q'\le \infty$, 
	one has the Loewner ordering $
	\W{\mathbf{X}}{\varepsilon}^{(q)}  \preceq\ \W{\mathbf{X}}{\varepsilon}^{(q')}
	$ and the associated quadratic models $Q_\varepsilon^{(q)}$ and $Q_\varepsilon^{(q')}$ (cf. (eq:smoothedell1:IRLSmajorizer of the paper)) satisfy for all $\mathbf{Z}\in\R^{d_1 \times d_2}$ that
	\begin{equation} 
	Q_\varepsilon^{(q)}(\mathbf{Z}\mid\mathbf{X}) \leq Q_\varepsilon^{(q')}(\mathbf{Z}\mid\mathbf{X}).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm POC10 of arXiv:2411.03104, '{\bf Coupling Methods and Applications on Path Dependent McKean-Vlasov SDEs}\footnote{Supp'] Assume {\bf(C)} with
\begin{align}
K_b<\frac{2\beta^4}{\text{\rm{e}}^{\frac{2\beta^2}{\delta}r_0}(K_2-K_\sigma)\delta^2}
 \end{align}
 for $\delta:=\int_0^\infty s\text{\rm{e}}^{\frac{1}{2\beta^2}\int_0^s\{\gamma(v)+K_\sigma v\}\text{\rm{d}} v}\text{\rm{d}} s$.
Then there exist constants $c,\lambda>0$ such that
\begin{align*}&\mathbb W_1^{\Gamma^{r_0}}(P_t^\ast\mu_0,P_t^\ast\nu_0)\leq c\text{\rm{e}}^{-\lambda t}\mathbb W_1^{\Gamma^{r_0}}(\mu_0,\nu_0),\ \ \mu_0,\nu_0\in \mathscr P_{1}(\mathscr C_\infty).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary corollary_riccati_with_source of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Consider a Riccati equation 
    \begin{equation}
    \begin{cases}
        \bm \dot{\bm{\psi}}_t + \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{0}}}} + \frac{1}{2}\, \bm \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{11}}}} + \frac{1}{2}\, \bm \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{1}}}}^{\mathrel{\sqcup \mkern -3mu \sqcup} 2} + \bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{1}}}}\mathrel{\sqcup \mkern -3mu \sqcup}\bm{\gamma} + \bm f = 0,\quad t \in [0, T]\\
        \bm \bm{\psi}_T = \bm{p},
    \end{cases}
    \end{equation}
    where $\bm{p}, \bm{\gamma}, \bm f \in \TA[2]$. If the coefficient 
    $$
    \widetilde\bm{p} := \bm{p} + \left(\bm f - \dfrac{1}{2}\bm{\gamma}|_{{\color{NavyBlue}{\mathbf{1}}}} - \dfrac12\bm{\gamma}^{\mathrel{\sqcup \mkern -3mu \sqcup} 2}\right){\color{NavyBlue}{\mathbf{0}}} + \gamma{\color{NavyBlue}{\mathbf{1}}} \in \mathcal{B},
    $$
    then there exists a solution $\bm{\psi}$ and $r > 0$ such that
    \begin{enumerate}
        \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, the function $t \mapsto \bm \psi_t^{{\color{NavyBlue}{\mathbf{v}}}}$ is $C^1$ on $[0\,, T]\,$.
        \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, $\bm \psi_t|_{{\color{NavyBlue}{\mathbf{v}}}} \in \mathcal{A}_{\widetilde\bm{p}, r}$.
    \end{enumerate}

[Definition 2 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $(p_e)_{e \in E}$ be a random vector of elements of $[0,1]$. An \textbf{inhomogeneous random graph} (sampled from $(p_e)$) is a graph $K$ such that, conditional on $(p_e)_{e\in E}$, the variables $(\1_{e\in K})_{e\in E}$ are independent and satisfy
\begin{equation}
    \1_{e\in K} \sim \operatorname{Ber}(p_e).
\end{equation}

If, for $\mathbf{e} \in E$ chosen uniformly at random, the sequence of random variables $(n p_{\mathbf{e}})_{n \geq 1}$ is uniformly integrable, we say that $K$ is \textbf{weakly inhomogeneous}.

[Lemma 3 of arXiv:2511.05618, 'Coupling Invasion and First Passage Percolation'] For any edge $e$ not adjacent to the origin,
    \begin{align*}
        T_K(0, e)=\min_{f\sim e}T_K(0, f)+\tau_{K, e}.
    \end{align*}

[Lemma 10 of arXiv:2605.11877, 'Fluctuation analysis for a randomly perturbed dynamical system with state-dependent impuls'] Let $t\in [0, \sfT]$. For a given fixed $\gamma>0$, there exists $\lambda>0$ with  $\lambda> \frac{\gamma}{\alpha}+ \frac{\gamma^2}{2\alpha^2}$
	 such that
	\begin{equation*}
		\begin{aligned}
			\mathbb{E}\left[e^{\gamma Q^\eps_t}\right]&\le  \frac{e^{\lambda t}}{1- e^\gamma \mathbb{E}\left[ e^{-\lambda \tau^\eps_1}\right]}, \quad \text{provided } e^\gamma \mathbb{E}\left[ e^{-\lambda \tau^\eps_1}\right]<1\\
			& \text{where, } \mathbb{E}\left[e^{-\lambda \tau^\eps_1}\right]= \exp\left(\frac{\alpha}{\eps^{2p}} \left(1-\sqrt{1+2\lambda \eps^{2p}}\right)\right); \quad (\text{cf. \cite{KS91}})
		\end{aligned}
	\end{equation*}
	In fact, with the assumptions in lemma \ref{L:Renewal-Process}, there further exists a constant $\kappa(\lambda)$ independent of the parameter $\eps$ such that $$
	\mathbb{E}\left[e^{\gamma Q^\eps_t}\right]\le \kappa(\lambda) e^{\lambda t}
	$$

[Proposition prop of arXiv:2411.04802, 'Dynkin ghost games with asymmetry and consolation'] If $\gamma_2$ is a $\Gamma^2-$randomised stopping time and $\tau$ is a stopping time, then
\begin{equation}
    J_1(x;\tau,\gamma_2)= \mathbb E_x\left[e^{-r\tau}(1-p_1\Gamma^2_{\tau})g_1(X_\tau)+p_1\int_{[0,\tau]} e^{-rt}V^{h_1}(X_t)\,d\Gamma^2_t\right].
    \end{equation}
Similarly, if $\gamma_1$ is a $\Gamma^1-$randomised stopping time, then 
\begin{equation}
    J_2(x;\gamma_1,\tau)=\mathbb E_x\left[e^{-r\tau}(1-p_2\Gamma^1_{\tau-})g_2(X_\tau)+p_2\int_{[0,\tau)} e^{-rt}V^{h_2}(X_t)\,d\Gamma^1_t\right].
    \end{equation}

[Lemma lem:martprelim of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Suppose Assumption (assump:initdiff of the paper) holds.
For all $\varepsilon > 0$, $t \in [0,\infty)$, and $ \varphi \in \mathcal{D}(\mathbb{R})$, the following equalities hold:
\begin{equation} 
\begin{split}
\mathcal{M}_t^\varepsilon(\varphi) & := \langle \tilde{\mathcal{E}}_t^{\theta,\varepsilon}, \varphi \rangle - \langle \tilde{\mathcal{E}}_0^{\theta,\varepsilon}, \varphi \rangle - \frac{1}{2} \int_0^t \langle \tilde{\mathcal{E}}_s^{\theta,\varepsilon},\varphi'' \rangle ds \\
& = -(1-e^{-\sigma\varepsilon^{1/4}})\sum_{i \in \mathbb{Z}} \int_0^t \mathcal{G}^\varepsilon(s,Y_i^\varepsilon(s))(p_{\varepsilon^{1/2\theta}} * \varphi)(Y_i^\varepsilon(s))dB_i^\varepsilon(s),
\end{split}
\end{equation}
and 
\begin{equation} 
\begin{split}
& \mathcal{W}_t^\varepsilon(\varphi) := \mathcal{M}_t^\varepsilon(\varphi)^2 - (1-e^{-\sigma\varepsilon^{1/4}})^2\int_0^t \left( \sum_{i \in \mathbb{Z}} \mathcal{G}^\varepsilon(s,Y_i^\varepsilon(s))^2(p_{\varepsilon^{1/2\theta}} * \varphi)(Y_i^\varepsilon(s))^2  \right) ds \\
& = 2(1-e^{-\sigma\varepsilon^{1/4}})^2\sum_{i \in \mathbb{Z}} \int_0^t \Bigg( \sum_{j \in \mathbb{Z}} \int_0^s \mathcal{G}^\varepsilon(u,Y_i^\varepsilon(u)) \mathcal{G}^\varepsilon(s,\tilde{X}_j^\varepsilon(s)) \\
& \hspace{2in}(p_{\varepsilon^{1/2\theta}} * \varphi)(Y_i^\varepsilon(u))(p_{\varepsilon^{1/2\theta}} * \varphi)(Y_j^\varepsilon(s)) dB_j^\varepsilon(u) \Bigg) dB_i^\varepsilon(s).
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem E.g., Lemma 2.8 of~\cite{MaTo} of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Starting from a domain $\Lambda$ with boundary conditions $\tau$, if we change the boundary conditions on a subset $\Delta \subset \partial \Lambda$ of size $|\Delta|$ to get boundary conditions $\tau^{\Delta}$, then 
    \begin{align*}
        t_{\textsc{mix}}(\Lambda, \tau) \le  4\beta |E(\Lambda)|\log 2\cdot e^{4\beta |\Delta|}\cdot  t_{\textsc{mix}}(\Lambda, \tau^\Delta)
    \end{align*}

[Lemma 2-l03 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Recall the definition of $M^{p,\ell}_{k,x}$ introduced in
(equation 2-06b of the paper). There exists a finite constant ${\mathfrak c}({\boldsymbol u}^N)$,
uniformly bounded in $N$, such that
\begin{equation*}
\begin{gathered}
\sum_{k=1}^d \sum_{x\in{\mathbb T}_N^d}  M^{p, \ell}_{k,x} (\eta)^2
\;\le\; {\mathfrak c}({\boldsymbol u}^N) \, s_d(\ell)\, \frac{K}{N^2}\, 
\sum_{x\in{\mathbb T}_N^d}  H^{(\ell)}_{1,x} (\eta)^2 \;, 
\\
\frac{\sqrt{K}}{N}\,
\sum_{k=1}^d  \sum_{x\in{\mathbb T}_N^d}  |\,M^{p, \ell}_{k,x} (\eta)\,|
\;\le\; {\mathfrak c}({\boldsymbol u}^N)\,  \frac{K}{N^2} \, 
\Big\{\,  s_d(\ell)\, \frac{ N^{d}}{\gamma}
\;+\; \gamma\, 
\sum_{x\in{\mathbb T}_N^d} H^{(\ell)}_{1,x} (\eta)^2\,\Big\}
\end{gathered}
\end{equation*}
for all $\gamma>0$, $1\le p\le 3$.

