body:
[Theorem thm:matrix_azuma of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] {tropp2012user}}]

  Consider a finite adapted sequence $\{X_k\} \subset \mathrm{SA}_d$, and a fixed sequence $\{A_k\} \subset \mathrm{SA}_d$, that satisfy
  \begin{align*}
    \mathbb{E}[ X_k \mid \mathcal{F}_{k-1} ] = 0 \quad \text{and} \quad X_k^2 \preceq A_k^2 \quad \text{a.s.}
  \end{align*}
  Let \(\sigma^2 := \left\| \sum_k A_k^2 \right\|\).
  Then, for all $t \geq 0$,
  \begin{align*}
    \mathbb{P}\left[ \lambda_{\max} \left( \sum_k X_k \right) \geq t \right] \leq d \cdot e^{-t^2 / 8\sigma^2}~.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop strongly-convex-coordinate-gradients of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ m, d, M \in {\mathbb N} $, $ \mu, B, R \in (0,\infty) $, and let
$\mathcal V\subseteq{\mathbb R}^d$. Let $U$ be an ${\mathbb R}^m$-valued random variable with a
Lebesgue density $g$ satisfying
\bas{
  \|g\|_{L^\infty}\le B,
  \qquad
  \text{and}
  \qquad
  {\mathbb P}\bigl( | U | < R \bigr) = 1 .
}
Let $U_1,\dots,U_M$ be independent copies of $U$, and set
$\mathbf U=(U_1,\dots,U_M)$. Let
$\ell:{\mathbb R}^d\times{\mathbb R}^m\to{\mathbb R}$ be differentiable in its first argument. For
every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $, define
\bas{
  \varphi_{\theta,i} \colon {\mathbb R}^m \to {\mathbb R},
\qquad
  \varphi_{\theta,i}( u )
  =
  \frac{\partial\ell}{\partial\theta_i}(\theta,u),
}
and assume that $\varphi_{\theta,i}$ is $\mu$-strongly convex.
For every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $, define
\bas{
X_M^{(i)}(\theta,\mathbf U)
=-\frac1M\sum_{r=1}^M
\frac{\partial\ell}{\partial\theta_i}(\theta,U_r).
}
Let $\omega_m$ denote the Lebesgue volume of the Euclidean unit ball in
${\mathbb R}^m$, and set
\bas{
C_m=1+m3^{m-1}
}
and
\bas{
s_0
=\mu\min\left\{
\frac{R^2}{4},
\frac{1}{
16B^2\omega_m^2C_m^2R^{2m-2}}
\right\}.
}
Then the minibatch innovation $(X_M,\mathbf U)$ is $(c_M,q)$-regular on
$\mathcal V$ with
\bas{
c_M=\frac{(1-e^{-1})s_0^2}{2M^2}
\qquad
  \text{and}
\qquad
q=\frac{1-e^{-1}}2.
}
If, in addition, the coordinate derivatives of $\ell$ are uniformly bounded
on $ \mathcal V \times \{ u \in {\mathbb R}^m \colon | u | < R \} $,
then assumption~(equation eq:combined-main-boundedness of the paper) in
(thm:combined-early-late-numerical-time of the paper) is satisfied for $X_M$.

[Lemma 5 of arXiv:2605.13518, 'The inertial It\^{o} drift and its applications to particle collision'] Under Hypothesis \ref{hyp}, for every $p\geq 1$  we have
\begin{equation}

\sup_{\epsilon\in\,(	0,1)}\,\sup_{t \in\,[0,T]}\mathbb{E}\,\vert \sqrt{\mu(\epsilon)}\,u_{\e}(t)\vert^{2p}\leq c_{p,T},  \ \ \ \ \ \    \sup_{\epsilon\in\,(	0,1)}\,\sup_{t \in\,[0,T]}\mathbb{E}\,\vert \sqrt{\mu(\epsilon)}\,u_{\e}(t)\vert^{2p}\leq c_{p,T}.
	\end{equation}
	Moreover, for every $\delta>0$ and $\epsilon \in\,(0,1)$  we have
	\begin{equation}

\mathbb{E}\sup_{t \in\,[0,T]}\,\vert \sqrt{\mu(\epsilon)}\,u_{\e}(t)\vert^{2}\leq c_{\delta, T}\,\mu(\e)^{-\delta},\ \ \ \ \ \ \mathbb{E}\sup_{t \in\,[0,T]}\,\vert \sqrt{\mu(\epsilon)}\,u_{\e}(t)\vert^{2}\leq c_{\delta, T}\,\mu(\e)^{-\delta}.	
\end{equation}

