[Theorem 1 (Absorption probability for a random walk) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $d\geq 1$ and $n\geq d+1$. Let $\xi_1,\dots,\xi_n$ be (possibly dependent) random $d$-dimensional vectors with partial sums
$$
S_i = \xi_1 + \dots + \xi_i,\quad  1\leq i\leq n,\quad  S_0=0.
$$
We impose the following conditions on the joint distribution of the tuple $(\xi_1,\dots, \xi_n)$:
\begin{itemize}
\item [(i)] \emph{Symmetric exchangeability:} For every permutation $\sigma$ of $\{1,\dots,n\}$ and every choice of
signs $\eps_1,\dots,\eps_n\in\{+1,-1\}$, we have the equality in
distribution
    $$
    (\xi_1,\dots,\xi_n) \stackrel{d}{=}(\eps_1 \xi_{\sigma(1)}, \dots, \eps_n \xi_{\sigma(n)}).
    $$
\item[(ii)] \emph{General position of partial sums:}
For every $1\leq i_1 < \dots < i_d\leq n$, the probability that the vectors $S_{i_1}, \dots,S_{i_d}$ are linearly dependent is $0$.
\end{itemize}

Then
\begin{align}
    \pwalk{n}{d}
    &:=
    \pr\big(0 \in \Conv(S_1, S_2, \dots, S_n)\big)
    =
    \frac{2}{2^{n}n!}
    \sum_{r\geq 0}
    \stirlingb{n}{d+1+2r},

    \\
        \qwalk{n}{d}
    &:=
    \pr\big(0 \notin \Conv(S_1, S_2, \dots, S_n)\big)
    =
    \frac{2}{2^{n}n!}
    \sum_{r\geq 0}
    \stirlingb{n}{d-1-2r}.

\end{align}
Here, the numbers $\stirlingb{n}{k}$ with $n\in \{1,2,\dots\}$ and $k\in \mathbb Z$ are the $B$-Stirling numbers of the first kind defined by the generating function
\begin{align*}
    (t+1)(t+3) \cdots (t+2n-1)
    = \sum_{k\in \mathbb Z} \stirlingb{n}{k}\, t^k.
\end{align*}
In particular, $\stirlingb{n}{k}= 0$ for $n\in \{1,2,\dots\}$ and $k\notin\{0,\dots,n\}$, so that the sums appearing above terminate after finitely many nonzero terms. (Proof in the paper; no proof environment follows the statement in the TeX.)

