[Proposition 16 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] $\Psi^{HT}_{\beta}$ $(\beta \in (0,1])$, $\Psi^{LT}_{\beta}$ $(\beta>1)$ and $\Psi^{FT}_{\beta}$ $(\beta >1)$ satisfy:
\begin{enumerate}
 \item {\bf [Talagrand inequality]} There exists a universal constant $C_{\Psi}$ such that, for all sequence $(Y_k)_{1 \leqslant k \leqslant K}$ of independent, mean zero, random variables satisfying $|Y_k|_{\Psi}<+\infty$ for all $1 \leqslant k \leqslant K$, we have
\begin{equation}

 \left|\sum_{k=1}^K Y_k\right|_{\Psi} \leqslant C_{\Psi} \left( \Exp{\left|\sum_{k=1}^K Y_k\right|}+\left|\max_{1\leqslant k \leqslant K} |Y_k| \right|_{\Psi} \right).
\end{equation}
 \item {\bf [Maximal inequality]} There exists a universal constant $C_{\Psi}$ such that, for all sequence $(Y_k)_{1 \leqslant k \leqslant K}$ of random variables satisfying $|Y_k|_{\Psi}<+\infty$ for all $1 \leqslant k \leqslant K$, we have
 \begin{equation}

  \left|\max_{1\leqslant k \leqslant K} |Y_k| \right|_{\Psi} \leqslant C_{\Psi} \Psi^{-1}(K) \max_{1\leqslant k \leqslant K} |Y_k|_{\Psi}.
 \end{equation}
\end{enumerate}

[Thm 7 of arXiv:2605.07050, 'Universality of the fluctuations of the free energy in generalized Sherrington--Kirkpatric'] Recall the definition of $F_N(\beta)$ in Definition \ref{defn:sub_Gaussian}. Suppose that $W$ is a Wigner matrix, $\sqrt{N} W_{ij}$ $(i<j)$ is symmetric, and one of the following is true:
\begin{itemize}
\item the (rescaled) entry $\sqrt{N} W_{ij}$ is strictly sub-Gaussian, or
\item the (rescaled) prior $\sqrt{N} x_i$ is bounded, and its distribution is absolutely continuous in a neighborhood of $0$.
\end{itemize}
Suppose that Assumption \ref{assump:second_moment} holds with $\SNR_c$. Then, the statement in Theorem \ref{thm:free_energy_1} holds without any change for any $\beta \in (0, \sqrt{\SNR_c})$. In particular, it holds for any $\beta \in (0, 1/\sigma)$ if the prior is sub-Gaussian with variance proxy $\sigma^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 3 of arXiv:2608.30796, 'Tumor boundary instability induced by pressure feedback'] Let \(\lambda>0\) and \(\gamma>0\). The zero mode is neutral,
\begin{equation}

\mathcal{E}_0(\lambda,\gamma)=0.
\end{equation}
Moreover,
\begin{subequations}

\begin{align}
\mathcal{E}_l(\lambda,\gamma)
&=\frac{l^2}
{2(\sqrt{\lambda}+1)(\sqrt{\lambda}+\sqrt{\gamma})}
+O(l^4)
\qquad\text{as }l\to0^+,
\\
\mathcal{E}_l(\lambda,\gamma)
&=-\frac{l}
{(\sqrt{\lambda}+1)(\sqrt{\lambda}+\sqrt{\gamma})}
+\frac{1}{\sqrt{\lambda}+1}
+O(l^{-1})
\qquad\text{as }l\to+\infty.

\end{align}
\end{subequations}
Consequently, sufficiently high-frequency modes are stable, and the
continuous modal growth-rate curve has a unique positive zero
\(l_*(\lambda,\gamma)>0\). More precisely,
\begin{equation}

\mathcal E_l(\lambda,\gamma)>0
\quad\text{for }0<l<l_*(\lambda,\gamma),
\qquad
\mathcal E_l(\lambda,\gamma)<0
\quad\text{for }l>l_*(\lambda,\gamma).
\end{equation}

For a fixed integer \(l\geq1\), let \(\lambda_0^l>l^2\) denote the
threshold for the model without pressure feedback, characterized by
\begin{equation}

\mathcal{E}_l(\lambda_0^l,0)=0,
\end{equation}
as established in \cite{feng2025nonsymmetric}. If
\(0<\lambda<\lambda_0^l\), then there exists a unique
\(\gamma_l^*(\lambda)>0\) such that
\begin{equation}

\mathcal{E}_l(\lambda,\gamma_l^*(\lambda))=0.
\end{equation}
Furthermore,
\begin{equation}

\mathcal{E}_l(\lambda,\gamma)<0
\quad\text{for }0<\gamma<\gamma_l^*(\lambda),
\qquad
\mathcal{E}_l(\lambda,\gamma)>0
\quad\text{for }\gamma>\gamma_l^*(\lambda),
\end{equation}
and the crossing is transversal:
\begin{equation}

\partial_\gamma\mathcal{E}_l
(\lambda,\gamma_l^*(\lambda))>0.
\end{equation}

