[Proposition 7 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] For $n\ge a$, let
\begin{equation*}
s_n=\Big(\frac{a(2p-1)}{2a(1-p)-1}\Big)^2\sum_{k=a}^{n}(b_kc_k^{-1})^2.
\end{equation*}
Then,\vspace{.1cm}\\
\noindent{(i)} for $0\le p< (4a-1)/4a$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{s_n}{n^{4a(1-p)-1}}=\frac{(\Gamma(a(2p-1)+1))^2}{4a(1-p)-1},
\end{equation*} 
\noindent{(ii)} for $p=(4a-1)/4a$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{s_n}{\log n}=\Big(\Gamma\Big(a+\frac{1}{2}\Big)\Big)^2,\ \ \text{and}
\end{equation*}
\noindent{(iii)} for $(4a-1)/4a<p\le 1$, we have $\lim_{n\to\infty}s_n=l$,
where $l$ is some non zero constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 (Proposition 1.1 and Theorem 1.2 in \cite{AizenmanJung2007}, and Theorem 1 in \cite{Swart2018}) of arXiv:2604.15753, 'The truncation property and continuity for \\ the long-range contact process on $\mathbb{Z'] Consider the LRCP  on $\bZ^d$, $d\geq 1$, with $\lambda \in \Lambda$ and $\delta>0$. 
\begin{enumerate}
    \item[i)] The process is subcritical if and only if $\chi(\lambda,\delta)<\infty$ and there exists some $\tau<0$ such that
    \begin{equation}
     \inf_{t >0 } \frac{1}{t} \log  \bE_{\lambda,\delta} \left[  \left| \left\{ x\in \bZ^d \colon \eta_t^o(x)=1\right\} \right| \right] = \tau.
    \end{equation}
     Moreover, if the process is subcritical, then $\bar{\nu}_{\lambda,\delta} = \delta_{\underline{0}}$.
    \item[ii)] If the process is critical, then $\chi(\lambda,\delta)=\infty$.
\item[iii)]   If the process is supercritical, then  $\chi(\lambda,\delta)=\infty$ and $\bar{\nu}_{\lambda,\delta} \neq \delta_{\underline{0}}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2608.28307, 'Rigidity of closed $\lambda$-self-expanders'] Let $x:M^n\to \mathbb{R}^{n+1}$ be a $\lambda$-self-expander, then we have
\begin{equation}
\begin{split}
&LH=S(\lambda-H)-\frac{1}{2}H,\\
&LS=2|\nabla h|^2-S-2S^2+2\lambda Str(h^3),\\
&L|x|^2=|x|^2+2\lambda\langle x,\xi\rangle+2n.
\end{split}
\end{equation}

[Corollary uniform of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] The sequence $\{\Phi _{n}\}_{n\geq 0}$ converges to $\Phi
_{\infty }$ locally uniformly on $(0,1)$. Moreover, the fixed points $\phi
_{n}$ converge to $\phi ^{\ast }$. If $\phi ^{\ast }\in (0,1)$, then 
\begin{equation}
\Phi _{\infty }(\phi ^{\ast })=\phi ^{\ast }.  
\end{equation}

