body:
[Lemma lem:cluster size restricted of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] Let $J$ be an isometry-invariant, integrable, and regular kernel on $\mathbb{H}^1_L$. If the infinite cluster density $\theta \coloneqq \mathbb{P}_{J} \left( |K_0| = \infty \right)$ is positive then 
	\begin{equation*}
		\mathbb{P}_{J} \left( |K_{\max}(\Lambda_n)| \geq (\theta -\varepsilon)|\Lambda_n| \right) \underset{n\to \infty}{\longrightarrow} 1 
	\end{equation*}
    for every $\varepsilon>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 (diffusion local time) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[definition]{diffusion-local-time}
  For a diffusion $X$ with speed measure $m$, the \emph{diffusion local time} $\ell_t^a$ at level $a$ is defined by
\[
\ell^a_t(X) = \lim_{\varepsilon \downarrow 0} \frac{1}{m((a-\varepsilon, a+\varepsilon))} \int_0^t \mathbf{1}_{\{|X_s - a| < \varepsilon\}}\,ds.
\]
The following occupation-time formula holds: 
for measurable $f \geq 0$,
\begin{equation}
\int_0^t f(X_s)\,ds = \int f(a)\,\ell^a_t(X)\,m(da).
\end{equation}

[Proposition prop:Polya-Schur of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $T:\mathcal{P}(\mathbb{C})\rightarrow\mathcal{P}(\mathbb{C})$ be a linear operator which commutes with the diagonal (in the monomial bases) operator $z\partial_{z}$ and let $\tau_k$ be such that $Tz^k=\tau_kz^k$. Additionally, let $\Phi_{T}$ be the formal power series \begin{equation}
		\Phi_{T}(z)=\sum_{k=0}^{\infty}\frac{\tau_k}{k!}z^{k}=T\left[\exp( z)\right].
	\end{equation} Then, $T$ preserves real-rootedness if and only if either $\Phi_{T}(z)$ or $\Phi_{T}(-z)$ is an entire function in $\mathcal{LPI}$. Moreover, $T$ maps non-negative roots to real roots if and only if $\Phi_{T}\in\mathcal{LP}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose that $\{X_k\}_{k\geq 1}$ is a d-dimensional $\alpha$-mixing stationary sequence on a regular sublinear expectation space $(\Omega,\mathcal{H},\hat{\mathbb{E}})$ for some $\alpha>0$ with $\hat{\mathbb{E}}[|X_1|^{2}]<\infty$. If $X_1$ has no mean-uncertainty, then 
        \begin{equation*}
         \lim_{n\to\infty}\frac{1}{n}\sum_{k=1}^nX_k=\hat{\mathbb E}[X_1], \ \hat{\mathbb{E}}\text{-q.s.}
     \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

