[Proposition prop:L1_difference of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] If $f$ and $\widetilde{f}$ satisfy the assumptions in Definition  ~(ass:ft of the paper), then as $n\rightarrow\infty$,
\begin{equation}
    \sum_{x\in \Lambda_L}\Bigl|\, p_n(0,x) - \tilde{p}_n(0,x)\,\Bigr|
    = o(1).
\end{equation}

[Thm B-Tri of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > -\frac12$ and ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with ${\kappa}_i > -1$, $1 \le i \le d_2$, define
\begin{align} 
  {\mathfrak D}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle} u : = \, &   (1-|\bm y|) \Delta_{\bm x} - \big({\langle} \bm x, \nabla_{\bm x} {\rangle} + 
   {\langle} \bm y, \nabla_{\bm y} {\rangle}\big)^2  +  \sum_{i=1}^{d_2} \left( y_i \partial_{y_i}^2 + (\kappa_i +1) \partial_{y_i} \right) \\
    & - (|{\boldsymbol{\kappa}}| + 2\mu +d_1+d_2-1) \big({\langle} \bm x, \nabla_{\bm x} {\rangle} +  {\langle} \bm y, \nabla_{\bm y} {\rangle}\big). \notag
\end{align}
Then ${\mathcal V}_n({\mathbb B}^{d_1}\! \rtimes \triangle^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})$ is an eigenspace of 
${\mathfrak D}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}$ for each $n \in {\mathbb N}_0$. More precisely, 
\begin{align} 
  {\mathfrak D}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle} u = - n \big( n+ | {\boldsymbol{\kappa}}| + 2 \mu + d_1 +d_2 -1 \big) u, \quad
      \forall u \in {\mathcal V}_n\big({\mathbb B}^{d_1}\! \!\rtimes\!\triangle^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}\big).
\end{align}

[Prop 28 of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] Let $\sigma \subset \RR^D$ be an affine simplex and let $\tau \subset \sigma$ be its face. Let $v^\sigma_\bullet = (v_0, \ldots v_d)$ and $v^\tau_\bullet = (v_{u(0)}, \ldots v_{u(m)})$ be the (unique) orderings of the vertices of $\sigma$ and $\tau$ such that $u(0) < \ldots < u(m)$. Then the following holds:
    \begin{align*}
        \FK_k(\sigma, v_\bullet^\sigma)|_\tau = \FK_k(\tau, v_\bullet^\tau)
    \end{align*}

[Corollary 23 (Application to a near-output Wick-centered paracontrolled block) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Assume the hypotheses of Theorem~\ref{thm:final}.  Let $\Delta_Q$ and $\Delta_M$ be the Fourier multipliers associated with the fixed cutoffs $\chi_Q$ and $\chi_M$.  Let $\Psi^j_{\Lambda,N}$ be the Gaussian block synthesized by $S_{j,\Lambda,N,\cdot}$ and the isonormal process $W_j$.  Suppose that the dyadic multiplier of $I_\lambda(t,s)$, together with the localized product symbol, satisfies the order-zero amplitude hypothesis above with deterministic envelope $\Kdet(N)\lesssim N^{-\lambda}$ on the admissible near-output sector.  The near-output Wick-centered paracontrolled block is, at finite cutoff, the operator
\begin{equation}
 \cT^{\circ,{\rm near}}_\Lambda(w)(t)
 :=
 \sum_{(N,Q,M)\in\Triads}
 \int_0^t
 \Delta_M
 \Bigl[
 I_\lambda(t,s)\bigl(\Delta_Qw(s)\,\Psi^1_{\Lambda,N}(s)\bigr)
 \circ_{\rm loc}
 \Psi^2_{\Lambda,N}(t)
 \Bigr]^\circ\,\dd s.
\end{equation}
Here $[\,\cdot\,]^\circ$ means complete Wick centering of the two Gaussian factors before the operator estimate is applied.  Equivalently, the $(N,Q,M)$ block of~\eqref{eq:pc-operator-formal} is precisely
\begin{equation}
 \int_0^t \cB^\circ_{\Lambda,N,Q,M}(t,s)w_Q(s)\,\dd s,
\end{equation}
with the centered kernel of Section~\ref{sec:setup}.

If
\begin{equation}
 \Gamma>\frac d2,
 \qquad
 \sigma\in I_{\rm in}:=
 \bigl(\max\{0,d-\Gamma\},\,\lambda+\Gamma-d\bigr),
 \qquad
 s<\lambda+\Gamma-d,
\end{equation}
then, for every finite $p\ge2$,
\begin{equation}
 \cT^{\circ,{\rm near}}_\Lambda:
 C_TL^2\cap L_T^\infty B^\sigma_{2,\infty}
 \longrightarrow
 C_TH^{s-\lambda}\cap L_T^1B^{\sigma-\lambda}_{2,\infty}
\end{equation}
is uniformly bounded in $L^p(\Omega)$ and converges in $L^p$ operator norm.  If the Galerkin-state finite-state condition holds, it also converges on one full-probability event along the whole Galerkin cutoff sequence.

If the Volterra multiplier contributes $N^{-\lambda}$ and the two Gaussian covariance envelopes contribute $N^{-\alpha_1}$ and $N^{-\alpha_2}$, then the power-law exponent is
\begin{equation}
 \Gamma=\lambda+\alpha_1+\alpha_2.
\end{equation}
Thus the near-output centered Wick block~\eqref{eq:pc-operator-formal} maps the input regularity interval
\begin{equation}
 \max\{0,d-\lambda-\alpha_1-\alpha_2\}<\sigma
 <2\lambda+\alpha_1+\alpha_2-d,
 \qquad
 s<2\lambda+\alpha_1+\alpha_2-d.
\end{equation}
In the equal-gain case $\lambda=\alpha_1=\alpha_2=\alpha$, this becomes
\begin{equation}
 \sigma\in\bigl(\max\{0,d-3\alpha\},\,4\alpha-d\bigr),
 \qquad
 s<4\alpha-d.
\end{equation}
The interval is nonempty exactly when $\alpha>2d/7$; in dimension $d=3$ this is $\alpha>6/7$.  If $3\alpha>d$, the lower endpoint is $0$; for $d=3$ and $\alpha=1$, one may take any $0<\sigma<1$ and any $s<1$.  Deterministic covariance contractions and far-output tails are not included in this corollary.

[Proposition 160 of arXiv:2601.16377, '2601.16377'] The total number of lozenge tilings of the trapezoid of width $N$ and with dents at $\ell_1 < \ell_2 < \dots < \ell_N$ is
\begin{equation}

\prod_{1 \leq i < j \leq N}{\frac{\ell_j - \ell_i}{j - i}}.
\end{equation}

[Proposition eq:lln_conditions of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:condition_check}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega(d_G(x,y)^{-d \alpha})$ with $\alpha \in (0,2)$. 

    Let $\beta > \beta_c$.

    Let $(\mathcal{G}_r)_{r \in \mathbf{N}}$ be the sequence of random graphs sampled from $\mathbf{P}_{\beta}$ restricted to $B(r)$.

    Then
    \begin{equation}

        \lim_{k \to \infty}
        \limsup_{r \to \infty}
        \frac{1}{\# B(r)^2}
        \mathbf{E}_{\beta}
        \left[
            \sum_{u,v \in V(\mathcal{G}_r)}
            \mathbf{1}
            \left(
                \# 
                K_r(u) 
                ,
                \# 
                K_r(v) 
                > 
                k,
                u 
                \not\leftrightarrow
                v
            \right)
        \right]
        =
        0.
    \end{equation}

