body:
[Lemma hardtwoedge of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] The two-edge crossing probabilities satisfy
    \begin{align*}
        \pi_{(u),R}^{(2)} &\asymp  
        \pi_{(u),R}+ u^{-\gamma} R^{d(2-\gamma-\frac1\gamma)}\wedge 1
        \asymp \begin{cases}
                    u^{-\gamma} R^{d(2-\gamma-\frac1\gamma)} & \text{ on } \{u\geq R^{-d}\},\\
                    u^{-1} R^{d(1-\frac1\gamma)} & \text{ on } \{R^{-d} \geq u \geq R^{d(1-\frac1\gamma)}\},\\
                    1 & \text{ on } \{ R^{d(1-\frac1\gamma)} \geq u\}.
                \end{cases}\\
        \pi_{r,R}^{(2)}  &\asymp \pi_{r,R}+ r^{d\gamma} R^{d(2-\gamma-\frac1\gamma)}
        \asymp \begin{cases}
                    r^{d\gamma} R^{d(2-\gamma-\frac1\gamma)} & \text{ on } \{r \leq R (\log R)^{\frac{-1}{d(1-\gamma)}}\},\\
                    r^d R^{d(1-\frac1\gamma)} \log R & \text{ on } \{ R (\log R)^{\frac{-1}{d(1-\gamma)}} \leq r \leq R/2 \}.
                \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cylinder of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] Let $ (\varepsilon_n)_{ n \ge 1} $ be a positive sequence decreasing to $0$ such that $ \log \varepsilon_n \sim \log \varepsilon_{n+1}$. Then for every $ \bar{\omega} \in \Omega$ we have 
    \begin{equation*}
    \underline{\mathsf{ord}}_{\mathrm{loc}}  W ( \bar{\omega} ) \ge  \liminf_{ n \to + \infty} \frac{\log ( - \log W ( \mathcal{C}_{n} (\bar{\omega} ,\varepsilon_n )  )) }{  -  \log \varepsilon_n } 
    \end{equation*}
    and
    \begin{equation*} 
    \overline{\mathsf{ord}}_{\mathrm{loc}}  W ( \bar{\omega} )  \ge  \limsup_{ n \to + \infty}  \frac{\log ( - \log W ( \mathcal{C}_{n} (\bar{\omega} ,\varepsilon_n )  )) }{  -  \log \varepsilon_n }  \; . 
    \end{equation*}

