    \begin{equation}
        \sum_{k=1}^\infty \left(F_{\alpha,2}(w)F_{\beta,1}(w)\right)^k = c(w)F_{\alpha,2}(w)F_{\beta,1}(w)
    \end{equation}
    where $c(w)$ is defined by equation (equation eq:c-def of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:infvolRGmap of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [FSmap]

Under the assumptions of Theorem~(thm:contrlldRG of the paper),  for any $j\ge 0$,  there exists a map
\begin{align}
	\Phi_{j+1}^{\Z^d} = (\Phi^U_{j+1} , \Phi^K_{j+1}) : \cD^{(0)}_j \times \cK^{\Z^d}_j \times \mathbb{A}_j (\tilde{m}^2) 
		\rightarrow \left( (\R + \sigma_{\sf ox} \R)^{\Lambda} \times \cV^{(0)} \right) \times \R\cK^{\Z^d}_{j+1}
\end{align}
that satisfies (equation eq:controlledRG22 of the paper)--(equation eq:controlledRG24 of the paper) and its restriction to finite volume is identical to $\Phi_{j+1}^{\Lambda_N}$ in the following sense: 
if $j +1 < N$ and $K_j \in \cK^{\Z^d}_j$ projects to $K'_j  \in \cK^{\Lambda_N}_j$, 
and let $(U_{j+1},K_{j+1}) = \Phi^{\Z^d}_{j+1} (U_j, K_j)$ and $(U'_{j+1},K'_{j+1}) = \Phi^{\Lambda_N}_{j+1} (U_j, K'_j)$,  then $K_{j+1}$ also projects to $K'_{j+1}$ and $U_{j+1} = U'_{j+1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:improveMHperturb of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] In the setting of this subsection, for $\varepsilon > 0$ we have
	\begin{align*}
		t_{\mathrm{mix},1}(L_{\beta,\delta},\varepsilon) &\leq \dfrac{72n^3e^{\beta 2\delta}}{1-e^{-\beta}}\left(\beta n +  \log \left(\dfrac{2n+1}{\varepsilon}\right)\right), \\
		t_{\mathrm{mix},1}(P_{\beta,\delta},\varepsilon) &\geq \left(\dfrac{e^{\beta (n-2\delta)}}{(2n+1)^2} - 1\right)\log \left(\dfrac{1}{\varepsilon}\right).
	\end{align*}

