[Thm 11 of arXiv:2511.02763, 'The Cayley-Moser problem with Poissonian arrival of offers'] Assume that $M=+\infty$ and the function $\phi(x)$ defined by \eqref{defphi} satisfies 
\begin{equation}
\lim_{x\rightarrow \infty} \frac{\phi(x)}{\int_{x}^\infty \phi(u)du}=c,\;\;\;c>0.
\end{equation}
Then, as $t\rightarrow \infty$,
\begin{equation}
\mu(t)\sim\frac{1}{c}\ln(t),\;\;\;\mu'(t)\sim \frac{1}{ct},
\end{equation}
\begin{equation}
\lim_{t\rightarrow \infty} Var[S_t]=\frac{2}{c^2}.
\end{equation}

