[Lemma lem:resolvent of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] Fix $C>0$ and assume $|z-\Lambda_N|\leq C N^{\ell-1}$.  For all sufficiently
large $N$, the operators represented by the compressed forms satisfy
\begin{align}
 Q_1(K_{\ell,N}-z)Q_1
 &\geq c_\ell N^\ell Q_1,\\
 Z_3(K_{\ell,N}-z)Z_3
 &\geq c'_\ell N^\ell Z_3.
\end{align}
Moreover, on $P_{11}\mathcal H_{0,N}$,
\begin{equation}
 P_{11}\bigl(Q_1(K_{\ell,N}-z)Q_1\bigr)^{-1}P_{11}
 =\frac{P_{11}}{(2^\ell-1)\Lambda_N}
 +O_\ell(N^{-\ell-1})
\end{equation}
in operator norm.

[Corollary coA.2 of arXiv:2606.15203, 'The existence of invariant sublinear expectations for $G\text{-}$SDEs'] ([pengbook])
    For any $\xi \in L_G^2(\Omega_t;\mathbb{R}^d)$, we have 
    \begin{equation}
        \bar{E}[\vert X^{t,\xi}_{t+\delta}-\xi\vert ^2 | \Omega_t] \leq C(1+\vert \xi \vert^2)\delta\ for \ \delta\in[0,T-t],
    \end{equation}
    where the constant $C$ depends only on the Lipschitz constants of $b$, $h$ and $\sigma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 18 of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] An \emph{abstract ribbon graph} $\Gamma = (V,E,L)$ consists of 
    \begin{itemize}
        \item a set of \emph{vertices} $V$
        \item a set of directed \emph{edges} $E$, with \emph{head} and \emph{tail} maps $h,t:E\rightarrow V\sqcup\set{\infty}$
        \item a set of \emph{loops} $L$, which may be thought of as edges with no endpoints
        \item for each $v\in V$, a cyclic ordering of the set $E(v) := \set{E|h(E)=v}\sqcup\set{E|t(E)=v}$ of edges incident at $v$. $\set{E|h(E)=v}$ and $\set{E|t(E)=v}$ make up the \emph{incoming} and \emph{outgoing} edges at $v$, respectively.
        \item for each $v\in V$, a partition of $E(v)$ into two contiguous segments $E_s(v),E_t(v)$ with respect to the cyclic ordering. These form the \emph{source} and \emph{target} of $v$. If $E_s(v) = \emptyset$ (or respectively $E_t(v) = \emptyset$), then we additionally require a choice of breaking the cyclic ordering into a total ordering of $E_t(v)$ (or respectively $E_s(v)$). In all other cases, the cyclic ordering uniquely determines such a total ordering. We choose the total ordering on $E_t(v)$ such that it agrees with the cyclic ordering, and on $E_s(v)$ such that it is the reverse of the cyclic ordering.
    \end{itemize}
    Edges $e$ with $h(e) = \infty$ or $t(e) = \infty$ may be thought of as edges with a loose endpoint.

    Graphically, we may represent this as the disjoint union of a directed graph (possibly with parallel edges and edges whose head and tail are the same) and some loops, except each vertex is as depicted in Figure \ref{fig:ribbon-vertex}.

    \begin{figure}[hbt!]
        \begin{tikzpicture}
            \draw[draw=black, double=white, double distance=5pt] (-0.3,-0.3) to [out=down,in=up] (-1,-1);
            \draw[draw=black, double=white, double distance=5pt] (0.3,-0.3) to [out=down,in=up] (1,-1);
            \draw[draw=black, double=white, double distance=5pt] (0,-0.3) -- (0,-1);
            \draw[draw=black, double=white, double distance=5pt] (-0.2,0.3) to [out=up,in=down] (-0.7,1);
            \draw[draw=black, double=white, double distance=5pt] (0.2,0.3) to [out=up,in=down] (0.7,1);
            \draw[rounded corners] (-0.6,-0.3) rectangle (0.6,0.3);
        \end{tikzpicture}
        \caption{Vertex $v$ of a ribbon graph.} 
    \end{figure}

    In this diagram, the source of $v$ is taken to be the bottom side of the rectangle, while the target is the top side. The cyclic ordering is given by the locations of the endpoints of the edges on the perimeter of the rectangle in clockwise order. Thus, the orderings on $E_s(v)$ and $E_t(v)$ are given from left to right.

    When relevant, we will indicate the direction of an edge by drawing an arrow on the corresponding ribbon. In general, the direction of an edge is omitted when it may be arbitrarily chosen.

[Prop Prop_SmoothingOperators of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] There is a family of smoothing operators $\paren{S_\varepsilon : \varepsilon \in (0,1) }$ on $L^2\Gamma\paren{NZ{\backslash} Z, \mathring S \otimes \mathring{\mathfrak l}}$ such that
  for every
  $\varepsilon \in (0,1)$, \ 
  $\phi \in L^2\Gamma\paren{U{\backslash} Z, \mathring S \otimes \mathring{\mathfrak l}}$, and
  $k,\ell \in {\mathbf{N}}_0$ with $k \geqslant \ell$,
  \begin{align}

    \Abs{S_\varepsilon\phi}_{\mathring K^k}
    &\lesssim_{k,\ell}
      \varepsilon^{-k+\ell}
      \Abs{\phi}_{\mathring K^\ell}, \\


    \Abs{(S_\varepsilon-\mathbf{1})\phi}_{\mathring K^\ell}
    &\lesssim_{k,\ell}
      \varepsilon^{k-\ell}
      \Abs{\phi}_{\mathring K^k}, \\


    \varepsilon\Abs{\partial_\varepsilon S_\varepsilon\phi}_{\mathring K^k}
    &\lesssim_{k,\ell}
      \varepsilon^{-k+\ell} \Abs{\phi}_{\mathring K^\ell}, \quad\text{and} \\


    \varepsilon\Abs{\partial_\varepsilon S_\varepsilon\phi}_{\mathring K^\ell}
    &\lesssim_{k,\ell}
      \varepsilon^{k-\ell} \Abs{\phi}_{\mathring K^k}.
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: bound_int_t-harmonic_by_distance of arXiv:2609.00257, 'Stability estimates for the initial-to-final-state inverse problem'] Let $n\geq2$ and $V_1, V_2\in L^1(\mathbb{R}^n)\cap L^\infty(\mathbb{R}^n)$ with $\|V_j\|_{w_\delta} < \infty$, for $j\in \{1, 2\}$. Let also $\psi_1\equiv \psi_\lambda^{V_1}$ and $\psi_2 \equiv \psi_\lambda^{V_2}$ be the time-harmonic solutions (equation eq: time-harmonic solutions of the paper) to the Schr\"odinger equation, as constructed in subsection (sec: stationary states of the paper) for potentials $V_1$ and $V_2$ respectively. Then, there holds

\begin{equation}
\Big| \int_\Sigma (V_1-V_2) \psi_1 \overline{\psi_2} \Big| \leq T \mathrm{dist}_\delta (\mathcal{U}_T^1, \mathcal{U}_T^2) \|\psi_1\|_{C_TL^2_{-\delta}} \| \psi_2\|_{C_TL^2_{-\delta}}. 
\end{equation}

[Theorem thm:carpet-information of arXiv:2607.24705, 'Derangetropy Operators'] For every $f \in \mathcal{D}_{+}$:
		\begin{enumerate}[label=\normalfont(\roman*), leftmargin=*]
			\item the time-averaged carpet is the tent modulation,
			\begin{equation}
				2\pi\int_{0}^{1/2\pi} f_{\tau}\,d\tau
				= \rho_{\Lambda}[f],
				\qquad
				\Lambda(z) = 4\min(z,\,1-z);

			\end{equation}
			\item the time-averaged chi-square divergence from the base law is
			universal,
			\begin{equation}
				2\pi\int_{0}^{1/2\pi}
				\chi^{2}\big(f_{\tau}\,\|\,f\big)\,d\tau
				= \frac{2}{3},
				\qquad
				\chi^{2}\big(f_{\tau}\|f\big)
				= \int_{0}^{1}\big(w_{s} - 1\big)^{2}dz;

			\end{equation}
			\item information breathes but never grows:
			$D(f_{\tau}\,\|\,f) \le \log\big(1 + \chi^{2}(f_{\tau}\|f)\big)$,
			and $\sup_{\tau}\chi^{2}(f_{\tau}\|f)$ is a finite absolute
			constant.
		\end{enumerate}

