[Proposition 18 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. For any fixed $p, n,S\in \N$ with $p\ge 3$ it holds that
\begin{align}
\Xi_t^{(p)}(n,S)\lesssim & \left(\frac{N^{(n-p)/2}}{N^{(p-2)/2}} + \frac{(N\eta_t)^{n-p}}{(N\eta_t)^{p-2}}\right)\frac{N^\xi}{\eta_t^S},\\
\Theta_t^{(p)}(n,S)\lesssim & N^{(n-2p+2)/2+\xi},

\end{align}
for any fixed $\xi>0$, uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 94 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Let $F$ be a grounded set and let $F\cup g$ be an enlargement of $F$ in direction $s$.  Given $Q \in \S^\rm{u}_k(F\cup g)$ such that $Q[F]$ is nonsingular, let $C$ be its Verblunsky coefficient over $Q[F]$.  Then the map
\begin{align*}
\big\{Q \in \S^\rm{u}_k(F\cup g):\ Q[F]\ \hbox{nonsingular}\big\} &\to \S_k^\circ(F)\times \Xi(k,k|F\setminus sF|):\\ Q &\mapsto (Q[F],C)
\end{align*}
is a homeomorphism, and it maps $\S_k^\circ(F\cup g)$ onto $\S_k^\circ(F)\times \Xi^\circ(k,k|F\setminus sF|)$.

[Lemma 24 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] For any \(1/2<H<1\) we have that
\begin{equation}
\int_{u\vee v}^{1}(s-u)^{H-3/2}(s-v)^{H-3/2}ds < |u-v|^{2H-2}\beta(H-1/2,2-2H).
\end{equation}
\begin{proof}
\begin{align}
\int_{u\vee v}^{1}(s-u)^{H-3/2}&(s-v)^{H-3/2}ds = \int_0^{1-u\vee v}(s+|u-v|)^{H-3/2}s^{H-3/2}ds\\
&=|u-v|^{2H-3} \int_0^{1-u\vee v}\left(\frac{s}{|u-v|}\right)^{H-3/2}\left(\frac{s}{|u-v|}+1\right)^{H-3/2}ds\\
&=|u-v|^{2H-2}\int_0^{(1-u\vee v)/|u-v|}t^{H-3/2}(t+1)^{H-3/2}dt\\
&< |u-v|^{2H-2}\int_0^{\infty}t^{H-3/2}(t+1)^{H-3/2}dt\\
&=|u-v|^{2H-2}\beta(H-1/2,2-2H)
\end{align} 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop thm:haar_sampling of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $A \in M_N(\mathfrak{o})$ be random with distribution given as follows: pick the columns $v_N,v_{N-1},\ldots,v_1$ one by one, where the conditional distribution of $v_i$ given $v_{i+1},\ldots,v_N$ is that of a random column vector with additive Haar distribution conditioned on the event 
\begin{equation}
v_i \pmod{\mathfrak{p}} \not \in \Span(v_{i+1} \pmod{\mathfrak{p}},\ldots,v_N \pmod{\mathfrak{p}}) \subset \oplus_{i=1}^N(\mathfrak{o}/\mathfrak{p}),
\end{equation}
where in the case $i=N$ we take the span in (equation eq:notinspan of the paper) to be the $0$ subspace. Then $A$ is distributed by the Haar measure on $\mathrm{GL}_N(\mathfrak{o})$.

[Lemma lem:distance_from_left_to_right_less_than_distance_from_bottom_to_top of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Suppose that we have the setup described above and let $a,R_0$ be the constants in (lem:rectangles_are_not_wide of the paper).  Fix $j \in \{1,\ldots,N\}$,  $k \in \{0,1,\ldots,\lfloor R \rfloor -1\}$ and $m \in \{3q+1 : q \in [0,7]_\BZ\}$.  Then,  there exist constants $p \in (0,1) ,  B \in (0,\infty)$ depending only on $a,R_0$ such that the following is true.  We condition on $U_1,\ldots,U_N$ and the outermost loops in $\phi_j(\overline{\Gamma}|_{U_j})$ with height in $\{-\lambda ,  \lambda\}$ which intersect either the bottom boundary of $V_{j,k}^{m-1}$ or the top boundary of $V_{j,k}^{m+1}$,  and we assume that we are working on the event that the field $\Psi|_{U_j}$ has zero-boundary conditions,  and that $I_j^3 \cap \partial B_{2^{-2R/3}}(0) = \emptyset,  I_j^4 \cap \partial B_{2^{-R/3}}(0) = \emptyset$.  Then,  with conditional probability at least $p$,  the following hold.  First,  we have that
	\begin{align*}
			D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}
		([0,\ri] ,  [b_{j,k}^m ,  b_{j,k}^m + \ri]) < B \leq 
				D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}
			([0,b_{j,k}^m] ,  [\ri ,  \ri + b_{j,k}^m]).
	\end{align*}
	 More precisely, the rectangle $f^m_{j,k}(G^m_{j,k}) = (0,b^m_{j,k}) \times (0,1)$ can be divided from top to bottom into three conformal rectangles $G^{m,1}_{j,k}$, $G^{m,2}_{j,k}$ and $G^{m,3}_{j,k}$ such that $L(G_{j,k}^{m,i}) \subseteq L(f_{j,k}^m(G_{j,k}^m))$ and $R(G_{j,k}^{m,i}) \subseteq R(f_{j,k}^m(G_{j,k}^m))$ for all $i \in \{1,2,3\}$,  and such that the following hold. 
	\begin{enumerate}[label=({\alph*})]
		\item  The $D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}$-distance from the left boundary $L(G^{m,2}_{j,k})$ of $G^{m,2}_{j,k}$ to its right boundary $R(G^{m,2}_{j,k})$ is smaller than $B$;
		\item  The right boundary (as defined in (lem:genealogy of the paper)) of the metric ball $\SCB_B(L(f^m_{j,k}(G^{m}_{j,k})),\allowbreak D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})})$ intersects $L(G^{m,2}_{j,k})$;
		\item  The $D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}$-distance from the bottom boundary to the top boundary of $G^{m,1}_{j,k}$ (resp.\ $G^{m,3}_{j,k}$) is at least $B$.
		\end{enumerate}
	The same statement holds if we condition instead on all of the outermost loops in $\phi_j(\overline{\Gamma}|_{U_j})$ with height in $\{-\lambda,\lambda\}$ which intersect the bottom boundary of $V_{j,k'}^{m'-1}$ or the top boundary of $V_{j,k'}^{m'+1}$ for some $k'$ and some $m' \in \{3q+1 : q \in [0,7]_\BZ\}$,  since the proof below only uses that,  conditionally on the collection in question,  the loops of $\overline{\Gamma}$ contained in $G^m_{j,k}$ form a nested $\CLE_4$ in $G^m_{j,k}$.  It is in this form that we shall use the lemma.

[Theorem 124 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble $X$ satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit} and \ref{Assumptions_analyticity}, with segments $[\hat{a}_h,\hat{b}_h]$ indexed by $h \in [H]$ and equilibrium measure $\boldsymbol{\mu}$. There exists two small numbers $\eps_1,\eps_2>0$ and a large number $C>0$, all depending only on the constants in the assumptions and satisfying the following conditions for $\N$ large enough.

Consider a $3K$-tuple of real parameters $(\mathfrak{a}_k$, $\mathfrak{b}_k$, $\mathfrak{n}_k)_{k = 1}^{K}$ such that $\mathfrak a_1 < \mathfrak{b}_1<\mathfrak a_2<\dots< \mathfrak a_k<\mathfrak b_k$ and $[\mathfrak{a}_{k},\mathfrak{b}_{k}] \subset [\hat{a}_{h^k}',\hat{b}_{h^k}']$ for any $k \in [K]$. Define the shifted parameters
