[Lemma of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $p \geq 2$, $\tilde{\gamma}_\bullet, \tilde{\gamma}_\circ  >1/p$, and $\gamma_\bullet< \tilde{\gamma}_\bullet-1/p $, $\gamma_\circ< \tilde{\gamma}_\circ-1/p$. Let ${\color{purp}G}= (G^\bullet, G^\circ,\mathbb{G}^{\bullet \bullet}, \mathbb{G}^{\circ \bullet}, \mathbb{G}^{\bullet \circ} )$,  $\purp{\bar{G}}= (\bar{G}^\bullet, \bar{G}^\circ,\bar{\mathbb{G}}^{\bullet \bullet}, \bar{\mathbb{G}}^{\circ \bullet}, \bar{\mathbb{G}}^{\bullet \circ} )$ random variables with values in $\mathcal{R}^{\gamma_\bullet, \gamma_\circ}$. Assume further that there exist 
   constants   $K_{ij}$, $i,j \in \{ \bullet, \circ\}$, such that for all $(s,t)$
    \begin{equs}
        \| G^i_{s,t}-\bar{G}^i_{s,t}\|_{L_p}\leq  K_i |t-s|^{\tilde{\gamma}_i}, \qquad   
        \| \mathbb{G}^{i j }_{s,t}-  \bar{\mathbb{G}}^{i j}_{s,t}\|_{L_{p/2}}\leq  K_{ij} |t-s|^{\tilde{\gamma}_i+\tilde{\gamma}_j}
    \end{equs}
    for $i,j \in \{ \bullet, \circ\}$ with $(i,j) \neq (\circ, \circ)$. Then, there exists a constant $C=C(\gamma_\bullet, \tilde{\gamma}_\bullet, \gamma_\circ, \tilde{\gamma}_\circ, p)$, such that 
    \begin{equs}
        \| [G^i-\bar{G}^i]_{\mathcal{C}^{\gamma_i}} \|_{L_p} \leq N K_i, \qquad \| [\mathbb{G}^{ij}-\bar{\mathbb{G}}^{ij}]_{\mathcal{C}^{\gamma_i+\gamma_j}_2} \|_{L_p/2} \leq  N ( K_{ij}+K_iK_j). 
    \end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:W_n_var of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] We have 
\begin{equation}
    \mathbb{E} [W_k^2] = \frac{\Gamma(k + 2q)}{ \Gamma(k)} \sum_{l = 1}^{k} \frac{\Gamma(l)}{\Gamma(l + 2q)} \\
    = H(k, q),
\end{equation}
where 
\begin{equation}
    H(k, q) := \begin{cases}
            \frac{k}{(2q - 1)}\big(\frac{\Gamma(k + 2q)}{\Gamma(k + 1) \Gamma(2q)}-1\big) & \text{if } q \ne 1/2, \\[0.5em]
            k \sum_{j = 1}^{k} \frac{1}{j} & \text{if } q = 1/2.
        \end{cases}
\end{equation}
Consequently, for any $p \in [0, 1)$, there is a constant $C_p > 0$, such that for all $n \ge 1$,
\begin{equation}
    \mathbb{E} W_n^2 \le C_p n^2 r_n^{-2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $q\in\N$, and let $F:\ccC_T^d\to \R^q$
    be a continuous non-anticipative functional. Assume that there exists a constant
    $C>0$ such that
    \begin{equation*}
        \|F(t,x)\|
        \leq C \biggl(1+\sup_{s\in[0,t]}\|x(s)\|\biggr), \quad (t,x)\in\ccC_T^d .
    \end{equation*}
    Then there exist continuous non-anticipative functionals
    \begin{equation*}
        F^n:\ccC_T^d\to\R^q,\quad n\in\N,
    \end{equation*}
    such that the following properties hold.

    \begin{enumerate}
        \item $F^n\to F$ locally uniformly on $\ccC_T^d$.

        \item For each $n\in\N$, $F^n$ is Lipschitz continuous with respect
              to the metric $d_{\ccC_T}$.

        \item There exists a constant $C'>0$, independent of $n$, such that
              \begin{equation*}
                  \|F^n(t,x)\|
                  \leq C'\biggl(1+\sup_{s\in[0,t]}\|x(s)\|\biggr),
                  \quad (t,x)\in\ccC_T^d,\ n\in\N .
              \end{equation*}
    \end{enumerate}

    In particular, for each $n\in\N$ and each fixed $t\in[0,T]$, there
    exists a constant $L_n>0$ such that
    \begin{equation*}
        \|F^n(t,x)-F^n(t,y)\|
        \leq L_n \sup_{s\in[0,t]}\|x(s)-y(s)\|,
        \quad x,y\in C([0,t],\R^d).
    \end{equation*}

