[Lemma lem:action_correlation of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] For each $x,y\in V_N^{(2)}$, we have that 
\begin{equation}
\begin{split}
\partial_t \varphi^N_t(x,y)
=\mathscr L_N^{(2)} 
\varphi_t^N(x,y)
+ \mathfrak g^N_t(x,y) 
\end{split}
\end{equation} 
where 
$
\mathfrak g^N_t(x,y)
= g^N_t(x)\mathbf{1}_{y=x+1}
+ g^N_t(x-1)\mathbf{1}_{y=x-1}
$
and $g^N_t(x)$ is defined in (equation eq:def of g of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t1.1 of arXiv:2411.19255, 'Moderate, large and super large deviations principles for Poisson process with uniform cat'] Let the scaling $\varphi(T)$ satisfies the condition ((15.11.2024-1 of the paper)). 
Then the family of random variables $\xi_T(1)$ satisfies
	LDP with normalization function
	$\psi(T)=\varphi(T)$ and with rate function
	\begin{equation}
	J_k(x)= \left\{
	\begin{array}{lcl}
		\ \infty,  \text{ if }\ x\in (-\infty,0),\\
		x\ln\left(\frac{\lambda+\mu}{\lambda}\right), \text{ if }\ x\in \big[0,\frac{\alpha}{k}\big),\\
		x\ln\left(\frac{kx(\lambda+\mu)}{\alpha\lambda}\right)-x+\frac{\alpha}{k}, \text{ if }\ x\in \big[\frac{\alpha}{k},\infty\big).\\
	\end{array}
	\right.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:BE of arXiv:2412.08502, 'Berry-Esseen inequality for random walks conditioned to stay positive'] Assume $\mathbb{E} X_1 = 0, \mathbb{E} |X_1|^2 = \sigma^2$ and $\mathbb{E} |X_1|^3 < \infty$. 
Then there exists an absolute constant $A$ such that
\begin{align}

    \bigg|
        \mathbb{P}\left(\frac{S_n}{\sigma\sqrt{n}} \ge x\mid  \tau>n\right) - e^{-x^2/2}
    \bigg|
\le
    A
    \frac{(\mathbb{E} |X_1|^3)^3}{\sigma^9\sqrt{n}}.
\end{align}
Furthermore,

\begin{align}

    \bigg|
        \frac{\mathbb{P}(\tau>n)}
        {\sqrt{\frac{2}{\pi}}
        |\mathbb{E} S_\tau|n^{-1/2}}
    -
        1
    \bigg|
\le
    A \frac{(\mathbb{E} |X_1|^3)^3}{\sigma^9 \sqrt{n}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2604.22644, '2604.22644'] For $0 < q < 1$,
\begin{align}
    E[q^{\theta_1} I(e_1 \text{ does not reach } N)] = \frac{q}{2} + \int_0^1 p q b(1;p) dp,
\end{align}
where $b(k;p)$ is the unique solution to the following linear boundary value problem:
\begin{align}
    b(k;p) = q r^k p b(k+1;p) + q (1 - r^k p) b(k-1;p), \quad k = 1, 2, \dots, N-1,
\end{align}
with boundary conditions $b(0;p) = 1$ and $b(N;p) = 0$.

