[Assertion 1 of arXiv:2604.14396, 'On the tails of Dickman-like perpetuities'] Let $\alpha>0$ and $Z_\alpha$ be the Dickman-like perpetuity, that is, it corresponds to $(M_\alpha,Q)$ satisfying the standing assumptions. Then

\noindent (a) $Z_\alpha-Q_1=\int_{[0,\infty)}\eee^{-y}{\rm d}A(y)$, where $A$ is a compound Poisson process with the jumps $Q_2$, $Q_3,\ldots$ and the jump times $-\log M_{\alpha,\,1}$, $-\log(M_{\alpha,\,1}M_{\alpha,\,2}),\ldots$; in particular, the distribution of $Z_\alpha-Q_1$ is selfdecomposable; its L\'{e}vy measure $\nu^\ast_\alpha$ is given by $\nu^\ast_\alpha({\rm d}x)=|x|^{-1}k_\alpha(x){\rm d}x$, where $k_\alpha(x)=\alpha \mmp\{Q>x\}$ for $x\in (0,\infty)$ and $k_\alpha(x)=\alpha\mmp\{Q\leq x\}$ for $x\in (-\infty, 0)$.

\noindent (b) $\me [\eee^{sZ_\alpha}]<\infty$ for all $s\geq 0$ and
\begin{equation}
\me [\eee^{sZ_\alpha}]=\me [\eee^{sQ}]\exp\Big(\alpha\int_0^s \frac{\me [\eee^{yQ}]-1}{y}{\rm d}y\Big),\quad s\geq 0.
\end{equation}

\noindent (c) 
For $t>0$,
\begin{equation}
\alpha^{-1}tq_\alpha(t)=\mmp\{Z_\alpha>t\}-\mmp\{Z_\alpha-Q_1>t\},
\end{equation}
where $q_\alpha$ denotes a density, continuous on $(0,\infty)$, of the distribution of $Z_\alpha-Q_1$.

Furthermore,
\begin{equation}
\alpha^{-1}tq_\alpha(t)~\sim~\mmp\{Z_\alpha>t\},\quad t\to\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 (The key integral) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Let \(\alpha_1,\dots,\alpha_n\in\mathbb C\) satisfy $\Re \alpha_i>-1$ for all $i=1,\dots,n$. Then, for every \(\alpha\in\mathbb C\) satisfying
\begin{equation}
0<\Re\alpha<\frac{n+\sum_{i=1}^n \Re\alpha_i}{p-1}
\end{equation}
one has
\begin{multline}
\int_{\partial \mathbb B_p^n(a)}
\frac{\prod_{i=1}^n |x_i|^{\alpha_i}}{\Bigl(\sum_{r=1}^n a_r^{2p}|x_r|^{2p-2}\Bigr)^{(\alpha+1)/2}}\, d\mathcal H^{n-1}(x)
\\
=
\frac{p \, \prod_{i=1}^n a_i^{-\alpha_i-1}}
{\Gamma\!\left(\dfrac{n+\sum_{i=1}^n \alpha_i-\alpha(p-1)}{p}\right)\Gamma(\frac \alpha 2)}
\int_0^\infty
\theta^{\alpha/2-1}
\prod_{i=1}^n
\left(
\int_{\mathbb R}
|y|^{\alpha_i}e^{-|y|^p-\theta a_i^2|y|^{2p-2}}\,dy
\right)\,d\theta.
\end{multline}
The integral on the left converges absolutely for every \(\alpha\in\mathbb C\), whereas the integral on the right converges absolutely for all \(\alpha\) satisfying~\eqref{eq:key_integral_strip}.

