body:
[Theorem 7 (Soft Edge) of arXiv:2511.12623, 'The eigenvector bead process'] Fix an integer $\ell \ge 1$.
For $1 \le i,j \le \ell$, the overlap matrix converges to the identity matrix, that is,
\[
\lim_{N \to \infty} \bigl(\Omega^{(N)}_{i,j}\bigr)_{1 \le i,j \le \ell} = I_\ell.
\]
Moreover, there exists a constant $c_q > 0$, depending only on the aspect ratio $q$, such that the leading-order correction scales as $O(N^{-1/3})$ and satisfies
\begin{equation}
  N^{1/3}\bigl(\Omega^{(N)}_{i,j} - (I_\ell)_{i,j}\bigr)
  \;\underset{N \to \infty}{\overset{d}{\sim}}\;
  \begin{cases}
    c_q\,\dfrac{g_i g_j}{\alpha_j - \alpha_i}, & i \ne j,\\[0.8ex]
    0, & i = j,
  \end{cases}
  \qquad 1 \le i,j \le \ell.
\end{equation}
Here \((\alpha_i)_{i=1}^\ell\) follow the Airy$_{\beta}$ point process, and \((g_i)_{i=1}^\ell\) are i.i.d.\ standard Gaussians \(\mathcal{N}(0,1)\) independent of \((\alpha_i)\). For the right edge, set \(c_q = (1+\sqrt{q})^{-1/3}\) and for the left edge, set \(c_q = (1-\sqrt{q})^{-1/3}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 (Integral Asymptotics 1) of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] When $\rho>0$ (which necessarily
implies that $H_0>1/2$), one has
\begin{align}

\lim_{\th\to0}\msf J(\th)
=\begin{cases}
\displaystyle\frac{4\Ga(H_0)\Ga(1-H_0)\Ga(d-H)}{\Ga(2H_0-1)(1+\rho)\rho}&H_0<1,
\vspace{5pt}\\
\displaystyle\frac{4\Ga(d-H)}{(1+\rho)\rho}&H_0=1.
\end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop_SliceDerivativeOfUniversalDiracOperator of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir}\times\mathbf{Ram}$ the following hold:
  \begin{enumerate}
  \item

    For every $\dot{\mathbf{p}}_\mathrm{BG} = (\dot g;\dot \gamma^\mathrm{BG},\dot\nabla^\mathrm{BG};0) \in H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\mathrm{BG}}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      - \frac12 \sum_{i,j=1}^d \dot g(e_i,e_j) \gamma(e_i)\nabla_{e_j} \phi
      + \frac14\gamma\paren[\big]{(\nabla^*\dot g)^\sharp + \nabla(\tr_g\dot g)}\phi.
    \end{equation*}
  \item

    For every $\dot{\mathbf{p}}_\mathscr{G} = (0;[\xi,\gamma],-\nabla\xi;0) \in V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\mathscr{G}}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      \sum_{i=1}^d \paren[\big]{
        [\xi,\gamma(e_i)] \nabla_{e_i} \phi
        - \gamma(e_i) (\nabla_{e_i}\xi) \phi
      }.
    \end{equation*}
  \item

    For every $\dot{\mathbf{p}}_\nabla = (0;0,\dot\nabla;0) \in V_{\nabla;{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\nabla}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      \sum_{i=1}^d \gamma(e_i) \dot\nabla_{e_i}\phi.
    \end{equation*}    
  \end{enumerate}
  Moreover, $\nabla^\mathbf{Sl} \mathbf{res} = 0$.

