[Definition eq:detailed balance reactions of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] A chemical system  $(\Omega, \mathcal R,  \mathcal R_s , \mathcal K, \mathcal K_s )$ satisfies the property of detailed balance if there exists a  $f_s  \in \mathcal P (\mathbb N^M ) $ that is  such that 
\begin{equation} 
R_\rho (n) f_s( n)  = R_{- \rho}(n+ S_\rho) f_s( n + S_\rho), \quad \forall n \in \mathbb N^M, \  \forall \rho \in \{ 1, \dots, r \}
\end{equation}
and 
\begin{equation} 
A_k (n) f_s( n)  = B_k (n+ e_k) f_s( n + e_k ), \quad \forall n \in \mathbb N^M, \  \forall k \in \Omega_c. 
\end{equation}

[Theorem thm: general approx result of arXiv:2411.02917, '\hspace*{2mm}\\[-16mm] Stein's Method for Spatial Random Graphs'] Let $(\mathrm{H},\mathrm{T})\sim P^{\lambda}\otimes Q^{\kappa}$ be the generalised random geometric graph with vertex process fulfilling the stability condition~(equation eq: stability cond of the paper) and $(\Xi,\Sigma)$ a random graph having law $P\otimes Q$, where $Q$ is an edge kernel and $\Xi\sim P$ fulfils Condition~(equation eq:condsigma of the paper) and has Papangelou kernel $L$. Then, for all $f \colon \mathbb{G} \to \R$ bounded and measurable,
\begin{align} 
    \bigl| \E\bigl(f(\Xi,\Sigma)\bigr)-\E\bigl(f(\mathrm{H},\mathrm{T})\bigr)\bigr| &\leq \E \biggl(\int_{\mathcal{X}}\triangle_V h_f(\Xi,\Sigma)\,\bigl|\lambda(x\,|\, \Xi) \, \alpha(\diff x)-L(\diff x\vert\Xi)\bigr| \biggr) \notag\\
    &\hspace*{4mm} {} + \E\biggl(\int_{\mathcal{X}} \triangle_Eh_f(\Xi,\Sigma)\, \E\bigl[\norm{{\hat{v}(\Tilde{\Sigma}_{\Xi,\Sigma,x})}}_1 \bigm| \Xi,\Sigma\bigr] \,\lambda(x\,|\, \Xi) \,\alpha(\diff x) \biggr) \notag\\
    &\hspace*{4mm} {} + \E \biggl( \int_{\mathcal{X}}\int_{\mathfrak{N}_2} \triangle_Vh_f(\Xi,\sigma)\,\bigabs{\tilde{Q}_1(\Xi,x;\diff \sigma) - Q(\Xi;\diff \sigma)}\,L(\diff x \,\vert \Xi) \biggr),
\end{align}
\vspace*{-6mm}

where
\begin{align*}
  \Tilde{\Sigma}_{\xi,\sigma,x}\sim \tilde{Q}_{2 \,|\, 1}(\xi,x,\sigma ;\, \cdot)
  &= \mathcal{L} \bigl( \Sigma \vert_{\langle \xi, x \rangle} \bigm| \Xi = \xi+\delta_x, \Sigma \vert_{\xi^{\langle2\rangle}} = \sigma \bigr) \\[0.5mm]
  \tilde{Q}_1(\xi, x;\, \cdot) &= \mathcal{L} \bigl( \Sigma \vert_{\xi^{\langle 2\rangle}} \bigm| \Xi = \xi+\delta_x\bigr) \\[-0.5mm]
  \norm{\hat{v}(\tilde{\Sigma}_{\xi,\sigma,x})}_1 &= \sum_{i=1}^{\abs{\xi}} \Bigl| \kappa(x_i,x) - \Prob\bigl(\Tilde{\Sigma}_{\xi,\sigma,x}(\{x,x_i\}) = 1 \bigm| (\Tilde{\Sigma}_{\xi,\sigma,x}(\{x,x_j\}))_{j\neq i}\bigr) \Bigr|.
\end{align*}
Furthermore, for all $(\xi,\sigma)\in\mathbb{G}$ and $B^*$ as in Theorem~(thm: coupling time of the paper),
the Stein factors are are given as
\begin{align*}
    \triangle_V\,h_f(\xi,\sigma) &= \sup\limits_{x\in\mathcal{X}\setminus\xi} \; \Bigl| \hspace*{1.5pt} \E \hspace*{1.5pt} h_f(\xi + \delta_x,\sigma + \Tilde{\Sigma}_{\xi,\sigma,x}) -h_f(\xi,\sigma)  \Bigr| \leq 2B^{*}\norm{f}_{\infty}, \\
    \triangle_E\,h_f(\xi,\sigma) &= \sup\limits_{\substack{x\in\mathcal{X}\setminus\xi,\,y\in\xi \\
    \sigma_2\in \mathfrak{N}_2\vert_{\langle\xi\setminus\{y\},x\rangle}

    }} \Bigl| h_f(\xi + \delta_x,\sigma + \sigma_2 +\delta_{\{x,y\}}) - h_f\bigl(\xi + \delta_x,\sigma + \sigma_2 \bigr) \Bigr| \leq \norm{f}_{\infty}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem GeneralizKolmogBackwardEq of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let  $A \in \mathcal{F}_{T}$ for $T < \infty$, and let  $P^i$, $i \in \mathcal{Z}$, be given stochastic processes.  The two following statements are equivalent:
\begin{itemize}
	\item[(i)] The multivariate process $(P^i)_{i \in \mathcal{Z}}$  satisfies $P^i(t)= \mathbb{P}_{t}^i[A]$, $t \in [0,T]${.}
	\item[(ii)]  The multivariate process $(P^i)_{i \in \mathcal{Z}}$ is a solution in  $\mathcal{Y}(\Lambda)$ for the backward equation
\begin{align}
	0 = \mathds{1}_{\{   \Lambda^{i\raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(t-)< \infty\}} I^i(t-) \bigg( P^i(\mathrm{d} t)+\sum_{j:j\neq  i} \big(P^j(t)-P^i(t) \big) \Lambda^{ij}(\mathrm{d} t)\bigg) 
\end{align}
with terminal value $P^i(T)= \mathbb{P}_T^i[A]$. 
\end{itemize} 
If for a  subset $\mathcal{Z}_0 \subset \mathcal{Z}$ we have $\Lambda^{ij}=0$ for all $i \in \mathcal{Z}_0$ and $j \not\in \mathcal{Z}_0$, then the equivalence is also true for the sub-process $(P^i)_{i  \in \mathcal{Z}_0}$ only. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 62 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definitions \ref{Def.ParametersEdge} and \ref{Def.ScalingEdge}. Then for each $j \in \llbracket 1, m \rrbracket$
\begin{equation}
\lim_{N \rightarrow \infty} \sum_{i \geq 1} \mathbb{P}(Y^{j,N}_i \geq \sigma_2^{-1} [h_1(\kappa_j) - h_2(\kappa_j)] N^{1/2} + 1) = 1.
\end{equation}

