[Lemma lem:c_perturbed of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] \begin{equation}
        \left(\frac{1}{m} U_{m-1}(x)\right) \left(\frac{1}{m+1} U_m(x)\right)^{t-1} = \sum_{k \ge 0} \tilde{c}_t(m; k) \, \frac{1}{k+1}U_k(x),
    \end{equation}
    where $\tilde{c}_t(m; k) = 0$ unless $k \equiv tm-1 \pmod 2$.
    As $m \to \infty$, for $k \equiv tm-1 \pmod 2$ and $k = \lfloor \xi m \rfloor$,
