\begin{align*}
    (s,s') \textrm{ is {\rm GOOD} and } \Exp{D_{(s,s',s'')}}>0 \implies (s',s'') \textrm{ is {\rm GOOD}.}\addtocounter{equation}{1}\tag{\theequation} 
\end{align*}
To check this, note that by definition
\begin{align}
    \Exp{D_{n,(s,s',s'')}}=\frac{\frac{1}{N^{(s')}}\sum_{x=1}^{N^{(s')}}d_x^{(s',s)}(n)d_x^{(s',s'')}(n)}{\frac{1}{N^{(s')}}\sum_{x=1}^{N^{(s')}}d_x^{(s',s)}(n)}&=O\left(\sqrt{\Exp{(d_{o}^{(s,s')}(n))^2} \Exp{(d_{o}^{(s',s'')}(n))^2}} \right)\\&=O\left(\sqrt{\Exp{(D_{n,(s,s')})^2} \Exp{(D_{n,(s',s'')})^2}} \right),
\end{align}
