body:
[Lemma 23 (Changing path through the saddle point) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$, $a \in \R$, $b > 0$ such that $(a,b) \neq z_0$, and let
$\alpha \in (0,\pi)$ be such that ${\m} < x(\alpha) < {\M}$. Then:
\begin{equation}
I_1^{z_0}(a,b) = \frac{1}{2i\pi} \int_{S^-_{x, \alpha} \cup \Gamma_{x,\alpha} \cup S^+_{x, \alpha}} \phi^{z_0}(x) \frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))} e^{-a x - b Y^+(x)} \, dx,
\end{equation}
and
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi} \int_{S^-_{x, \alpha} \cup \Gamma_{x,\alpha} \cup S^+_{x, \alpha}} \frac{e^{(a_0 - a)x} \left(
e^{(b_0 - b) Y^+(x)} \fc_{b_0 > 0} + e^{b_0 Z^+(x) - b Y^+(x)} \fc_{b_0 < 0}
\right)}{\partial_y\gamma_+(x,Y^+(x))} \, dx, \quad \text{if } b > b_0.
\end{equation}

Furthermore, if $b_0 > 0$, then
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi} \int_{S^-_{y, \alpha} \cup \Gamma_{y,\alpha} \cup S^+_{y, \alpha}} \frac{e^{(a_0 - a) X^+(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^+(y),y)} \, dy, \quad \text{if } a > a_0,
\end{equation}
and
\begin{equation}
I_2^{z_0}(a,b) = -\frac{1}{2i\pi} \int_{S^-_{y, \alpha} \cup \Gamma_{y,\alpha} \cup S^+_{y, \alpha}} \frac{e^{(a_0 - a) X^-(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^-(y),y)} \, dy, \quad \text{if } a < a_0.
\end{equation}

