[Proposition prop:Cnk-intro of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] Let $n \ge 3$ and $N = \binom n 2$.
For $0 \le k  \le n$, we have
\begin{align} 
C(n, n+k) \lesssim   \binom N {n+k}
	\bigg( \frac 2 e \bigg)^n   \bigg( \frac{ e n }{ k }\bigg)^{k/2} .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Let $U\subset \BC$ be a domain, let $z \in U$, and let $(U_n)_{n\ge 0}$ be a sequence of domains in $\BC$ containing $z$. The sequence $(U_n)_{n\ge 0}$ converges in the Carath\'eodory sense toward $U$ with respect to $z$ if: 
	\begin{itemize}
		\item For every compact set $K\subset U$, we have $K\subset U_n$ for all $n$ large enough;
		\item For every connected open set $V\ni z$, if $V \subset U_n$ for infinitely many $n\ge 0$, then $V \subset U$.
	\end{itemize}

[Lemma 30 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)\cap \Leb^{\infty}(\Rbb^n,\gamma_n)$, and $1\leq q\leq p\leq 2$,
\begin{equation}
\begin{aligned}
    &\left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq M(p)^k\Vop^{k}(f) \\
    &\cdot\left[1+ \frac{q}{2k(2-q)}\max\left\{\ln^+\left(\frac{\Vop^k(f)}{\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^2}\right),\, \ln^+\left(\frac{\Vop^k(f)}{\sum_{|\kappa|=k} \left\|\Dop^\kappa f\right\|_{\Leb^q}^2}\right)\right\}\right]^\frac{kp}{2},
\end{aligned}
\end{equation}
and further for all $\kappa\in \Nbb^n$ with $|\kappa|=k$,
\begin{equation}
    \left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\Dop^\kappa f\right\|_{\Leb^p}^{p} \geq M(p)^{k} \Vop^\kappa(f) \left[1+\frac{q}{2k(2-q)} \ln^{+}\left(\frac{\Vop^\kappa(f)}{\left\|\Dop^\kappa f\right\|_{\Leb^q}^{2}}\right)\right]^\frac{kp}{2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2511.13559, 'Asymptotic analysis of rare events in high dimensions'] Let $N\geq1$, $\sup_{u\in D}|g(u)|\leq1$, and suppose Assumptions~\ref{assume1},~\ref{assume:global2} are satisfied. Suppose there is $R \geq 12/\cmin + 2(1+2N)(\log\la)/d$ and constants $\CR$, $C_{\g,\ell}$, $\ell=0,\dots,2N$, $C_{\z,\ell}$, $\ell=0,\dots,2N+2$ 
such that $\g\in C^{2N}(\us(R\e)\times[0,(R\e)^2))$, $\z\in C^{2N+2}(\us(R\e)\times[0,(R\e)^2))$, and
\begingroup
\addtolength{\jot}{0.3em}
\begin{align}
&\e\leq s,\qquad R\e\leq\min(1,\rho_0,2\rho_1, 2/\delta_2(\rho_1)),\\
&R\e\leq1/(2C_{\z,0}+2C_{\z,1}),\qquad R^4d^2/\la\leq \CR,\\
\begin{split}
&\max_{j=0,\dots,N}\g_{0,j}(R\e,(R\e)^2)\leq C_{\g,0}, \\
&\max_{j=0,\dots,\lfloor N-\frac\ell2\rfloor}\g_{\ell,j}(R\e,0)\leq C_{\g,\ell} \,d^{\lceil\frac\ell2\rceil},\quad\ell=1,\dots,2N,
\end{split}\\
\begin{split}
&\omega_{0,2}(R\e,R\e)\vee \max_{j=3,\dots,N+1}\omega_{0,j}(R\e,(R\e)^2)\leq C_{\z,0},\\
&\max_{j=j_\ell,\dots,\lfloor N+1-\frac\ell2\rfloor}\omega_{\ell,j}(R\e,0)\leq C_{\z,\ell} \,d^{(\lceil\frac\ell2\rceil-2)_+},\quad\ell=1,\dots,2N+2.
\end{split}
\end{align}
\endgroup
Here, $j_1=j_2=1$, $j_\ell=0$ for $\ell\geq3$, and $(\cdot)_+=\max(\cdot, 0)$.  Then
\bs
\int_{D}g(u)e^{-\la z(u)}\dd u =  \frac{(2\pi/\la)^{d/2}e^{-\la z(0_{d+1})}}{\la(\det H)^{1/2}}\left(g(0_{d+1})+\sum_{m=1}^{N-1}a_m\left(\frac{d^2}{\la}\right)^{m}+ \Rem_N\right),
\es where
\begin{align}

\max_{m=1,\dots,N-1}|a_m|&\leq C_{\g,\z,N},\qquad |\Rem_N|\leq C_{\g,\z,N,R} (d^2/\la)^{N}.
\end{align}
The constant $C_{\g,\z,N}$ depends on $N$, $C_{\g,\ell}$, $\ell=0,\dots,2N$, and $C_{\z,\ell}$, $\ell=0,\dots,2N+2$. The constant $C_{\g,\z,N,R}$ depends on these same constants and also on $\CR$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def: identically distributed of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $X_1$ and $X_2$ be two n-dimensional random vectors defined respectively in sublinear expectation spaces $(\Omega_1, \mathcal{H}_1, \hat{\mathbb{E}}_1)$ and $(\Omega_2, \mathcal{H}_2, \hat{\mathbb{E}}_2)$. They are called identically distributed, denoted by $X_1\stackrel{d}{=} X_2$, if
        \begin{equation}
            \hat{\mathbb{E}}_1[\phi(X_1)]=\hat{\mathbb{E}}_2[\phi(X_2)], \text{ for all } \phi \in C_{lip}(\mathbb{R}^n).
        \end{equation}
		It is clear that $X_1\stackrel{d}{=}X_2$ if and only if their distributions coincide.

[Theorem 39 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $G_n = (V_n, E_n)$, with $|V_n|=n$, be a sequence of $b$-expander graphs with minimum and maximum degree $\deg_{\mathrm{min}}(n) = \deg_{\mathrm{min}}$ and $\deg_{\max}(n) = \deg_{\max(n)}$, such that for some fixed $\Delta > 0$ we have $\deg_{\max}/\deg_{\mathrm{min}} \leq \Delta$ for all $n$. Suppose that $\mu$ satisfies Assumption \ref{as:mu_tail}. Then there exists constants $C_1 = C_1(b,\Delta, \mu), C_2(\mu)$ such that if $\deg_{\mathrm{min}} \geq C_2 \log n$, then we have for $\beta \leq C_1 (\deg_{\mathrm{min}}/ \log n)^{1/\alpha}$ and any $\delta > 0$ that
	\begin{equation*}
		\widehat \P \left( C_3^{-1} \sqrt{n} \leq \diam(\cT) \leq C_3  \sqrt{n}  \right) \geq 1-\delta,
	\end{equation*}
	for some $C_3 = C_2(\delta, b, \Delta) > 0$ and all $n = n(\delta)$ large enough. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm aggregated of arXiv:2608.20635, 'Minimax Optimality of Score-Entropy Discrete Diffusion'] Consider a discretization scheme $0 = t_0 < t_1 < \cdots < t_N = T - \delta$. For $k \in \{0, 1, \cdots, N - 1\}$, denote by $s_{T - t_k}$ the output of Algorithm (alg:thresholding of the paper) constructed using $n$ samples from $p_{T- t_k}$, then there exists a positive numerical constant $C_2$, such that 
	\begin{align*}
		& \sum_{k = 0}^{N - 1} (t_{k + 1} - t_k) \cdot \mathbb{E}[ \mathcal{L}_{\mathsf{SE}}(s_{T - t_k}, p_{T - t_k}, T - t_k) ] \\
        & \leq \frac{ C_2\, v |\mathcal{X}| \log_v |\mathcal{X}| (\log n)^2}{n} \cdot \Big(T + \log\frac{1}{\delta}\Big) \cdot  \Big(1 + \log v + \log\Big(1 + \frac{1}{\delta}\Big)\Big). 
	\end{align*}

[Theorem th:lm of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Fix $t_0 \in I$. Suppose $\mathbb{E}[(X(t)-X(s))^2]^{1/2} \asymp \varphi(|t-s|)$ for all $t,s \in I$, where $\varphi$ is non-decreasing, continuous and regularly varying at 0 of index $\theta \in [0\,,1]$ with
    \begin{align}
        \int_0^1 \frac{\varphi(hr) \, {\rm d} r}{r\sqrt{\log(2/r)}} \lesssim \varphi(h)\sqrt{\log\log(1/h)}=o(1) \quad \text{as $h\to0^+$.}
    \end{align}
    If there is a sequence $(t_n)_{n=n_0}^\infty$ in $I$ with $|t_n-t_0| = a^{-n}$ for some $a>1$, and there exists $C_0>0$ such that
    \begin{align}
        \Var(X(t_n)-X(t_0)|X(t_m)-X(t_0))
        \ge C_0 \Var(X(t_n)-X(t_0))
    \end{align}
    uniformly for all $m>n\ge n_0$, then
    \begin{align}
        \lim_{h \to 0^+} \sup_{t \in I: 0<|t-t_0|\le h} \frac{|X(t)-X(t_0)|}{\varphi(|t-t_0|) \sqrt{\log\log(1/|t-t_0|)}} = K_2 \quad \text{a.s.}
    \end{align}
    where $0<K_2<\infty$ is a non-random number possibly depending on $t_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi eq:assumptioninticonditionK of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Let $R_{0} \in [0,R_{\max}]$ be a random variable. Let $(\nu^{K}_{0})_{K \geq 1}$ be a sequence of random variables in $\mathcal{M}_{P}(\mathbb{R}^{*}_{+})$, such that
    \begin{align}
    \underset{K \geq 1}{\mathrm{sup}} \bigg( \dfrac{1}{K} \hspace{0.1 cm} \mathbb{E}\left(\langle \nu^{K}_{0},1+\mathrm{Id}+\omega \rangle\right) \bigg) < + \infty.

    \end{align}
We use the Poisson point measures $\mathcal{N}$ and $\mathcal{N}'$ of Section~(sec:construction of the paper), independent from $R_{0}$ and $(\nu^{K}_{0})_{K \geq 1}$. For every $K \geq 1$, the renormalized process $(\mu^{K}_{t},R^{K}_{t})_{t \geq 0}$ with initial condition $(\mu^{K}_{0},R_{0})$, is given for every $t \geq 0$ by $\mu^{K}_{t} := \dfrac{\nu^{K}_{t}}{K}$ and

\begin{align*}
    (\nu^{K}_{t},R^{K}_{t}) = &  \hspace{0.1 cm}X^{K}_{t}(\nu^{K}_{0},R_{0})  \\  & +  \displaystyle{\int_{0}^{t}\int_{\mathcal{U} \times \mathbb{R}^{*}_{+} } \mathbb{1}_{\{u \in V^{K}_{s-} \}} \mathbb{1}_{\{h \leq b\left(\xi^{u,K}_{s-}\right)\}}}  [ X^{K}_{t-s}(\nu^{K}_{s-} + \delta_{x_{0}} + \delta_{\xi^{u,K}_{s-}-x_{0}} -\delta_{\xi^{u,K}_{s-}},R^{K}_{s})  \\
    &  \hspace{3 cm} - X^{K}_{t-s}(\nu^{K}_{s-},R^{K}_{s}) ] \mathcal{N}(\mathrm{d}s,\mathrm{d}u,\mathrm{d}h)  \\
     & + 
    \displaystyle{\int_{0}^{t}\int_{\mathcal{U} \times \mathbb{R}^{*}_{+} } \mathbb{1}_{\{ u \in V^{K}_{s-}\}} \mathbb{1}_{\{h \leq d\left(\xi^{u,K}_{s-}\right)\}} [X^{K}_{t-s}(\nu^{K}_{s-} - \delta_{\xi^{u,K}_{s-}},R^{K}_{s})}  \\ 
    & \hspace{3 cm} - X^{K}_{t-s}(\nu^{K}_{s-},R^{K}_{s}) ] \mathcal{N}'(\mathrm{d}s,\mathrm{d}u,\mathrm{d}h), 
\end{align*}
where for all $t \geq 0$, $V^{K}_{t}$ is the set containing alive individuals at time $t$, and $\xi^{u,K}_{t}$ are individual energies, defined and actualized over time with the same conventions as in Section~(sec:construction of the paper), simply replacing the flow $X$ by $X^{K}$.

[Thm P^hk strong conv to hatP of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] Suppose that Assumption \textup{(Assumption:Hypo of the paper)} holds for $\set{P_{s,t}(x,\cdot):0\leq s\leq t\leq T,x\in\mathbb{R}^n}$ the transition distribution  under the strong Markov reference measure $\mathbf{R}$. Let $\mathbf{P},\hat\mathbf{P}$ be the same as in Lemma (lem:from bR to bP of the paper) and $g_k,f_k$, $k\geq1$ be as in Lemma (lem:f_k,g_k approximation convergence of the paper). For every $k\geq 1$, we define 
\begin{equation}
    h_k(t,x):=\int_{\mathbb{R}^n}g_k(y)P_{t,T}(x,dy)\text{ for }(t,x)\in[0,T]\times\mathbb{R}^n,
\end{equation}
and 
\begin{equation}
    \mathbf{P}^{h_k}:=\frac{\mathbbm{1}_{\left\{ X_0\in A_k \right\}}}{r_k}\frac{h_k(T,X_T)}{h_k(0,X_0)}\mathbf{P},
\end{equation}
where $A_k:=\set{x\in\mathbb{R}^n:h_k(0,x)>0}$ and $r_k:=\rho_0(A_k)$. 
Then $\set{\mathbf{P}^{h_k}}_{k \geq 1}$ is a sequence of $h$-transforms by harmonic functions, and  $\mathbf{P}^{h_k}$ converges to $\hat\mathbf{P}$ in the strong topology in the sense that \[\lim_{k\to\infty}\sup_{A\in\mathcal F}|\mathbf{P}^{h_k}(A)-\hat{\mathbf{P}}(A)|=0.\]

[Theorem t:covindfn of arXiv:2411.08848, 'Stationary random measures: Covariance asymptotics, variance bounds and central limit theo'] Let ${\mathcal X}$ be a stationary random measure whose truncated correlation measure ${\bf K}$ has finite total variation. Assume that $A$ and $B$ are bounded open sets with $C^1$-smooth boundaries.  Let ${\mathcal X}_L$ be the scaled random measure defined by ${\mathcal X}_L(A) := {\mathcal X}(LA)$,  $L \geq 1$.  Then

\begin{enumerate}
\item $L^{-d}\mathrm{Cov}({\mathcal X}_L(A),{\mathcal X}_L(B)) \to Q_0^{{\bf K}}(f,g) = (\lambda_D + \int {\bf K} ) \, |A \cap B|, $ where $| \cdot |$ is the Lebesgue measure. 
\item If $\lambda_D + \int {\bf K} = 0$ and further $\int |z||{\bf K}|(\mathrm{d} z)<\infty$, then it holds that

\begin{equation}

L^{-d+1}\mathrm{Cov}({\mathcal X}_L(A),{\mathcal X}_L(B))  \to  -\frac12 \int_{\partial A\cap \partial B} \varepsilon(x) \left[\int |z\cdot N_A(x)| \ {\bf K}(\mathrm{d} z) \, \right] \, \sigma_A(\mathrm{d} x),
\end{equation}

where $N_A(x)$ is the exterior normal to $A$ at $x$ and $\sigma_A$ is the surface area measure of $\partial A$. Further, $\varepsilon(x) \in \{+1,0,-1\}$ is defined as follows: $\varepsilon(x) = +1$ (resp. $-1$) if $N_A(x)$ is the exterior (resp. interior) normal to $B$ at $x$, and $0$ otherwise. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor: spatial mixing of Ising model of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Let $M_1<M_3<M_4<M_2$ be four integers. Let $\mathcal{E}$ be an event supported on $\Lambda_{M_3,M_4}$. Then there exists an absolute constant $c>0$ such that for any boundary conditions $\xi,\xi'$ on $\partial\Lambda_N$ and any boundary condition $
u,
u'$ on $\partial\Lambda_M$, we have egin{equation}
        \Big| rac{\mu^{
u,\xi}_{\Lambda_{M_1,M_2}}(\mathcal{E})}{\mu^{
u',\xi'}_{\Lambda_{M_1,M_2}}(\mathcal{E})}-1\Big|\le c( rac{M_3}{M_1})^{- rac{1}{8}}+c( rac{M_2}{M_4})^{- rac{1}{8}}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 10 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta$ be measurable. Moreover, let the cost function $\ell$ satisfy Assumption~\ref{L}. Then, for any probability measure $\mu$ on $\bigl([0,1]\times\mathbb{R}^d\times\mathbb{R}^d\times\mathbb{R}^{d^2}\times\mathbb{R}^{\mathbb{N}},
\mathcal{B}([0,1]\times\mathbb{R}^d\times\mathbb{R}^d\times\mathbb{R}^{d^2}\times\mathbb{R}^{\mathbb{N}})\bigr)$, the following hold:
\begin{itemize}
\item[(1)] The map $(t,x,b,c,v)\mapsto\lambda(t,x)$ is measurable with respect to the $\mu$-completion of $\mathcal{B}([0,1]\times\mathbb{R}^d\times\mathbb{R}^d\times\mathbb{R}^{d^2}\times\mathbb{R}^{\mathbb{N}})$.
\item[(2)] For any $\varepsilon>0$, there exists a family of probability measures
$\{\overline{\mathbb{Q}}^{\varepsilon,t,x,b,c,v}\}$ indexed by $(t,x,b,c,v)\in[0,1]\times\mathbb{R}^d\times\mathbb{R}^d\times\mathbb{R}^{d^2}\times\mathbb{R}^{\mathbb{N}}$ belonging to $\overline{\mathfrak{P}}_{\Theta}^{t,x,b,c,v}$ such that $(t,x,b,c,v)\mapsto\overline{\mathbb{Q}}^{\varepsilon,t,x,b,c,v}$ is measurable with respect to the same completion and 
\begin{equation*}
\mathbb{E}^{\overline{\mathbb{Q}}^{\varepsilon,t,x,b,c,v}}\Bigl[\int_{t}^{1}
\overline{\ell}(s,\overline{X}_s,\overline{b}_s,\overline{c}_s,\overline{v}_s)\,\mathrm{d}s+\lambda_1(\overline{X}_1)\Bigr]<\lambda(t,x)+\varepsilon.
\end{equation*}
\end{itemize}

