[Thm prop:coupling0 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $\gamma$ chosen small enough, then, given any $0 < \eta' < \eta < \tfrac{1}{2}$ sufficiently small (depending only on $\gamma$) there exists a constant $c=c(\eta,\eta') > 0$ such that, if $k$ is sufficiently large, for any $2k \leq T \leq {\rm e}^{ck^\gamma}$, $n \geq k$ and $x,\widetilde{x} \in {\rm D}_n$ satisfying that $x \in {\rm B}^-[\widetilde{x};T-1]$ and $\overline{{\rm B}^+[\widetilde{x};T]} \subseteq {\rm D}_n$, the asymptotics	\begin{equation}
		\mathbb{P} \Big( \big\{ Z_t[x;1] = (u,\overline{y})\big\} \setminus \mathrm{NR}^{\eta,[2,T-1]}_{n,t}(x) \,\Big|\,Z_t[\widetilde{x};T] = (v,\overline{z}) \Big)=r_{k,T}(\widehat{u},\widehat{v})h_k(\overline{y})(1+o_k(1))
	\end{equation} hold uniformly over all $t > 0$, $(u,\overline{y}) \in \mathcal Z_k^{\eta'}[1]$ and $(v,\overline{z}) \in \mathcal Z_k^{\eta'}[T]$, where the functions $r_{k,T}$, $h_k$ are respectively given by
	\begin{equation}
		r_{k,T}(\widehat{u},\widehat{v}):=	 \sqrt{\frac{2}{\pi}}(Tk^{\frac{3}{2}})^{-1}{\rm e}^{-2(T-1)k^\gamma}\left(\widehat{u}{\rm e}^{2\sqrt{2}\widehat{u}}\right)\left(\widehat{v}{\rm e}^{-2\sqrt{2}\widehat{v}-\frac{\widehat{v}^2}{Tk^\gamma}}\right)
	\end{equation}and
	\begin{equation}
		h_k(\overline{y}):=\begin{cases}1 & \text{ if $\overline{y}=\emptyset$}\\ \\\displaystyle{\prod_{i=1}^m \amalg_{{\rm B}^-[0;1]}(y_i) \Pi_{{\rm B}^+[0;1]}(0,y_i')} &\text{ if $\overline{y}=((y_1,y_1'),\dots,(y_{m},y'_{m}))$ for some $m \in \mathbb N$}\,.
		\end{cases}	
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lbm-active-response-multiplicity of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For $x\in\Omega_{\rm LBM}$ and an eigenvalue $\Lambda>0$ of multiplicity $r$,
\begin{equation}
 \mathcal N_x(\Lambda)\text{ is a singleton}
 \quad\Longleftrightarrow\quad r=1.

\end{equation}

[Thm th:2.1 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Suppose $\xi < g_\alpha$. Then, it holds
	\begin{equation}  \begin{aligned} 
	& \lim_{T \to \infty} \mathbb{P}(x^f_{\alpha T}(T) > \xi T - S T^{1/3}) \\
	& = \lim_{T \to \infty} \mathbb{P}(x_{\alpha T}(t) > \xi T - f(T-t)-ST^{1/3} \ \forall t \in [0,T]).
	\end{aligned}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 85 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] We denote by:
	\begin{enumerate}
		\item $\HFrm_\weak$ the full subcategory of~$\CohFrm$ containing Heyting frames;
		\item $\HFrm_\strong$ the wide subcategory of~$\HFrm_\weak$ containing coherent morphisms that restrict to Heyting algebra morphisms on the compact elements.
	\end{enumerate}

[Lemma lem:cov of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] For any distinct $e, e' \in \binom{[n]}{2}$, we have
\begin{equation}
	\mleft| \operatorname{Cov}[X(e), X(e')] \mright| \lesssim \frac{1}{n}.
\end{equation}
Moreover, if $e$ and $e'$ do not share a vertex, then the right-hand side
above can be improved to $\frac{1}{n^2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $k\ge3$ be fixed and let $\varepsilon>0$.  Suppose that
$\boldsymbol\alpha\in\mathbb R^k$, $N$ is sufficiently large, and
\begin{equation}
  |g_k(\boldsymbol\alpha;N)|\ge A
  >N^{1-1/K_k+\varepsilon}.
\end{equation}
Then there are integers $q,a_1,\ldots,a_k$ such that
\begin{equation}
  1\le q\ll_{k,\varepsilon}
  N^\varepsilon(NA^{-1})^k
\end{equation}
and
\begin{equation}
  |q\alpha_j-a_j|
  \ll_{k,\varepsilon}
  N^{-j+\varepsilon}(NA^{-1})^k
  \qquad(1\le j\le k).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 15 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Choosing 
\begin{align*}
     a_T=&6\langle\partial_1Y,\partial_1Y\rangle_T(\partial_1Y_T)^2+6\langle\partial_2Y,\partial_2Y\rangle_T(\partial_2Y_T)^2+2\langle\partial_2Y,\partial_2Y\rangle_T(\partial_1Y_T)^2\\
    &+2\langle\partial_1Y,\partial_1Y\rangle_T(\partial_2Y_T)^2+4\langle\partial_1Y,\partial_2Y\rangle_T^2-3\langle\partial_1Y,\partial_1Y\rangle_T^2-3\langle\partial_2Y,\partial_2Y\rangle_T^2\\
    &-2\langle\partial_1Y,\partial_1Y\rangle_T\langle\partial_2Y,\partial_2Y\rangle_T\\
    &+8 \int_0^T\int_0^s \partial_1 Y_u\ d(\partial_2 Y_u) \ d\langle\partial_1 Y,\partial_2Y\rangle_s +8 \int_0^T\int_0^s \partial_2 Y_u\ d(\partial_1 Y_u) \ d\langle\partial_1 Y,\partial_2Y\rangle_s\\
    &+8 \int_0^T\int_0^s \partial_1 Y_u\ d\langle\partial_2 Y,\partial_2 Y\rangle_u\ d(\partial_1Y_s)+8 \int_0^T\int_0^s \langle\partial_2 Y,\partial_2 Y\rangle_u\ d(\partial_1 Y_u)\ d(\partial_1Y_s)\\
    &+8 \int_0^T\int_0^s \partial_2 Y_u\ d\langle\partial_1 Y,\partial_1 Y\rangle_u\ d(\partial_2Y_s)+8 \int_0^T\int_0^s \langle\partial_1 Y,\partial_1 Y\rangle_u\ d(\partial_2 Y_u)\ d(\partial_2Y_s),\\
     b_T=&\begin{pmatrix}
        3\langle\partial_1Y,\partial_1Y\rangle_T\partial_1Y_T+2\langle\partial_1Y,\partial_2Y\rangle_T\partial_2Y_T+\langle\partial_2Y,\partial_2Y\rangle_T\partial_1Y_T\\ 
        3\langle\partial_2Y,\partial_2Y\rangle_T\partial_2Y_T+2\langle\partial_1Y,\partial_2Y\rangle_T\partial_1Y_T+\langle\partial_1Y,\partial_1Y\rangle_T\partial_2Y_T
    \end{pmatrix},
    \end{align*}
    \begin{align*}
     &c_T:\R^2\to\R,\quad c_T((x_1,x_2))=&&6\langle\partial_1Y,\partial_1Y\rangle_Tx_1^2+6\langle\partial_2Y,\partial_2Y\rangle_Tx_2^2+2\langle\partial_1Y,\partial_1Y\rangle_Tx_2^2\\
     & &&+2\langle\partial_2Y,\partial_2Y\rangle_Tx_1^2+8\langle\partial_1Y,\partial_2Y\rangle_Tx_1x_2,
     \end{align*}
     and
     \begin{align*}
         d_T=\langle\partial_1Y,\partial_1Y\rangle_T+\langle\partial_2Y,\partial_2Y\rangle_T
     \end{align*}

yields
\begin{align*}
   & \int|\nabla Y_T+\nabla Z_T(u)|^4-2|\nabla Y_T+\nabla Z_T(u)|^2-c_T(\nabla Z_T(u))-4b_T(\nabla Z_T(u))-a_T+2d_T\\
    &=\int[\![\nabla Y_T^4]\!]
    +4[\![\nabla Y_T^3]\!]\cdot\nabla Z_T(u)+4\nabla Y_T\cdot(\nabla Z_T(u))^3
    +(\nabla Z_T(u))^4\\&
    +\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})[\![\partial_iY_T\partial_j Y_T]\!]\partial_k Z_T(u) \partial_l Z_T(u)\\&-2[\![\nabla Y_T^2]\!]-4(\nabla Y_T)(\nabla Z_T(u))-2(\nabla Z_T(u))^2.
\end{align*}
If we define
\begin{align*}
    &\Phi_T(u)\coloneq\int4\nabla Y_T\cdot(\nabla Z_T(u))^3 +4[\![\nabla Y_T^3]\!]\cdot\nabla Z_T(u)\nonumber\\
    &+\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})[\![\partial_iY_T\partial_j Y_T]\!]\partial_k Z_T(u) \partial_l Z_T(u)\\
    &-4(\nabla Y_T)(\nabla Z_T(u))-2(\nabla Z_T(u))^2
\end{align*}
we obtain the representation
\begin{align*}
    F_T(u)=\mathbb{E}\left[ f(Y_T+Z_T(u))+\Phi_T(u)+\Vert\nabla Z_T(u)\Vert_{L^4}^4+\frac{1}{2}\int_0^\infty\Vert u_s\Vert^2_{L^2}\ ds\right].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 16 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Let $(x_{1}^{0},\cdots\!,x_{N}^{0})\in \Delta_{N}^{c}$, 
and let $(x_{1}(t),\cdots\!,x_{N}(t),\xi_{1}(t),\cdots\!,\xi_{N}(t))\in C^{1}(\mathbb{R};\mathbb{T}^{2N}\times \mathbb{R}^{2N})$ 
be a solution to \eqref{trajectories intro}. Let $\mathcal{F}_{\varepsilon,N}(t)$ be given by \eqref{total energy discrete}. Then
\begin{align*}
\frac{\dd}{\dd t}\mathcal{F}_{\varepsilon,N}(t)=0 \qquad \mbox{for all}\ t\in \mathbb{R}_{+}.     
\end{align*}

