body:
[Cor 53 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$, $k\geq 0$, $j\geq 1$, $l\geq 0$, with $j+2l\leq 2k+1$.
Let $b\in2\lambda\N$ with $b\geq v + 2\lambda$.
Then
\begin{multline*}
\E\Big[\big\Vert
\ell_{0,b}^{2k+1-j-2l}V_{A_{0,b}}^{l}
\,:\Phi_{D\setminus A_{0,b}}^{j} :
\ind_{\{z\in A_{0,b}\text{~or~}\ell_{0,b}(z)=b\}}
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
\leq
\\
C_{j,l}(1\vee\diam(D)^{j/4})
b^{4k+2-2j - 4l}
\\
\times
\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\Big(
1\vee\log\Big(\dfrac{2(1\vee\diam(D))}{\vert w-z\vert}\Big)^{j+2l}
\Big)
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w,
\end{multline*}
where $C_{j,l}>0$ is a constant depending only on $j$ and $l$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] Consider $H_c^\ast(F(S^1\vee S^1),n)$ as a $S_n\times D_{12}$-module, by inclusion of the dihedral group of order 12 in $GL_2(\mathbb{Z})$.  There exist isomorphisms of graded symmetric sequences:
	\begin{enumerate}
		\item $H^{\ast+1}(\mathsf{gr}_2(\mathsf{FT}_\Gamma))\oplus \mathsf{W}_{\pm} 
		\cong H_c^{\ast}(F(S^1\vee S^1),-)\tensor_{D_{12}} V_{120}$	
		\item $H^{\ast+2}(\mathsf{gr}_1(\mathsf{FT}_\Gamma)) \cong  H_c^\ast(F(S^1\vee S^1),-)\tensor_{D_{12}} (\chi_s \oplus V_{120} ) \oplus \mathsf{W}_{\pm}$	
		\item  $H^{\ast+3}(\mathsf{gr}_0(\mathsf{FT}_\Gamma))\cong H_c^\ast(F(S^1\vee S^1),-)\tensor_{D_{12}} \chi_s$	
	\end{enumerate}
where $\chi_s$ is the 1-dimensional representation fixed by rotation generator $r$ and alternating on reflection generator $s$, $V_{120}$ is the 2-dimensional irreducible in which $r$ corresponds to $120^\circ$ rotation, and $\mathsf{W}_{\pm}$ is a $\mathbb{Z}_2$ graded sum of Whitehouse modules $\mathsf{W}_{n,\ast}$ concentrated in degrees $n$ and $n-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2609.01237, ''] For each $v \in H^1(\Omega)$, we say that $v$ satisfies \textbf{Condition $\cA$} if and only if
	\begin{align*}
-\Delta v^{(2)} + \beta v^{(2)} &= 0, \quad \text{in } \Omega_2, 
    \\
{\boldsymbol{n}_2 \cdot  \nabla v^{(2)}}  &= 0, \quad  \text{on } \partial\Omega,
	\end{align*}
where $v^{(2)} = \restr{v}{\Omega_2}$.  Define the set
    \begin{align*}
\cH \coloneqq \{ v \in H^1(\Omega) \mid v \text{ satisfies Condition $\cA$} \}.
    \end{align*}

[Definition 84 (Deformation tensors) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $Z$ be a spacetime vectorfield.
We define the \emph{deformation tensor} $\deform{Z}$  of $Z$ 
(with respect to $\gfour$)
to be the following symmetric type $\binom{0}{2}$ tensorfield:
\begin{align} 
\deformarg{Z}{\alpha}{\beta} 
& 
\eqdef \Lie_Z \gfour_{\alpha \beta} 
= 
\Dfour_\alpha Z_\beta + \Dfour_\alpha Z_\beta,
\end{align}
where the final equality in \eqref{E:DEFORMATIONTENSORDEF} follows from the torsion-free property of $\Dfour$. We define $\angdeform{Z} \eqdef \torusproject \deform{Z}$ as in Def.\,\ref{D:PROJECTIONTENSORFIELDSANDTANGENCYTOHYPERSURFACES}.

[Proposition semigroup strong continuity of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $f \in \mathcal H$, 
\begin{equation} 
\lim_{\tau \rightarrow 0} \| \mathbf P_\tau f- f\|_{\mathcal H} 	= 0. 
\end{equation}

