[Theorem 12 (Uniform bounded four-moment surrogate) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Assume W3 and W5.  After decreasing \(\delta_0\) as in
Lemma~\ref{lem:uniform-fourth-package}, the variables
\(\widehat Y_s\), \(|s|\le\delta_0\), satisfy
\begin{equation}
 \sup_{|s|\le\delta_0}|\widehat Y_s|
 \le 2\sqrt{2C_4}
 \quad\text{almost surely},
\end{equation}
and
\begin{equation}
 \E\widehat Y_s^q=\E Y_s^q,
 \qquad q=1,2,3,4,
 \qquad |s|\le\delta_0.
\end{equation}
Consequently
\begin{align}
 \E Z^{(4)}(s)&=m(s),\\
 \Var(Z^{(4)}(s))&=v(s),\\
 \cum_r(\widehat Y_s)&=\cum_r(Y_s),
 \qquad r=3,4.
\end{align}
If \(f\) is Borel measurable, the parameters in
\eqref{eq:Q-s-U-package} may be chosen Borel measurably in \(s\).

[Lemma 10 (Consistency and localization) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[lemma]{le:ll_consistency}
\label[lemma]{le:ll_outer_localization}
Under the standing assumptions,
\begin{equation}
    \sup_{t\le1}|X_t-\hat X_t^n|
    \xrightarrow{P}0,
\end{equation}
and
\begin{equation}
    \sup_{t\le1}
    |\hat X_t^n-\hat X_{\varphi_n(t)}^n|
    \xrightarrow{P}0.
\end{equation}
Moreover,
\begin{equation}
    \lim_{\rho\uparrow\infty}
    \limsup_{n\to\infty}
    \Prob*{P}{(\Xi_{n,\rho})^c}
    =
    0 .
\end{equation}

