		 & \ \ +  \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \upmu  \exp(2\LogDensity)\Speed (\Speed_{;\LogDensity} \Lunit \LogDensity + \Speed_{;\Ent} \Lunit \Ent) |\tander^N \vortrenormalized|^2 \weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond \\
