[Lemma lem.tau-tails of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] There exist constants $C=C(d,\Lambda,r_0)>0$ and $c=c(d,\Lambda,r_0)>0$ such that for every $\lambda\in(0,1]$ and $t>0$,
		\begin{equation}
			\sup_\omega \widehat P^{\lambda,\omega}_0\bigl(\tau_1\ge\lambda^{-2}t\bigr)\le Ce^{-ct}\, ,
		\end{equation}
		and for every $k\ge 1$,
		\begin{equation}
			\widehat{\mathbb P}^\lambda_0\bigl(\Delta\tau_k\ge\lambda^{-2}t\bigr)\le Ce^{-ct}\, .
		\end{equation}

[Proposition Prop.BDG of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For two constants $p\geq 1$ and $T>0$, assume that
 	\begin{eqnarray*}
 	\sup_{t\in[0,T]}\mathbf{E}\Big[\big|X(t)\big|^{p}\Big]<\infty
 	\quad \mbox{and}\quad 
 	\int_0^T ds \int_0^\infty \big|g(s,y)\big|^{2p}\mu(dy) <\infty.
 	\end{eqnarray*}
 	Then there exists a constant $C>0$ depending only on $p$ such that
 	\begin{eqnarray} 
 	\sup_{t\in[0,T]}\mathbf{E}\Big[ \big| B(f,t) \big|^{2p}  \Big] 
 	\leq C\cdot \sup_{t\in[0,T]}\mathbf{E} \Big[\big|X(t)\big|^p \Big] \cdot \bigg| \int_0^T   \big|f(s)\big|^{2} ds  \bigg|^{p}
 	\end{eqnarray}
 	and 
 	\begin{eqnarray} 
 	\sup_{t\in[0,T]}\mathbf{E}\Big[ \big| \widetilde{N}(g,t) \big|^{2p}  \Big] 

 	\!\!\!&\leq\!\!\!& C  \cdot \sup_{t\in[0,T]}\mathbf{E} \Big[\big|X(t)\big|^p \Big] \cdot \bigg| \int_0^T ds \int_0^\infty\big|g(s,y)\big|^{2} \mu(dy)  \bigg|^{p} \cr
 	\!\!\!&\!\!\!& + C \cdot \sup_{t\in[0,T]}\mathbf{E}\Big[\big|X(t)\big|\Big]\cdot \int_0^T ds \int_0^\infty\big|g(s,y)\big|^{2p} \mu(dy) .
 	\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem prop:instest of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For every $\mathsf{q} \in \mathsf{R}_1\cup \cdots \cup \mathsf{R}_7$, define the constants 
\begin{equation} 
    \Delta \mathrm G_{*} = \mathrm G_{*}(z_*^+) - \mathrm G_{*}(z_*^-), \qquad * \in \{1, 2, 3, 12, 23, 123\}. 
\end{equation}
There exist constants $C, c, L_0>0$ such that for every $L \ge L_0$ and $\mathbf{n}\in {\mathbb N}^3$, 
\begin{equation} 
    |\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}| 
    \le C^{|\mathbf{n}|} \sqrt{n_1! (n_2-n_1+a_1+b_1)! (n_2-n_3+a_3+b_3)!n_3!} 
    \, L^{3|{\mathbf v}|} e^{c|{\mathbf v}| L^{1/2}}
    e^{- L \sum_{* \in \mathcal A_3} v_* \Delta \mathrm G_*}
\end{equation}
for every ${\boldsymbol \sigma}, {\boldsymbol \tau}\in \mathcal S_{\mb{n}}$  of the following forms: 
\begin{enumerate} [(a)]
\item 
${\boldsymbol \sigma} =2^{a_2} (23)^{a_{23}}3^{a_3}(123)^{a_{123}}(12)^{a_{12}}1^{a_1}$ and 
${\boldsymbol \tau} = 3^{b_3'}2^{b_2'}1^{b_{1}}2^{b_2''}3^{b_3''}$ 
if $\mathsf{q}\in \mathsf{R}_1\cup \mathsf{R}_2$; 
\item 
${\boldsymbol \sigma} = 3^{a_3}(23)^{a_{23}}2^{a_2}(123)^{a_{123}}(12)^{a_{12}}1^{a_1}$ and ${\boldsymbol \tau} = 3^{b_3'}2^{b_2'}1^{b_{1}}2^{b_2''}3^{b_3''}$  if $\mathsf{q} \in \mathsf{R}_3\cup \mathsf{R}_4$; 
\item 
${\boldsymbol \sigma} = 3^{a_3}(23)^{a_{23}}(123)^{a_{123}}1^{a_1} (12)^{a_{12}} 2^{a_2}$ and ${\boldsymbol \tau} = 3^{b_3'}2^{b_2'}1^{b_{1}}2^{b_2''}3^{b_3''}$   if $\mathsf{q} \in \mathsf{R}_5$; 
\item 
${\boldsymbol \sigma} = 3^{a_3}(23)^{a_{23}}(123)^{a_{123}}1^{a_1} (12)^{a_{12}} 2^{a_2}$ and ${\boldsymbol \tau} = 2^{b_2}(23)^{b_{23}}3^{b_{3}'}(12)^{b_{12}}1^{b_1}3^{b_{3}''}$ if $\mathsf{q} \in \mathsf{R}_6\cup \mathsf{R}_7$,
\end{enumerate}
where ${\mathbf v}=(v_{123}, v_{12}, v_{23}, v_1, v_2, v_3)$ is given by 
\begin{equation*}
    {\mathbf v}= \begin{cases}
    (a_{123}, a_{12}, a_{23}, a_1, a_2, a_3) \qquad \text{for $\mathsf{q}\in \mathsf{R}_1\cup\cdots \cup \mathsf{R}_5$,}\\
    (a_{123}, a_{12}, a_{23}, a_1, b_2, a_3) \qquad \text{for $\mathsf{q}\in \mathsf{R}_6\cup \mathsf{R}_7$.}
    \end{cases}
\end{equation*}
Furthermore, if $\mathsf{q}\in \mathsf{R}_1$ and $a_2>0$ in (a), then $\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}=0$. Similarly, if $\mathsf{q}\in \mathsf{R}_7$ and $b_2>0$ in (d), then $\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}=0$.

