[Lemma L:4th-power-I2 of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] Let the term $\mathcal{I}_2$ be defined in equation (equation E:LLn-4th-power of the paper). Then, for the solutions $\Phi(x,y)$ and $\Xi(x,y)$ of Poisson equations (equation E:I2-Poisson-Eq of the paper), we have the following representation of $\mathcal{I}_2:$
\begin{equation*}
\begin{aligned}
 \mathcal{I}_2 & =   \int_0^t e^{2\alpha s} (X_s^\varepsilon- \bar{X}_s) \mathscr{L}_y \Phi(X_s^\varepsilon, Y_s^\eta) \thinspace ds \\
&  = \eta e^{2 \alpha t} (X_t^\varepsilon- \bar{X}_t)\Phi(X_t^\varepsilon, Y_t^\eta)  - \eta \int_0^t 2 \alpha e^{2 \alpha s} (X_s^\varepsilon- \bar{X}_s)\Phi(X_s^\varepsilon, Y_s^\eta) \thinspace ds \\
&  - \eta^2  e^{2 \alpha t} \Xi(X_t^\varepsilon,Y_t^\eta) + \eta^2  \Xi(X_0^\varepsilon,Y_0^\eta) + \eta^2 \int_0^t 2 \alpha e^{2 \alpha s} \Xi(X_s^\varepsilon, Y_s^\eta) \thinspace ds - {\eta \varepsilon}\int_0^t e^{2\alpha s} \sigma^2(X_s^\varepsilon)  \Phi_{x}(X_s^\varepsilon, Y_s^\eta) \thinspace ds \\
 &  + \eta^2  \int_0^t  e^{2 \alpha s} \Xi_x(X_s^\varepsilon, Y_s^\eta) c(X_s^\varepsilon, Y_s^\eta) \thinspace ds  + \eta^2  \sqrt{\varepsilon}\int_0^t  e^{2 \alpha s} \sigma(X_s^\varepsilon) \Xi_x(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^1\\
 &  + \frac{\eta^2}{\sqrt{\eta}}\int_0^t e^{2 \alpha s} \tau(X_s^\varepsilon) \Xi_y(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^2 + \frac{\varepsilon \eta^2}{2} \int_0^t  e^{2 \alpha s} \sigma^2(X_s^\varepsilon) \Xi_{xx}(X_s^\varepsilon, Y_s^\eta) \thinspace ds\\
\end{aligned}
\end{equation*}
\begin{equation*}
\begin{aligned}
&  - \eta  \int_0^t e^{2\alpha s} \Phi(X_s^\varepsilon, Y_s^\eta) \{\bar{c}(X_s^\varepsilon) - \bar{c}(\bar{X}_s) \} \thinspace ds  -  \sqrt{\varepsilon} \eta \int_0^t e^{2\alpha s} \sigma(X_s^\varepsilon) \Phi(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^1 \\
&  -  \eta  \int_0^t e^{2\alpha s} (X_s^\varepsilon- \bar{X}_s) \Phi_x(X_s^\varepsilon, Y_s^\eta)c(X_s^\varepsilon, Y_s^\eta) \thinspace ds - \eta \sqrt{\varepsilon}\int_0^t e^{2\alpha s} (X_s^\varepsilon- \bar{X}_s) \sigma(X_s^\varepsilon) \Phi_x(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^1 \\
&  - \frac{\eta}{\sqrt{\eta}}\int_0^t e^{2\alpha s} (X_s^\varepsilon- \bar{X}_s) \tau(X_s^\varepsilon) \Phi_y(X_s^\varepsilon, Y_s^\eta) \thinspace dW_s^2  - \frac{\varepsilon \eta}{2}\int_0^t e^{2\alpha s} (X_s^\varepsilon- \bar{X}_s) \sigma^2(X_s^\varepsilon) \Phi_{xx}(X_s^\varepsilon, Y_s^\eta) \thinspace ds.
\end{aligned}
\end{equation*}

