body:
[Theorem 15 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] Suppose that $\v \in \boldsymbol{L}^\infty(\R^2)$ is
	compactly supported and divergence-free.
	Then the following properties are equivalent:
	\begin{enumerate}
		\item[(i)] for any $\rho_0 \in L^2(\R^2)$
		there exists a unique solution $\rho\in L^\infty(I; L^2(\R^2))$
		of \eqref{CE} with the initial condition $\rho|_0 = \rho_0$;
		\item[(ii)] for any $\rho_0 \in L^2(\R^2)$
		there exists a unique solution $\rho\in L^\infty(I; L^2(\R^2))$
		of \eqref{CE} with the final condition $\rho|_T = \rho_0$.
		\item[(iii)] the stream function of $\vi$ has the weak Sard property;
		\item[(iv)] the operator $\vi \cdot \nabla$ is essentially skew adjoint.
	\end{enumerate}

[Lemma 11 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] There exists a positive constant $C>0$, such that
	\begin{equation*}
		\mathbf{E}\left[ E_{0, 0}^\omega\left[ \left(\frac{\mu^{(1)}_{1} - \tau^{(1)}_1}{n^{1/2}} \wedge 1\right) \left(\frac{\mu^{(2)}_{1} - \tau^{(2)}_1}{n^{1/2}} \wedge 1\right) \right]\right]\le Cn^{2\varepsilon - 1}.
	\end{equation*}

