[Theo 4 of arXiv:2506.21087, 'Quasi-Stationary Distributions of Interacting Dynamical Systems and their approximation'] Assume \ref{condhzero}, \ref{condhun}, \ref{condhdeux} and \ref{condhtrois}. Assume  that  $(\mu_n)_{n\ge1}$ is $a.s.$ tight on ${\cal P}(\MM)$ and that $(\gamma_n)$ satisfies \eqref{hyp:pas}. Then,
\begin{itemize}
\item[(i)] The sequence $(\mutilde^{(n)})_{n\ge1}$ is almost surely tight on ${\cal C}(\ER_+,{\cal P}(\MM))$ and every weak limit of $(\mutilde^{(n)})_{n\ge1}$ is a solution of the ODE
\begin{equation}

\frac{d\nu_t}{dt}=-\nu_t+\Pi_{\nu_t}.
\end{equation}
\item[(ii)] If furthermore  \ref{condhquatre} holds, then every weak limit of $(\mutilde^{(n)})_{n\ge1}$ is stationary which implies that every weak limit of $(\mu_n)_{n\ge1}$ is a QSD $\mu^\star$ related to $(K_{\mu,\partial})_{\mu\in{\cal P}(\MM)}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 81 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We endow the space $\scrd_{S,X}^{2 \alpha}([0,T], W)$ with the seminorm
\begin{align*}
\| Y,Y' \|_{X,2\alpha}^{\wedge} := \| Y' \|_{\alpha}^{\wedge} + \| R^Y \|_{2 \alpha}.
\end{align*}

[Lemma lem:HittingTimesGeneralCheeger of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $\varepsilon \in (0,1]$, and let $C$ be as in Lemma~(lem:revprelim of the paper). Suppose that the single ball chains are reversible and $\Phi_{\ast}^{(n)} = \Omega(n^{\alpha - 1})$ for some $\alpha \in (0,1]$. Let $k = \floor{\frac{1}{\alpha}}$. Further, let
    \begin{equation*}
        t_n = \frac{mn}{\gamma_n} \brac{\frac{1}{2} \log n + (k+1)\log(2dm)}, \text{ and } t_n' = \frac{mn}{\gamma_n} \brac{\frac{1}{2} \log n - \log(2C)},
    \end{equation*}
    for $n \in \mathbb{N}$. Then for all $\mathbf{x} \in \Omega_n$ and $n$ large enough, we have
    \begin{equation*}
        \Ps{\mathbf{x}}{X^{(n)}_{t_n} \in {\mathrm{Centre}(C)}} > 1-\varepsilon.
    \end{equation*}
    Moreover, we can find a sequence of starting states $(\mathbf{x}_n)_{n \geqslant 1}$ such that for $n$ large enough, we have
    \begin{equation*}
        \Ps{\mathbf{x}_n}{X^{(n)}_{t_n'} \in {\mathrm{Centre}(C)}} < \varepsilon.
    \end{equation*}

