body:
[Proposition propoAiry: any q potential of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Let $K_q$ be the fundamental solution of (equation eqAiry: Airy PDE with q of the paper). There exist numerical constants $\varepsilon_\star,\mathcal{E}_\star,\Lambda_\star>0$ with the following properties.

	\begin{enumerate}
		\item For every $\ell_0>0$, there is $C=C(\ell_0)<\infty$ such that, if $\Lambda_q(a,b)\geq\ell_0$ and $\varepsilon_\infty(q)\leq\varepsilon_\star$, then
		\begin{equation}
			K_q(x,y;a,b)
			\leq
			Cxy\sqrt{q(a)q(b)}
			\exp\{-\alpha_1\Lambda_q(a,b)\},
			\qquad x,y\geq 0.
		\end{equation}

		\item If $\Lambda_q(a,b)\geq\Lambda_\star$, $\varepsilon_\infty(q)\leq\varepsilon_\star$, and $\mathcal{E}(q)\leq\mathcal{E}_\star$, then
		\begin{equation}
			K_q(x,y;a,b)
			\geq
			C^{-1}xy\sqrt{q(a)q(b)}
			\exp\{-\alpha_1\Lambda_q(a,b)\}
		\end{equation}
		for $0\leq x\leq 2q(a)^{-1/3}$ and $0\leq y\leq 2q(b)^{-1/3}$.
		Here $C<\infty$ is numerical.
	\end{enumerate}

