[Lemma L:HAtInfty of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose $\alpha>0$, $\beta\in(0,2]$, $\gamma \ge 0$, and $d \in \mathbb{N}$.
  Denote the following cases:
  \begin{multicols}{2}
    \begin{itemize}

      \item Case 1: $0 < \alpha \le \beta \le 2$;

      \item Case 2: $0 < \beta < 2 \wedge \alpha$ and $\alpha \not\in 2\mathbb{N}$;

      \item Case 3: $\alpha>\beta =2$ and $\alpha\not\in 2\mathbb{N}$;
            \begin{itemize}
              \item Subcase 3-1: $\gamma < \alpha - 3 + d/2$;
              \item Subcase 3-2: $\gamma > \alpha - 3 + d/2$;
              \item Subcase 3-3: $\gamma = \alpha - 3 + d/2$.
            \end{itemize}

      \item Case 4: $\alpha = 2$ and $\beta < 2$;

      \item Case 5: $\alpha \in 2 \mathbb{N}+2$ and $\beta \in (0, 2)$.

    \end{itemize}
  \end{multicols}
  \noindent Then the function $f(x)$, defined in~(equation E:f(x) of the paper), has the
  following asymptotic expansion at infinity along the positive real line as
  $x\to+\infty$:
  \begin{align*}
    f(x) =
    \begin{dcases}
                                                & \text{\textit{Case(s)}}                                                                                     \\[1em]
      \frac{h_{1,1}}{x} + o\left(x^{-1}\right), & \text{1, 2, 3-1;}                                                                                           \\[1em]
      \frac{2^{\frac{4d-2-4\alpha\gamma-3\alpha}{2(\alpha-2)}} \alpha ^{\frac{\alpha  \gamma +\alpha -d}{\alpha-2}}}{\sqrt{\alpha -2}}
      \sin\left( C_3\: x^{1/(\alpha-2)} + \frac{\pi}{4} \left(d-2\gamma\right)\right) x^{-\frac{2\gamma-d+2}{2(\alpha-2)}}
      + o\left(x^{-\frac{2 \gamma -d+2}{2(\alpha-2)}}\right),
                                                & \text{3-2;}                                                                                                 \\[1em]
      \left( \frac{2^{-2\alpha-d+1/2} \alpha^{\alpha +d/2}}{\sqrt{\alpha-2}}\sin\left(C_3\: x^{1 /(\alpha-2)} + \pi(3-\alpha)/2 \right) + h_{1,1}\right)\frac{1}{x} + o\left(x^{-1}\right),
                                                & \text{3-3;}                                                                                                 \\[1em]
      \frac{\beta ^{\frac{-4\gamma+\beta (d-3)+2}{4-2\beta}}}{\sqrt{2-\beta}} x^{\frac{d/2+1-(\beta+\gamma)}{2-\beta}}                                        \\
      \quad \times \exp\left( -(2-\beta) \beta^{\beta / (2-\beta)} x^{1/(2-\beta)} \right) \left(1+O\left(x^{-1/(2-\beta)}\right)\right),
                                                & \text{4;}                                                                                                   \\[1em]
      C_{5,1}\: x^{\frac{d/2+1-(\beta+\gamma)}{\alpha-\beta}} \cos\left(C_{5,2} - C_{5,3}\cos\left(\theta_{\alpha,\beta}\right)\: x^{1/(\alpha-\beta)}\right) \\
      \quad \times \exp\left(- C_{5,3}\sin\left(\theta_{\alpha,\beta}\right)\: x^{1/(\alpha-\beta)}\right) \left(1+O\left(x^{-1/(\alpha-\beta)}\right)\right),
                                                & \text{5;}                                                                                                   \\[1em]
    \end{dcases}
  \end{align*}
  where the constants are given below
  \begin{gather}
    h_{1,1} = \frac{\Gamma\left((d+\alpha)/2\right) \Gamma\left(1+\alpha/2\right)}{\pi\: \Gamma(2\beta+\gamma)} \sin\left(\pi\alpha /2\right), \\
    C_3     = (\alpha -2)\: 2^{(\alpha+2)/(\alpha-2)} \alpha^{-\alpha/(\alpha -2)}, \nonumber
  \end{gather}
  and in Case 5,
  \begin{align}
    \theta_{\alpha, \beta} \coloneqq \frac{2-\beta}{\alpha-\beta} \times \frac{\pi}{2} \in (0, \pi/2),
  \end{align}
  and 
  \begin{align*}
    C_{5,1} & =  (2\pi)^{(\alpha/2 -1)/2} \left(\alpha -\beta \right)^{-1/2}
    (\alpha/2)^{\frac{\beta(1-d)+ \alpha(2\beta+2\gamma-3)}{2\alpha-2\beta}}
    \beta^{\frac{\beta(1+d)- \alpha (2\beta +2\gamma-1)}{2\alpha-2\beta}},                         \\
    C_{5,2} & = \frac{\pi(\alpha/2-1)(d/2+1-(\beta+\gamma))}{\alpha-\beta}, \quad \text{and}       \\
    C_{5,3} &  (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3} and \eqref{PETNs-3.01} hold. Then, for every $\tau \in \mathbb{R}$ and $D = \{D(t), t \in \mathbb{R}\} \in \mathfrak{D}$, there exist ${T} := {T}(\tau, D) > 1$ and  $\epsilon_{0}\in (0,1]$ such that for all $\epsilon\in (0,\epsilon_{0})$ and $t \geq {T}$, the solution $v$ of \eqref{PEeq-2.15} satisfies
	\begin{align}
		&~~\mathbb{E}\left[|v(\tau, \tau - t, \zeta)|^4\right] + \int_{\tau - t}^\tau e^{-\kappa(\tau - s)}\mathbb{E}\left[|v(s, \tau - t, \zeta)|^2\|v(s, \tau - t, \zeta)\|^2\right]{d}s\\ \notag
		&\leq \mathcal{R}_1 + \mathcal{R}_1\int_{-\infty}^\tau e^{-\kappa(\tau - s)}|g(s)|^{4} {d}s,
	\end{align}
	and
	\begin{align}
		\begin{split}
			\int_{\tau - 1}^\tau \mathbb{E}\left[\|v(s, \tau - t, \zeta)\|^2\right]{d}s\leq \mathcal{R}_2 + \mathcal{R}_2\int_{-\infty}^\tau e^{-\kappa(\tau - s)}|g(s)|^{4} {d}s,
		\end{split}
	\end{align}
	where $\zeta\in L^4(\Omega,\mathscr F_{\tau-t};\mathcal H)$ with $\mathscr{L}(\zeta) \in D(\tau - t)$, and $\mathcal{R}_i$ $(i=1,2)$ are positive constants independent of $\tau$, ${\epsilon}$ and $D$.

