[Lemma Pdefmj of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $j\ge 0$ and 
\begin{equation}

M_j(u)=(K+j+\nu_b+2)(-1)^{j}w_{\gamma-1,\nu_b+1}(K-1+j)\mathcal T(bu^{K+j}),
\end{equation}
then we have the following convergent series representation for $|u|<1$:
\begin{equation}

M_j(u)=\sum_{m=j+1}^{+\infty}(-1)^{m}w_{\gamma-1,\nu_b+1}(K-1+m)u^{K-1+m}.
\end{equation}
Moreover, let $1\le j\le {5}$, then there exist universal constants {$0<c_{\nu,1}<c_{\nu,2}$} such that:\\ \noindent\underline{behavior for small u}:  for $0\le u\le  b$,
\begin{equation}

{c_{\nu,1}}\le \frac{M_j(u)}{\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+j+4-\alpha_\gamma}u^{K+j}}\le {c_{\nu,2}}\end{equation}
\noindent\underline{behavior for large u}: for $b\le u< \frac 12$:
\begin{equation}

{c_{\nu,1}}\le \frac{M_j(u)}{\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+3}\left(\frac{u}{1-u}\right)^{K-1}u^{\alpha_\gamma}}\leq {c_{\nu,2}}.
\end{equation}
\noindent\underline{control of the iterate}:  let $1\le j\le 5$, then
\begin{equation}

\left\|\frac{\mathcal T (u^jM_0)}{M_0}\right\|_{L^\infty(u\leq \frac 12)}\le \frac{c_\nu}{b}.
\end{equation}

\noindent\underline{control of the derivative}: 
\begin{equation}

\forall 0\le u\le \frac 12, \ \ \frac{|uM_0'|}{M_0}\leq \frac{c_\nu}b. 
\end{equation}

