\prod_{i=1}^{q_{\times}}x_i
-
\Phi^{\times,R_{\times},\beta_{\times}}_{q_{\times},\varepsilon_{\times}}(\mathbf{x})
\right|
\le
\varepsilon_{\times}   
\end{equation*}
Moreover, $\Phi^{\times,R_{\times},\beta_{\times}}_{q_{\times},\varepsilon_{\times}}
(\mathbb R^{q_{\times}}) \subseteq [-R_{\times}^{q_{\times}},R_{\times}^{q_{\times}}]$, and $\sup_{
x\in\mathbb R^{q_{\times}}
\setminus
(-R_{\times},R_{\times})^{q_{\times}}
}
\left|
\Phi^{\times,R_{\times},\beta_{\times}}_{q_{\times},\varepsilon_{\times}}(\mathbf{x})
\right|
\le
\varepsilon_{\times}.
$ Finally, the network may be chosen with $\operatorname{depth}(\Phi^{\times,R_{\times},\beta_{\times}}_{q_{\times},\varepsilon_{\times}}) \leq C \log(q_{\times})\left(
1+ \Big|\log_2\left(\frac{\varepsilon_{\times}}{q_{\times} R_{\times}^{q_{\times}}}\right)\Big|
\right)$, $\operatorname{width}(\Phi^{\times,R_{\times},\beta_{\times}}_{q_{\times},\varepsilon_{\times}}) \leq C q_{\times}$, and $\operatorname{size}(\Phi^{\times,R_{\times},\beta_{\times}}_{q_{\times},\varepsilon_{\times}}) \leq C q_{\times}$.

[Definition Def:ms-dissipative-schurz of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let $\left\{X(t):t\in[0,\infty)] \subseteq D \subseteq \mathbb{R}^d \right\}$ be a solution of the SDE (equation eq:main_d of the paper) corresponding to initial data $X(0)\in D$ which is measurable with respect to $\mathcal{F}_0$. The SDE is called 
    \begin{enumerate}
    \item mean-square dissipative if  there exist $r,R>0$ such that     $$\limsup_{t\to\infty}\mathbb{E}\left[\|X(t)\|^2\right]<R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right]<r^2$;

    \item uniformly mean-square dissipative if  there exist $r,R>0$ such that $$\lim_{t\to\infty}\expect{\sup_{0\leq s \leq t}\|X(s)\|^2} <R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right] < r^2$.
    \end{enumerate}

