body:
[Proposition 7 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] Assume probability measures $\mu,\nu \in \mathcal{P}^\ba_1(\Rd)$ and a cost function that satisfies the conditions (H1)-(H3). Then, for any real constant $C_0$, the set
	\begin{equation}

		\left\{ (\gamma,q) \in \Gamma Q(\mu,\nu) \, : \, \int_X \! \int_Y  \cost  \Big(x,y,\frac{d q}{d\gamma}(x,y) \Big) \gamma(dxdy) \leq C_0 \right\}
	\end{equation}
	is compact for the topology of weak convergence in  $\Mes(\Rd \times \Rd ; \R \times \Rd)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor pant_iter_conv of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Let $\mathscr{X}_n(t)$ be the sequence of binary-tree stochastic Picard iterations for (equation pantode of the paper)
\begin{equation}
{{\mathscr{X}}_{n}}(t)=\left\{ \begin{array}{*{35}{l}}
   w_0 & \text{if} & T_\theta\ge t,  \\
   \frac{a}{2}\mathscr{\mathscr{X}}_{n-1}^{(1)}(\alpha (t-T_\theta))
   +\frac{a}{2}\mathscr{X}_{n-1}^{(2)}(\alpha (t-T_\theta)) & \text{if} & T_\theta<t.  \\
\end{array} \right.
\end{equation}
and $\tilde\mathscr{X}_n(t)$ is the sequence of unary-tree stochastic Picard iterations for (equation pantode of the paper)
\begin{equation}
{{\tilde\mathscr{X}}_{n}}(t)=\left\{ \begin{array}{*{35}{l}}
   w_0 & \text{if} & T_0\ge t,  \\
   a\mathscr{\mathscr{X}}_{n-1}^{(1)}(\alpha (t-T_0)) & \text{if} & T_0<t.  \\
\end{array} \right.
\end{equation}
Denote $\mathcal{Y}_n=\mathscr{X}_n$ or $\tilde\mathscr{X}$ and $\mathcal{Y}=\mathscr{X}$ or $\tilde\mathscr{X}$, respectively. Suppose that for all $t>0$, $\mathcal{Y}_n(t)$ converges a.s.\ as $n\to\infty$. Then there exists 
a stochastic process 
$\mathcal{Y}(t)$ such that $\mathcal{Y}_n(t,\omega)\to \mathcal{Y}(t,\omega)$ as $n\to\infty$ a.e.\ with respect to 
the product measure $\mu_{[0,\infty)}\otimes \mathbb P $. Moreover, for all $t>0$, $\mathcal{Y}(t)$ is a solution process for the pantograph equation, i.e.\ satisfying (equation pantbinary of the paper) or (equation pantrecursion of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cr-bcle of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] Let $\kappa \in (2,4)$, $\kappa'=16/\kappa $, $\rho \in (-2,\kappa-4)$, and $\rho_B'=\kappa'-4+\frac{\kappa'}{4}\rho$ as in~(equation eq:parameter-nonsimple of the paper).
    Denote by $\mathcal L$ the loop in $\BCLE_\kappa(\rho)$ surrounding the origin which can be either clockwise or counterclockwise, and let $D(\mathcal L)$ be the connected component of $\mathbb D \setminus \mathcal L$ that contains the origin. Let $\{ 0 \in \BCLE_\kappa^\circlearrowright(\rho) \}$ (resp.\ $\{ 0 \notin \BCLE_\kappa^\circlearrowright(\rho) \}$) the event that $\mathcal L$ is a clockwise (resp.\ counterclockwise) loop. For $\lambda> \frac{\kappa}{8}-1$ and $\theta=\frac{\pi}{\kappa} \sqrt{(4-\kappa)^2-8\kappa \lambda}$, we have
    \begin{align}
        \mathbb{E}[{\rm CR}(0,D(\mathcal L))^\lambda \1_{0 \in {\rm BCLE}^\circlearrowright_\kappa(\rho)}] &= \frac{\sin(\frac{\pi(4-\kappa)}{4}) \sin(\frac{2\pi}{\kappa}(\kappa-\rho-4))}{\sin(\frac{\pi(4-\kappa)}{\kappa}) \sin(\frac{\pi}{4}(\kappa - 2\rho-4))} \cdot \frac{\sin( \frac{\kappa-2\rho-4}{4} \theta)}{\sin( \frac{\kappa}{4} \theta)},  \\
        \mathbb{E}[{\rm CR}(0,D(\mathcal L))^\lambda \1_{0 \notin {\rm BCLE}^\circlearrowright_\kappa(\rho)}] &= \frac{\sin(\frac{\pi(4-\kappa)}{4}) \sin(\frac{2\pi}{\kappa}(\rho+2))}{\sin(\frac{\pi(4-\kappa)}{\kappa}) \sin(\frac{\pi}{4}(\kappa - 2\rho-4))} \cdot \frac{\sin( \frac{2\rho+8-\kappa}{4} \theta)}{\sin( \frac{\kappa}{4} \theta)}. 
    \end{align}
    If $\lambda \le \frac{\kappa}{8}-1$, the left hand sides of~(equation eq:cr-simple-bcle-true of the paper) and~(equation eq:cr-simple-bcle-false of the paper) are infinite.

    Denote by $\mathcal L'$ the loop in $\BCLE_{\kappa'}(\rho_B')$ surrounding the origin which can be either clockwise or counterclockwise, and let $D(\mathcal L')$ be the connected component of $\mathbb D \setminus \mathcal L'$ that contains the origin. Let $\{ 0 \in \BCLE_{\kappa'}^\circlearrowright(\rho_B') \}$ (resp.\ $\{ 0 \notin \BCLE_{\kappa'}^\circlearrowright(\rho_B') \}$) the event $\mathcal L'$ is a clockwise (resp.\ counterclockwise) loop. For $\lambda> \frac{\kappa'}{8}-1$ and $\theta=\frac{\pi}{\kappa} \sqrt{(4-\kappa)^2-8\kappa \lambda}$, we have
    \begin{align}
        \mathbb{E}[{\rm CR}(0,D(\mathcal L'))^\lambda \1_{0 \in {\rm BCLE}^\circlearrowright_{\kappa'}(\rho_B')}] &= \frac{\sin(\frac{\pi(4-\kappa)}{\kappa}) \sin(-\frac{\pi}{2} \rho)}{\sin(\frac{\pi(4-\kappa)}{4}) \sin(\frac{2\pi}{\kappa}(\rho + 2))} \cdot \frac{\sin( \frac{\kappa-2\rho-4}{4} \theta)}{\sin(\theta)},  \\
        \mathbb{E}[{\rm CR}(0,D(\mathcal L'))^\lambda \1_{0 \notin {\rm BCLE}^\circlearrowright_{\kappa'}(\rho_B')}] &= \frac{\sin(\frac{\pi(4-\kappa)}{\kappa}) \sin(\frac{\pi}{4}(\kappa-2\rho - 4))}{\sin(\frac{\pi(4-\kappa)}{4}) \sin(\frac{2\pi}{\kappa}(\rho + 2))} \cdot \frac{\sin( \frac{2\rho+4}{4} \theta)}{\sin(\theta)}. 
    \end{align}
    If $\lambda \le \frac{\kappa'}{8}-1$, the left hand sides of~(equation eq:cr-nonsimple-bcle-true of the paper) and~(equation eq:cr-nonsimple-bcle-false of the paper) are infinite.

[Prop imbalance of arXiv:2506.12171, 'The multinomial dimer model'] If $U$ is a potential counterexample in $G\subset \Lambda$ with multiplicities $N_v=N$ at all $v\in G^\circ$ and multiplicities $N_v$ between $1$ and $N$ at $v\in \partial G$, then 
    \begin{equation*}
        ND \cdot \text{imbalance}_{{\mathbf N}}(U) = -N |I_E(U)| + \sum_{u\in \partial U} |X_E(u)| N_u \,\text{sign}(u),
    \end{equation*}
    where $\text{sign}(u) = +1$ if $u\in W$ and $-1$ if $u\in B$ and $X_E(u)$ is the set of $e\in X_E(U)$ incident to the specified vertex $u\in \partial U$ (this can be empty).

