[Definition 73 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\xi \in \bbr^m$ be arbitrary. An $\bbr^m$-valued continuous, adapted process $Y = (Y_t)_{t \in [0,T_0]}$ for some $T_0 \in (0,T]$ is called a \emph{local solution} to the It\^{o} SDE \eqref{SDE-Ito} with $Y_0 = \xi$ if
\begin{align*}
Y_t = \xi + \int_0^t f_0(s,Y_s) ds + \int_0^t f(s,Y_s) dB_s, \quad t \in [0,T_0].
\end{align*}
If we can choose $T_0 = T$, then we also call $Y$ a \emph{(global) solution} to the It\^{o} SDE \eqref{SDE-Ito} with $Y_0 = \xi$.

[Lem cases_sb of arXiv:2601.00119, 'The largest common subtree of two random trees'] Let $h\geq 1$. If $\operatorname{LCS}^\bullet(\tau_*,\tau_*') > h+1$ then, for any $0<\alpha<1$, one of the following situations happens: 
    \begin{enumerate}
        \item[\emph{(i)}] There is $v\in \tau_*$ and $v'\in \tau_*'$ with $|v|=|v'|=1$ such that $\mathrm{Ht}(\theta_v\tau_*)\wedge \mathrm{Ht}(\theta_{v'}\tau_*')\le h$ and \[h^{-\alpha}\operatorname{LCS}^\bullet(\theta_v\tau_*,\theta_{v'}\tau_*')> \mathrm{Ht}(\theta_v\tau_*)\wedge \mathrm{Ht}(\theta_{v'}\tau_*') +1.\] 
        \item[\emph{(ii)}] It holds that 
        \[\left(\sum_{i=1}^{\mathrm{k}_\varnothing(\tau_*)}1+\mathrm{Ht}(\theta_i\tau_*)\right)\wedge \left(\sum_{i=1}^{\mathrm{k}_\varnothing(\tau_*')}1+\mathrm{Ht}(\theta_i\tau_*')\right)>h^{1-\alpha}.\]
    \end{enumerate}

[Thm CPPR-survival of arXiv:2507.00329, 'Oriented bond-site percolation in random environment and contact processes with periodic r'] Consider the generalised contact process on $\mathbb{Z}_{\geq0}$ with $\mathbb{X}\sim\mathrm{PPP}(\lambda)$ and either 
\begin{align}\tag{Uni}
    \mathbb{Y}&=2 (\mathbb{Z} + U), \qquad \text{where $U$ is a uniform random variable on $[0,1)$, or}\\
    \mathbb{Y}&=2\mathbb{Z} + B, \qquad \text{where $B$ is a Bernoulli random variable with parameter $q\in(0,1)$.} \tag{Ber}
\end{align}
Then, the contact process has a positive probability of survival for sufficiently large $\lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $u$ be a quasi-classical solution of \eqref{eq:model-half-space}--\eqref{eq:model-half-space-bc} with $g\equiv0$. Assume that
\[
f=D_i f^i,
\qquad
f^i\in C_x^{\alpha}(\bar Q_T^+;L_\omega^\gamma),
\qquad i=1,\dots,n.
\]
Then
\begin{equation}
|D_{x'}u|_{\alpha;Q_T^+}^{L_\omega^\gamma}
\le C\Bigl(
|u|_{0;Q_T^+}^{L_\omega^\gamma}
+\sum_{i=1}^n |f^i|_{\alpha;Q_T^+}^{L_\omega^\gamma}
\Bigr),
\end{equation}
where $C$ depends only on $n$, $\alpha$, $\gamma$, $\kappa$, and $K$.

