[Definition 10 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let us recursively define $\sfK^D\colon \psi^+(D)\to \bigl[D\bigl(\psi^+(D)\bigr)\bigr]^{<\omega}$ as follows:
    \begin{equation*} \textstyle
        \sfK^D\bigl(\psi(\sigma)\bigr) = \{\sigma\}\cup \bigcup \bigl\{ \sfK^D(s)\bigm| s\in \supp^D_{\psi^+ (D)}(\sigma)\bigr\}.
    \end{equation*}
    We also define $\hat\sfK^D\colon D\bigl(\psi^+(D)\bigr)\to \bigl[D\bigl(\psi^+(D)\bigr)\bigr]^{<\omega}$ by
    \begin{equation*}
        \hat\sfK^D(\sigma) = \bigcup \bigl\{ \sfK^D(s)\bigm| s\in \supp^D_{\psi^+(D)}(\sigma)\bigr\}.
    \end{equation*}

