[Theorem 7 (Exact $\MAX_6$ identity) of arXiv:2608.25221, 'Representing MAX functions using two-hidden-layer ReLU networks'] We have the following identity.
\begin{align}
2\MAX_6={}&-\frac13 G_{\mathcal O[P_0]}
+\frac1{90} G_{\mathcal O[P_{22}]}
+\frac1{180}G_{\mathcal O[P_{51}]}
-\frac1{360}G_{\mathcal O[P_{71}]}\notag\\
&+\frac1{180}G_{\mathcal O[P_{130}]}
-\frac1{90}G_{\mathcal O[P_{135}]}
+\frac1{720}G_{\mathcal O[P_{136}]}.
\end{align} where
\begin{align*}
 P_0&=[11,11\mid 11,11],\\
 P_{22}&=[11,12\mid 11,34],\\
 P_{51}&=[11,12\mid 34,56],\\
 P_{71}&=[11,22\mid 34,56],\\
 P_{130}&=[12,13\mid 14,56],\\
 P_{135}&=[12,13\mid 24,56],\\
 P_{136}&=[12,13\mid 45,46].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:L2-strong of arXiv:2603.14906, 'Four Levels of Thermodynamic Convergence of Singularly Perturbed Markov Semigroups'] Suppose that (ass:standing,ass:CDkappa,ass:fundamental of the paper) hold and that the averaging model satisfies the tractable-subclass structure (equation eq:tractable-drift of the paper), so that $\pi^\varepsilon\equiv\pi$ for all $\varepsilon$.
Fix $t>0$ and set $u^\varepsilon(t)=P_t^\varepsilon f$, $\bar u(t)=\bar P_t\bar f$. Then:
\begin{align*}
\text{(i)}\;&
\|\nabla_x \sqrt{u^\varepsilon(t)}\|_{L^2(\pi;a_1)}^2=o(\varepsilon),
\\
\text{(ii)}\;&

\nabla_y \sqrt{u^\varepsilon(t)}
\;\longrightarrow\;

\sqrt{\bar u(t)\circ\Phi}
\quad\text{strongly in }L^2(a_2;\pi),
\end{align*}
and consequently
\begin{align*}
\text{(iii)}\;&
\|\nabla_x u^\varepsilon(t)\|_{L^2(\pi;a_1)}^2=o(\varepsilon),
\\
\text{(iv)}\;&

\nabla_y u^\varepsilon(t)
\;\longrightarrow\;

\nabla_y \big(\bar u(t)\circ\Phi\big)
\quad\text{strongly in }L^2(a_2;\pi).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 224 (Preliminary top-order $L^2$ estimates for $\upchi$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$, and let
$\mathfrak{P}^{(N)}$
be the set of order $N$ $\nullhyparg{u}$-tangential commutator operators from
Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N) = \blowupratetoporderwave$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. Let $\varsigma_0$ be the constant featured in Lemma\,\ref{L:PRELIMINARYBELOWTOPORDERL2ESTIMATESFOREIKONALFUINCTIONQUANTITIES} (see also Remark\,\ref{R:SMALLNESSCONSTANTFORBELOWTOPORDERACOUSTICVARIABLES}).
Then the following estimates hold for
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$, where the implicit constants are \textbf{independent} of $\varsigma_0$:\begin{align}
	\begin{split} 
		 \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}}  
		 \left| \upmu \tander^N \mytr_{\gtorus} \upchi \right|^2 \weight^{\blowupratetoporderwave} \voldiamond
		 & \lesssim  \initialsmalldoublenull^2 + \totalbulkcontrolimprecisefullymodifiedchi(\ubar,u) +   (1 + \varsigma_0^{-1}) \int_{\ubar' = \leftubar}^{\ubar} \totalfluxcontrolvelocity_{[1,N]}(\ubar',u) \, \mathrm{d} \ubar'   \\
			& \ \ +  (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N]}(\ubar,u') \, \mathrm{d} u' + (1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N]}(\ubar,u) \\
			& \ \ +  \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N}(\ubar,u')+ \fluxcontrolGradEnt_{\le N }(\ubar,u')\right\} \, \mathrm{d} u',
	\end{split} \\
	\begin{split}
		 \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}}  
				 \left| \upmu \angLie_{\tander}^N \upchi \right|_{\gtorus}^2 \weight^{\blowupratetoporderwave} \voldiamond & \lesssim  \initialsmalldoublenull^2 + (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N]}(\ubar,u') \, \mathrm{d} u' + (1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N]}(\ubar,u) \\
				 & \ \ +   \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N}(\ubar,u')+ \fluxcontrolGradEnt_{\le N }(\ubar,u')\right\} \, \mathrm{d} u' \\
				 & \ \ + \max_{\tander^N \in \mathfrak{P}^{(N)}}  \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}}  
				 \left| \upmu \tander^N \mytr_{\gtorus}\upchi \right|^2 \weight^{\blowupratetoporderwave} \voldiamond.  
	\end{split}
\end{align}

