	\begin{align*}
		V^\ast X &= V^\ast WX_0\\
		&= V^\ast P WX_0 + V^\ast P^\perp WX_0 \\
		&= V^\ast P X_0 + V^\ast P^\perp WX_0\\
		&= V^\ast P X_0 + (P^\perp V)^\ast W (P^\perp X_0).
	\end{align*}

