Let $G$ have unbounded support and let $\rho(\gamma^n, B)$ be the number of horizontal edges with weights greater than $B$ in the geodesic $\gamma^n:=\gamma((0,0),(n,{\lceil v n \rceil}))$. For all $\beta>0$ there exists  $B>0$ such that $\lim_{n \to \infty} \mathchoice
{\mathbb P \left( \rule{0pt}{11pt} \rho(\gamma^n,B)>\beta n \right)}
{\mathbb P \left(\rho(\gamma^n,B)>\beta n\right)}
{\mathbb P \left(\rho(\gamma^n,B)>\beta n\right)}
{\mathbb P \left(\rho(\gamma^n,B)>\beta n\right)}
=0$.

[Proposition alter of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] For any $n\geq1$, we have
    \begin{equation}
        B_n\left(1,q\right)=\sum_{k=0}^{n-1}\left(-1\right)^{n-1-k}h_{n-1-k}\Big(\tfrac{\left[1\right]_q^2}{q},\tfrac{\left[2\right]_q^2}{q^2},\dots,\tfrac{\left[k+1\right]_q^2}{q^{k+1}}\Big)\big(\left[k{+}1\right]_q!\big)^{2}\prod_{j=1}^{k}q^{-j},
    \end{equation}
    where $h_k\left(x_1, \dots x_n\right)$ is the homogeneous symmetric function with degree $k$ and variable $x_1 \dots x_n$.

[Theorem multivariate case of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $L\ge 1,n\ge 1$ and $g_n=([n]\times [L],E(g_n))$ be a grid graph. Assume that $w_{G_{g_n}}\to w$, where $w$ is an $\mathcal{M}_L$-decorated graphon. Let $a\in \mathcal{A}$ be a normalized random variable and let $(a_k^{(r)})_{k\in [n],r\in [L]}$ be $g_n$-independent and identically distributed random variable with common law $a$. Let
    \begin{align*}
        S_n^{(r)}=\frac{1}{\sqrt{n}}\sum_{k\in [n]}a_k^{(r)}.
    \end{align*}
    Then, $(S_n^{(r)})_{r\in [L]}$ converges in distribution to a family $(s_r)_{r\in [L]}$ whose joint distribution $\nu_{w}$ depends only on $w$. Moreover, for any $p\ge 1$ and $l\in [L]^p$, we have
    \begin{align*}
        \tau(s_{l_1}\cdots s_{l_p})=\sum_{\substack{\pi \in P_2(p)\\\pi\le \ker (l)}}\rho(F_{f_\pi}^l,w)=:\nu_w(l).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2607.11608, '2607.11608'] Let $1 \le p\le \infty$ and $s\in \R$, we define the harmonic Sobolev space $\mathcal{W}^{s,p}(\R)$ (respectively $\mathcal{W}_{\text{rad}}^{s,p}(\R^d)$ if $d\ge 2$) the space of functions (respectively radial functions) induced by the 
 norm
\begin{align*}
\|u\|_{\mathcal{W}^{s,p}(\R^d)}:=\|\mathcal{L}^{\frac{s}{2}}u\|_{L^{p}(\R^d)}.
\end{align*}
If $p=2$ we set $\mathcal{H}^s:=\mathcal{W}^{s,2}$, and for  $u$ of the form $u=\sum_{n\ge 0} c_n h_n$ we have 
\begin{align}
\|u\|^2_{\mathcal{H}^s(\R^d)}:=\|\mathcal{L}^{\frac{s}{2}}u\|^2_{L^{2}(\R^d)}=\sum_{n\ge 0} \nu^{2s}_n |c_n|^{2}. 
\end{align}

[Prop P: contractive of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Suppose that $T$ is an operator on $CDF(\overline{\mathbb{R}})$ satisfying the following two properties:
		\begin{itemize}
			\item[(i)] \emph{Monotonicity:} If $F \leq G$ pointwise in $\mathbb{R}$, then $TF\leq TG$ also holds.
		\item[(ii)] \emph{Discrete-Time Reaction-Diffusion Equation:} There is a function $\mathcal{L}$ defined on $CDF(\overline{\mathbb{R}})$ and a function $Q$ defined on $[0,1]$ such that
			\begin{align*}
				TF - F = \mathcal{L}F - Q(F) \quad \text{for each} \, \, F \in CDF(\overline{\mathbb{R}}).
			\end{align*}
		\item[(iii)] \emph{Commutation with Constants:} Given $F,G \in CDF(\overline{\mathbb{R}})$, if the difference $F - G$ is a constant function, then $\mathcal{L}F = \mathcal{L}G$.

		\end{itemize}
		If there is a constant $L > 0$ such that $|Q(q) - Q(q')| \leq L|q - q'|$ for each $q,q' \in [0,1]$, then
		\begin{align*}
			\| T^{n}F - T^{n}G \|_{\sup} \leq (1 + L )^{n} \| F - G \|_{\sup} \quad \text{for any} \, \, F,G \in CDF(\overline{\mathbb{R}}), \, \, n \in \mathbb{N}.
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_stop_markov of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] Suppose $0 \leq a \leq x \leq w \leq y \leq b$ with $x < y$ and let $\mathbb{P}_w \in \mathscr{M}_{\gamma,\delta}(w)$. Then provided $\mathbb{P}_w(\tau_x < \tau_y) >0$,
\begin{equation}
\mathbb{P}_w(\tau_x < \tau_y, \tau_a < \tau_b) = \mathbb{P}_w(\tau_x < \tau_y) \mathbb{P}_x'(\tau_a < \tau_b),
\end{equation}
for some $\mathbb{P}_x' \in \mathscr{M}_{\gamma,\delta}(x)$. Moreover, the analogous inequality holds for all variations of the ordering of the stopping times, i.e.\ exchanging $\tau_x < \tau_y$ for $\tau_y < \tau_x$, and similarly for $\tau_a$ and $\tau_b$.

