body:
[Proposition EstimImpo of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] We have, for all integers $k \leqslant n \leqslant m \leqslant l$,
    \begin{align*}
        &\mathbb{E}\Big[
            \big|
                A_N(k2^{-N} \xrightarrow{m2^{-N}} l2^{-N})
                - A_N(k2^{-N} \xrightarrow{n2^{-N}} l2^{-N})
            \big|^p
        \Big] \\
        &\qquad\leqslant
        \sup_{\substack{k \leqslant j \leqslant l \\ n \leqslant i \leqslant m}}
        \sigma\big(\square(i2^{-N},(i+1)2^{-N},j2^{-N},(j+1)2^{-N})\big)^{\beta}
        (l-k)^{\beta}(m-n)^{\beta} \\
        &\qquad\quad+
        \sup_{\substack{k \leqslant j \leqslant l \\ n \leqslant i \leqslant m}}
        \sigma\big(\square(i2^{-N},(i+1)2^{-N},j2^{-N},(j+1)2^{-N})\big)^{2\beta}
        (l-k)^{\beta} n^{2\beta}.
    \end{align*}

[Lemma lem:centear of arXiv:2606.02472, 'Correlated uniform attachment trees'] If $T$ is a $(K,\delta,c_1)$-good tree on $\{0,\ldots, n\}$ with centrality sets denoted by $A_r$, $r=1,\ldots, n$, then
\be{
\babs{ A_{\ceil{(c_1+\delta) K}} \cap \bclc{0,\ldots, K-1 }
}\geq \bclr{c_1 (1-e^{-1/c_1})-\delta}K.
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dense_discrete_measures of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] The following assertions hold:
\begin{itemize}
\item[(i)] The family of discrete $d$-Williamson measures with full support is dense in $(\mathcal{P}_{\mathcal{W}_d},\tau_w)$.
\item[(ii)] The family of singular $d$-Williamson measures with full support is dense in $(\mathcal{P}_{\mathcal{W}_d},\tau_w)$.
\item[(iii)] The family of absolutely continuous $d$-Williamson measures with full support is dense in $(\mathcal{P}_{\mathcal{W}_d},\tau_w)$.
\end{itemize}

[Lemma lem: r8 bound of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $\delta > 0$ sufficiently small, there exists $C_\delta > 0$ such that
  \begin{align}
    \mathbb E[|R_8|]\leq 
    C_\delta(1+\|H(\varphi_-,\varphi_+)\|_{B^{s}_{p,p}}^{r}) +  \delta \mathbb E [\mathcal{C}_T (u)],
  \end{align}
  where $p \in [1,2)$ is sufficiently close to $2$, $s$ is sufficiently small, and  is as below and $r \in [1,\infty)$ is sufficiently large. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 5 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] Let $\{\mu_N\}_{N\in\mathbb N}$ be a sequence of probability measures in the state-space $\mathscr X_N$ and let {$\rho_0:\mathbb T\to\mathbb R$ be an integrable function}.
The sequence $\{\mu_N\}_{N\in\mathbb N}$ is associated to $\rho_0$ if for every $G\in C(\mathbb T)$ and for every $\delta>0$ we have that 
\begin{equation*}
\lim_{N\to\infty}\mu_N\bigg( \eta\in\mathscr X_N \,;\,  
\Big| \frac{1}{N} \sum_{x\in\mathbb T_N} \eta_x G\Big(\frac xN\Big) - \int_{\mathbb T} G(u) \rho_0(u)du \Big| > \delta\bigg) =0.
\end{equation*}

[Lem 7 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] The operator $L_0\equiv L_{0,\ell}$ is given by
\begin{align*}
L_{0,\ell} = \frac12 \sum_{x=-\ell+1}^{\ell-1}
\Big( \big( \partial_{\eta(x)} - \partial_{\eta(x-1)} \big)^2
- \big( V'(\eta(x)) - V'(\eta(x-1)) \big)\big( \partial_{\eta(x)} - \partial_{\eta(x-1)} \big)  \Big).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2608.24731, 'Optimal Alternating Regret for Online Learning and Games\thanks{Authors are alphabetically'] \label[lemma]{lem:one-step}
Assume $\eta \le \frac{1}{8}$ and $\beta = \eta/4$. Then for any $t \ge 1$, we have
\begin{equation*}
\log \left( \sum_{i=1}^d p_{t,i}
\exp\!\left(
\eta\bigl((\boldsymbol{\xi}_t+\boldsymbol{\xi}_{t+1})^\top \boldsymbol{x}_t
-\xi_{t,i}-\xi_{t+1,i}\bigr)
+\beta(\xi_{t,i}^2-\xi_{t+1,i}^2)
\right)  \right) 
\leq 0.
\end{equation*}

[Lemma 6 (Cauchy-area theorem for Bernoulli width) of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] For any $x \in T$, the function $\Phi_x: [0,\infty) \rightarrow [0,+\infty)$ is nondecreasing and concave on $[0,\infty)$ with $\Phi_x(0)=0$. Moreover, it satisfies
\begin{equation}
  b(T)=\lim_{t \to \infty} \Phi_x(t)=\int_0^\infty \Phi_x'(t)\,dt.

\end{equation}
The derivative is understood almost everywhere.

[Corollary 4 of arXiv:2608.26618, 'A Unified Descriptive-Complexity Framework for Model Selection under Correlated Designs'] For every $\lambda \geq \lambda_{\rm sel}$, if the following conditions hold:
\begin{itemize}
    \item[(\romannumeral 1)]
    There exists a sufficiently large constant $c_1>1$ such that, for every
    $S\in\mathcal M_{\mathrm{sub}}$,
    \begin{equation*}
    \mathrm{APP}(S)\ge
    c_1\Bigg(
    (s^*-s)\log n
    +\lambda\Bigl((g^*\log m)^{\frac{2}{\alpha}}-(g\log m)^{\frac{2}{\alpha}}\Bigr)
    +\log^{\frac{2}{\alpha}}\binom{g^*}{\Delta^-(S)}
    \Bigg).
    \end{equation*}

\item[(\romannumeral 2)]
There exists a constant \(\kappa>0\) such that
\(2B_S<u_S\) for all \(S\in\mathcal M_w\) with
\(g>(1+\kappa)g^*\).
Moreover, for every \(S\in\mathcal M_w\) with
\(g\le(1+\kappa)g^*\),
\begin{equation*}
\begin{aligned}
\mathrm{APP}(S)\ge{}&
\lambda\left\{
\log
\binom{g^*}{\Delta^-(S)}
\binom{m-g^*}{\Delta^+(S)}
\right\}^{\frac{2}{\alpha}}
+2(s^*-s)\log n
\\
&+2\lambda\left\{
(g^*\log m)^{\frac{2}{\alpha}}
-(g\log m)^{\frac{2}{\alpha}}
\right\}
+\log\log n
+8(r_S-\widetilde r_S).
\end{aligned}
\end{equation*}
\end{itemize}
Then
\[
\Pr\!\left(
\min_{S\in\mathcal M_n,\;S\neq S^*}\mathrm{DCIC}(S)>\mathrm{DCIC}(S^*)
\right)\to 1
\qquad \text{as } n\to\infty.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:incrementLambda of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] For any $\varphi\in\mathscr{S}(\mathbb{R} )$, any $0\le s<t\le T$ and any $\varepsilon >0$, the quadratic term defined in (equation eq:Lambda of the paper) satisfies
    \begin{equation}
        \mathbb{E}_{\rho ,\mathcal{E}}\left[ \big( \Lambda_t^N(\varphi )-\Lambda_s^N(\varphi )\big)^2\right] \le C_{19} N^{\frac32 a-2\gamma -2}(t-s)^{3/2} \|\nabla\varphi\|_{L^2}^2
    \end{equation}
    for some constant $C_{19}=C_{19}(\kappa ,\rho ,\mathcal{E})>0$.

