[Lemma 2 of arXiv:2605.31300, 'Cone-Additive Functions for Random Walks on Free Products of Graphs'] Let be $\pi=[u_0,\ldots,u_m]\in\Pi$ and $v\in V$. Then:
\begin{enumerate}
\item If $\{u_0,\ldots,u_m\}\cap C(v)\neq \emptyset$ then $\pi\bigl|_{C(v)}$ is a well-defined path.
\item If $\{u_0,\ldots,u_m\}\cap C(v)^c\neq \emptyset$ then $\pi\bigl|_{\neg C(v)}$ is a well-defined path.
\end{enumerate}

[Theorem 5 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\psi \in \mathbf{\Psi}$, $A \in \mathcal{A}$, $t \in (0,1)$ if $\psi$ is strict and $t \in [0,1)$ if $\psi$ is non-strict. Moreover, let $\fg^t$ be defined as in eq. \eqref{eq:fct_g_t}, and $L$, $R$ be defined according to eq. \eqref{eq:definition_L_R}. Then the following assertions hold:
    \begin{itemize}
    \item[$(i)$] $\fg^t$ is a non-increasing function;
        \item[$(ii)$] If $0 < L < R$, then $\fg^t$ is strictly decreasing on $\left[t,\psi\left(\frac{L\varphi(t)}{1-L}\right)\right)$ and $\fg^t(x) = t$ holds for every $x \in \left[\psi\left(\frac{L\varphi(t)}{1-L}\right),1\right]$;
        \item[$(iii)$] $\fg^t$ is a convex function.
    \end{itemize}

[Lemma Palm-Lcal-ii of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For $l=1,2$ and for all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
\begin{align}
\lefteqn{\mathbb{E}^0_{{\mathcal V }_l} [f ({\mathcal H })]}{\nonumber}\\
& = 
\frac {4\lambda_l^2v_l^2} {\Lambda_{l}}
\int_{(\mathbb{R}^+)^3}
\mathbb{E}_{\mathcal H }\left[ f\left(\theta_{\hat{s}(0,h,-t',h')}           \left({\mathcal H }^l+\delta_{(0,h)}+\delta_{(-t',h')}+{\mathcal H }^m\right)\right) \prod_{i=1,2}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}(0,h,-t',h'),v_i}_{\hat{h}(0,h,-t',h')}\right)=0}  \right] {\rm d}t' {\rm d}h' {\rm d}h ,
\nonumber
\end{align}

where, $m\neq l$ and $(\hat{s}(t,h,t',h'),\hat{h}(t,h,t',h'))$ is the coordinates of the intersection point of the two radial birds with head points $(t,h)$ and $(t',h')$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lemma1stResult of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Suppose that Assumption (Assumptions of the paper) holds, let $\mathbf{X}_0$ be an initial random variable independent of $\mathbf{W}$, and let $\mathbf{X} = (\mathbf{X}_t)_{t \geq 0}$ be the corresponding solution to (equation eqGenSDEIntro of the paper) with $d$-th component $X = (X_t)_{t \geq 0}$. Then for all $\ell \in \mathbb{N}$, all $R > 0$ and all $\delta > 0$ it holds that
\begin{equation}

\begin{aligned}
&2  \Phi\Bigl(- \tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert \Bigr)^{\ell+1} - 2 \sum_{j = 1}^\ell \Phi\Bigl(-\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^j P \Bigl(\sup_{t \in I_{\ell-j}} \Vert \mathbf{X}_t \Vert > R \Bigr) \\
&\quad \leq P \Bigl(T_{1,\delta}(X) = \ell, \sup_{t \in [0, (\ell+1) \delta]} \Vert \mathbf{X}_t \Vert \leq R \Bigr) \\
&\quad \leq 2 \Phi\Bigl(\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^{\ell+1}
\end{aligned}
\end{equation}
and
\begin{equation}

\begin{aligned}
&2 \Phi\Bigl(-\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^\ell - 2 \sum_{j = 1}^{\ell-1} \Phi\Bigl(-\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^j P \Bigl(\sup_{t \in I_{\ell-j}} \Vert \mathbf{X}_t \Vert > R \Bigr) \\
&\quad \leq P \Bigl(T_{1,\delta}(X) \geq \ell, \sup_{t \in [0, \ell \delta]} \Vert \mathbf{X}_t \Vert \leq R \Bigr) \\
&\quad \leq 2 \Phi\Bigl(\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^\ell,
\end{aligned}
\end{equation}
where $\Phi$ denotes the cumulative distribution function of the standard normal distribution and $I_1 \coloneq [0, \delta]$, $I_j \coloneq ((j-1) \delta, j \delta]$, $j = 2, \ldots, \ell+1$.

