body:
[Definition defn:SFS-defn of arXiv:2609.00233, 'A survey on mapping class groups of 3-manifolds'] A \emph{Seifert fibration} on a compact, orientable $3$-manifold $M$ is a map $\pi \colon M \to B$, where  $B$ is a compact surface, possibly nonorientable, such that the following holds.
\begin{enumerate}
    \item For every $x$ in the interior of $B$
there is a $D^2$ neighbourhood of $x$ and a diffeomorphism $\pi^{-1}(D^2) \cong D^2 \times S^1$, with respect to which the restriction of $\pi$ to $\pi^{-1}(D^2)$ is given by
\begin{align*}
\pi \colon D^2 \times S^1 &\to D^2 \\
(rt_1,t_2) & \mapsto rt_1^at_2^b,
\end{align*}
where $t_i \in S^1$, $r \in [0,1]$, and $a,b \in \mathbb Z$ with $a \neq 0$ and $\gcd(a,b)=1$.
\item For every $x \in \partial B$, there is a half-disc neighbourhood $D^2_+$ of $x$ and a diffeomorphism $\pi^{-1}(D^2_+) \cong D^2_+ \times S^1$, with respect to which the restriction of $\pi$ to $\pi^{-1}(D^2)$ is given by
\begin{align*}
\pi \colon D^2_+ \times S^1 &\to D^2_+ \\
(rt_1,t_2) & \mapsto rt_1,
\end{align*}
where $t_i \in S^1$ and $r \in [0,1]$ such that $rt_1 \in D^2_+$.
\end{enumerate}

