[Lemma 3 (Permutation invariance and symmetrization) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] For every $1\le r\le\infty$ and $\pi\in\mathfrak S([m])$,
\begin{equation}

 \Prof_{m,r}(U_\pi K)=\Prof_{m,r}(K),
 \qquad
 \Prof_{m,r}(\operatorname{Sym}_mK)\le\Prof_{m,r}(K).
\end{equation}

[Defn Double divisor of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Suppose $\Omega$ is a simply connected domain $(\Omega \subsetneq \mathbb{C})$.

A double divisor $\left(\boldsymbol{\sigma^{+}}, \boldsymbol{\sigma^{-}}\right)$ is a pair of divisor in  $\overline{\Omega}$

 \begin{equation}
  \boldsymbol{\sigma}^{+}=\sum \sigma_j^{+} \cdot z_j, \boldsymbol{\sigma}^{-}=\sum \sigma_j^{-} \cdot z_j.
 \end{equation}

We introduce an equivalence relation for double divisors:

\begin{equation}
    \left(\boldsymbol{\sigma_{1}^{+}}, \boldsymbol{\sigma_{1}^{-}}\right) \sim \left(\boldsymbol{\sigma_{2}^{+}}, \boldsymbol{\sigma_{2}^{-}}\right)
\end{equation}
 if and only if
 \begin{equation}
    \boldsymbol{\sigma_{1}^{+}}+ \boldsymbol{\sigma_{1}^{-}} = \boldsymbol{\sigma_{2}^{+}}+ \boldsymbol{\sigma_{2}^{-}} \quad on \ \partial \Omega.
\end{equation}
Thus, we may choose a representative $\boldsymbol{\sigma}^{-}$ from each equivalence class  that is supported in $\Omega$, i.e., $\sigma_j^{-}=0$ if $z_j \in \partial \Omega$ .

[Definition 1 (Relaxed determinant benchmark) of arXiv:2604.10820, 'A Strict Gap Between Relaxed and Partition-Constrained\\ Spectral Compression in a Six-Sta'] For a positive self-adjoint operator $T$, define
\begin{equation*}
\mathfrak D^{\mathrm{rel}}_3(T):=\sup_{U^*U=I_3}\det(U^*TU).
\end{equation*}

[Conj 4 of arXiv:2506.15159, 'Conditional central limit theorems for exponential random graphs'] Let $H$ be a fixed 
 graph containing $t$ triangles and $s$ two stars. Under the same conditions as in \cref{thm:twostar}, with $F_n$ denoting the number of copies of $H$ in $G_n$, we have
\be{
\frac{F_n- \mu_F}{\sigma_F}\to N(0,1)\quad \text{in distribution},
}
where 
\begin{align}
    \mu_F&=\frac{(n)_{(v(H))} }{\operatorname{Aut}(H)}\t p^{e(H)}+ \left(\frac{(n-3)_{(v(H)-3)}}{\operatorname{Aut}(H)}\right)\big(2s\t p^{e(H)-2}\mu_{\t V}+6t\t p^{e(H)-3}\mu_{\t \triangle}\big),\\
\sigma_F^2&=\left(\frac{(n-3)_{(v(H)-3)}}{\operatorname{Aut}(H)}\right)^2\left(4s^2\t p^{2e(H)-4}\sigma^{2}_{V} +36t^2\t p^{2e(H)-6}\sigma^{2}_{\t \triangle }\right),
\end{align}
 $(n)_{(k)}=n(n-1)\cdots (n-k+1),$ $\operatorname{Aut}(K)$ denotes the number of automorphisms of $K$
to itself and and $\t \triangle :=\sum_{i<j<k}\t Y_{ik}\t Y_{jk}\t Y_{ij}$. The values of $\mu_{\t V}, \sigma_{V}, \mu_{\t\triangle}, \sigma_{\t \triangle}$ are in \cref{muv,sigmav,IET',sigmat}, respectively. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Definition 43 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] For a vertex set $A\subset V_n$ we define the minimal subtree of $\cT=\cT_{n,\beta}^\omega$ containing all vertices in $A$ as
	\begin{equation}  
		\cT_A \ := \bigcup_{u,v \in A} \gamma_{\cT}(u, v),
	\end{equation}
	where $\gamma_{\cT}(u, v)$ is the unique path in $\cT$ (regarded as a graph with its own vertex and edge set) connecting $u$ and $v$.

