[Definition 33 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Consider a family of functions $(R_s)_{s\geq 0}$, where each $R_s:[0,1]\to[0,1]$ is a function that satisfies
\begin{equation}
R_0(v)=v, \   R_s(v)\ge v,
\end{equation}
and the family has the property that $s\mapsto R_s(v)$ is non-decreasing and continuous for every $v \in [0,1]$. 

We say the family $(R_s)_{s\geq 0}$ satisfies an enlargement inequality for $(X,d,\mu)$ if
\begin{equation}

\mu(A_s)\ge R_s(\mu(A)).
\end{equation}
We call each $R_s$ an enlargement function. Moreover, we associate with $(R_s)_{s\geq 0}$ the function $\Theta: \R_+ \to [0,1/2]$ given by
\begin{equation}

\Theta(s):=\sup_{0\le v\le1}\sqrt{v\bigl(1-R_s(v)\bigr)}.
\end{equation}
Finally, the function $\Theta$ is non-increasing in $s$.

[Definition def:bivariate of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] If $(X_{n,L})_{n,L\geq 1}$ is a bi-indexed sequence of real-valued random variables, and $Y$ is a real-valued random variable on the same probability space, 

	we write
$	\lim_{L\rightarrow \infty}	\lim_{n\rightarrow \infty} X_{n,L}=Y,$
	if for any $\epsilon>0$ there exists $L_0=L_0(\epsilon)$ such that for any $L\geq L_0$,
\begin{align}
	\lim_{n\to\infty} \mathbb P(|X_{n,L}-Y|> \epsilon)=0.
\end{align}

[Definition 2 of arXiv:2607.17662, 'On the Strong Law of Large Numbers under Sublinear Expectations'] A set function $V : \mathcal{F} \to [0,1]$ is called a \textit{capacity} if it satisfies:
		\begin{enumerate}
			\item[(a)] $V(\emptyset) = 0$, $V(\Omega) = 1$.
			\item[(b)] $V(A) \leq V(B)$ for $A \subset B$, $A, B \in \mathcal{F}$.
		\end{enumerate}
		A capacity $V$ is called \textit{sub-additive} if $V(A \cup B) \leq V(A) + V(B)$ for all $A, B \in \mathcal{F}$.

[Theorem 27 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Assume that there exist constants $L > 0$ and $C_{LG} > 0$ such that the following conditions hold:
    \begin{enumerate}
        \item[(i)] (uniform Lipschitz condition) For all $(t,x) \in \ccC_T^d$ and $(t,y) \in\ccC_T^d$, we have
              \begin{equation}
                  \|b(t,x) - b(t,y)\|^2 + \|\sigma(t,x) - \sigma(t,y)\|^2 \leq L \sup_{0 \leq s \leq t}\|x(s)-y(s)\|^2.
              \end{equation}
        \item[(ii)] (linear growth condition) For all $(t,x) \in\ccC_T^d$, it holds that
              \begin{equation}
                  \|b(t,x)\|^2 + \|\sigma(t,x)\|^2 \leq C_{LG}\left(1 + \sup_{s \in [0,t]}\|x(s)\|^2 \right).
              \end{equation}
    \end{enumerate}
    Then the path-dependent SDE \eqref{path_dependent_sde_existence} admits a unique strong solution $X = (X(t))_{t \in [0,T]}$.
    Moreover, this solution satisfies the integrability condition $E\left[ \int_0^T \|X(t)\|^2 dt \right] < \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Local second-order estimate) of arXiv:2608.29736, '2608.29736'] For every compact subset \(K\Subset M\setminus Z\), there exists a
constant \(C_K>0\), independent of \(t\), such that
\begin{equation}
\omega<\eta_t\leq C_K\omega
\qquad\text{on }K.
\end{equation}

