body:
[Proposition prop:non-cros of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Suppose that $(\sigma,b)$ satisfy Assumption~(assu:H of the paper) and conditions~(item:1a of the paper)--(item:1d of the paper). Then, almost surely, for all $(a_1,r_1),(a_2,r_2)\in \mathbb D^2$ and all $y,z\in {\mathbb R}$,
    \begin{align*}
        \overline\mathcal S_{r_1,y}(a_1)<  \overline\mathcal S_{r_2,y}(a_2) \ \Longrightarrow \ \overline\mathcal S_{r_1,z}(a_1)\le \overline\mathcal S_{r_2,z}(a_2).
    \end{align*}

[Theorem 73 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose that $\beta$ and $\epsilon$ are, for some $s > 0$, as in Assumption \ref{as:betaeps_s}. Then there exists a constant $C_K = C_K(s) > 0$ such that, for $n$ large enough, we have with high $\widehat{\P}$-probability that



    \begin{equation}
        \frac{\epsilon^{-1}}{C_K \log n} {\diam}(\cT^\Ker_{p_1}) - o(n^{1/3}) \leq {\diam}(\cT)
    \end{equation}
    and
    \begin{equation}
        {\diam}(\cT) \leq 3 \epsilon^{-1} {\diam}(\cT^\Ker_{p_1}) \log n + o(n^{1/3}) +O( \epsilon^{-1} \log n).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_large_dev_up of arXiv:2604.14851, 'Pool model: a mass preserving multi particle aggregation process'] For all fixed $\lambda>0$ and any $\epsilon>0$, there is an event $E_{\epsilon}$ such that ${\bf P}(E_{\epsilon})=1$ and that for all $\omega\in E_{\epsilon}$ there is some $R_0(\omega)<\infty$ so that 
		 \begin{equation} 

		|A_0(\omega)\cap B(R)|<(\lambda+\epsilon) \pi R^2, \ \forall R\ge R_0(\omega).
		 \end{equation}

[Corollary cor:tail-rate of arXiv:2607.04620, 'The Exact Ville Identity\\ \large From the Absorbing Case to the General Law\\ with an App'] Let $S_n$ be a centered martingale with $\mathbb{E}[S_n^2]=n$, and let $T$ be a first-passage time with $L=\mathbb{E}[S_T\mathbf{1}(T<\infty)]$ finite as in (thm:conservation of the paper). Then, from the moment inequalities of [klass2026beyond], for every $p>1$,
\begin{equation}
  |L|^{p/(p-1)}
  \le
  \liminf_{n\to\infty}\mathbb{P}(T>n)
  \left(\mathbb{E}[|S_n|^p\mathbf{1}(T>n)]\right)^{1/(p-1)}.

\end{equation}
The case $p=2$, after dropping the indicator inside the moment, gives the cruder $\liminf_n n\mathbb{P}(T>n)\ge L^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 (Relative Palm determinant comparison) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Fix \(s<1\) and \(C_0<\infty\). There are \(c,C>0\) such that, uniformly for
\(|a|\le s\) and \(0\le r\le C_0n^{-1/2}(\log n)^{1/4}\),
\begin{equation}
 0\le\log\frac{q_n(a,r)}{q(\sqrt n\,r)}\le Ce^{-cn+nr^2}.
\end{equation}
In particular, \(q_n(a,r)/q(\sqrt n\,r)=1+O(e^{-c'n})\) uniformly in this range.
Also
\begin{equation}
 K_n(a,a)=\frac n\pi\bigl(1+O(e^{-c'n})\bigr).
\end{equation}

[Lemma 17 (Resolvent representation of hitting) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] For $x,y$ in $V$, let
\begin{equation*}
G_q(x,y)
  :=
  \int_0^\infty e^{-qt}P_t(x,y)\dd t.
\end{equation*}
Then, we find
\begin{equation}
  h_q(x,y)
  =
  \frac{G_q(x,y)}{G_q(y,y)}.
\end{equation}

[Lemma L: test function increasing of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Fix $T,A > 0$ and let $F : \mathbb{R} \times (0,T) \to [0,A)$ be an upper semicontinuous function that is nondecreasing in the spatial variable.  Fix $(x_{0},t_{0}) \in \mathbb{R} \times (0,+\infty)$ and let $\varphi$ be a smooth function defined in some neighborhood of $(x_{0},t_{0})$ such that $\varphi(x_{0},t_{0}) < A$ and $\partial_{x} \varphi(x_{0},t_{0}) > 0$.  If $\varphi$ touches $F$ from above at $(x_{0},t_{0})$, then there is an $r > 0$, a nondecreasing $C^{2}$ function $\psi_{1} : \mathbb{R} \to [0,1]$ with $\psi_{1}(x) = \psi_{1}(x_{0} - r)$ for each $x \leq x_{0} - r$ and $\psi_{1}(x) = A$ for each $x \geq x_{0} + r$, and a $C^{2}$ function $\psi_{2} : \mathbb{R} \to \mathbb{R}$ with $\psi_{2}(t_{0}) = 0$ such that if $\psi$ is the function
	\begin{align*}
		\psi(x,t) = \psi_{1}(x) + \psi_{2}(t),
	\end{align*}
then
	\begin{align*}
		F(x,t) \leq \psi(x,t) \quad \text{for each} \, \, (x,t) \in \mathbb{R} \times [t_{0}-r,t_{0}+r]
	\end{align*}
and equality holds if and only if $(x,t) = (x_{0},t_{0})$.  Further, for any $\delta > 0$, it is possible to construct $\psi$ in such a way that 
	\begin{gather*}
		\psi(x_{0},t_{0}) = \varphi(x_{0},t_{0}), \quad \partial_{x} \psi(x_{0},t_{0}) = \partial_{x} \varphi(x_{0},t_{0}), \quad \partial_{t} \varphi(x_{0},t_{0}) = \partial_{t} \varphi(x_{0},t_{0}), \\
		\left| \partial_{x}^{2} \psi(x_{0},t_{0}) - \partial_{x}^{2} \varphi(x_{0},t_{0}) \right| \leq \delta.
	\end{gather*}

