body:
[Cor spec-frag-pos-recurrent of arXiv:2511.10223, 'Stochastic Reaction Networks Within Interacting Compartments with Content-Dependent Fragme'] Let $N$ be the coarse-grained model associated to (equation eq:specific-content-dependent-fragmentation of the paper):
\begin{equation*}
\begin{tikzcd}
    0\arrow[yshift=.5ex]{r}{\kappa_b}& S\arrow[yshift=-.5ex]{l}{\kappa_d} & &
    0\arrow[yshift=.5ex]{r}{\kappa_I}& C\arrow[yshift=-.5ex]{l}{\kappa_E} \arrow[yshift=.5ex]{r}{\kappa_FS_C}& 2C\arrow[yshift=-.5ex]{l}{\kappa_C} & &
    \mu.
\end{tikzcd}
\end{equation*}
Assume that condition~(con:lambda finite of the paper) holds, i.e., $\lambda<\infty$. If both $\kappa_C>0$ and $\kappa_E>0$, then the state $(0,0,0,\dots)$ with no compartments is positive recurrent. Moreover,
\begin{itemize}
    \item If $\kappa_I>0$ and either $\kappa_b>0$ or $\mu\ne\delta_0$, then all states are reachable from $(0,0,0,\dots)$ and hence positive recurrent.
    \item If $\kappa_I>0$ and both $\kappa_b=0$ and $\mu=\delta_0$, then all states with zero $S$ are positive recurrent and all other states are transient. These other states all have finite expected time to be absorbed by the collection of zero-$S$ states.
    \item If $\kappa_I=0$, then all states with a positive number of compartments are transient, but are absorbed by the state with zero compartments in finite expected time.
\end{itemize}

[Theorem 6 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] \sloppy Assume that the function $g$, defined in \eqref{g_defn}, is in $\mathcal{C}^{(1)}[0,1]$ and monotonically increasing throughout $[0,1]$, with $g(0)>0$ and $g(1)<1$, and that the function $\hat{G}:[0,1]\rightarrow\mathbb{R}$, defined as
\begin{align}_defn}
\hat{G}(q)=q(1-q)\{2g(q)-1\}+\alpha\{g(q)-q\} \text{ for all }q\in[0,1],
\end{align}
with $\alpha$ as in \eqref{beta_{n}_s_{n}_defns}, has a unique root, say $q^{*}$, in $[0,1]$. In addition to the constraints described in \eqref{k_{n}_sequence_conditions} on $\eta_{1}$ and $\eta_{2}$, we assume that $\eta_{2}\leqslant 1$, and letting $\upsilon=\sup\{g'(q):q\in[0,1]\}$, we assume that $0<\upsilon\leqslant\min\{2,(1+\sqrt{5})(1-\eta_{1})^{-1}\eta_{1}\}$. Then, for the model in \S\ref{subsec:model_growing_sample_size}, the sequence $\{(n^{-1}A_{n},s_{n}^{-1}B_{n},s_{n}^{-1}C_{n})\}$ converges almost surely to a compact, connected, internally chain transitive invariant set, corresponding to the differential inclusion $(\dot{a}(t),\dot{b}(t),\dot{c}(t))\in F(a(t),b(t),c(t))$ for $t\geqslant 0$ (with $F$ as defined in \eqref{set_valued_function}), contained in the set
\begin{equation}
\hat{\Lambda}=\left\{(a,b,c)\in\hat{\mathcal{S}}:q_{\alpha}(a,b,c)=q^{*},a=g(q^{*})\right\}._defn}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma singularvalueproduct of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Fix some constants $\sigma>0,c>0,C>0$ and $\tau\in(0,1].$ Let $M_1,M_2$ be two $n\times n$ random matrices (not necessarily independent) that satisfy, for any $\delta_1,\delta_2>0$,
\begin{equation}
    \mathbb{P}(\sigma_{min}(M_1)\leq\delta_1 n^{-1/2}, \sigma_{min}(M_2)\leq\delta_2 n^{-1/2})\leq C(\delta_1\delta_2)^\tau+e^{-cn^\sigma},
\end{equation}
and for any $k\in\{1,2\}$ it satisfies 
\begin{equation}
    \mathbb{P}(\sigma_{min}(M_{k})\leq\delta_{k} n^{-1/2})\leq C(\delta_{k})^\tau+e^{-cn^\sigma}.
\end{equation}
Then for any $\delta>0$, we have
$$
\mathbb{P}\left(\sqrt{\sigma_{min}(M_1) \sigma_{min}(M_2)}\leq \delta n^{-1/2}\right)\leq C_0C(\delta^\tau\log(\delta^{-1}))^2+e^{-cn^\sigma},
$$where $C_0>0$ is a universal constant.

