[Proposition YASHAsd of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Let \( \mathcal{A} \) be a \( \mathrm{P} \)-weak point attractor. Then
	\begin{align}
		\mu_{\omega^-}\big({\mathcal{A}}(\omega^-)\big) = 1  \quad \mathbf{P}\text{-a.s.},
	\end{align}
	which in particular implies that
	\begin{align}
		\mathrm{supp}(\mu_{\omega^-})\subseteq {\mathcal{A}}(\omega^-)  \quad \mathbf{P}\text{-a.s.}
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor_uniform_random_cond of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $\nu>0$, $R> 0$, $M\ge 1$ and $\{\theta_k^n\}_{m\in I}$ time independent satisfying (hyp_noise of the paper). Assume $p \in (4, \infty)$, $-1/2 < r<- 2/p$. Let $\omega^{n,\omega_0}$ be the solution of (equation main_ito_cutoff of the paper) associated to $\{\theta_k^n\}_{k\in I}$ defined as in (hyp_noise of the paper) and some $\mathcal{F}_0$ measurable initial datum $\omega_0\in \mathcal{B}_p(M)\ \mathbb{P}-a.s.$ Let $\omega^{R,{\operatorname{det}},\omega_0}$ be the solution of (equation main_det_cutoff of the paper)
with the same \emph{random} initial datum $\omega_0$. Then for all $r_0 < -2/p$ and $\varepsilon >0$ we have 
    \begin{equation*}
        \lim_{n\rightarrow\infty}\sup_{\omega_0\in L^0_{\mathcal{F}_0}\left(\Omega;\mathcal{B}_p(M)\right)}\mathbb{P}\left( \sup_{t\in [0, T]}\|\omega^{n,\omega_0}_t - \omega^{R,{\operatorname{det}},\omega_0}_{t}\|_{H^{r_0}_g} > \varepsilon \right) =0.
    \end{equation*}

