[Theorem 7 (Fast regret of online MYULA) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under the same assumptions of \cref{thm:linear-statistical}, the approximate posterior computed by \cref{alg:proximal} satisfies
    \begin{equation}
    \E \sbr{\W^2(Q_t,\Pi_t)} \lesssim t^{-1},
    \end{equation}
and thus
    \begin{equation}
    \fR\del[1]{(Q_t)_{t=0}^{T-1}}\lesssim \log T+1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\{\tau_n\}_{n \ge 1}$ and $\{\sigma_n\}_{n \ge 1}$ denote the sequence of inter-arrival times for the collection $\DD$, that satisfy (\textbf{A1}) and (\textbf{A2}). Then, as $n \to \infty,$
\begin{equation}

\frac{|D^c_{\mu_n}|}{n}
\longrightarrow \E\left[\tau \right] \text{ a.s.}, 
\end{equation}
\begin{equation}

 \frac{|D_{\mu_n}|}{n}\longrightarrow \E\left[\sigma \right] \text{ a.s.}
\end{equation}

[Theorem thm:main_mmpp_cm of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Consider an MMPP with monotone, irreducible generator matrix $T$ and increasing vector of arrival rates $\alpha$. If $k\geq3$, then the model is DCM if and only if, for all triples $\ell<i<j$, 
	\begin{equation}
		(\alpha_j-\alpha_i) \sum_{s\leq\ell}v^*_s  \leq \sum_{s\leq\ell}(T_{is}-T_{js}).
	\end{equation}
	All MMPPs with $k=2$ are DCM. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LEM:chan of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $F$ be a bounded, continuous function on $L^2$. Then, we have
\begin{align}
&\int_{ \{ \textup{dist}(\phi, \mathcal{M}_k^{\varepsilon, \ge d} ) < \delta    \} }F(\phi) \mu_{\varepsilon}^k(d\phi) \notag \\
&=\int \dots \int \limits_{ U_\varepsilon } F( m_{\xi_1,\dots,\xi_k}^\varepsilon+v   )e^{-\frac 12 \| \partial_x m^\varepsilon_{\xi_1,\dots,\xi_k}  \|_{L^2 }^2  -\jb{ (-\partial_x^2) m^\varepsilon_{\xi_1,\dots, \xi_k}, v }_{L^2} } \notag  \\
&\hphantom{XXXXXX} \cdot 
\textup{Det}_{\xi_1,\dots,\xi_k}(v) \, \mu^{\perp}_{\varepsilon, \xi_1,\dots,\xi_k}(dv) \, d\sigma(\xi_1,\dots,\xi_k),

\end{align}

\noindent
where $\mathcal{M}^{ \varepsilon, \ge d}_k$ is as defined in (equation MAN1 of the paper), $\Delta_k=\{ -\overline L_\varepsilon \le \xi_1 \le \cdots \le \xi_k \le \overline L_\varepsilon  \}$,
\begin{align}
&U_\varepsilon=\big\{ ( \xi_1,\dots, \xi_k, v )\in  \Delta_k \times V_{\xi_1,\dots,\xi_k}: \|v \|_{L^2 }< \delta \; \textup{and} \; \min_{i \neq j}|\xi_i-\xi_j| \ge d   \big\} \notag \\
&\textup{Det}_{\xi_1,\dots,\xi_k}(v):=\det\big( \Id-W_{\xi_1,\dots \xi_k, v }\big),

\end{align}

\noindent
and $\mu^{\perp}_{\varepsilon, \xi_1,\dots,\xi_k }$ is the Gaussian measure on the normal space $V_{\xi_1,\dots,\xi_k}$ with covariance $\varepsilon(-\partial_x^2)^{-1}$, subject to Dirichlet boundary conditions on $[-L_\varepsilon, L_\varepsilon]$
\begin{align*}
\mu^{\perp}_{\varepsilon, \xi_1,\dots,\xi_k }(dv)=Z_{\varepsilon,\xi_1,\dots,\xi_k}^{-1} e^{-\frac 1{2\varepsilon} \int_{-L_\varepsilon}^{L_\varepsilon} |\partial_x v|^2 dx  }\prod_{x \in [-L_\varepsilon, L_\varepsilon ]} dv(x). 
\end{align*}

\noindent
In (equation wein1 of the paper) $W_{\xi_1, \dots, \xi_k, v}$ denotes the Weingarten map, defined in (equation Wein of the paper). In addition,  $d\sigma$ is the surface measure on the manifold, parametrized by $(\xi_1,\dots, \xi_k)\in  [- \overline L_\varepsilon, \overline L_\varepsilon]^k$, as defined in (equation surfm of the paper).

[Corollary 9 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] For $H=K$, we have $\Pp$-a.s.~for all $t\in(0,1]$,
\begin{align*}
V_n^{(q)}(Y,t)\longrightarrow\begin{cases}+\infty&\text{for $q\le 1/H$,}\\
0&\text{for $q>1/H$.}
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop R2 of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Assume that (equation hyp1 of the paper) holds true. Then for each $\lambda\in {\mathscr{F}}(U)$ the stochastic integral $\int_{0}^{t}\Pi_{\lambda}{\rm d} W^{Q}(s)$ is well defined as an ${\mathscr{F}}(U)$--valued process, and
\begin{align}
  {\mathbb E}\norma{\int_{0}^{t}\Pi_{\lambda} {\rm d} W^{Q}(s)}_{{\rm BL}}^{2}<+\infty.  
\end{align}
Furthermore, the process $\int_{0}^{t}\Pi_{\lambda} {\rm d} W_{s}^{Q}$ has a.s. continuous sample paths.

