[Theorem 1 of arXiv:2511.09726, 'The non-covered set in Dvoretzky covering is a set of multiplicity'] Suppose that the sequence $(\ell_n)$ satisfies the assumptions \eqref{A}, \eqref{B} and there exists an integer $d\geq1$ such that 
\begin{equation}
    \int_{\mathbb{T}^d}K(t_1)\cdots K(t_d) K(-\sum_{i=1}^dt_i)\mathrm{d}t_1\cdots \mathrm{d}t_d<\infty.

\end{equation}
 Then the d-th convolution $\ast^d\mu_{D}$ of $\mu_D$ is a.s. absolutely continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Propo 15 of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] For $k\geq 2$, $r\in [d]$,  $n\in\{1,\ldots, k-1\}$, and $t_0:=0<t_1<\cdots < t_n<T$, we have
\begin{equation}
	\begin{split}
		\Q^{(k),\bm \theta }_{T,r}&\Big(\Delta_T(n)\Big) = \prod_{h=1}^n\prod_{m=1}^d\E_{m}\left[e^{-\bm \theta \cdot \bo Z_{T-t_h}}\right]^{\ell_{h,m} -g_{h,m}}p_{i_h}(\bm \ell_{h})\bm \ell_{h}^{\floor{\bo g_h}}\\
		&\hspace{.5cm}  \times 
		\prod_{h=0}^{n-1}\prod_{m=1}^d\prod_{\substack{ q\leq g_{h,m}:\\ k_{v(h,m,q)}\geq 2}}\E_{m}\left[Z^{(c(v(h,m,q)))}_{t_{v(h,m,q)}-t_h} \prod_{j=1}^d\E_{j}\left[e^{-\bm \theta\cdot \bo Z_{T-t_{v(h,m,q)}}}\right]^{ Z^{(j)}_{t_{v(h,m,q)}-t_h}-\delta_{c(v(h,m,q)),j}}\right]\\
	& \hspace{3cm} \times
	\frac{\prod_{h=1}^{n}\prod_{m=1}^{d}\E_{m}\left[N_{T-t_{h}}e^{-\bm \theta \cdot \bo Z_{T-t_{h}}}\right]
		^{\#\{ q\leq g_{h,m}:k_{v(h,m,q)}=1\}}
	}{\E_{r}\left[N_{T}^{\floor{k}}e^{-\bm \theta\cdot \bo Z_{T}}\right]} \prod_{h=1}^n\alpha_{i_{h}} {\rm d}t_h,
\end{split}
\end{equation}where  $t_{v(h,m,q)}$ and $c(v(h,m,q))$ are the spine splitting times  and type associated to the vertex $v(h,m,q)$.  When  $h=0$, we observe that $v(0)=\emptyset$, $g_{0,m}=\delta_{r,m}$ and $v(0, r, 1)=v(1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

