body:
[Proposition prop:spectralspeedup of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $P \in \mathcal{L}(\pi)$ and $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix. Fix $\alpha \in (0,1)$ and recall that $\overline{P}_{\alpha}(Q)$ is introduced in (equation eq:PbaralphaQ of the paper). Let $n := |\mathcal{X}|$. We have 
	\begin{itemize}
		\item $\lambda_2(\overline{P}_{\alpha}(Q)) \leq \lambda_2(P)$, where the equality holds if and only if there exists a common eigenvector $f$ such that $\overline{P}_{\alpha}(Q)f = \lambda_2(\overline{P}_{\alpha}(Q))f$, $Pf = \lambda_2(P) f$ and $QPQf = \lambda_2(QPQ) f$.

		\item $\lambda_n(P) \leq \lambda_n(\overline{P}_{\alpha}(Q))$, where the equality holds if and only if there exists a common eigenvector $g$ such that $\overline{P}_{\alpha}(Q)g = \lambda_n(\overline{P}_{\alpha}(Q))g$, $Pg = \lambda_n(P) g$ and $QPQg = \lambda_n(QPQ) g$.
	\end{itemize}
	Consequently, this leads to
	\begin{align*}
		\mathrm{SLEM}(\overline{P}_\alpha(Q)) \leq \mathrm{SLEM}(P).
	\end{align*}
	If $P$ (and hence $QPQ$) is further assumed to be positive-semi-definite, then
	\begin{align*}
		\max\{\alpha,1-\alpha\} \lambda_2(P) &\leq \lambda_2(\overline{P}_{\alpha}(Q)) \leq \lambda_2(P), \\
		\max\{\alpha,1-\alpha\} \mathrm{SLEM}(P) &\leq \mathrm{SLEM}(\overline{P}_\alpha(Q)) \leq \mathrm{SLEM}(P).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] Consider large $n,m\in\mN$ such that $\lim_{n\rightarrow\infty}\frac{m}{n}\rightarrow\alpha\geq 1$ and let $A_{ij}\sim \cN(0,1)$ be the independent elements of $A\in\mR^{m\times n}$. For a real scalar $c_3\geq 0$ set
  \begin{eqnarray}

 \hat{\gamma}_{1} & = &  \frac{c_3 + \sqrt{c_3^2+4\alpha}}{4}
 \nonumber \\
 \phi_{1}(\gamma_1) & = &  \gamma_{1}c_3 - \frac{\alpha}{2}\log \lp 1 - \frac{c_3}{2 \gamma_{1}}   \rp
 \nonumber \\
 \hat{\gamma}_{2} & = &  \frac{c_3 + \sqrt{c_3^2+4}}{4}
 \nonumber \\
 \phi_{2}(\gamma_2) & = &  \gamma_{2}c_3 - \frac{1}{2}\log \lp 1 - \frac{c_3}{2 \gamma_{2}}   \rp.
 \end{eqnarray}
 Let $\xi^+_{sph}$ be as in (\ref{eq:inteq1ab0}) and for a real scalar $u\geq \mE \xi^+_{sph}$ set
 \begin{eqnarray}

 \nonumber \\
 \phi_u(u) & = & -\frac{c_3^2}{2} + \phi_{1}(\hat{\gamma}_1) + \phi_{2}(\hat{\gamma}_2) -c_3 u .
 \end{eqnarray}
One then has the following LDP with the indicator rate function $\zeta_u(u)$
\begin{eqnarray}

\lim_{n\rightarrow \infty} \frac{\log\lp \mP\lp \xi^+_{sph} \geq u  \rp \rp}{n} \leq \min_{c_3\geq 0}\phi_u(u) \triangleq -\zeta_u(u).
\end{eqnarray}

