[Proposition prop:eta-conditional-factorization of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] For every fixed \(n\ge1\) and \(T>0\),  there exists $C_{\eta,T,n}>0$ so that
\begin{equation}
\begin{aligned}
  \sup_{0\le t\le T}
  \mathbb E_{\mathbb Q^{N,\eta}}
  \left[
    \left\|
      \Theta_t^{N,n}-\overline\Gamma_t^{N,n}
    \right\|_1
  \right]\le
  \left[
    \frac{2\eta N \Lambda_L}{(1-\eta)r_N}
    \int_0^T
    \mathbb E_{\mathbb Q^{N,\mathrm{full}}}
    \left[
      \left\|
        R_s^{N:(1)}-X_s^1
      \right\|_1
    \right]\mathrm d s
  \right]^{1/2}
\le
  C_{\eta,T,n}N^{-1/8}.
\end{aligned}

\end{equation}

[Definition eq:psi1 of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:subexp}
A real random variable \(\xi\) is \(K\)-subexponential if
\begin{equation}
 \mathbb E\exp(\left\lvert\xi\right\rvert/K)\le2.
\end{equation}
It is \(K\)-sub-Gaussian if \(\mathbb E\exp(\xi^2/K^2)\le2\).  Sub-Gaussianity implies subexponentiality after changing \(K\).

[Lemma 9 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Set $\bm{\sigma}_1,\bm{\sigma}_2\in\C^2$. Assume $\left(\mathbf{W}_t^{H}\right)_{t\geq 0}\subset \C^2$ to be an fBm with Hurst index $H\in\left(0,1\right)$. Let $\left(\psi_t^{(1)}\right)_{t\geq 0}$ and $\left(\psi_t^{(2)}\right)_{t\geq 0}$ be scalar solutions to the system
\begin{align}
    \begin{split}
        \txtd \psi_t^{(1)} = \alpha\psi_t^{(1)}~\txtd t + \left\langle \txtd \mathbf{W}_t^{H} , \bm{\sigma}_1 \right\rangle,\\
        \txtd \psi_t^{(2)} = \beta \psi_t^{(2)}~\txtd t + \left\langle \txtd \mathbf{W}_t^{H} , \bm{\sigma}_2 \right\rangle,
    \end{split}
\end{align}
each initial conditions at $t=0$ in $\C$. Lastly, consider $\alpha,\beta\in\C$ with negative real part. Then, for all $\tau\ge0$, we obtain that
\begin{align}
    &\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(2)} \right)
    = H \underbrace{\left\langle \bm{\sigma}_2, \bm{\sigma}_1 \right\rangle}_{\text{masking}} \underbrace{P(\alpha,\beta,H,\tau)}_{\text{memory}} \underbrace{\left( -\alpha - \overline{\beta} \right)^{-1}}_{\text{mitigation}},
\end{align}
with $P$ introduced in \eqref{eq:function_P}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:finite-vol of arXiv:2604.13968, 'Divisible sandpiles via random walks in random scenery'] Let $K\subseteq V$ be finite, connected, and proper, with $o\in K$. Then $v_K(x)<\infty$ for every $x\in V$. Let $D_K\coloneqq\{x\in K:v_K(x)>0\}$ and let $D_K(o)$ denote the connected component of~$o$ in~$D_K$ (with $D_K(o)\coloneqq\varnothing$ if $o\notin D_K$). If $o\notin D_K$, then $v_K(o)=0$. If $o\in D_K$, then
		\begin{equation}
			v_K(o)=\mathbb{E}_o\bigl[S_{\tau_{D_K(o)}}\bigr]\,.
		\end{equation}
		In particular,
		\begin{equation}
			v_K(o)=\max\biggl\{0,\;\sup_{\substack{C\subseteq K,\; C\textup{ connected}\\ o\in C}}\sum_{v\in C}g_C(v)\bigl(\sigma(v)-1\bigr)\biggr\}\,.
		\end{equation}

