[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ X(\cdot) $ be an $ \mathcal{X} $-valued stochastic process.
    \begin{enumerate}[(i)]
        \item  We say that $ X(\cdot) $ is measurable if the map $ (t , \omega) \mapsto X(t, \omega) $ is strongly $ (\mathcal{B}([0,T] )\times  \mathcal{F}) / \mathcal{B}(\mathcal{X}) $-measurable; 
        \item We say that $ X(\cdot) $ is $ \mathbf{F} $-adapted if it its measurable and for each $ t \in [0,T] $, the map $ \omega \mapsto X(t, \omega) $ is strongly $ \mathcal{F}_{t}/ \mathcal{B}(\mathcal{X}) $-measurable;
        \item We say that $ X(\cdot) $ is $ \mathbf{F} $-progressively measurable if for each $ t \in [0,T] $, the map $ (s, \omega) \mapsto X(s, \omega) $ from $ [0, t] \times \Omega $ is strongly $ ( \mathcal{B}([0,t]) \times \mathcal{F}_{t})/ \mathcal{B}(\mathcal{X}) $ -measurable.
    \end{enumerate}

