\begin{align*}
h(x_1,\dots,x_r) \,:=\, \int_{\AA^r} f_K\big((x_1,a_1),\dots,(x_r,a_r)\big) \; \Theta^r (\d {(a_1,\dots,a_r)}).
\end{align*}
We show that the estimate
\begin{align} 
\int_{\left(\R^d\right)^{r-1}} h(\mathbf{0},x_2,\dots,x_{r}) \; \d {(x_2,\dots,x_r)} \,\leq\, \rho^{r-1} \,<\, \infty
