[Theorem 9 (Averaging and Fluctuations of the Effective Model) of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] Assume $\psi_0\in L^2$ and the validity of \cref{hp:noise}. Let $\Psi^{\tau}$ be the unique solution of \eqref{eq:simplified_model} given by \autoref{prop:well_effective} and let  $\Xi^{\tau}=\frac{\Psi^\tau-\bar{\psi}}{\sqrt{\tau}}$. Then for each $\theta_1\in [-2,0),\theta_2\in [-3,-\frac{5}{3})$ and $q\geq 1$
 \begin{align}
     \mathbb{E}\left[\sup_{t\in [0,T]}\|\Psi_t^{\tau}-\bar{\psi}_t\|_{H^{\theta_1}}^q\right]&\lesssim \tau^{-\frac{q\theta_1}{4}},\\
     \mathbb{E}\left[\sup_{t\in [0,T]}\|\Xi_t^{\tau}-\xi_t\|_{H^{\theta_2}}^q\right]&\lesssim \begin{cases}\tau^{-\frac{q(3\theta_2+5)}{4}}\quad &\text{if }\theta_2\in [-2,-\frac{5}{3}),\\
        \tau^{-\frac{q(\theta_2+1)}{4}}\quad &\text{if }\theta_2\in [-3,-2].
     \end{cases}
 \end{align}
 Above we denote by $\bar{\psi}$ the unique weak solution of \eqref{eq:averaging} given by \cref{prop:well_posed_averaging_limit} and by $\xi$ the unique weak solution of \eqref{eq:gaussianlimit} given by \cref{prop:well_posed_fluctuations}, driven by the same Brownian motions as $\Psi^\tau$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] For every fixed $k\ge 0$ and $\vv \zeta=( \zeta_0,\dots,\zeta_k)$,
\begin{equation}
\lim_{m\to\infty}
\tfrac{
\EE\left[
\left(
R_m(\vv\tau)
+\frac{R_k(\vv\zeta)P_m(\vv\tau)}
       {P_{k+1}(\vv\zeta)}
\right)^{-\alpha}
\prod_{j=1}^k
R_j^{\,2t_{j+1}-2t_j}(\vv\zeta)
\right]
}
{\EE\left[R_m^{-\alpha}(\vv\tau)\right]}
=
\EE\!\left[
\prod_{j=1}^k
R_j^{\,2t_{j+1}-2t_j}(\vv\zeta)
\right].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Structure of the scaled NP operator) of arXiv:2608.30991, 'A block-Toeplitz approach to the spectrum of the Neumann-Poincaré operator on self-similar'] The scaled Neumann-Poincaré operator $\widetilde{\mathbb{K}}^*_\alpha$ admits the explicit block-Toeplitz representation:
	\begin{equation*}
		\widetilde{\mathbb{K}}^*_\alpha = \begin{pmatrix} \tilde{K}^*_0 & r^{-\alpha} \tilde{K}^*_{-1} & r^{-2\alpha} \tilde{K}^*_{-2} & \cdots \\ r^\alpha \tilde{K}^*_1 & \tilde{K}^*_0 & r^{-\alpha} \tilde{K}^*_{-1} & \cdots \\ r^{2\alpha} \tilde{K}^*_2 & r^\alpha \tilde{K}^*_1 & \tilde{K}^*_0 & \cdots \\ \vdots & \vdots & \vdots & \ddots \end{pmatrix}. 
	\end{equation*}
	The blocks are defined by $(\widetilde{\mathbb{K}}^*_\alpha)_{j,k} = r^{(j-k)\alpha} \tilde{K}^*_{j-k}$ for $j, k \ge 0$. The reference operator $\tilde{K}^*_m : W_0^{s,p}(\Gamma_0) \to W_0^{s,p}(\Gamma_0)$ is given by:
	\begin{equation*}
		(\tilde{K}^*_m \psi)(\tilde{x}) = P_{0,0} \left( \mathrm{} \int_{\Gamma_0} \frac{\partial G}{\partial \nu_{\tilde{x}}}(\eta_m(\tilde{x}), \tilde{y}) \psi(\tilde{y}) \, d\sigma_0(\tilde{y}) \right).
	\end{equation*}

[Lemma claim:S over 64v of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] There exists a  constant $C>0$ such that for any $n\geq 1$, and $t \leq n/16$,
        \begin{equation}\begin{aligned}
        \mathbb{P}\Big(\Big|\Big\{u \in [n] &: \phi_n^{\scriptscriptstyle{({2}})}(u) > \Big( \frac{n}{64t}\Big)^2 \Big\}\Big|\le t\Big)\\ &\le
            \mathbb{P}\left(\Big|\left\{u \in [n] : \phi_n(u) >  \frac{n}{64t} \right\}\Big|\le t\right) \leq C \exp \Big( -  \frac{t}{8} \Big) .\end{aligned}
        \end{equation}

