body:
[Lemma lem:fourier_identities of arXiv:2607.14266, 'The Swapping Mechanism for Interacting Diffusions: Framework, Comparison with Switching, a'] For $B\in\mathbb{R}$ and $s,t>0$, the following distributional identities
			hold:
			\begin{align}
				\int_{-\infty}^{\infty} e^{i\psi B}
				\cosh\!\bigl(st\sqrt{\psi^{2}+1}\bigr)\mathrm{d}\psi
				&= \frac{st\pi}{2}\int_{0}^{1}
				\frac{I_1(st\sqrt{1-z})}{\sqrt{z(1-z)}}
				\bigl[\delta(B-ist\sqrt{z})
				+\delta(B+ist\sqrt{z})\bigr]\mathrm{d} z
				\notag\\
				&\quad+\pi\bigl[\delta(B-ist)+\delta(B+ist)\bigr],
				\\[4pt]
				\int_{-\infty}^{\infty} e^{i\psi B}
				\frac{\psi\sinh(st\sqrt{\psi^{2}+1})}
				{\sqrt{\psi^{2}+1}}\mathrm{d}\psi
				&= \frac{st\pi}{2}\int_{0}^{1}
				\frac{I_1(st\sqrt{1-z})}{\sqrt{1-z}}
				\bigl[\delta(B-ist\sqrt{z})
				-\delta(B+ist\sqrt{z})\bigr]\mathrm{d} z
				\notag\\
				&\quad+\pi\bigl[\delta(B-ist)-\delta(B+ist)\bigr],
				\\[4pt]
				\int_{-\infty}^{\infty} e^{i\psi B}
				\frac{\sinh(st\sqrt{\psi^{2}+1})}
				{\sqrt{\psi^{2}+1}}\mathrm{d}\psi
				&= \frac{st\pi}{2}\int_{0}^{1}
				\frac{I_0(st\sqrt{1-z})}{\sqrt{z}}
				\bigl[\delta(B-ist\sqrt{z})
				+\delta(B+ist\sqrt{z})\bigr]\mathrm{d} z.

			\end{align}
			The Bessel summation identities used below are
			\begin{align}
				\sum_{k=\ell}^{\infty}\binom{k}{\ell}\frac{A^{2k}}{(2k)!}
				&= \frac{\sqrt{\pi}\,(A/2)^{\ell+1/2}\,I_{\ell-1/2}(A)}{\ell!},
				\\
				\sum_{k=\ell}^{\infty}\binom{k}{\ell}\frac{(st)^{2k+1}}{(2k+1)!}
				&= \frac{(2st)^{\ell+1/2}\sqrt{\pi}\,I_{\ell+1/2}(st)}
				{2^{2\ell+1}\,\ell!},

			\end{align}
			both following from $I_\nu(A)=\sum_{m=0}^\infty(A/2)^{2m+\nu}/
			[m!\,\Gamma(m+\nu+1)]$ by reindexing.

