body:
[Lemma 21 (Scalability of random matrices) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $(\r,\c)$ be an $m\times n$ $\delta$-smooth margin and let $\X$ be an $m\times n$ nonnegative random matrix with independent entries. Denoting $p_{0}=\max_{i,j} \P(\X_{ij}=0)$,
	\begin{align}
		\P(\X\notin \mathcal{S}(\r,\c)) \le 2^{m+n-2}\, p_0^{\delta^3(m \wedge n)/2}.
	\end{align}
	In particular, suppose there exist constants $\gamma\in(0,1]$ and $\eta>0$ such that $\tfrac{m\land n}{m\lor n} \ge \gamma$ and
	\begin{align}
		p_0 \le \exp\!\left( -\frac{2\log 2}{\delta^3}\,(1 + \gamma^{-1}) - \eta \right).
	\end{align}
	Then
	\begin{align}
		\P(\X\notin \mathcal{S}(\r,\c)) \le \frac{1}{4} \exp\!\left( -\frac{\eta \delta^3}{2}\,(m \wedge n) \right).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:fin-add-coherent-risk of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\Omega,\mathcal{Z})$ be an upward-scalable gamble space with $0\in\mathcal{Z}$ and $\mathrm{dcl}(\mathcal{Z})$ convex.
  Then
  \begin{equation}

    \overline{\textsf{\textbf{E}}} X
    =
    \sup_{Q\in\Delta_{0,f}(\mathcal{Z})} \mathbb{E}_Q X~,
  \end{equation}
  for all $X\in\mathcal{X}_b$. (Proof in the paper; no proof environment follows the statement in the TeX.)

