[Definition 8 of arXiv:2604.25769, 'The conformal dimension of the Brownian tree is one'] Let $x \in \SCT$ and $n \in \BN$. Then we shall write 
    \begin{itemize}
        \item $\varrho(x, n) \defeq \eta + 2\sup\{\sigma(y, n) : y \in \SCT \text{ with } d_\SCT(x, y) \le 26\alpha^n\}$ (cf.~\Cref{lem:core});
        \item $\varsigma(x, n) \defeq \eta + 64\alpha \cdot \mathbf 1_{\widetilde E(x, n)}$; 
        \item $\varpi(x, n) \defeq \prod_{j = 1}^n \varsigma(x, j)$. 
    \end{itemize}

[Corollary 16 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Let $u\in \mathcal{K}(Q;\mathcal{C}^{\infty }(\Omega ;A))$. Then, as $\varepsilon \rightarrow 0$,

		\begin{itemize}
			\item[(i)] $u^{\varepsilon }\rightarrow \varrho (u)$  in $
			L^{\Phi}(Q\times \Omega )$-weak $\digamma\,\Sigma $, where $\varrho $ denote the
			canonical mapping of $\mathfrak{X}^{\Phi}_{A}$ into $\mathcal{X}^{\Phi}_{A}$, and the
			function $\varrho (u)$ is defined by $\varrho (u)\equiv \varrho
			(u(x,\omega,\cdot ))$ for a.e. $(x,\omega )\in Q\times \Omega $;

			\item[(ii)] $\left\| u^{\varepsilon }\right\| _{L^{\Phi}(Q\times \Omega
				)}\rightarrow \left\| \varrho (u)\right\| _{L^{\Phi}(Q\times \Omega ; \mathcal{X}^{\Phi}_{A})}$.
		\end{itemize}

