[Theorem 17 (Endpoint trichotomy and symmetry) of arXiv:2601.16580, 'Coin flipping and waiting times paradoxes \\ Why fair coins are exceptional'] Let $T_1,T_2$ be fixed and consider independent Bernoulli$(p)$ streams with random tie‑break.
As $p\downarrow 0$:
\[
\begin{aligned}
\text{\emph{(A)}}\;\;&h(T_1)<h(T_2) \;\Longrightarrow\;
W^{\mathrm{rtb}}(T_1\!>\!T_2;p)\to 1,\\[2pt]
\text{\emph{(B)}}\;\;&h(T_1)>h(T_2) \;\Longrightarrow\;
W^{\mathrm{rtb}}(T_1\!>\!T_2;p)\to 0,\\[2pt]
\text{\emph{(C)}}\;\;&h(T_1)=h(T_2)\ge 1 \;\Longrightarrow\;
W^{\mathrm{rtb}}(T_1\!>\!T_2;p)\to \tfrac12,\\[2pt]
\text{\emph{(D)}}\;\;&h(T_1)=h(T_2)=0 \;\Longrightarrow\;
W^{\mathrm{rtb}}(T_1\!>\!T_2;p)\to \mathbf{1}_{\{|T_1|<|T_2|\}}+\tfrac12\,\mathbf{1}_{\{|T_1|=|T_2|\}}.
\end{aligned}
\]
By complement symmetry ($\mathrm{H}\leftrightarrow \mathrm{T}$), as $p\uparrow 1$ the same statements hold with
$h(\cdot)$ replaced by $t(\cdot)$.

[Theorem thm:RBJ-H5 of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable satisfies the mixed diamond
equation
\begin{equation}
\bigl(q\mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}^{-1}
+ p\mathcal{M}_{t+1, \mathbf{a}+\mathbf{2},
\mathbf{n}}^{-1}\bigr)
\mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
- \mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\bigl(q\mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}}
+ p\mathcal{M}_{t, \mathbf{a},
\mathbf{n}+\mathbf{1}}\bigr) = 0,
\end{equation}
at every $(t, \mathbf{a}, \mathbf{n})$ with
$a_i < y_{n_i+1} + t - 1$ for all~$i$.

[Lemma C-for-critical-def of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For $f$ of the form (equation Form of f of the paper), 
\begin{equation}
\sqrt{\frac{2}{\pi}}\int_0^\infty u_\phi(t, x+\sqrt{2}t)xe^{\sqrt{2} x} dx \to \mathbf{C}(f)
\end{equation}
as $t\to \infty$, where $\mathbf{C}(f)$ is a positive constant. Furthermore, for any fixed $x \in \mathbb{R}$, 
\begin{equation}
\mathbf{C}(f(x+ \cdot)) = e^{\sqrt{2}x}\mathbf{C}(f).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2507.10294, 'Guessing Strategies for Shelf-Shuffling Machines'] We have
    \begin{equation}\max_{1\leq i\leq n-j}p_{i,j}=\frac{\binom{2j-2}{j-1}}{2^{2j-1}}\end{equation}
    and this maximum is achieved if and only if $i=2j-1$ or $i=2j-2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj ER of arXiv:2601.20502, 'Optimal matching under size priority'] Let $G_n$ be Erdös-Reny\'i graphs with parameters $(n, \frac{c}{n})$.
    Define $\mathcal{M}_{\max}(G_n)$ to be the set of maximum size matchings of $G_n$. Writing $\underline{\gamma}$ to be the smallest solution to $x=e^{-ce^{-cx}}$ and $\overline{\gamma}=e^{-c\underline{\gamma}}$, we then have the following:
        \begin{equation}
            \begin{aligned}
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall \mathbb{M} \in \mathcal{M}_{\max}(G_n), e \in \mathbb{M}}\right] &= \underline{\gamma}^2, \\
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall \mathbb{M} \in \mathcal{M}_{\max}(G_n), e \notin \mathbb{M}}\right] &= (1-\overline{\gamma})^2.
            \end{aligned}
        \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition prop:passage of arXiv:2608.23545, 'Eulerian walkers on $\Z^2$ have range exponent $2/3$'] For all vertices $x$, $y$, and $z$,
		\begin{equation}
			\tau(x,z)\leq\tau(x,y)+\tau(y,z)\, ,
		\end{equation}
		and
		\begin{equation}
			\tau(x,y)\leq d_G(x,y)\, .
		\end{equation}
		If the boundary routing of every nonempty finite set terminates, then
		for every integer $n\geq0$,
		\begin{equation}
			A_n=\{x:\tau(o,x)\leq n\}\, .
		\end{equation}

[Theorem 10 (Scaling limit of deterministic Schr\"{o}dinger bridges) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let Assumption \ref{assumption: limit_theory} hold. For each $k$, let
		\begin{align}
			\pi_k \in \argmin_{\pi \in \Pi(\mu_{0}^k, \mu_1^{k})} D_{\textup{KL}}(\pi \Vert \mathcal{R}_k)
		\end{align}
		be the static Schr\"{o}dinger bridge with margins $\mu_0^k, \mu_1^k$ and reference measure $\mathcal{R}_k$, and let $\pi^{\r,\c;\bLambda}$ denote the SSB with the limiting margins $\mu_0, \mu_1$ and reference measure $\mathcal{R}$. Then
		\begin{align}
			d_{H}(\pi_k, \pi^{\r, \c; \bLambda})^2 \leq 8(K + 4\log\delta^{-1}) \left( \|\rho_{\r_k} - \rho_{\r}\|_{L^1} + \|\rho_{\c_k} - \rho_{\c}\|_{L^1} \right) + 4\, e^{3K}\,\delta^{-12}\, d_{H}(\mathcal{R}_k, \mathcal{R})^2.
		\end{align}
		In particular, $d_{H}(\pi_k, \pi^{\r, \c; \bLambda}) \to 0$ as $k \to \infty$, so the sequence of discrete bridges converges to the continuous SSB in the Hellinger metric. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Classification of the $2n$-sum range of arXiv:2609.01926, 'On Sum Ranges for $3n$-convergence'] Let $\sum A = \lim_{k \to \infty} \sum_{n=1}^{2k} a_n$ be a series of real numbers that $2n$-converges to $x$. Then $\textnormal{SR}_2(A)$ is one of the following:
    \begin{enumerate}
        \item[(1)] The whole of $\mathbb{R}$;
        \item[(2)] The singleton $\{x\}$;
        \item[(3)] A shifted additive subgroup of the form $r + \Gamma$, where $r \in \mathbb{R}$ and $\Gamma \subseteq \mathbb{R}$ is any countable additive subgroup. Note that case (2) is a special case where $r = x$ and $\Gamma = \{0\}$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2506.20470, 'Pivot probabilities and norm effects in Gaussian elimination for $\beta$-ensembles'] Let $A$ be a $2 \times 2$ GUE matrix and GEPP pivot comparisons use the $L^1$ norm (as in LAPACK). Then the pivot probability is
    \begin{equation}
    \P(\|A_{21}\|_1 > |A_{11}|) = \P(|Z_1| + |Z_2| > \sqrt 2 |Z_3|) = \frac23
\end{equation}
for $Z_i \sim N(0,1)$ iid. (Proof in the paper; no proof environment follows the statement in the TeX.)

