body:
[Prop i!-left-Quillen-equiv-sp of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $i\colon G\to G'$ be an \emph{injective} homomorphism of compact Lie groups. Then
    \[
        i_!\colon\cat{$\bm{G}$-OrthSp}\rightleftarrows\cat{$\bm{G'}$-OrthSp}
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 i^*
    \]
    is a Quillen adjunction in which both adjoints are homotopical. In particular, they descend to an adjunction $i_!\colon{\mathfrak S\kern-.5pt\mathfrak p}_G\rightleftarrows{\mathfrak S\kern-.5pt\mathfrak p}_{G'}
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 i^*$.
    \begin{proof}
        [DHLPS2019Proper]*{Theorem~1.66(i)} shows that $i^*$ is homotopical right Quillen, while $i_!$ is homotopical by [schwede2018global]*{Corollary~3.2.21}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: ModuleRephrasingWalkDet of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] It holds that $p^2 \nmid \det(\bW)$ if and only if one of the following two events occurs: 
    \begin{enumerate}[leftmargin = 1.6em]
        \item It holds that $\coker\bigl(\bM - x\bI,\, \zeta\bigr)_{p,\beta} \cong 0$ for all monic $\beta(x) \in \bbZ[x]$ with irreducible reduction in $\bbF_p[x]$.
        \item Or, there exists $a\in \bbZ$ such that one has an isomorphism of $\bbZ[x]$-modules 
        \begin{align}
            \coker\bigl(\bM - x\bI,\, \zeta\bigr)_{p, x-a} \cong \bbF_{p}[x]/(x-a)\bbF_{p}[x],
        \end{align}
        and it holds that $\coker\bigl(\bM - x\bI,\, \zeta\bigr)_{p,\beta} \cong 0$ for every $\beta \not\equiv x-a \bmod p$.     
    \end{enumerate}

[Lemma 41 (Short-time full covariance negative moments) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] For every $q\ge1$, after decreasing $t_0$ if necessary,
\[
    \sup_{\substack{
        0\le\delta\le1,\ z\in K_0\\
        0<t\le t_0}}
    \mathbb E_z\left[
        \lambda_{\min}\left(
            T_t^{-1}\mathcal M_{t,r}^{\delta,\mathsf O}T_t^{-1}
        \right)^{-q}
    \right]<\infty .
\]

