[Lem dif:scm of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions     \mbox{\normalfont  (asump:tame of the paper)} to \mbox{\normalfont  (asump:sig:gam:tame of the paper)}   are satisfied, then for any $p_0\geq 2$, $t\in[0,T]$ and $i\in\{1,\ldots,N\}$
			\begin{align*}
				E_{\kappa_{n}(t)}|x_t^{i,N,n}-x_{\kappa_{n}(t)}^{i,N,n}|^{p_0}\leq K
					(n^{-\frac{p_0}{3}}+n^{-\frac{3}{4}})\big(1+|x_{\kappa_n(t)}^{i,N,n}|^{p_0}+\frac{1}{N} \displaystyle\sum_{k=1}^{N}|x_{\kappa_n(t)}^{k,N,n}|^{p_0}\big)
			\end{align*}
almost surely where  $K>0$ is a constant independent of $N$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] If $0 <t <\pi$, then 
		\begin{equation*}
			s_{\xi_B}(t)-\bar{s}_{\xi_B}(t) \leq 2\Lambda(t^{1/h})
		\end{equation*}
		where 
		\begin{equation*}
			\Lambda(t) = \int_{0}^{+\infty} \coth(tu)-\frac{1}{tu} \, \mu(\mathrm{d}u)
		\end{equation*}

