[Cor 3.1 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let the generator $g$ satisfy assumption (A:H1 of the paper) plus $\mu_\cdot\in {\mathbb R}_+$ (or assumption (A:H1 of the paper)(i)-(ii) plus (equation eq:2.3* of the paper) or assumption (A:H1' of the paper)) with the nonnegative process $f_\cdot$ satisfying $\mathbb{E}\left[(\int_0^\tau f_t{\rm d}t)^{p}\right]<+\infty$ instead of (equation eq:2.2 of the paper). Assume further that for some constant $M>0$,
\begin{align}
\int_0^\tau\left(\mu_t+\frac{\theta}{2(p-1)}\nu_t^2\right)^+{\rm d}t\leq M.
\end{align}
Then, for each $\xi\in L_\tau^p(0;{\mathbb R})$, BSDE (equation BSDE1.1 of the paper) admits an adapted solution $(y_t,z_t)_{t\in[0,\tau]}$ such that $y_\cdot\in S_\tau^p(0;{\mathbb R})$. Furthermore, if
\begin{align}
\int_0^\tau\left(\mu_t+\frac{\theta}{2[1\wedge(p-1)]}\nu_t^2\right)^+{\rm d}t\leq M,
\end{align}
then $z_\cdot\in M_\tau^p(0;{\mathbb R}^{d})$.

[Definition eq:fully_linear_val_sec2 of arXiv:2608.24963, 'Why and When Neural Networks Improve Local Approximation in Optimization'] A model $m_k$ is said to be \emph{fully linear} on $\Ball{x_k}{\Delta_k}$ if there exist constants $\kappa_f,\kappa_g>0$, independent of $k$, such that for all $x\in\Ball{x_k}{\Delta_k}$,
\begin{equation}
    |f(x)-m_k(x)| \le \kappa_f\Delta_k^2,
\end{equation}
and
\begin{equation}
    \|\nabla f(x)-\nabla m_k(x)\| \le \kappa_g\Delta_k.
\end{equation}

[Def 41 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $
\in \Omega_{G_ g}$ and $x,y\in V_ g$.
 egin{enumerate}
    \item[$(i)$] We say that $x$ is \emph{connected} to $y$ in $
$ and write $x\overset{
}{\longleftrightarrow} y$, if there is a sequence of points $x_0=x,x_1,\ldots, x_\ell=y$ such that $
_{x_ix_{i+1}}>0$ for $0\leq i \leq \ell-1$.
    \item[$(ii)$] The \emph{cluster} of $x$ in $
$, denoted by $\mathbf{C}_
(x)$, is the set of points connected to $x$ in $
$.
\end{enumerate}

[Theorem th:mainSPECTRUMgraph of arXiv:2510.00748, '\bf On irreducible central limit theorems'] Let $Z_n$ be as in (equation eq:bilformsubsec of the paper), and let $G_n=(V_n,\mathcal{E}_n)$ be its associated graph. Suppose that there exists $k\ge 2$ such that, as $n\to \infty$,
\begin{equation}
\liminf_n \mu_k^{(n)} >0.
\end{equation}
Then $\{Z_n\}$ is irreducible, in the sense of Definition (def:irreducibility of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] For all~$\lambda>0$, $\sigma\in(0,1/10)$ and~$\delta\in(0,1)$ there exist~$c>0$ and~$a_2\ge0$ such that for all $s\ge 1$, all~$u$ satisfying $s\ge u\ge s-\lambda$ and all~$n$ with~$s\le n^{1-\delta}$,
\begin{equation}

\begin{aligned}
Q_{n,s,u}\Biggl(\biggl(\,\bigcap_{k=1}^n\Bigl\{h(x_k)\le&\frac {n-k}n\wt m_n+s+\gamma_{n,a}(k)\Bigr\}\biggr)^\cc\,\Biggr)
\\
&\le
c\frac{(1+s-u)s}n\sum_{1\le k\le n/2}\bigl[k+\gamma_{n,a}(k)^2\bigr]\texte^{-\frac18 c_2\gamma_{n,a}(k)}
\end{aligned}
\end{equation}
holds for all~$a\ge a_2$ with
\begin{equation}

\gamma_{n,a}(k):=a+\bigl(\min\{k,n-k\}\bigr)^\sigma.
\end{equation}
Here~$c_2$ is as in \eqref{E:4.73}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2606.22044, 'Degenerate Stochastic Delay Modified Equation: Approximation of Stochastic Variance Reduce'] Let $Y_{t}$ be defined by (\ref{sfde-0-0}) and for any $g\in\mathcal{G}_{1}^{2},$ denote $P_{t}g(y)=\mathbb{E}[g(Y_{t}^{y})]$. Then, for arbitrary $y\in\mathbb{R}^{d}$, whenever $\eta\in(0,1]$ and $t\in[0,m\eta]$, the following holds:
\begin{align}
|\nabla P_{t}g(y)|\leq e^{Cm\eta},
\end{align}
\begin{align}
\|\nabla^{2}P_{t}g(y)\|_{{\rm HS}}\leq C_{1}e^{C_{2}m\eta},
\end{align}
where $C,C_{1},C_{2}$ are positive constants, and are independent of $m$ and $\eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp 8 ($L^p$ decay) of arXiv:2606.24167, '\bf On the stability of rarefaction for stochastic viscous conservation law'] Let $\phi\in X_1(T) $ be the solution of \eqref{perturbation}. Then for any $4< p< \infty$ 
	\begin{eqnarray}
		\mathbb{E} \| \phi \|_p^p \le C_{p}(1 + t)^{- \frac{p-2}{4}}\ln^\frac{p}{2}(2+t).
	\end{eqnarray}

