[Lemma eq: phi_k Bound of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] For some large enough universal constant $c(\nu_\infty,a_\infty)>0$:
\begin{equation}

|\phi_k|\leq c(\nu_\infty,a_\infty)\frac{\Gamma(k+\nu_\infty+2)}{a_\infty^k}, \ \ \forall k\ge 1.
\end{equation}
Also, we have
\begin{equation}

\sum_{k=0}^{+\infty}\left|\frac{a_\infty^kg_k}{\Gamma(\nu_\infty+k+3)}\right|\leq c(\nu_\infty,a_\infty). 
\end{equation}
where $g_k$ is defined as
\begin{equation}

\left|\begin{array}{l}
\Theta=\sum_{k=0}^{+\infty}\theta_kx^k\\
 G=\mu_0+x\left[x\sum_{j=1}^4\mu_j\Theta^j+x^2(x\Theta')\sum_{j=1}^4\nu_j\Theta^j\right]=\sum_{k=0}^{+\infty}g_kx^k.
 \end{array}\right.
 \end{equation}

[Lem 2 of arXiv:2606.03661, '2606.03661'] Let $0<\alpha<1$ and $\nu>-1$. Suppose that $f$ is such that the Mellin transforms exist, the boundary term in the Mellin transform of $f^\prime$ vanishes, and the Mellin convolution theorem applies. Then
\begin{equation}

\mathcal{M}[\mathscr{D}_t^{(\alpha,\nu)} f;s]
=
 \frac{(1-s)\Gamma(1+\nu-s)}{\Gamma(2+\nu-\alpha-s)}F(s-1). 
\end{equation}

[Lemma 13 of arXiv:2609.02225, '\textbf{The direct moving plane method for weak solutions of the fractional $p$-Laplacian}'] There exists \(c_H=c_H(n,s,p)>0\) such that, for every \(\lambda\in\mathbb R\) and \(x\in\Sigma_\lambda^-\),
\begin{equation}
 \int_{\Sigma_\lambda}
 \frac{
 \bigl(
  |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy
 \ge c_H(\lambda-x_1)^{-sp}u(x)^{p-2}.
\end{equation}
If \(\lambda\le0\), then
\begin{equation}
 \int_{\Sigma_\lambda}
 \frac{
 \bigl(
  |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy
 \ge c_H|x|^{-sp}u(x)^{p-2},
 \qquad\text{for }x\in\Sigma_\lambda^-.
\end{equation}
Let \(I\subset\mathbb R\) be a bounded interval and set $L_I:=\max\left\{1,\sup_{\mu\in I}|\mu|\right\}$. Then, for every \(\lambda\in I\) and every \(x\in\Sigma_\lambda^-\) with \(|x|\ge L_I\), there exists \(c_H'=c_H'(n,s,p)>0\) such that
\begin{equation}
   \int_{\Sigma_\lambda}
 \frac{
 \bigl(
 |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy
 \ge c_H'|x|^{-sp}u(x)^{p-2}.
\end{equation}

