[Lemma lem:R<p/q of arXiv:2607.14062, 'Gilbert's disc model conditioned on the square lattice'] Let $a,b\in \mathbb{Z}_{>0} = \{1,2,\dots\}$, let $R \in (0, a/b)$, and let $u_0,\ldots,u_n\in\mathbb{Z}^2$. If there exists $P\in\mathcal P$ such that $u=(u_0,\ldots,u_n)$ is a path of $\Gamma_{p,R}^{\texttt{CN}}(P)$ (resp.\ of $\Gamma^{\texttt{NN}}_{p,R}(P)$), then 
    \begin{equation}
    \forall k\in \{0,\ldots, n-b\}, \quad \|u_{k+b}-u_k\|_\infty \leq a.
    \end{equation}

[Lemma lem:F of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] There exists $C>0$ such that, for all $1/2<\lambda \le 7/8$, $T>0$ and $N$ large enough,
	\begin{equation}
		\int_0^T f_{\lambda,N}(t)\,{\rm d} t \le C e^{CT}\set{N^{-1}+N^{2\lambda-5/2}\,T^{1/2}}\; \text{.}
	\end{equation}

