Then
\bas{
\frac{1-\beta}{1-\beta^n}=\frac{x}{1-(1-x)^n}.
}
Assume first that $n\le (1-\beta)^{-1}$, that is, $nx\le 1$. Since $(1-x)^n\le e^{-nx}$ and $1-e^{-y}\ge y/2$ for every $y\in[0,1]$, we obtain
\bas{
1-(1-x)^n\ge 1-e^{-nx}\ge \frac{nx}{2}
\text{, \ \  which yields \ \ }
\frac{1-\beta}{1-\beta^n}=\frac{x}{1-(1-x)^n}\le \frac{2}{n}.
}
This proves the first assertion.

Now assume that $n\ge (1-\beta)^{-1}$, that is, $nx\ge 1$. Then
\bas{
\beta^n=(1-x)^n\le e^{-nx}\le e^{-1} \text{ \ \ and, hence, \ \ }
\frac{1-\beta}{1-\beta^n}\le \frac{1-\beta}{1-e^{-1}}.
}
This proves the second","release_manifest_digest":"sha256:5ff183d3d3ca192609bffed8dd25d7e96daca8bdbb0012add5e8a8241b37d1d4","revision_digest":"sha256:df7e8439e76512f30029be528b9cb7ac480a638252dda41c2fc326ae0f561649","source_id":"arxiv:2608.30382","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

