[Lemma 16 of arXiv:2606.10313, '\textbf{Invariance principles for additive functionals of voter models}'] Let $\eta_0$ be distributed with $\mu_p$.
For any $t\geq 0$,
\begin{align*}
&\lim_{N\rightarrow+\infty}\Big(\frac{1}{\sqrt{N}}\tilde{G}^N(tN, \eta_{tN})-\frac{1}{\sqrt{N}}\tilde{G}^N(0, \eta_0)\\
&\text{\quad\quad\quad}-\frac{1}{\sqrt{N}}
\int_0^{tN}\left(S(N)F(\eta_s)-\mathbb{E}_{\mu_p}S(N)F(\eta_s)\right)ds\Big)=0
\end{align*}
in $L^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let us fix $T>0$, $p\in [2, \infty)$ and $u_0\in \Vp\cap \bM$. If $u_m$ denotes the unique solution of the SDE \eqref{eqn-Faedo-Galerkin}, then, for each fixed $m\in \N$, the following estimate holds true:
			\begin{align}
				& \sup_{m\in\N}\E \bigg[ \sup_{t\in[0,T]}\big(\|u_m(t)\|_{H_0^1(\bO)}^{4} + \|u_m(t)\|_{L^p(\bO)}^{2p}\big) \bigg] + \sup_{m\in\N}\E\left[\int_0^T\|{P_m(|u_m(t)|^{p-2}u_m(t))}\|_{L^{2}(\bO)}^{2}dt\right]\\
				& \quad + \sup_{m\in\N}\E\left[\int_0^T\|\Delta u_m(t)\|_{L^2(\bO)}^2dt\right] + 2(p-1)\sup_{m\in\N}\E\left[\int_0^T\||u_m(t)|^{\frac{p-2}{2}} \nabla u_m(t)\|_{L^2(\bO)}^2dt\right]\\
				& \leq C\left(\|u_0\|_{\Vp},T,  \sum_{i=1}^M \|f_i\|_{\Vp}\right).
			\end{align}

