[Cor sufficient-inequalities-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a $(d,0)$-non-degenerate weight pair with $d\geq 1$ and assume that $r=r_{d,0}({\mathbf{a}})$ is finite.
	Assume that the following inequalities hold for all $n\geq 0$, all $q\leq q'$ in $\{0,\dots,r-1\}$, and all $s \leq s'$ in $\{0,\dots,d-1\}$,
	\begin{equation}
	\frac{b_{nd+1}}{b_{(n-1)d+1}}
	\leq
	\frac{
		\PFComp{\shift{q' d+s'}{\mathbf{a}},{\mathbf{b}}}{nd+(d-s')}
	}{
		\PFComp{\shift{q' d+s'}{\mathbf{a}},{\mathbf{b}}}{(n-1)d+(d-s')}}
	\leq
	\frac{
		\PFComp{\shift{q d+s}{\mathbf{a}},{\mathbf{b}}}{nd+(d-s)}
	}{
		\PFComp{\shift{q d+s}{\mathbf{a}},{\mathbf{b}}}{(n-1)d+(d-s)}}
	\leq
	\frac{b_{(n+1)d+1}}{b_{nd+1}},
	\end{equation}
	where we omit the ill-defined inequality on the left when $n=0$.
	Then $({\mathbf{a}},{\mathbf{b}})$ is $(d,0)$-admissible, and $(\shift{qd+s}{\mathbf{a}},{\mathbf{b}})$ is $(d,\overline{d-s})$-admissible for every $s\in\{0,\dots,d-1\}$ and $q\in\{0,\dots,r-1\}$.

[Corollary gt_V_pm_rec of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] For any $s \in (0,1)$ and $t \in \mathbb{R}$ we have
\begin{multline}
    \lim_{\alpha \to \infty} \frac{g_\alpha(s)}{g_\alpha\left( V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) \right)} = \\
 \lim_{\alpha \to \infty} \frac{g_\alpha(s)}
 {g_\alpha\left( s+ \frac{1}{\gamma(\alpha)} \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} \right)} \cdot \frac{g_\alpha\left( s+ \frac{1}{\gamma(\alpha)} \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} \right)}
 {g_\alpha\left( V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) \right)}
        \stackrel{(equation psi_exp of the paper), (equation ugly_logarithm of the paper)}{=} \\
    \lim_{\alpha \to \infty}
  \frac{g_\alpha(s)}{g_\alpha\left( s+ \frac{1}{\gamma(\alpha)} \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} \right)} \cdot 1 \stackrel{(equation psi_exp of the paper)}{=}  e^{\psi(s)t}+e^{-\psi(s)t}.
\end{multline}

