[Lemma 19 (Score-profile coupling reduction) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] The space $E$ is Polish and
\begin{equation}

\mathcal C(\mu,\nu)
=
\left\{
(T_s,T_s)_\#\kappa:
\kappa\in\mathcal C(P,Q)
\right\}.
\end{equation}
Consequently,
\begin{equation}

W_s(P,Q)=W_1(\mu,\nu),
\end{equation}
where the right-hand side uses the $L^1(\lambda)$ distance on $E$.
In particular, $W_s$ is a pseudometric and satisfies the triangle inequality.

[Definition Multi-species 2-spin model of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] Fix $k\geq 1$. Let $\Lambda = \diag(\alpha_1,\dots, \alpha_k)$ be a matrix satisfying $\alpha_i\in (0,1)$ for all $i$ and $\sum_{i=1}^k \alpha_i=1$. Let $\Delta^2$ be a $k\times k$ symmetric matrix of non-negative entries. 
    A multi-species model with species density matrix $\Lambda$ and variance profile matrix $\Delta^2$ satisfies the following assumptions.
    \begin{itemize}
        \item Given $N \geq k$, there is a partition of spins $\{1,2,\dots, N\} = \cup_{s=1}^k I_s$, where the species density
        \[
        \Lambda_N:=\frac1N\diag(|I_1|,...,|I_k|) \quad \text{satisfies} \quad \lim_{N\to\infty}\Lambda_N=\Lambda.
        \]
        \item Let $(g_{ij})_{1 \leq i, j\leq N}$ be independent centered Gaussian variables such that $\mathbb{E}[g_{ij}^2] = \Delta^2_{s,t}$ for $i\in I_s$ and $j\in I_t$. The Hamiltonian of the model, at each spin configuration $\sigma\in \Sigma_N$, is defined as
         \begin{equation*} 
        H_N(\sigma) = \frac1{\sqrt N}\sum_{i,j=1}^N g_{ij}\sigma_i\sigma_j.
         \end{equation*} 
    \end{itemize}
    Here, $\Sigma_N = \{\pm 1\}^N$ in the case of Ising spins and is the product of spheres $S_{|I_1|-1}  \times  \dots \times S_{|I_k|-1}$ in the case of spherical model.

[Prop main term being probability of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $O_n$ be the event defined in (equation definition of O_n of the paper) and $S_n$ be the random walk defined in (equation def of S_n and S_n hat of the paper). Then, 
    \begin{align}
\mathbb{E}_2\left[ \frac{1}{|S_n(X_0-X_2)|^4} \mathbbm{1}_{O_n} \right]= \mathbb{P}_2[O_n]. 
        \end{align}
    In particular, 
    \begin{align}
\mathbb{E}\left[ \frac{1}{|S_n(X_0-X_2)|^4} \mathbbm{1}_{O_n} \right]= \mathbb{P}[O_n]. 
        \end{align}
Furthermore, for any integer $k\in \mathbb{Z}$, 
\begin{align}
\mathbb{E}_2&\left[ \frac{1}{|S_n(X_0-X_2)|^4} \mathbbm{1}_{O_n} \mathbbm{1}_{\left \{ \frac{|X_0-X_2|}{|X_0-X_3|} \in [2^k, 2^{k+1})\right\}}\right] \nonumber
           \\ &\qquad \qquad\qquad\qquad = \mathbb{P}_2\left[O_n \cap \left\{ \frac{1}{|S_n||X_0-X_3|}\in [2^k, 2^{k+1})\right\}\right].
            \end{align}

