[Defi 3 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $p \in (0, \infty)$. A collection $\{X^n_s : s\in S_n, n \ge 1\}$ of $\cX$-valued random elements is  \textit{$(\nu_n)$-compactly uniformly $p$-th order integrable} (or $(\nu_n)$-$\CUI(p)$, for short) if:
	\begin{enumerate}[\rm (a)]
		\item the map $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF \otimes \cS_n/\cB(\cX)$-measurable for every $n \ge 1$,

		\item for any $\ep >0$, there exists $K_\ep \in \cK(\cX)$ such that
		\begin{align*}
			 \sup_{n \ge 1} \bE\int_{S_n} \lt\|X^n_s\rt\|^p \1_{\{X^n_s \notin K_\ep\}} \nu_n(\od s)  \le \ep.
		\end{align*}
	\end{enumerate}

[Lemma cme-f of arXiv:2507.20324, 'Non-existence of several random fractals in Brownian motion and Brownian loop soup'] For a fixed $n$-box $S$, recall that $\widetilde{\mathbb{P}}(\cdot):=\mathbb{P}(\cdot|S\in\mathfrak{S}_{n}(\delta+2^{-\sqrt{n}}))$, and assume that
\[\mathrm{dist}(S,T),\mathrm{dist}(S,U)\geq 2^{-n+jL}.\]
Then there exist $c,c_{1},c_{2}>0$, such that
\begin{equation}
c_{1}\mathrm{dist}(S,T)^{-2}2^{-2n}\leq\widetilde{\mathbb{P}}_{n}(T\in\mathfrak{S}_{n}|\mathscr{F}_{j-1})\leq c_{2}\mathrm{dist}(S,T)^{-2}2^{-2n},
\end{equation}
and
\begin{equation}
\widetilde{\mathbb{P}}_{n}(T,U\in\mathfrak{S}_{n}|\mathscr{F}_{j-1})\leq cD_{1}^{-2}D_{2}^{-2}2^{-4n},
\end{equation}
where
\[D_{1}=\min\{\mathrm{dist}(S,T),\mathrm{dist}(T,U),\mathrm{dist}(U,S)\},\]
and
\[D_{2}=\max\{\mathrm{dist}(S,T),\mathrm{dist}(T,U),\mathrm{dist}(U,S)\},\] and $\mathscr{F}_{j}$ is the increasing family of $\sigma$-fields defined in (equation filtration of the paper).
Moreover,
\begin{equation}
\widetilde{\mathbb{P}}_{n}(T\in\mathfrak{S}_{n},T\lessdot S|\mathscr{F}_{j-1})\geq c'\mathrm{dist}(S,T)^{-2}2^{-2n}
\end{equation}
for some $c'>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Punctured intertwining) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] For every $A\subset D$, every $y\in D$, we have:
\begin{equation}
  \forall t\geq0\,,\quad\Pp_A^D(y\in S_t^D)
  =\frac{1}{\pi(y)}
  \sum_{a\in A}\pi(a)
  \Pp_a(X_t=y,\ t<\tau_{D^c}).
\end{equation}
In particular, for $A=\{x\}$, we get:
\begin{equation}
  \forall t\geq0\,,\quad\Pp_{\{x\}}^D(y\in S_t^D)
  =\frac{\pi(x)}{\pi(y)}
  \Pp_x(X_t=y,\ t<\tau_{D^c}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem fplinax of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] Let $ X_t $ be the solution of ((mSDEline of the paper)). If $ A_t, B_t $ and $ C_t $ satisfy the conditions of Lemma (Malianx of the paper). Then the memory-dependent PDEEs for PDFs $ p(x,t) $ of the solutions $ X_t $, satisfies the following equation
		\begin{align}
		\frac{\partial }{\partial t}p(x,t)=&-\frac{\partial }{\partial x}\big\{\big(A_tx+\frac{1}{2}B^2_tx+\hat{C}_tx\big)p(x,t)\big\}+\frac{\partial^2 }{\partial x^2}\big\{\big(\frac{1}{2}B^2_tx^2+\hat{C}_tx^2\big)p(x,t)\big\},
		\end{align}
		where $ \hat{C}_t= C_t\int_{0}^{t}\phi(t,r)C_r\mathrm{d}r$ and the initial condition is given by $p(x,0)=\delta(x-x_0)$.

[Lemma 14 (Fixed-level finite-fourth tail removal) of arXiv:2608.04824, 'Strong Convergence for a General Class of Random Matrix Models'] Under Definition~\ref{def:iid-entry-model}, almost surely,
\begin{equation}
 \lim_{K\to\infty}\limsup_{n\to\infty}
 \max_{1\leq\kappa\leq d}
 \|X_{\kappa,n}-X_{\kappa,n}^{(K)}\|=0.
\end{equation}
Moreover,
\begin{equation}
 \max_{1\leq\kappa\leq d}\limsup_{n\to\infty}
 \|X_{\kappa,n}\|<\infty
 \qquad\text{almost surely}.
\end{equation}

[Proposition PropBivIntegral of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any pair $0 < a < b < 1$, we can write the KL product-reference
error over the interval $[a,b]$ as
\begin{subequations}
  \begin{align}

    \Gamma_{\scaleto{\operatorname{prod}}{5pt}}(a, b) & = \int_{\ensuremath{\varphi}(a)}^{\ensuremath{\varphi}(b)}
    \int_\eta^{\ensuremath{\varphi}(b)} \ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\eta, \xi) \, d\xi \, d\eta.
  \end{align}
  Moreover, the associated \textsf{IGC}\xspace increment takes the form
  \begin{align}

    \mathsf{G}(a, b) & = \int_{\ensuremath{\varphi}(a)}^{\ensuremath{\varphi}(b)} \ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\eta,
    \eta) \, d\eta.
  \end{align}
  Finally, the total correlation (\ensuremath{\mathsf{TC}}) and dual total correlation
  (\ensuremath{\mathsf{DTC}}) have the representations
  \begin{align}

    \ensuremath{\mathsf{TC}}(Z) \stackrel{(\ensuremath{\mathsf{TC}})}{=} \int_{-\infty}^{\infty}
    \int_\eta^\infty \ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\eta, \xi) \, d\xi \, d\eta, \qquad
    \mbox{and} \qquad \ensuremath{\mathsf{DTC}}(Z) \stackrel{(\ensuremath{\mathsf{DTC}})}{=}
    \int_{-\infty}^{\infty} \int_{-\infty}^\eta \ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\eta, \xi) \,
    d\xi \, d\eta.
  \end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:2_35 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] There exist constants $C_{\mathfrak{t}}, C_{1}>0$ and $q \geqslant 1$ such that the following holds. 

  For every initial condition ${\tt u}\in\R^{\mcb{n}}$ and under assumption that (equation eq:assumpV of the paper) holds, the statement of Lemma~(lem:solutionconstruction of the paper) holds with the existence time $\tilde{T}_{\Xi}$ replaced by  $\tilde{T}_{\hat\Xi}$, with $\tilde{T}_{\hat\Xi} = C_{\mathfrak{t}}\hat\Xi^{-p}$ for   
\begin{equ}\hat\Xi =
\max \Big(
{\talloblong \omega\xi \talloblong}_{4}, C_R,
\|V\|_{C^9(\R^{\mcb{n}})} \Big)\,.
\end{equ}
In particular, $\hat{\Xi}$ is independent of ${\tt u}$.

Moreover, on the event $\{T\leqslant \tilde T_{\hat\Xi}\}$, 
    \begin{equs}
       \sup_{t\in[0,T]} |{u_\eps}(t)| \leqslant |{\tt u}|+C_1T^{-q}\,.
    \end{equs}
Finally, in view of the $\eps \downarrow 0$ convergence in probability of $u_\eps$ to a limit $u$ stated in Theorem~(thm:main of the paper), on the event $\{T\leqslant \tilde T_{\hat\Xi}\}$, one has
    \begin{equs}
  \sup_{t\in[0,T]} |{u}(t)|\leqslant    \liminf_{\eps\downarrow0} \sup_{t\in[0,T]} |{u_{\eps}}(t)| \leqslant |u(0)|+C_1T^{-q}\,.
    \end{equs}

[Lemma lemma8 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold. Let $f: \mathbb{R} \rightarrow \mathbb{R}$ be a deterministic c\`adl\`ag function such that $t \in \mathbb{R} \mapsto f(t) e^{-\alpha t}$ is directly Riemann integrable. Suppose further that $t \in \mathbb{R} \mapsto m_{t}^{f} e^{-\frac{\alpha}{2}t}(1+t^{2})$ is bounded. Then,  
\begin{enumerate}[label=(\textbf{\roman*})]
\item The characteristic  $\chi_{f}$ satisfies (C1 of the paper)-(C3 of the paper). Moreover, for all $h \in \mathbb{N}_{0}$ and $\varepsilon>0$, 
\begin{align} 
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon} |\chi_{f,u}(s-S(u))| \mathbf{1}_{(-\infty,0)}(s-S(u)) \right] < \infty
\end{align}
\noindent and 
\begin{align}  
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i} |\chi_{f,u}(s-S(u))| \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}

\item For every $t \in \mathbb{R}$, the series $\mathcal{Z}_{t}^{\chi_{f}}$ converges unconditionally in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$ and almost surely over every admissible ordering of $\mathcal{I}$. Moreover, for all $t \in \mathbb{R}$, $\mathbb{E}[\chi_{f}(t)] = 0$ and  
\begin{align}
\mathcal{Z}_{t}^{f} - m^{f}_{t} \stackrel{a.s.}{=}  \mathcal{Z}_{t}^{\chi_{f}}. 
\end{align}

\item For $n \in \mathbb{N}_{0}$ and $t \in \mathbb{R}$, 
\begin{align}
\sum_{0\leq |u| \leq n} \chi_{f, u}(t - S(u)) \stackrel{a.s.}{=}  \sum_{0\leq |u| \leq n} f(t - S(u)) - f \ast \nu^{(\infty)}(t) + \sum_{|u| = n+1} f \ast \nu^{(\infty)}(t - S(u)). 
\end{align}
\end{enumerate}

[Lemma 6 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $ r, M > 0$ and $\Phi:[M,+\infty)$ be differentiable and convex.  If
    \begin{equation}
        \gamma:=\frac{r}{M} -\Phi'(M)<0,
    \end{equation}
    then for every $T \ge M$, the inequality
    \begin{equation}
        \sum\limits_{l = 0}^{\infty} (T+l)^r e^{-\Phi(T+l)} \leq \frac{M^r e^{-\Phi( M)}}{1-e^{\gamma}}
    \end{equation}
    holds.

