[Proposition 17 of arXiv:2603.25400, 'One-arm probabilities for the two-dimensional metric-graph and discrete Gaussian free fiel'] There is a constant $\rho>0$ such that for any integer $k\in[N(\log N)^{-1},N/2]$ and any $h\le\sqrt{\log N}$, we have
    \begin{equation}
        \mathbb P[0\connect{\varphi_N\ge h}\partial B_k]\lesssim\widetilde \eta_{N,k}^{h,\rho},
    \end{equation}
    where
    $$\wt\eta_{N,k}^{h,\rho}:=\begin{cases}
        \frac{|h|\vee\sqrt{\log N-\log k}}{\sqrt{\log N}},&h\le 0;\\
        \sqrt{\frac{\log N-\log k}{\log N}}\exp\left(-\frac{\rho h^2}{\log N-\log k}\right), &h>0.
    \end{cases}$$

[Lemma lem : FdTmon/Intrinsic/Pgrad of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Assume that $\FdTmon(D)<\infty$. Then for $\hd$-almost all $z\inX \setminus\bigcup_{k\ge 1}\sigma_k$,
	\begin{equation}
		(\Pgrad D)_z = \mu,
	\end{equation}
	and for all $k\ge 1$, for $\hd$-almost all $z  = \sigma_k(t)\in \sigma_k$, for all $u\in \mathbb{R}^d \setminus \p{\sigma_k'(t)\mathbb{R} }$,
	\begin{equation}
		(\Pgrad D)_z(u) = \mu(u).
	\end{equation}

