[Proposition prop:char_func of arXiv:2607.14266, 'The Swapping Mechanism for Interacting Diffusions: Framework, Comparison with Switching, a'] Let $Q(k_x,k_y,t):=\mathbb{E}[e^{i(k_xX_t+k_yY_t)}]$ with initial condition
		$(X_0,Y_0)=(x_0,y_0)$. Then
		\begin{equation}
			\begin{aligned}
				Q(k_x,k_y,t)
				&=\frac{e^{i(k_xx_0+k_yy_0)}\bigl(\kappa_-+\sqrt{\kappa_-^2+4s^2}\bigr)+2s\,e^{i(k_yx_0+k_xy_0)}}{2\sqrt{\kappa_-^2+4s^2}}\,e^{-tR_+}\\
				&\quad-\frac{e^{i(k_xx_0+k_yy_0)}\bigl(\kappa_--\sqrt{\kappa_-^2+4s^2}\bigr)+2s\,e^{i(k_yx_0+k_xy_0)}}{2\sqrt{\kappa_-^2+4s^2}}\,e^{-tR_-},
			\end{aligned}
		\end{equation}
		where
		\begin{equation}
			\kappa_\pm
			=\tfrac{\sigma_1^2\pm\sigma_2^2}{2}(k_x^2\pm k_y^2)
			+i(\mu_1\pm\mu_2)(k_x\pm k_y),
			\qquad
			R_\pm=\frac{2s+\kappa_+\pm\sqrt{\kappa_-^2+4s^2}}{2}.
		\end{equation}
		The complex square root is chosen with non-negative real part.

[Prop 4 of arXiv:2506.13661, 'Box-Covariances of Hyperuniform Point Processes'] Let $\eta$ be a stationary point process with truncated pair correlation measure $\beta.$ It holds that 
	\begin{align}
		\mathrm{Cov} (\eta(\Lambda_n),\eta(\Lambda_n(nz)))= \lambda_d(\Lambda_n\cap\Lambda_n(nz)) + \int_{\Lambda_n}\beta(\Lambda_n(nz-x))\lambda_d(\mathrm{d}x).
	\end{align}

