[Lemma 5 (Uniform fixed surplus Wright bound) of arXiv:2608.04799, '2608.04799'] For every integer \(R_0\ge0\), there is \(C=C(R_0)<\infty\) such that
\begin{equation}
  c(k,k+r-1)
  \le C k^{k+3r/2-2}
\end{equation}
for all \(k\ge1\) and \(0\le r\le R_0\), with the convention that the left
side is zero when the edge count is infeasible.

[Lemma lemmaexitright of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Pick universal constants $\frac{1}{\delta},\Theta^*\gg1 $ large enough as in Lemma (propositionfundamental of the paper), then  for all $0<b<b^*(\Theta^*,\delta)$ small enough and $\alpha_\gamma$ given by 
\begin{equation}

\alpha_\gamma=\frac{K^{\nu_b+3}\big(b\sqrt{\delta}\big)^{K-1}}{\Theta^*}
\end{equation}
or 
\begin{equation}

\alpha_\gamma=1-\frac{K^{\nu_b+3}\big(b\sqrt{\delta}\big)^{K-1}}{\Theta^*},
\end{equation}
the $C^\infty$ solution exits on the left of $P_3$ at $u=U_*$, where $-\frac{3}{4}<U_*<0$, by crossing $\Delta_2=0$ in the case (equation boudnaryleyeralphagright of the paper) and by crossing $\Delta_1=0$ in the case (equation boudnaryleyeralphagrightbis of the paper).

[Lem nec_hyp of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] \begin{enumerate}
        \item The standard foliation by disks on $S^1 \times D^2$ cannot be $C^0$-approximated by contact structures with boundary slope $0$ for the standard boundary framing.

        \item An irrational foliation $\mathcal{F}$ on $\mathbb{T}^2 \times I$ cannot be $C^0$-approximated by contact structures realizing the same boundary slopes as $\mathcal{F}$. 
    \end{enumerate}

[Lemma 8 of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Suppose that Assumption~\ref{a2-2} holds. Then, for every $d' > d$ there exists a constant $C_{12}>0$ such that for every $R \geq R_1$ (here $R_{1}$ is the same constant in Assumption~\ref{a2-2} associated with $d'$) and $f, g\colon B(R) \to \R$ with $(g)_{B(R)} = 1$,

  \begin{align}
    &\norm{f - (fg)_{B(R)}}{\rho_{*}}{B(R)}
    \nonumber\\%[.5ex]
    &\mspace{36mu}\leq\;
    C_{12}\, R^{1-d/d'}\,
    \Bigl(
      1 + \Norm{g}{\rho_{*}/(\rho_{*}-1), B(R)}
    \Bigr)\,
    \Biggl(
      \sum_{\substack{y, z \in B(\delta_{\mathrm{S}} R) \\ y \sim z}}
      \mspace{-12mu}\bigl|f(y) - f(z)\bigr|^{\rho}
    \Biggr)^{\!1/\rho}.
  \end{align}







  Here $\rho, \rho_{*} \in (1, \infty)$ and $\delta_{\mathrm{S}} \in [1, \infty)$ are the same constants as in Assumption~\ref{a2-2}-(ii) satisfying \eqref{a2-2-3} and \eqref{a2-2-2}.

