[Lemma LEM:OUdec of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $L_\varepsilon=\varepsilon^{-\frac 12+\eta}$ and $ \min_{ \ell \neq i}|\xi_\ell-\xi_i | \ge d_\varepsilon= \big|\log  (\varepsilon \log \frac 1 \varepsilon) \big|$. 

\begin{itemize}

\item[(i)] Bulk regime: Let $|x|, |y| \le L_\varepsilon -|\log \varepsilon|$ and $|\xi_j| \le \overline L_\varepsilon$, $j=1,\dots,k$, where $\overline L_\varepsilon$ is defined in
(equation cjL of the paper).  Then 
\begin{align*}
|G_{\textup{OU}, \xi_1,\dots, \xi_k }^D(x,y)-c e^{-|x-y|}| \lesssim e^{-2(L_\varepsilon -\max \{ |x|, |y| \}  )}
\end{align*}

\noindent
as $\varepsilon \to 0$, where the exponentially small error term is independent of the tangential modes $\xi_1,\dots,\xi_k$ satisfying $|\xi_j| \le \overline L_\varepsilon$.

\medskip 

\item[(ii)] Diagonal regime: for any $x\in [-L_\varepsilon, L_\varepsilon]$
\begin{align*}
|G_{\textup{OU}, \xi_1,\dots, \xi_k }^D(x,x)| \lesssim 1,
\end{align*}

\noindent
uniformly in $\xi_1,\dots, \xi_k \in [-\overline L_\varepsilon, \overline L_\varepsilon]$.

\end{itemize}

[Corollary 32 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Fix $m\in \N$ and a measurable, non-increasing function $\Omega:\R_+\to\R_+$. Let $f_1,\dots,f_{m+1}:\R^n\to\R_+$ be measurable, even functions that satisfy
    $$\left(\prod_{i=1}^{m}f_i(a_i)\right)\cdot f_{m+1}(v) \leq \Omega^{m+1}\left(\sum_{i=1}^m\langle a_i,v\rangle_+\right) \quad \text{for all } a_1,\dots,a_m,v\in \R^n.$$ 
    Then, we have
    \begin{equation}
  \begin{split}
    &\prod_{i=1}^m\left(\int_{\R^n}f_i(x)dx\right)\Bigg(\int_{\R^n} f_{m+1}(v)^\frac{1}{m}dv\Bigg)^m
    \\
    &\leq \left(\int_{\R^n}\cdots\int_{\R^n}\Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m \langle a_i, \xi \rangle_+\right)^{m+1}\right)da_1\cdots da_m\right)\left(\int_{\R^n}\Omega\left(|v|^\frac{m+1}{m}\right)dv\right)^{m}.
\end{split}
    \end{equation}
    When $\Omega$ is log-concave and integrable over $\R_+$, there is equality when there exists $C>0$ such that $$\prod_{i=1}^mf_i(a_i) = C\cdot \Omega\left(\left(\max_{|\xi| \leq 1} \sum_{i=1}^m \langle a_i, \xi \rangle_+\right)^{m+1}\right) \text{ and }f_{m+1} = \frac{1}{C} \cdot \Omega\left( |\cdot|^{\frac{m+1}{m}}\right)^m.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

