[Lemma lem:formula-for-nu of arXiv:2411.09075, 'Weak Poincar{\'e} Inequalities, Simulated Annealing, and Sampling from Spherical Spin Glas'] Let $\eps$ be as in Lemma~(lem:band-models-eps-strictly-rs of the paper). 
    On an event with probability $1-e^{-cN^{1/5}}$, the following holds.
    The density of $(a,b)$ under $\nu$, conditioned on $|a|,|b| \le \eps N^{1/10}$, is given by
    \[ \nu(a,b) \propto \exp\left( N \wh{E}_{a,b} + \sqrt{N} g_{a,b} + \Error^{(1)}_{a,b} + \Error^{(2)}_{a,b} + \Delta_{a,b}\right), \]
    where $|\Delta_{a,b}| \le 1$ and
    \begin{align*}
        \wh{E}_{a,b} &= \frac{\xi_{a,b}(1)}{2} + \log r_{a,b} + \frac{1}{N} \E_{\mu_\TAP} \HTAP(v(a,b)) - \frac{\xi_t(1)}{2} \\
            &= \frac{1}{2} \left( \log r_{a,b}^2 - \xi_t(\|v(a,b)\|^2) - r_{a,b}^2 \cdot \frac{\xi_t'\left( q_{\boldm} \left( 1 + \frac{a}{\sqrt{N}} \right) \right)^2}{\xi_t'(q_{\boldm})} \right) \\
            &\qquad - \gamma(q_{\bx}) \cdot \frac{\xi_t'\left( q_{\boldm} \left( 1 + \frac{a}{\sqrt{N}} \right) \right)}{\xi_t'(q_{\boldm})} \cdot \left( \left( 1 + \frac{b}{\sqrt{N}} \right) -  q_{\boldm} \cdot \frac{\xi_t''(q_{\boldm})}{\gamma'(q_{\boldm})} \cdot \left( 1 + \frac{a}{\sqrt{N}} \right) \right) \\
            &\qquad + \xi_t\left( q_{\bx} \left( 1 + \frac{b}{\sqrt{N}} \right) \right) + \frac{\gamma\left( q_{\boldm} \left( 1 + \frac{a}{\sqrt{N}} \right) \right)}{\gamma'(q_{\boldm})} \cdot \left( (1-q_{\boldm}) \xi_t''(q_{\boldm}) + \frac{1}{1-q_{\boldm}} \right).
    \end{align*}
    for the error terms
    \begin{align*}
        \Error^{(1)}_{a,b} &= \left( \log \wh{Z}_{a,b} - \frac{N\xi_{a,b}(1)}{2} - \frac{N \xi''_{a,b}(0)}{4} + \frac{1}{2} \log \det \left( (1+\xi''_{a,b}(0)) \Id - \grad^2 H_N(v(a,b)) \right) \right) - 4 \log r_{a,b}
    \end{align*}
    and
    \begin{align*}
        \Error^{(2)}_{a,b} &= \frac{N\xi''_{a,b}(0)}{4} - \frac{1}{2} \log \det \left( (1+\xi''_{a,b}(0)) \Id - \grad^2 H_N(v(a,b)) \right)
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

