[Definition 1 of arXiv:2608.14802, 'Dynamical Gibbs-non-Gibbs transitions for finite-alphabet models on trees'] A configuration $\eta \in \Omega$ is \underline{good} for $\mu^l_t$ if for all $x\in V$, all local
functions $\varphi$, and each sequence of finite volumes $\Lambda_n\uparrow V$,
\begin{equation}
    \lim_{n\rightarrow \infty}\sup_{\substack{\xi^1,\xi^2\in \Omega\\ \Delta:~\Lambda_n\subset \Delta \Subset V}}\Big|\mu^l_t(\varphi|\eta_{\Lambda_n\setminus \{x\}}\xi^1_{\Delta \setminus \Lambda_n})-\mu^l_t(\varphi|\eta_{\Lambda_n\setminus \{x\}}\xi^2_{\Delta \setminus \Lambda_n})\Big|=0.
\end{equation}
A configuration which is not good is called \underline{bad}. If all configurations are good for $\mu^l_t$, the measure $\mu^l_t$ is called \underline{quasilocally Gibbs}.

[Lemma 25 (Krawtchouk transform functional equation) of arXiv:2609.03736, '2609.03736'] For every radial vector $u$,
\begin{equation}
 G_{\cK_nu}(z)=2^{-n/2}(1+z)^nG_u(\omega(z)).

\end{equation}
Thus, if $g\in\cE_n^\varepsilon$ with $\varepsilon\in\{-1,1\}$, then
\begin{equation}
 G_g(z)=\varepsilon2^{-n/2}(1+z)^nG_g(\omega(z)).

\end{equation}

[Proposition 10 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $\bu \in \StokesV$ and $\phi,\,\psi \in \newone{V}$. Then, the following equalities hold:  
   \begin{equation}
      (B_1(\bu,\phi),\psi)_{\newone{H}}= \duality{\tilde{B}_1(u,\phi)}{\psi}{\newone{V}}{\newonep{V}}.
    \end{equation}
Moreover, if $\bu \in \StokesV$, $\phi \in \newone{V}$, and $\psi \in \zero{H}{2}(\domO)$, then
      \begin{equation}
         (B_1(\bu,\phi),\psi)_{\newone{H}}= b_1(\bu,\phi,\psi).
      \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Question 19 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose that $\beta \neq \beta'$. Is it true that for any finite set of edges $F \subset E^d$, with $|F| \geq 2$, one has
    \begin{equation*}
        \E[ \bP_{\infty, \beta}^{\omega}(F \subset \cT)] \neq \E[ \bP_{\infty, \beta'}^{\omega}(F \subset \cT)] \, ?
    \end{equation*}
    Note that if $F$ consists of just a single edge, then by transitivity we clearly have an equality for the averaged law. (Stated as a question by the paper; open unless the paper says otherwise.)

[Corollary 9 of arXiv:2605.16560, 'Seasonal Statistics of Shannon Rate in a Dynamical Poisson-Voronoi Cellular Network'] The marginal pdf of  $R_{\sst I}$ is given by

\begin{align}
    f_{R_{\sst I}}(r) &= 4\la\pi r \; \mathrm{erfc}(r\sqrt{\la\pi}),\nn
\end{align}

for $r\geq 0$, where $\mathrm{erfc}(z)=\frac{2}{\sqrt{\pi}}\int_z^\infty e^{-z^2}{\rm d}z$.

\iffalse
\begin{enumerate}
\item $\E^0_{\Vcal_{\sst I}}\left[e^{-\g H_{\sst I}^2}\right]= \left(1+\frac{\g}{\la\pi}\right)^{-\frac{3}{2}}$ for any $\gamma\geq 0$,

\item $\E^0_{\Vcal_{\sst I}}\left[e^{-\b R_{\sst I}^2}\right]= \frac{2\la\pi}{\beta}\left[1-\left(1+\frac{\beta}{\la\pi}\right)^{-\half}\right]$, for any $\beta\geq 0$.
\end{enumerate}
\fi (Proof in the paper; no proof environment follows the statement in the TeX.)

