[Lemma martingale of arXiv:2505.04942, '\textbf{Randomized Routing to Remote Queues}'] Assume the conditions of Theorem~(theorem:load-balancing of the paper) hold. Then with probability 1,
	\begin{equation}
		\limsup_{n \to \infty} \frac{\max_{1\leq j \leq n^{\alpha}T}|M^{m}_{n,k}(j)|}{\sqrt{n^{\alpha}(\chi_{n}\log n \vee 1)}} \leq \sqrt{10 T}
	\end{equation}
	for $ \alpha > 0 $, $ T > 0 $, $ m = 1, \ldots, b $, and $ k = 1, \ldots, s $. Let $ \{ q_{n} : n\in \mathbb{N} \} $ be a sequence of positive integers such that $ \lim_{n \to \infty} q_{n}/(\log n)^{2} = \infty $. Then  with probability 1,
	\begin{equation}
		\limsup_{n \to \infty} \max_{1 \leq j \leq nT}\frac{\max_{1 \leq i \leq q_{n}}|M^{m}_{n,k}(j+i) - M^{m}_{n,k}(j)|}{\sqrt{q_{n}(\chi_{n}\log n \vee 1)}} \leq \sqrt{20}.
	\end{equation}
	Write $ \hat{M}^{m}_{n,k}(t) = M^{m}_{n,k}(\lfloor nt \rfloor)/\sqrt{n} $ for $ n \in \mathbb{N} $ and $ t \geq 0 $. Then, $ \sup_{0 \leq t \leq T} \hat{M}^{m}_{n,k}(t) \Rightarrow 0 $ as $ n \to \infty $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Local Fourier semi-norms of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Let $\alpha\in (\frac{1}{3},\frac{1}{2})$. 
Let $\square_1\subsetneq \square_2\subset \mathbf{Cyl}$ a strict inclusion of rectangles in our cylinder $\mathbf{Cyl}$ and $\chi\in C^\infty_c(\square_2)$ such that $\chi=1$ on $\square_1$. Then for any $T\in \mathcal{C}^{\alpha,\alpha-1}$   
\begin{equation}
 \boxed{ \sum_{j=0}^\infty 2^{j\alpha}   \Vert \mathcal{F}^{-1}\left( \sum_{k\in \mathbb{Z}^2}  \psi(2^{-j}k)  \widehat{T\chi} \right) \Vert_{L^\infty}  \leqslant \Vert \Vert_{\mathcal{C}^{\alpha,\alpha-1}}           }   
\end{equation}

[Proposition prop:capped-martingale-estimate-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exist constants \(C<\infty\), \(c>0\), and \(\eta>0\) such that, for every \(n\ge1\), every \(2^n\le\lvert\xi\rvert\le2^{n+1}\), and every \(d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\),
\begin{equation}
\mathbb{P}\left(
\left|
\widehat F^{\mathrm{pre,cap}}_{\xi,d,n}
\right|
>
2^{-sn/2}2^{-3\varepsilon n}
\right)
\le
C\exp(-c2^{\eta n}),
\end{equation}
and
\begin{equation}
\mathbb{P}\left(
\sup_{L>m_{\xi,d}}
\left|
\widehat F^{\mathrm{post,cap}}_{\xi,d,n,L}
\right|
>
2^{-sn/2}2^{-3\varepsilon n}
\right)
\le
C\exp(-c2^{\eta n}).
\end{equation}
Consequently, on \(\mathcal G_n^{\mathrm{pre}}\), the corresponding unstopped centered capped arrays satisfy the same estimates.

[Definition 1 of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] A stochastically continuous Markovian semigroup $P_t$ is called eventually Feller (see \cite{REISS2006SPA}) if there exists a $t_0 \geq 0$ such that for any $h \in C_b(\mathscr{D})$ the following two conditions are satisfied:
\begin{equation}
    P_t h \in C_b(\mathscr{D} ), \quad \text{for every } t \geq t_0, 
\end{equation}
\begin{equation}
    \lim_{s \downarrow t} P_s h(\xi) = P_t h(\xi), \quad \text{for every } \xi \in \mathscr{D} \text{ and } t \geq t_0.
\end{equation}
In particular, when $t_0 = 0$, $P_t$ is Feller.

[Lemma lemma4.4 of arXiv:2609.02607, 'Spatial inhomogeneity for a three-dimensional doubly degenerate nutrient system with indir'] Let $K>0$ with the property that (equation 1.6 of the paper) holds.  Then for each $\eta>0$, there exists $\delta_1=\delta_1(K,\eta)>0$ whenever $u_0, v_0$ and $w_0$ fulfill
(equation 1.2 of the paper), as well as
\begin{align}
    \int_{\Omega}v_0\leq \delta_1,
\end{align}
the solution $(u,v,w)$ of (equation 1.1 of the paper) obtained in Theorem (theorem 1.1 of the paper) satisfies
\begin{align}
    \|u(\cdot,t)-u_0\|_{(W^{1,\infty}(\Omega))^*}\leq \eta\qquad for \;all\; t>0.
\end{align}
Moreover, the corresponding limit function  from Lemma (lemma4.3 of the paper) admits
\begin{align}
   \|u_{\infty}-u_0\|_{(W^{1,\infty}(\Omega))^*}\leq \eta.
\end{align}

[Theorem 22 of arXiv:2605.16868, '\ttl'] For $\boldsymbol{F}\in\mathcal{R}$, the reflection map $R_F \coloneq (\Psi_F,\Phi_F)$ is Lipschitz.  Namely, for bounded parameters $(\gamma, k)$ we have
\begin{equation}

\|\Psi_F(X^1)-\Psi_F(X^2)\|_{T,1}\leq\frac{k}{1-\gamma}\|X^1-X^2\|_{T,1}\,,
\end{equation}
\begin{equation}

\|\Phi_F(X^1)-\Phi_F(X^2)\|_{T,1}\leq \left(1+\frac{2k}{1-\gamma}\right)\|X^1-X^2\|_{T,1}\,,
\end{equation}
for all $X^1,X^2 \in \mathcal{D}_T(L^1)$.

[Lemma ApprxSplit of arXiv:2609.02180, 'Helly-Type Theorems for Splitting Point Sets \thanks{A preliminary version of this article'] Let $P\subset {\mathbb R}^d$ be an $m$-point set, $1\leq k \leq d-1$, and let $\epsilon >0$. There exists a set $A\subseteq P$ of size at most $O\br{\frac{d}{\epsilon^2}\ln(\frac{d}{\epsilon})}$ with the following property:
  \begin{enumerate}[(i)]
    \item if $\tau$ is a $k$-flat that $\alpha$-splits $P$ then it $(\alpha-\epsilon)$-splits $A$;
    \item if $\tau$ is a $k$-flat that $\alpha$-splits $A$ then it $(\alpha-\epsilon)$-splits $P$.
  \end{enumerate}

[Lemma lem:nmlsi of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] For any $p\in\ensuremath{\mathcal P}_\ensuremath{\mathcal A}(\O)$, let $h=h(m_\ensuremath{\mathcal A}(p))$ denote the unique $h\in\G_\ensuremath{\mathcal A}$ such that $m_\ensuremath{\mathcal A}(\mu_{J,h})=m_\ensuremath{\mathcal A}(p)$, and let \(p_t\) denote the solution of (equation non-linear rqs of the paper) with initial datum $p$. If the system satisfies the Nonlinear MLSI with rate function $\ensuremath{\mathcal I}$, then 
\begin{equation}
    H(p_t|\mu_{J,h}) \le e^{-\ensuremath{\mathcal I}(h) t} H(p|\mu_{J,h})\,,\qquad t\ge 0.
\end{equation}

[Lem appendix_modulus_continuity of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] In the proof of Lemma~(lem:weak_conv of the paper), we find some $\delta > 0$ such that 
	\begin{equation} \mathbb{P}(w_T(\delta) > \varepsilon) < \eta \end{equation}
	for all $T$ large enough.

