\begin{equation*}\begin{split}
    &\widehat{Z}_n(u,v) = Z_n(T^{-1}(u,v)) = Z_n(u,h(u,v)) \quad \text{for $n \in {\mathbb N}$, and } \qquad 
    \widehat{Z}(u,v) = Z(T^{-1}(u,v)) = Z(u, h(u,v)) 
\end{split} \end{equation*} 
in $(u,v)\in V$. 
