body:
[Lemma 28 of arXiv:2605.13512, '2605.13512'] \leavevmode
\begin{enumerate}
\item
Fix finite $A<B$ and $\tau>0$. Then there exists a constant $C=C(A,B,\tau)$ such that for all
$A\le a<b\le B$ and all $s,t\in T\cup\{0\}$ with $0\le s,t\le \tau$,
\begin{equation}
\left|\int_a^b \lambda(x,t)\,dx-\int_a^b \lambda(x,s)\,dx\right|
\le C|t-s|.
\end{equation}

\item
If $t\in T\cup\{0\}$ and $(a,t),(b,t)\in {\rm Leb}(G\circ \lambda)$, then
\begin{equation}
\lim_{s\to t,\ s\in T}
\frac{1}{t-s}
\left(
\int_a^b \lambda(x,t)\,dx-\int_a^b \lambda(x,s)\,dx
\right)
=
G(a,\lambda(a,t))-G(b,\lambda(b,t)).
\end{equation}
\end{enumerate}

