[Proposition 3 (Second-chaos representation) of arXiv:2604.00642, 'Quantitative central limit theorem for an integrated periodogram via the fourth moment the'] There exists $k_n\in\Hh^{\odot 2}$ such that
\begin{equation*}
F_n=I_2(k_n).
\end{equation*}
Moreover, with
\begin{equation}
 A_{n,h}(\lambda,\mu):=\int_{-\pi}^{\pi} h(\omega)\,D_n(\lambda-\omega)\,D_n(\omega-\mu)\,\dd\omega,\qquad h\in L^1(-\pi,\pi),
\end{equation}
we have
\begin{equation}
 V_n=2\,\norm{k_n}_{\Hh^{\otimes 2}}^2
 =2n\int g(\lambda)g(\mu)\,\left| A_{n,f}(\lambda,\mu) \right|^2\,\dd\lambda\,\dd\mu.
\end{equation}

[Lemma lem:hi_invariance of arXiv:2605.31054, 'On the empirical spectral distribution of matrix perpetuities'] Assume that ${\mathbf u}{\mathbf A}{\mathbf A}^\top\,{\mathbf u}^\top\stackrel{d}{=}{\mathbf A}{\mathbf A}^\top$ for every orthogonal matrix ${\mathbf u}$. Fix $k\in\{1,\ldots,N\}$ and let $s>0$ be such that
$ {\mathbb E}\left[ \prod_{i=1}^k \lambda_i({\mathbf A}{\mathbf A}^\top)^{s/k}\right]<\infty$.
Then
\begin{align}
h_k(s)={\mathbb E}\left[\det\big(({\mathbf A}{\mathbf A}^\top)^{[k]}\big)^{s/k}\right].
\end{align}

