        \draw (3, 2) node[above]{$\sqsubset$};
      \end{tikzpicture}
      \caption{\centering The countermodel for Proposition (prop:eik-box-fragment of the paper).}

    \end{figure}
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

