[Prop dinh ly 2 of arXiv:2411.04081, 'A Multi-level Monte Carlo simulation for invariant distribution of Markovian switching L\''] Assume that \textbf{C4} holds with  $q=4p_0$;    $\sigma_\Delta, \gamma_\Delta$ satisfy (equation T3T4 of the paper). Moreover, assume that there exist constants $\widetilde{L_0}>0$, $\widetilde{{\zeta_0}} \in \mathbb{R}$ and $\widetilde{{\zeta_1}} \in[0, +\infty)$ such that for all $i \in S, x \in \mathbb{R}^d$,
		\begin{equation}
			|\gamma_{\Delta}(i,x)|\leq \widetilde{L_0}(1+|x|),
		\end{equation}
		and
		\begin{equation} 
			\langle x,b(i,x) \rangle  + \dfrac{p_0-1}{2}  |\sigma_{\Delta}(i,x)|^2 + \dfrac{1}{2\widetilde{L_0}}|\gamma_{\Delta}(i,x)|^2 \int_{\mathbb{R}_{0}^d}|z|\left(\left(1+\widetilde{L_0}|z|\right)^{p_0-1}-1\right) \nu(d z) \leq \widetilde{{\zeta_0}}  |x|^2+\widetilde{{\zeta_1}}.
		\end{equation}
Then, for any positive integer  $k \leq  p_0/2$,  there exists a positive constant $C$, which  depends neither on $t$  nor on $\Delta$, such that
		\begin{align*}
			\mathbb{E} \left[|\widehat{X}_t|^{2k} \right] \vee \mathbb{E} \left[|\widehat{X}_{\underline{t}}|^{2k}\right] \le \left\{ \begin{array}{l l}
				Ce^{{2k\widetilde{{\zeta_0}} t}} \quad &\text{ if \;\;} \widetilde{{\zeta_0}} >0,\\
				C(1+t)^{k} \quad &\text{ if \;\;} \widetilde{{\zeta_0}} =0,\\
				C \quad &\text{ if \;\;} \widetilde{{\zeta_0}} <0.
			\end{array} \right. 

		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem coupling of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] Let $\alpha \in (0,2)$ and $\beta > 0$. 
	Let $f \colon \mathbb{R}\times (0,\infty) \to \mathbb{R}$ measurable and $r_0 >0$ be such that, for any $r \geq r_0$, the function $f(\cdot,r)$ is even and the function $y \in [0,\infty) \mapsto (y/r)^\alpha (1+f(y,r))$ is non-decreasing.
	For any $r_0 \leq s < t$, $0 \leq x' \leq x$ and $0 \leq y' \leq y$,
	\begin{align*}
		\widetilde{G}^{|\cdot|}(s,x;t,y) \leq 2 \exp \mathopen{}\mathclose\bgroup\originalleft( \frac{(x'-y')^2 - (x-y)^2}{2(t-s)}\aftergroup\egroup\originalright) \widetilde{G}^{|\cdot|}(s,x';t,y').
	\end{align*}

