body:
[Lemma 21 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] For any measurable random variable $X=X(A)$,
    \begin{equation}
        \textup{Var}(X)\le \frac12 \expecb{ \int_{x\in \ZZ^d} |D_x X |^2},
    \end{equation}
    where 
    \begin{equation*}
     D_x X(A):=X(A)-X(A^{(x)}).
    \end{equation*}
Here $A^{(x)}$ is the random field defined by $A^{(x)}(x')=A(x')$ for $x'\neq x$, while $A^{(x)}(x)$ is an i.i.d. copy of $A(x)$.
    Moreover, this implies, for $p\ge 1$,
    \begin{equation}
        \expecb{|X-\expec X|^{2p}}^{\frac1p}\lesssim 4 p^2\expecb{\Big(\int_{x\in \ZZ^d} |D_x X |^2\Big)^p}^\frac1p.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2607.14062, 'Gilbert's disc model conditioned on the square lattice'] Let $p_1,p_2\in[1,\infty]$ with $p_1\leq p_2$. We have
    \begin{displaymath}
    R_{\min}^{\texttt{CN}}(p_2) \leq R_{\min}^{\texttt{CN}}(p_1)\text{, }
    R_{c}^{\texttt{CN}}(p_2) \leq R_{c}^{\texttt{CN}}(p_1)\text{, and }
    R_{\max}^{\texttt{CN}}(p_2) \leq R_{\max}^{\texttt{CN}}(p_1).
\end{displaymath}
    The same property holds for the nearest neighbor model.

[Proposition 16 (Jabin and Wang {\cite[Theorem 3) of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] {JW18}}]
     Let $E$ be a Polish space and $\rho\in\mathcal{P}(E)$ be a probability measure on $E$. Suppose that $\phi:E\times E\to\R$ is a measurable function satisfying the cancellation rule
     \begin{equation}
         \int_E\phi(x,y)\dd\rho(y)=0,\quad\forall x\in E.
     \end{equation}
     Then there exists a constant $C_2>0$, such that when $\|\phi\|_{L^{\infty}}\leq C_2$, one has
     \begin{equation}
         \sup_{N\geq 2}\int_{E^N}   \rho^{\otimes N}(X_N)\exp{\left(\frac{1}{N}\sum_{j,k=1}^{N}\phi(x_1,x_j)\phi(x_1,x_k)\right)}\dd X_N\leq C<+\infty,
     \end{equation}
     where $X_N=(x_1,x_2,\dots,x_N)$ for $N\geq 2$ and $C$ is a generic constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Determinantal cofactor comparison) of arXiv:2607.20329, '2607.20329'] For each $\F\in\{\R,\C\}$ and every $n\ge1$,
		\begin{equation}
			C_n^{\det}(C_n^{\det})^*
			\preceq_{\mathrm{Lt}}
			C_n^{\mathrm{per}}(C_n^{\mathrm{per}})^*.
		\end{equation}
		Moreover,
		\begin{equation}
			|\det G_n|^2\le_{\mathrm{Lt}}|\per G_n|^2.
		\end{equation}
		Finally, for every $z\in\F^{n+1}$,
		\begin{equation}
			0\le
			\E e^{\ii\RePart\langle z,C_{n+1}^{\mathrm{per}}\rangle}
			\le
			\E e^{\ii\RePart\langle z,C_{n+1}^{\det}\rangle}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:core of invariant lower probabilities of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an upper probability. Then
	\begin{longlist}
		\item	for any $P\in \operatorname{core}(V)$, there exists a unique $\hat{P}\in \mathcal{M}(T)\cap\operatorname{core}(V)$ such that $P(A)=\hat{P}(A)$ for any $A\in\mathcal{I}$;
		\medskip
		\item given $A\in\mathcal{F}$, if for any $P\in\operatorname{core}(V)$, $\hat{P}(A)=0$, then $V(A)=0$.
	\end{longlist}

