[Definition def-sol-infinity of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] Let $g\in L_{loc}^2([0,\infty);H)$. We say that $\theta$ is a weak solution of  
	\begin{equation}
		\partial_t\theta=-\Lambda^{2\alpha}\theta-R^{\perp}\theta\cdot\nabla \theta+\Lambda^{2\beta} g,
	\end{equation}
	if $\theta\in L^\infty_{loc}([0,\infty);H^{\alpha-2\beta}(\mathbb{T}^2)) \cap L^2_{loc}([0,\infty);H^{2\alpha-2\beta}(\mathbb{T}^2))\cap C([0,\infty);H_w^{\alpha-2\beta}(\mathbb{T}^2)),$ and for every $\varphi\in  C^\infty([0,\infty);H^\infty(\mathbb{T}^2)), $  for all $ t>0, $ 
	\begin{equation}
		\begin{aligned}
			\langle \theta(t),\varphi(t)\rangle&=\langle \theta(0),\varphi(0)\rangle-\int^t_0\langle \theta,\Lambda^{2\alpha}\varphi\rangle  \,\mathrm{d}s-\frac{1}{2}\int^t_0\left\langle R_2 \theta,\left[\Lambda, \partial_1 \varphi\right]\Lambda^{-1} \theta\right\rangle \,\mathrm{d}s\\&+\frac{1}{2}\int_0^t\left\langle R_1 \theta  ,\left[\Lambda, \partial_2 \varphi\right]\Lambda^{-1} \theta\right\rangle \,\mathrm{d}s+\int^t_0\langle \theta,\partial_s\varphi\rangle \,\mathrm{d}s+\int^t_0\langle\Lambda^{2\beta}\varphi,g\rangle \,\mathrm{d}s.
		\end{aligned}
	\end{equation}

[Lem l.01 of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] Let $\mathfrak{X}$, $\mu$, $Y$, $\xi$, and $\mathcal{G}[\mu,Y,\xi]$ be as in Section~(s.tools.gmc of the paper).
For every $0\leq f\inL(\mathfrak{X}^n)$, 
\begin{align}
	\mu^{\otimes n}f >0 \text{ implies that } \mathbb{P}\text{-a.s.\ } \mathcal{G}[\mu,Y,\xi]^{\otimes n}f>0 \ .
\end{align}

