[Proposition 7 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Assume the set-up \eqref{eq:OU_flow}--\eqref{eq:char_flow}. The following results hold uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$.

\noindent \emph{(i)} For any fixed $n_1,n_2\in\N$ and multi-indices $\bm{k}\in \N^{n_1},\bm{l}\in\N^{n_2}$ we have
\begin{equation}
\left(\E^{(W)}-\E^{(G)}\right)\left[\eta_t^{|\bm{k}|+|\bm{l}|}\Delta_t(\bm{k}) \overline{\Delta_t(\bm{l})}\right] =\mathcal{O}(\eta_t).

\end{equation}

\noindent \emph{(ii)} For $\beta=2$ and any fixed $p,q\in\N\cup\{0\}$ with $p+q\ge 3$ it further holds that
\begin{equation}
\left\vert \kappa_{p,q}\left(N\eta_t\langle G_t-m_t\rangle\right)\right\vert \lesssim  \frac{1}{\sqrt{N}}\bm{1}_{p+q=3} + \frac{1}{N}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:IBJ-multipoint of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable satisfies the mixed diamond
equation
\begin{align}
&\bigl(\Lambda_{\mathbf{a},
\mathbf{n}}
\mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}^{-1}
+ p_{t+1}
\mathcal{M}_{t+1, \mathbf{a}+\mathbf{2},
\mathbf{n}}^{-1}
q_{\mathbf{n}+\mathbf{1}}\bigr)
\mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
\nonumber \\
&{}-
\mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\bigl(p_{t+1}q_{\mathbf{n}+\mathbf{1}}
\mathcal{M}_{t, \mathbf{a},
\mathbf{n}+\mathbf{1}}
+ \mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}}
\Lambda_{\mathbf{a},
\mathbf{n}}\bigr) = 0,
\end{align}
at every $(t, \mathbf{a}, \mathbf{n})$ with
$a_i < y_{n_i+1} + t - 1$ for all~$i$, where
\[
q_{\mathbf{n}+\mathbf{1}}
\vcentcolon= \mathrm{Diag}(q_{n_1+1}, \dotsc, q_{n_m+1}), 
\Lambda_{\mathbf{a}, \mathbf{n}}
\vcentcolon= (I + B_{\mathbf{a}, \mathbf{n}}(\mathbf{a},
\mathbf{a}))
(I + B_{\mathbf{a}, \mathbf{n}+\mathbf{1}}(\mathbf{a},
\mathbf{a}))^{-1}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Finite-horizon error decomposition) of arXiv:2608.19762, '2608.19762'] Let
\(
    e_s:=\delta x_s-\widehat{\delta x}_s.
\)
Then, for every $h\geq1$,
\begin{equation}
\begin{aligned}
    e_{t+h}
    ={}&
    \Phi_{t+h,t+1}
    r_{B,t}(\xi_t)\\
    &+
    \sum_{j=t+1}^{t+h-1}
    \Phi_{t+h,j+1}
    \left(
        r_j^{\mathrm{sm}}
        +
        r_j^{\mathrm{sw}}
    \right).
\end{aligned}

\end{equation}

If $D\widetilde f_j$ is $L_j$-Lipschitz along the segment joining
$x_j^{\mathrm c}$ and $x_j^{\mathrm c}+\delta x_j$, then
\begin{equation}
\begin{aligned}
    &\|e_{t+h}\|
    \leq{}
    \|\Phi_{t+h,t+1}\|
    \|r_{B,t}(\xi_t)\|\\
    &+
    \sum_{j=t+1}^{t+h-1}
    \|\Phi_{t+h,j+1}\|
    \left(
        \frac{L_j}{2}\|\delta x_j\|^2
        +
        \|r_j^{\mathrm{sw}}\|
    \right).
\end{aligned}

\end{equation}

If, in addition, $F_{t+h}$ has an $L_{F,t+h}$-Lipschitz gradient along the
segment joining $\theta_{t+h}^{\mathrm c}$ and
$\theta_{t+h}^{\mathrm s}$, then
\begin{equation}
\begin{aligned}
    \bigl|
        \delta F_{t+h}
        -
        c_{t+h}^{\top}
        \Phi_{t+h,t+1}
        B_t\xi_t
    \bigr|
    &\leq{}
    \|c_{t+h}\|\,\|e_{t+h}\|\\
    &+
    \frac{L_{F,t+h}}{2}
    \|\delta\theta_{t+h}\|^2.
\end{aligned}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2609.02699, '\vspace{-0.5 cm}Gauge theory and symplectic structures'] The equations on an almost Hermitian manifold $(M,g,J)$ for 
$A\in\mathcal{A},\beta\in\displaystyle\bigoplus_{p>0}\mathrm{Re}(\Omega^{0,2p+1}),\phi\in\Gamma(S_+)$ are
\begin{align}
    D_{A,\beta}\phi=0\\
    \Pi(F_A-F_{{A^{\mathrm{Ch}}}}+F_\beta+rq(\psi_0))=\Pi(q(\phi))
\end{align}

