body:
[Definition def:PfaffHaf of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] For a $2n \times 2n$ skew-symmetric matrix $M$, the Pfaffian of $M$ is defined by
\begin{align}
 \operatorname{Pf}(M)=\frac{1}{2^n n!} \sum_{\sigma\in S_{2n}} \operatorname{sgn}(\sigma) \prod_{i=1}^n M_{{\sigma(2i-1)},{\sigma(2i)}}
 = \sum_{\alpha\in \Pi_{2n}} \operatorname{sgn}(\pi_\alpha) \prod_{i=1}^n M_{\alpha_{i,1},\alpha_{i,2}},
\end{align}
while for a $2n \times 2n$ symmetric matrix $M$, the Hafnian of $M$ is defined by
\begin{align}
 \operatorname{Hf}(M)=\frac{1}{2^n n!} \sum_{\sigma\in S_{2n}} \prod_{i=1}^n M_{{\sigma(2i-1)},{\sigma(2i)}}
 =\sum_{\alpha\in \Pi_{2n}} \prod_{i=1}^n M_{\alpha_{i,1},\alpha_{i,2}}.
\end{align}
Here $\Pi_{2n}$ refers to the set of matchings on $[\![2n ]\!]$, i.e., partitions $(\alpha_{1,1},\alpha_{1,2}), \dots, (\alpha_{n,1},\alpha_{n,2})$ of $[\![2n ]\!]$ with $\alpha_{i,1}<\alpha_{i,2}$ and $\alpha_{1,1}<\cdots<\alpha_{n,1}$. In the Pfaffian formula, $\pi_\alpha$ denotes the corresponding permutation $(\alpha_{1,1},\alpha_{1,2}, \alpha_{2,1},\alpha_{2,2},\dots, \alpha_{n,1},\alpha_{n,2})$.

[Theorem thm:axial of arXiv:2608.30254, 'Exact Recovery Thresholds for Weighted Data Selection\\ in Vector-Valued Linear Regression'] For every $d,m\ge1$,
\[
  \frac{L^{\star}_{D_{d,m}}\bigl((m+1)d-1;\mathrm{weighted}\bigr)}
       {L^{\star}_{D_{d,m}}}
  \;=\;1+\frac{m+1}{2md\,(m^2+m-1)}\;>\;1 .
\]

[Thm herm_corner of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Fix a positive integer $n$, let $\lambda \in \Sig_n$, and let $A$ be a random element of $\Her_n(F)$ distributed by the $K$-invariant measure with singular numbers $\lambda$. Then the singular numbers of its top-left $(n-1) \times (n-1)$ corner $A'$ are given by
    \begin{equation}
        \Pr(\SN(A') = \nu) = \sum_{\kappa \in \Sig_{n-1}} \frac{P_{\lambda/\kappa}(1;t) P_\kappa(t,\ldots,t^{n-1};t)}{P_\lambda(1,\ldots,t^{n-1};t)} \cdot \frac{ Q_{\nu/\kappa}(-1;t)P_\nu(t,\ldots,t^{n-1};t)}{P_\kappa(t,\ldots,t^{n-1};t) \Pi_t(-1;t,\ldots,t^{n-1})}
    \end{equation}
    where $t=-q^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma pi=rho of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] Let $\widehat\pi^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}$ and $\widehat\gamma^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}$ be two shift-covariant non-crossing systems of geodesics such that $\widehat\mathbb{P}\{\widehat\pi^0\preceq\widehat\gamma^0\}=1$. Assume that either $\widehat\pi^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}\in{\widehat{\mathbbold\Pi}_c}$ or $\widehat\gamma^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}\in{\widehat{\mathbbold\Pi}_c}$. Assume also that there exists a cocycle ${\widehat B}\in\widehat{\mathcal{K}}$ such that both $\widehat\pi^u$ and $\widehat\gamma^u$ are ${\widehat B}$-geodesics for all $u\in\mathbb{Z}^2$. 
    That is, 
    \begin{align}
    \widehat\mathbb{P}\bigl\{{\widehat\omega}:\forall u\in\mathbb{Z}^2,\forall n\ge u\cdot(e_1+e_2):{\widehat B}({\widehat\omega},\widehat\pi_n^u({\widehat\omega}),\widehat\pi_{n+1}^u({\widehat\omega}))=\omega_{\widehat\pi_n^u({\widehat\omega})}({\widehat\omega})\bigr\}=1
    \end{align}
    and
    \begin{align}
    \widehat\mathbb{P}\bigl\{{\widehat\omega}:\forall u\in\mathbb{Z}^2,\forall n\ge u\cdot(e_1+e_2):{\widehat B}({\widehat\omega},\widehat\gamma_n^u({\widehat\omega}),\widehat\gamma_{n+1}^u({\widehat\omega}))=\omega_{\widehat\gamma_n^u({\widehat\omega})}({\widehat\omega})\bigr\}=1.
    \end{align}
    Then $\widehat\mathbb{P}\{\forall u\in\mathbb{Z}^2:\widehat\pi^u=\widehat\gamma^u\}=1$.

