[Definition 19 (Pairwise Disagreement~\citep{black2022model}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] The pairwise disagreement of the empirical Rashomon set $\emprashomonset$, at a test instance $x$, is the average disagreement between pairs of models $f_{k},f_{l} \in \emprashomonset$ and is defined as,
\begin{align}
      \pairwisedisag(x) = \frac{1}{\abs{\emprashomonset}(\abs{\emprashomonset}-1)}\sum_{h_k,h_l \in \emprashomonset, h_k \ne _l}\Indic{h_{k}(x) \ne h_{l}(x)},
\end{align}  
where $h(x)= \Indic{f(x) \geq \frac{1}{2}}$ is the hard decision of $f$.

[Lemma 43 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let	$A \in \Sym(\Hcal)\cap\HS(\Hcal)$, $I+A > 0$. Then
		$(A-\log(I+A))\in \Sym^{+}(\Hcal) \cap\Tr(\Hcal)$. Furthermore,
		\begin{align}
			||A-\log(I+A)||_{\tr} = -\log\dettwo(I+A) \leq ||(I+A)^{-1}||\;||A||^2_{\HS}.
		\end{align}

