body:
[Proposition 21 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,\|\cdot\|_X)$ and $(Y,\|\cdot\|_Y)$ be finite dimensional normed spaces. Let $c: X \times Y \to \R$ be a continuous cost function that is positively 1-homogeneous in the second variable, meaning $c(x, ty) = tc(x,y)$ for all $t > 0$.

    Suppose a bounded set $K\subset X$ satisfies the non-degeneracy condition:
    \begin{equation}

        \inf_{u \in \mathbb{S}_Y} \sup_{x \in K} -c(x,u) = \epsilon > 0,
    \end{equation}
    where $\mathbb{S}_Y = \{y \in Y \mid \|y\|_Y = 1\}$. Let $L \subset Y$ be a non-empty set and suppose that $-c$ is non-negative on $K\times L$. Set $M(K,L) = \sup_{x\in K, y\in L} -c(x, y)$. Then,
    \begin{enumerate}
        \item If $L$ is unbounded, then $M(K,L)=\infty$.
        \item If $L$ is bounded, then $0\leq M(K,L)<\infty$ and $L\subseteq M(K,L)K^{\circ, c}$. Moreover, if $-c(x,y)=0$ for all $x \in K$ implies $y=o$, then $M(K,L)=0$ implies $L=\{o_Y\}$.
    \end{enumerate}

[Lemma 15 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $0<s<t$, $n,k\geq 1$, $x\in E$ and $z\in\mathbb R^d$ we set 
\begin{align*}
\phi_{s,t}^{n,k}(z,x):=\mathbf E_x\big[f_1(\mathbf Z_s^{n,z})\,f_2(\mathbf Z_t^{n,z})\,\mathbf 1_{\{\tau_{k-1}^n<s<t\leq\tau_k^n\}}\big].
\end{align*}
Then, for all $T>0$, $0<s_1<s_2<T$, $t_1<t_2<T$ and $L,M>0$ we have
\begin{align*}
&\lvert\phi_{s_1,t_1}^{n,k}(y,x)-\phi_{s_2,t_2}^{n,k}(y,x)\rvert\\
&\leq\big(\|f_1'\|_\infty\,\|f_2\|_\infty\,(s_2-s_1)+\|f_1\|_\infty\,\|f_2'\|_\infty\,(t_2-t_1)\big)\,\Big(L\,(\lvert z\rvert+TM)\,e^{TL}+M\Big)\\
&+2\,\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(s_2\leq\tau_k^n,L_{s_2}^n>L)+\mathbf P_x(s_2\leq\tau_k^n,M_{s_2}^n>M)\big)\\
&+\|f_1\|_\infty\,\|f_2\|_\infty\,\mathbf P_x(s_1\leq\tau_{k-1}^n<s_2)+\mathbf P_x(t_1\leq\tau_k^n<t_2)+\mathbf P_x(t_2\leq\tau_k^n,L_{t_2}^n>L)\\
&+\mathbf P_x(t_2\leq\tau_k^n,M_{t_2}^n>M)\big)+\mathbf P_x(s_1\leq\tau_{k-1}^n<s_2)+\mathbf P_x(t_1\leq\tau_k^n<t_2)\big).
\end{align*}

[Definition def:families of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $n, m \geq 1$. The three family types, each with a \emph{base} and \emph{flipped-pair} class, are:
\begin{align*}
	\text{torus-torus:} \quad
	& T^{tor}_n \cup_C \overline{T^{tor}_m}
	&& \bigl(T^{tor}_n\bigr)^{\mathrm{fl}} \cup_C
	\overline{\bigl(T^{tor}_m\bigr)^{\mathrm{fl}}} \\
	\text{twist-torus:} \quad
	& T^{tw}_n \cup_C \overline{\bigl(T^{tor}_m\bigr)^{\mathrm{fl}}}
	&& \bigl(T^{tw}_n\bigr)^{\mathrm{fl}} \cup_C
	\overline{T^{tor}_m} \\
	\text{twist-twist:} \quad
	& T^{tw}_n \cup_C \overline{T^{tw}_m}
	&& \bigl(T^{tw}_n\bigr)^{\mathrm{fl}} \cup_C
	\overline{\bigl(T^{tw}_m\bigr)^{\mathrm{fl}}}
\end{align*}
In each case the first tangle variant occupies the inside ball, the mirrored variant the outside ball, and the boundary Conway spheres are identified as in Figure (fig:families of the paper), matching the strand endpoints so that the union of the four strand arcs is a single circle. In each type, the flipped-pair gluing is obtained from the base gluing by flipping both slots. The resulting knots are the \emph{$(n, m)$ knots} of their type and class, collectively the \emph{family knots}.

[Lemma 147 of arXiv:2601.16377, '2601.16377'] Consider two discrete ensembles satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the Conditions 1.,2.,3.,4.,5. of the additional Assumption~\ref{Assumptions_extra} with $H = 1$. Assume the two ensembles differ only by the weights $w^{(0)}$ and $w^{(1)}$ and the regular parts of the potential $U^{(0)}$ and $U^{(1)}$ appearing in Assumption~\ref{Assumptions_analyticity}. Their respective unique band are denoted $(\alpha^{(0)},\beta^{(0)})$ and $(\alpha^{(1)},\beta^{(1)})$.
 For any $\eta>0$ there exists $\eps>0$ depending only on the constants in the assumptions and $\eta$, such that if
 \begin{equation}
  |\alpha^{(0)}-\alpha^{(1)}|+|\beta^{(0)}-\beta^{(1)}|<\eps,
 \end{equation}
 then for all $u \in [0,1]$, the discrete ensemble with weight $w^{(u)}(x)= \big(w^{(0)}(x)\big)^{1-u} \cdot \big(w^{(1)}(x)\big)^{u}$ and regular part of the potential $U^{(u)} = (1-u)U^{(0)} + uU^{(1)}$ also satisfies Assumptions \ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the Conditions 1.,2.,3.,4.,5. of the additional Assumption~\ref{Assumptions_extra}, with constants that can be chosen independently of $u$. Denoting $(\alpha^{(u)},\beta^{(u)})$ the unique band of the corresponding ensemble, we have
\begin{equation}

\sup_{u \in [0,1]} \big( |\alpha^{(u)}-\alpha^{(0)}|+|\beta^{(u)}-\beta^{(0)}|\big)<\eta.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

