[Corollary gumbel of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] \phantom{a}
\begin{itemize}
\item[(a)]
For $x>0$ and real $s$,
\begin{align}
\lim_{\varepsilon\to0^+}F(x,({s-\log\varepsilon})/{\varepsilon};e^{-\varepsilon})=\exp \left({-xe^{-s}}\right).
\end{align}
\item[(b)]
The counting function $N_q$ of the absolute squares of zeroes of the Gaussian power series ${\varphi (z)}=\sum_{k\ge 0} c_k z^k $ conditioned on the event that $|g(0)|^2=t$ converges in distribution, in the scaling limit
\begin{align}
q\to 1^{-}\,\, \text{ and }\,\, t=\frac{s-\log \log \frac1 q }{\log \frac 1 q},
\end{align}
 to Poisson$(e^{-s})$.
\end{itemize}

