[Defn 3 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] \begin{enumerate}
 \item[\rm (i)]
 We say condition   ${\bf (ED)} _{\leq, x_0, R}$ holds
  if for the  ball $B=B(x_0, R)$ with $\overline B \subsetneq \sX$,
  there is a constant $C_1=C_1(x_0, R)>0$  so that   for
      any  open subset $ U\subset 2^{-1}B$ and every $  x\in B_U(x_0,  R/64)$,
\begin{equation}
\P_x  \big( X^{B}_{\tau_{B_U(x_0, R/32)}} \in U \big)
\leq   C_1\E_x[\tau_{B_U(x_0,  R/32)}]  .
 \end{equation}

  \item[\rm (ii)]
We say condition  ${\bf {(\wh{ED})}} _{\leq, x_0, R}$ holds
 if for the  ball $B=B(x_0, R)$ with $\overline B \subsetneq \sX$,
there is a constant $C_2=C_2(x_0, R)>0$  so that  for
 any  open subset $  U\subset 2^{-1}B$ and
every $x\in  U \cap A(x_0, 3R/8, R/2)$,
\begin{equation}
\P_x  \Big( \wh X^{B}_{\wh\tau^B_{U\cap  A(x_0, R/4, R/2)}}  \in U \Big)
\leq   C_2\E_x \left[ \wh\tau^{B}_{U\cap  A(x_0, R/4, R/2)} \right] .
 \end{equation}

\item[\rm (iii)] We say condition  ${\bf (ED)}^s _{\leq, R}$
  (resp. ${\bf (\wh {ED} ) }^s_{\leq, R}$) holds
 if  \eqref{e:ED1} holds  with $C_1=C_1 (R)$ (resp.  \eqref{e:ED2} holds with constant $C_2=C_2(R)$)
for any ball $B$ with radius $R$  and  $\overline B \subsetneq \sX$.

 \end{enumerate}

[Theorem 7 (Critical rescaled power variation) of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] Assume $H=K$.  Then, $\Pp$-a.s.~for every $t\in[0,1]$,
\begin{equation}
\lim_{n\uparrow\infty}
\frac1{n^{1/(2H)}}
\sum_{k=0}^{\floor{tb^n}-1}
\abs{Y((k+1)b^{-n})-Y(kb^{-n})}^{1/H}
=
\frac{2^{1/(2H)}\Gamma\big(\frac{H+1}{2H}\big)}{\sqrt\pi}\,t.
\end{equation}
In particular, almost all sample paths of $Y$ have infinite $b$-adic $(1/H)^{\text{th}}$ variation:
\begin{equation}
 V_n^{(1/H)}(Y,t)  \longrightarrow+\infty\qquad\text{for every $t\in(0,1]$ $\Pp$-a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 18 of arXiv:2608.29761, '2608.29761'] Let $\mathcal P$ be a finite collection of points in $\M$, and $\delta>0$. We say that $\mathcal P$ is a $\delta$-net  if
\begin{itemize}
\item[(a)] for any $p\in \M$ there exists $p_j \in \mathcal{P}$ such that $\dis_{\M}(p,p_j)< \delta$,
\vskip .1cm
\item[(b)] for any $p_1,p_2\in\mathcal P$ we have  $ \dis_{\M}(p_1,p_2)\ge \delta$. 
\end{itemize}

[Lemma L:K6-7 of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] Let $\mathsf{K}_6(t, r_1 \vee r_2; \varepsilon, \eta)$ and $\mathsf{K}_7(t, r_1 \vee r_2; \varepsilon, \eta)$ be defined in equation (equation E:Second-der-X-W2W2 of the paper). Then, for any $p \in \mathbb{N}$ and $t \ge r_1 \vee r_2,$ there exists a time-independent positive constant $K$ such that
\begin{equation*}
\begin{aligned}
\mathsf{K}_6(t, r_1 \vee r_2; \varepsilon, \eta) + \mathsf{K}_7(t, r_1 \vee r_2; \varepsilon, \eta)  & \le K \left[\varepsilon^p + \frac{\varepsilon^p}{\eta^{p}} \right] e^{-(2p) \alpha (t- r_1 \vee r_2 )}  e^{-(2p)\frac{\lambda}{ \eta}(r_1 \vee r_2- r_1 \wedge r_2)}. \\

\end{aligned}
\end{equation*}

