body:
[Lemma 10 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] Let $\alpha>0$ and $\kappa\geq\kappa_c$. Let $u,v,w$ be vertices such that $v$ lies on the geodesic between $u$ and $w$. Then 
\begin{equation}
\P(\exists \ell\in\mathcal L_{\alpha,\kappa}\,:\, u,v \in \ell\text{ and }w\notin\ell) = 1 - \big(1 - \tau_\kappa^{2d(u,v)}\big)^\alpha\big(1 - \tau_\kappa^{2d(u,w)}\big)^{-\alpha}.
\end{equation}

[Conj 92 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $M>0$ and $\eta>0$.
The following asymptotic expansion holds in
$L^{2}(d\PP,\sigma((B_{t})_{0\leq t< \zeta_M}),H^{-\eta}(\C))$.
For every $N\geq 1$,
\begin{align*}
&\ind_{S_{\varepsilon}^{\rm CR}(\zeta_M)}
\\&
=
\sum_{n=1}^{N} \dfrac{(-1)^{n-1}}{n!}
\hat{\mu}^{\rm loop}_{\text{SLE}_{8/3}}
\Big(
\Big(\frac{1}{\pi}\vert \log (\varepsilon d(0,\Gamma)/\CR(0,\inter{\Gamma}))\vert + \cst (M)\Big)^{-n}
\Big)
:\Theta_{\zeta_M}^{n}:
\, + o(\vert \log\varepsilon\vert^{-N})
\\&
=
\sum_{n=1}^{N}  \dfrac{(-1)^{n-1}}{n!}
\dfrac{1}{\big(\frac{1}{\pi} \vert \log \varepsilon\vert\big)^{n}}
\sum_{k=1}^{n} 
\dfrac{n!(n-1)!}{(n-k)! k! (k-1)!} C^{\text{SLE}_{8/3}}_{n-k,M}\,
:\Theta_{\zeta_M}^{k}:
\, + o(\vert \log\varepsilon\vert^{-N}).
\end{align*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition 14 (Upward and downward one-sided exit problem) of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] Let  $q,\lambda > 0$,. Then,  the following limit cases, in terms of the resolvents $\overline{r}^{(q+\lambda)}$ and  $\underline{r}^{(q+\lambda)}$ defined in \textnormal{\textbf{(S1)}}, hold 
	\begin{itemize}
		\item[\upshape{(i)}] For $a,b \in \R_+$, 
		\begin{align}
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{a,U}^+} \1_{\{\tau_{a,U}^+ < \infty\}} \Bigr) &= \ee^{-\Phi_{q+\lambda}(a-x)} + \ee^{-\Phi_{q+\lambda}a} \cdot\frac{\lambda \int^{a}_{-\infty} \overline{r}^{(q+\lambda)}(x,y) \dd y}{1- \lambda \int^{a}_{-\infty} \overline{r}^{(q+\lambda)}(0,y) \dd y}, \quad x \in (-\infty,a], \notag \\
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{b,U}^-} \1_{\{\tau_{b,U}^- < \infty\}} \Bigr) &= {Z}^{(q+\lambda)}(x-b) - \frac{q+\lambda}{\Phi_{q+\lambda}} W^{(q+\lambda)}(x-b) + \lambda \int^\infty_b \underline{r}^{(q+\lambda)}(x,y) \dd y, \quad x \in [b,\infty). \notag
		\end{align}

		\item[\upshape{(ii)}] For $a,b \in \R_-$,
		\begin{align}
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{a,U}^+} \1_{\{\tau_{a,U}^+ < \infty\}} \Bigr) &= \ee^{-\Phi_{q+\lambda}(a-x)} + \lambda \int^{a}_{-\infty} \overline{r}^{(q+\lambda)}(x,y) \dd y, \quad x \in (-\infty,a], \notag \\
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{b,U}^-} \1_{\{\tau_{b,U}^- < \infty\}} \Bigr) &= {Z}^{(q+\lambda)}(x-b) - \frac{q+\lambda}{\Phi_{q+\lambda}} W^{(q+\lambda)}(x-b) \notag \\
			&\quad \quad + Z^{(q+\lambda)}(-b) \cdot \frac{ \lambda \int^\infty_b \underline{r}^{(q+\lambda)}(x,y) \dd y}{\lambda \int^\infty_b \underline{r}^{(q+\lambda)}(0,y) \dd y}, \quad x \in [b,\infty). \notag
		\end{align} 
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 11 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $\sigma, \alpha > 0$,
\begin{align*}
    \sigma \le c^{\SE}(\sigma, \alpha) \le \sigma \vee 2\alpha,
\end{align*}
and the constant $\sigma \vee 2\alpha$ is itself admissible: every $X \in \SE(\sigma^2,\alpha)$ satisfies $X \lecx (\sigma \vee 2\alpha)\,\Lap$.

