body:
[Theorem 1 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] Assume that under $\bbQ$ the conductances are i.i.d.\ (or more generally that $\bbQ$ satisfies a mixing condition, see Remark~\ref{rem:Discussion}, 1)). Then, there exists $\Omega_{\mathrm{typ}}$ with full $\bbQ$-measure such that for all $\omega\in \Omega_{\mathrm{typ}}$
\begin{itemize}

    \item[i)] \begin{equation}
        \lim_{N\to\infty} \frac{1}{N^{d-2} \log N}\log \bbP^\omega[\cW_N^+] = - 2 \overline{g} \,\capa^{\mathrm{hom}} (V)\,,
    \end{equation}
    \item[ii)]
    \begin{equation}
        \lim_{N\to\infty} \sup_{x\in  \bbZ^d} \bigg|\frac{\bbE^\omega[\varphi_x|\cW^+_N]}{\sqrt{4 \overline{g} \log N}} - \mathscr{h}^{\mathrm{hom}}_V(x/N)\bigg| = 0\,,
    \end{equation}
    \item[iii)] setting $a_N = \bbE^{\omega} [\varphi_0 | \cW^+_N]$, we have
\begin{equation}
    \hat{\bbP}^\omega_N  \to \bbP^\omega 
\end{equation}
    weakly as $N \to \infty$,
where $\hat{\bbP}^\omega_N$ is the law of the field $\varphi - a_N$ under $\bbP^\omega[ \, \cdot \,| \cW^+_N]$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:loctimemoments of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Under Assumption (assump:initdiff of the paper), for all $T \in [0,\infty)$, $\xi \in (0,\infty)$, and $r \in [1,\infty)$, the following bounds hold: 
\begin{equation} 
\sup_{j \in \mathbb{Z}} \mathbb{E} e^{\xi L_{(j,j+1)}(T)} < \infty;
\end{equation}
and consequently,
\begin{equation} 
\sup_{j \in \mathbb{Z}} \mathbb{E}|L_{(j,j+1)}(T)|^r < \infty.
\end{equation}

