body:
[Prop eq:greedy.path.u of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{prop:greedy.path}
   Let
   $(0,0)_0=(r_0,s_0)_0\to(r_1,s_1)_1\to\cdots$ be the
   $k$-greedy infection path. There exist constants $C,c$
   depending only on $\lambda$ and $k$ such that for all $n$ and all $t\geq 5$,
   \begin{align}
     \mathbf{P}\Biggl(\abs[\bigg]{r_n-\frac{\crist[k]n^2}{2}}\geq tn^{3/2}\Biggr) &\leq C\exp\biggl(-\frac{ct^2}{1+\frac{t}{\sqrt{n}}}\biggr),\\\intertext{and}
     \mathbf{P}\biggl(\abs[\Big]{s_n-\crist[k]n}\geq t\sqrt{n}\biggr)&\leq 2e^{-ct^2}.
   \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma cint of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For all $x,y\in[n]$ with $x\neq y$  and uniformly over $u\in [0,1]$, we have
\begin{align}
\mathbb E\bigl[u^{d(x)+d(y)}\mathbf{1}_{x,y\in\mathcal{Q}_n\cap \mathcal{T}_n}  \mathbf{1}_{B_{\omega}(x)\cap B_{\omega}(y)\neq  \varnothing}\bigr]  = \frac{c_{\textrm{int}}(w,u)}{n}+ O\Bigl(\frac{1}{n^2}\Bigr),
\end{align}
where 
\begin{equation}
c_{\textrm{int}}(w,u) :=  2\sum_{(i,j)\in \mathcal{M}} \mathbb E^{i,j,\ell_{i,j}}_{\mathbf{Y},\mathbf{Y}'} \bigl[u^{Y_k+Y_k'}\mathbf{1}_{Y_{2k}=Y_{2k}'=0}\bigr].
\end{equation}
where $\mathbb E^{i,j,\ell_{i,j}}_{\mathbf{Y},\mathbf{Y}'} \bigl[u^{Y_k+Y_k'}\mathbf{1}_{Y_{2k}=Y_{2k}'=0}\bigr]$ is explicitly given by Proposition~(prop:cross_monster of the paper), 
	and where $\mathcal{M}=\mathcal{M}(w^2)$, $\ell_{i,j}=\ell_{i,j}(w^2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

