[Definition 57 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $(H_s)_{s \ge 0}$ denote the height function at time $s$ for the Glauber dynamic on $\mX$, with floor constraint $\cH_{-q_0}$ and ceiling constraint $\cH_{q_0}$ (as in \Cref{def:constrained}), started from the maximal configuration compatible with these constraints (recall \Cref{def:partorder}). Then, for each $j \in [0, \mathfrak{j}]$ and $w \in \mathfrak{X}$, let 
\begin{flalign}

	H_{s,j} (w) = H_s (w) + (j-\mathfrak{j}) N^{M\delta-1}.
\end{flalign}

[Lemma lem:maximum principle trunc of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that the sequence of functions  $\psi^N (t)= (\psi_N(t, n ))_{n \in \mathbb N^M }  $ that are such that for every $n \in \mathbb N^M $ the function  $ t \mapsto \psi_N(t, n )$ is continuously differentiable and satisfies the following equation 
        \begin{align} 
 \partial_s  \psi^N(s, n)   -  
   \mathcal L^N_r[ \psi^N (s) ](n) - \bar{ \mathcal L}_s^N [ \psi^N (s) ](n) \leq 0 , \quad s \geq 0  \quad n \in \mathbb N^M     
\end{align}
    with initial datum $ \psi (0) = \psi_0 \in c_{00} (\mathbb N^M)$.
    Then 
    \begin{align*}
       \sup_{ t \in [0, \infty) } \max_{ n \in \mathbb N^M } \psi^N (t, n ) \leq    \sup_{ n \in \mathbb N^M } \psi_0 ( n ). 
    \end{align*}
    Moreover if $\psi^N $ attains a maximum at time $ t= \overline t  $, then $ \psi^N $ is constant. 

    Assume that the sequence of functions  $\psi^N (t)= (\psi_N(t, n ))_{n \in \mathbb N^M }  $ that are such that for every $n \in \mathbb N^M $ the function  $ t \mapsto \psi_N(t, n )$ is continuously differentiable and satisfies
        \begin{align} 
 \partial_s  \psi^N(s, n)   -  
   \mathcal L_r[ \psi^N (s) ](n) -  \mathcal L_s [ \psi^N (s) ](n) \geq 0 , \quad s\geq 0, \quad n \in \mathbb N^M     . 
\end{align}
    with initial datum $ \psi (0) = \psi_0 \in c_{00} (\mathbb N^M)$.
    Then 
    \begin{align*}
  \inf_{ t \in [0, \infty)   } \min_{ n \in \mathbb N^M } \psi^N (t, n ) \geq   \sup_{ n \in \mathbb N^M } \inf_0 ( n ) . 
    \end{align*}
    Moreover if $\psi^N $ attains a minimum at time $ t= \overline t  $, then $ \psi^N $ is constant.

