[Theorem thm:main2 of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Assume that $\alpha_e=0$, and for any $t\in [0,T]$, $\varphi\in\mathscr{S}(\mathbb{R} )$ define
    \begin{equation*}
        \mathcal{Z}_t^{N ,1}(\varphi ) = \mathcal{Y}_t^{p,N}(T_{v_1N^{a-1}t}\varphi) - \frac{\rho}{\mathcal{E}}\mathcal{Y}_t^{e,N}(T_{v_1N^{a-1}t}\varphi) \qquad \mbox{ and }\qquad  \mathcal{Z}_t^{N ,2}(\varphi ) = \mathcal{Y}_t^{p,N}(T_{v_2N^{a-1}t}\varphi)
    \end{equation*}
    where $v_1 = \frac{\alpha_p (\kappa -1)(1-\rho )}{N^\gamma}$ and $v_2 = \frac{\alpha_p(\kappa -1)(1-2\rho )}{N^\gamma}$. Then, in the diffusive timescale $a=2$ and with a weak asymmetry given by $\gamma =\frac12$, the couple of processes $(\mathcal{Z}^{N,1},\mathcal{Z}^{N,2})_{N\ge 1}$ converges in distribution, as $N\to\infty$ to a pair of independent processes $(\mathcal{Z}^1,\mathcal{Z}^2)$ starting from independent spatial white noises with respective variances $\sigma_1$ and $\sigma_2$, where $\mathcal{Z}^1$ is a solution to the Ornstein-Uhlenbeck equation 
    \begin{equation*}
        \partial_t\mathcal{Z}_t^1 = (\kappa -1)\Delta \mathcal{Z}_t^1 +\sqrt{\smash[b]{2(\kappa -1)\sigma_1^2}}\nabla\dot{\mathcal{W}}_t^1
    \end{equation*}
    in the sense of (defin:OUsolution of the paper), while $\mathcal{Z}^2$ is an energy solution to the SBE
    \begin{equation*}
        \partial_t\mathcal{Z}_t^2 = (\kappa -1)\Delta\mathcal{Z}_t^2 + \mathfrak{g}_2\nabla (\mathcal{Z}_t^2)^2 + \sqrt{\smash[b]{2(\kappa -1)\sigma_2^2}} \nabla\dot{\mathcal{W}}_t^2
    \end{equation*}
    in the sense of (defin:energysolution of the paper). Above, $(\mathcal{W}^1,\mathcal{W}^2)$ are two independent $\mathscr{S}'(\mathbb{R} )$-valued Brownian motions, and the parameters are given by
    \begin{equation*}
        \mathfrak{g}_2 = -\alpha_p(\kappa -1) ,\qquad \sigma_1^2 = \frac{\rho \big( 1-\frac{\rho}{\mathcal{E}}\big) \big(\kappa\frac{\rho}{\mathcal{E}} -1\big)}{\kappa -1} \qquad \mbox{ and }\qquad \sigma_2^2 = \rho (1-\rho ).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn ${\rm SLE}(0,\boldsymbol{\rho})$ of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Let $w$ be the growth point on $\partial \mathbb{D}$ and $\boldsymbol{\rho}=\sum_{i=1}^{n} \rho_j \delta_{u_j} + \sigma_0 \cdot 0 + \sigma_{\infty} \cdot \infty$ be a divisor on $\widehat{\mathbb{C}}$ that is symmetric under involution, i.e. $\boldsymbol{\rho}(z)=\boldsymbol{\rho}(\frac{z}{|z|^2})$ for all $z$ and $\int \boldsymbol{\rho}= -6$. Define the radial $\operatorname{SLE}(0,w, \boldsymbol{\rho})$ Loewner chain by
\begin{equation}
\partial_t g_t(z)=g_t(z)\frac{w(t)+g_t(z)}{w(t)-g_t(z)}, \quad g_0(z)=z,
\end{equation}
where the driving function $w(t)$ evolves as

\begin{equation}
\dot{w}(t)=w(t)\sum_j \rho_j\frac{g_t(u_j)+w(t)}{g_t(u_j)-w(t)}, \quad z(0)=z_0.
\end{equation}

In the angular coordinate, $w(t)=e^{i\theta(t)}$ and $u_j(t)= e^{i q_j(t)}$, let $h_t(z)$ be the covering conformal map of $g_t(z)$ (i.e. $e^{ih_t(z)}=g_t(e^{iz}))$.

Then the Loewner differential equation for $h_t(z)$ is 

\begin{equation}
\partial_t h_t(z)=\cot(\frac{h_t(z)-\theta_t}{2}), \quad h_0(z)=z,     z\in{\overline{\mathbb{H}}},
\end{equation}

where the driving function $\theta_t$ evolves as
\begin{equation}
\dot{\theta}_t=\sum_j \rho_j \cot( \frac{\theta_t-q_j(t)}{2}), \quad x(0)=x_0.
\end{equation}

[Definition 5 (Completely monotone functions) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] A \(C^\infty\) function \(\phi\) on an interval is completely monotone if
\begin{equation}
(-1)^n\phi^{(n)}(x)\ge0
\end{equation}
for every \(n\ge0\) and every \(x\) in the interval.

[Proposition increment-moments of arXiv:2604.27682, 'Multifractional Stable Motion with Random Hurst Exponent'] Under condition (equation eq: continuity assumption on H of the paper), for any $\delta>0$, there are constants $C > 0$ and $\epsilon > 0$ such that
    \begin{align*}
        \left\|\frac{X(t)-X(s)}{|t-s|^{\min_{r\in[s \wedge t,s \vee t]} H(r) - \frac{1}{\alpha} - \delta}}\right\|_{\Lambda^\alpha(\Omega)}^\alpha \leq C |t-s|, \quad \text{whenever } |t-s|\leq \epsilon.
    \end{align*}
    Hence, for any $\delta > 0$ and $\frac{\alpha}{1+\alpha\delta/2}<p<\alpha$, there are constants $C > 0$ and $\epsilon > 0$ such that
    \begin{align*}
        \left\|\frac{X(t)-X(s)}{|t-s|^{\min_{r\in[s \wedge t,s \vee t]} H(r) - \frac{1}{\alpha}-\delta}}\right\|_{\mathbb{L}^p(\Omega)}^p \leq C |t-s|,\quad \text{whenever } |t-s|\leq \epsilon.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:cluster-expansion of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] There is a $\beta^* = \beta^*(d)>0$ such that 
    \begin{enumerate}
        \item For any loop $\ell \in \Lambda$, $\langle W_{\ell} \rangle_{\beta,\Lambda}$ is an analytic function of $\beta$ in $\mbb{D}(0,\beta^*)$ and for real $\beta$ in this disk, there is a unique infinite volume limit of the Yang--Mills measure such that,
    \begin{equs}
        \langle W_{\ell} \rangle_{\beta,\Lambda_L} \to \langle W_{\ell} \rangle_{\beta,\Lambda_{\infty}}
    \end{equs}
    uniformly on $\mbb{D}(0,\beta^*)$ as $L \to \infty$.
    \item For any $L <\infty$, $Z_{\beta,\Lambda_L} \neq 0$ for all $\beta \in \mathbb{D}(0,\beta^*)$, and thus,
    \begin{equs}
        \frac{1}{Z_{\beta,\Lambda_L}}
    \end{equs}
    is analytic on $\beta \in \mathbb{D}(0,\beta^*)$.
    \item There exists a constant $C_d>0$ such that for any rectangular loop $\ell$ with both side lengths at least $15$,
    \begin{equs}
        |\langle W_{\ell} \rangle_{\beta,\Lambda_{\infty}}| \leq C_d^{|\ell|}\beta^{4|\ell|-16}.
    \end{equs}
    \end{enumerate}

[Lemma 42 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Assume $A>A_c(N)$ and let $\pi_{A,N}$ be a nonzero invariant law as in
  \cref{prop:nd-stationary-equation}. Let $(Y,\Theta)$ have law
  $\widetilde{\pi}_{A,N}$. Then, for every $0\leq\alpha<\beta_{A,N}$,
  \begin{equation}
    \Ee e^{\alpha Y}<\infty .
  \end{equation}

